window.BANK_DATA = {"subject": "人力资源管理专业知识和实务", "exam": "中级经济师", "version": 1, "chapters": [{"id": 1, "title": "劳动合同管理与特殊用工", "questions": [{"id": "1-1", "type": "single", "stem": "关于执行劳动条件和最低工资标准的说法，正确的是（ ）。", "options": {"A": "劳动合同履行地与用人单位注册地不一致时，涉及劳动条件的内容，执行用人单位注册地的有关规定", "B": "劳动合同履行地与用人单位注册地不一致时，涉及最低工资标准的内容，执行劳动合同履行地的标准", "C": "劳动合同履行地与用人单位注册地不一致时，涉及劳动条件的内容，由用人单位决定是执行用人单位注册地还是劳动合同履行地的有关规定", "D": "劳动合同履行地与用人单位注册地不一致时，涉及最低工资标准的内容，由劳动者决定是执行用人单位注册地还是劳动合同履行地的标准"}, "answer": "B", "analysis": "劳动合同履行地与用人单位注册地不一致时，有关劳动者的最低工资标准、劳动保护、劳动条件、职业危害防护以及本地区上年度职工月平均工资标准等事项，原则上按照劳动合同履行地的有关规定执行。用人单位注册地的有关标准高于劳动合同履行地的标准，且用人单位与劳动者约定按照注册地标准执行的，从其约定。", "optionAnalysis": {"A": "错误，原则上应执行劳动合同履行地的规定，并非当然执行用人单位注册地的规定。", "B": "正确，最低工资标准原则上按照劳动合同履行地的标准执行。", "C": "错误，适用标准不是由用人单位单方决定。", "D": "错误，适用标准也不是由劳动者单方决定。"}}, {"id": "1-2", "type": "multi", "stem": "关于用人单位义务的说法，错误的是（ ）。", "options": {"A": "用人单位安排劳动者加班，应当按照本单位规定的标准向劳动者支付加班费", "B": "用人单位应当保护劳动者的生命安全和身体健康", "C": "用人单位应该按照劳动合同约定和国家规定，向劳动者及时足额支付劳动报酬", "D": "用人单位应当严格执行劳动定额标准", "E": "劳动者拒绝用人单位管理人员违章指挥、强令冒险作业的，视为违反劳动合同"}, "answer": "AE", "analysis": "本题要求选择错误的说法。", "optionAnalysis": {"A": "错误。用人单位安排加班，应当按照国家有关规定向劳动者支付加班费，不能仅按照本单位自行规定的标准支付。", "B": "正确。用人单位负有保障劳动者生命安全和身体健康的法定义务。", "C": "正确。用人单位应当按照劳动合同约定和国家规定，及时足额支付劳动报酬。", "D": "正确。用人单位应当严格执行劳动定额标准，不得强迫或者变相强迫劳动者加班。", "E": "错误。劳动者拒绝用人单位管理人员违章指挥、强令冒险作业，不视为违反劳动合同。"}}, {"id": "1-3", "type": "single", "stem": "公司更换法定代表人时，关于劳动合同效力的说法正确的是（ ）。", "options": {"A": "劳动合同有效", "B": "劳动合同解除", "C": "劳动合同暂停执行", "D": "劳动合同终止"}, "answer": "A", "analysis": "用人单位变更名称、法定代表人、主要负责人或者投资人等事项，不影响劳动合同的履行。因此，公司更换法定代表人后，原劳动合同继续有效。", "optionAnalysis": {"A": "正确，劳动合同效力不受法定代表人变更的影响。", "B": "错误，法定代表人变更不属于劳动合同解除事由。", "C": "错误，劳动合同不因此暂停履行。", "D": "错误，法定代表人变更不导致劳动合同终止。"}}, {"id": "1-4", "type": "single", "stem": "如果员工主动辞职，下列说法正确的是（ ）。", "options": {"A": "应当提前30日通知用人单位", "B": "立即辞职，无须告诉用人单位", "C": "告知用人单位后，可以立即辞职", "D": "应当提前3日通知用人单位"}, "answer": "A", "analysis": "劳动者一般可以提前30日以书面形式通知用人单位解除劳动合同；劳动者在试用期内解除劳动合同的，应当提前3日通知用人单位。题干未说明员工处于试用期，因此适用一般规定。", "optionAnalysis": {"A": "正确，符合一般劳动者预告解除劳动合同的期限要求。", "B": "错误，普通主动辞职不属于无须通知即可立即解除的情形。", "C": "错误，仅告知用人单位通常不能立即解除，仍需遵守法定预告期。", "D": "错误，提前3日通知适用于试用期内的劳动者。"}}, {"id": "1-5", "type": "single", "stem": "如果甲员工以公司未为其缴纳社会保险为由解除劳动合同，下列判断中正确的是（ ）。", "options": {"A": "如需支付经济补偿，则经济补偿按甲在公司的工作年限，每满1年支付一个月工资的标准支付", "B": "甲只能采取书面形式通知公司", "C": "甲需提前30天通知公司", "D": "公司无需支付经济补偿"}, "answer": "A", "analysis": "用人单位未依法为劳动者缴纳社会保险费的，劳动者可以依法解除劳动合同，用人单位应当支付经济补偿。经济补偿一般按照劳动者在本单位的工作年限计算，每满1年支付1个月工资；6个月以上不满1年的，按1年计算；不满6个月的，支付半个月工资。", "optionAnalysis": {"A": "正确，表述符合经济补偿的一般计算标准。", "B": "错误，法律并未将此类解除限定为只能采用书面通知形式，但劳动者应保留有效通知证据。", "C": "错误，此种解除系因用人单位存在法定过错，不适用劳动者提前30日预告解除的一般规定。", "D": "错误，公司未依法缴纳社会保险费导致劳动者解除劳动合同的，依法应当支付经济补偿。"}}, {"id": "1-6", "type": "single", "stem": "关于企业实施经济性裁员的说法，正确的是（ ）。", "options": {"A": "经济补偿标准按员工工作年限，每满1年按半个月工资标准支付", "B": "企业应提前30日向工会或全体职工说明经济性裁员的情况", "C": "只要企业有重大技术革新情况，就可以经济性裁员", "D": "实施经济性裁员无须向当地劳动行政部门报告"}, "answer": "B", "analysis": "企业需要裁减人员达到法定人数或者比例，并符合法定实体条件时，应当提前30日向工会或者全体职工说明情况，听取意见后，将裁减人员方案向劳动行政部门报告，方可裁减人员。", "optionAnalysis": {"A": "错误，经济补偿一般为每满1年支付1个月工资，不是半个月工资；仅工作不满6个月时支付半个月工资。", "B": "正确，符合经济性裁员的法定程序要求。", "C": "错误，重大技术革新或者经营方式调整后，仍需变更劳动合同，变更后仍需裁减人员，并满足法定人数或比例等条件，不能仅凭存在重大技术革新直接裁员。", "D": "错误，裁减人员方案应当向劳动行政部门报告。"}}, {"id": "1-7", "type": "multi", "stem": "用人单位可以依法解除劳动合同的情形有（ ）。", "options": {"A": "劳动者严重违反用人单位规章制度的", "B": "劳动者被判处有期徒刑的", "C": "劳动者同时与其他用人单位建立劳动关系的", "D": "劳动者在试用期间被证明不符合录用条件的", "E": "劳动者以欺诈手段，使用人单位在违背真实意思情况下订立劳动合同的"}, "answer": "ABDE", "analysis": "B项应结合“劳动者被依法追究刑事责任”理解；被判处有期徒刑通常属于被依法追究刑事责任的情形。", "optionAnalysis": {"A": "正确。劳动者严重违反用人单位依法制定并公示的规章制度，用人单位可以依法解除劳动合同。", "B": "正确。劳动者被依法判处有期徒刑，属于被依法追究刑事责任，用人单位可以解除劳动合同。", "C": "错误。劳动者同时与其他用人单位建立劳动关系并不当然导致解除；只有对完成本单位工作任务造成严重影响，或者经用人单位提出后拒不改正的，用人单位才可以解除。", "D": "正确。劳动者在试用期间被证明不符合录用条件的，用人单位可以解除劳动合同，但应当能够证明录用条件及不符合条件的事实。", "E": "正确。劳动者以欺诈手段，使对方在违背真实意思的情况下订立或者变更劳动合同的，劳动合同无效或者部分无效，用人单位可以依法解除。"}}, {"id": "1-8", "type": "single", "stem": "员工实际工作12年，在所在单位7年，可以享受的医疗期是（ ）。", "options": {"A": "16个月", "B": "13个月", "C": "5个月", "D": "9个月"}, "answer": "D", "analysis": "医疗期需要结合劳动者的实际工作年限和在本单位工作年限确定。实际工作年限10年以上，在本单位工作年限5年以上不满10年的，医疗期为9个月。本题中，员工实际工作12年，属于“实际工作年限10年以上”；在本单位工作7年，属于“5年以上不满10年”。因此，可以享受的医疗期为9个月。", "optionAnalysis": {"A": "错误，法定医疗期档次中不存在与本题条件对应的16个月。", "B": "错误，法定医疗期档次中不存在与本题条件对应的13个月。", "C": "错误，本题条件对应的医疗期不是5个月。", "D": "正确。"}}, {"id": "1-9", "type": "single", "stem": "李某的医疗期是12个月，他在公司可能工作的年限是（ ）。", "options": {"A": "8年", "B": "9年", "C": "12年", "D": "7年"}, "answer": "C", "analysis": "按照医疗期的一般确定标准，实际工作年限10年以上、在本单位工作年限10年以上不满15年的，医疗期为12个月。", "optionAnalysis": {"A": "错误，在本单位工作8年属于5年以上不满10年，若实际工作年限达到10年以上，通常对应9个月医疗期。", "B": "错误，在本单位工作9年仍属于5年以上不满10年，通常对应9个月医疗期。", "C": "正确，在公司工作12年属于10年以上不满15年，具备对应12个月医疗期的可能。", "D": "错误，在公司工作7年属于5年以上不满10年，通常对应9个月医疗期。需要注意，医疗期还取决于实际工作总年限；题干仅问“可能工作的年限”，因此四个选项中12年符合条件。"}}, {"id": "1-10", "type": "multi", "stem": "下列行为应向用人单位支付违约金的是（ ）。", "options": {"A": "违反培训服务期", "B": "违反竞业限制", "C": "破坏用人单位财产", "D": "重大过失导致用人单位发生严重损失", "E": "与他人串通获取利益导致本单位发生损失"}, "answer": "AB", "analysis": "劳动合同法律制度原则上限制用人单位与劳动者约定违约金，依法可以约定由劳动者承担违约金的主要情形是违反专项培训服务期约定和违反竞业限制约定。", "optionAnalysis": {"A": "正确。劳动者违反合法有效的培训服务期约定，应在法定范围内支付违约金。", "B": "正确。劳动者违反合法有效的竞业限制约定，可以按照约定向用人单位支付违约金。", "C": "错误。破坏用人单位财产可能产生损害赔偿责任或者其他责任，但不属于法律允许约定劳动合同违约金的法定情形。", "D": "错误。因重大过失造成严重损失可能承担赔偿责任，但该责任与劳动合同违约金不是同一概念。", "E": "错误。与他人串通造成单位损失可能产生赔偿、纪律处分乃至刑事责任，但不属于法定的劳动合同违约金适用情形。"}}, {"id": "1-11", "type": "single", "stem": "钱某与公司在劳动合同中约定：“劳动合同期限六年，公司为钱某提供专业技术培训，培训费用9万元，服务期为培训结束后三年，若钱某提前离职，需一次性支付违约金9万元”。钱某在培训结束工作满二年后，因个人原因提前解除劳动合同。钱某应向公司支付的违约金是（ ）。", "options": {"A": "9万元", "B": "3万元", "C": "0万元", "D": "6万元"}, "answer": "B", "analysis": "劳动者违反服务期约定的，违约金数额不得超过用人单位提供的培训费用；用人单位要求劳动者支付的违约金，不得超过服务期尚未履行部分所应分摊的培训费用。服务期为3年，培训费用为9万元，因此每年分摊培训费用＝9÷3＝3万元。钱某已履行2年，尚未履行1年，因此应承担的违约金＝9×1÷3＝3万元。虽然合同约定提前离职一次性支付9万元，但用人单位实际可主张的金额不得超过未履行服务期所分摊的培训费用。", "optionAnalysis": {"A": "错误，9万元超过尚未履行部分分摊的培训费用。", "B": "正确。", "C": "错误，钱某因个人原因提前解除并违反服务期约定，依法应承担相应违约金。", "D": "错误，6万元相当于已履行两年所对应的培训费用，并非尚未履行部分。"}}, {"id": "1-12", "type": "single", "stem": "用人单位依法向劳动者支付经济补偿的时间应当是（ ）。", "options": {"A": "办理工作交接后3个月内", "B": "劳动合同解除之日起6个月内", "C": "劳动者书面要求用人单位支付经济补偿之日", "D": "工作交接办结当天"}, "answer": "D", "analysis": "劳动者应当按照双方约定办理工作交接；用人单位依照法律规定应当向劳动者支付经济补偿的，应当在办结工作交接时支付。", "optionAnalysis": {"A": "错误，法律没有规定可以在办理工作交接后3个月内支付。", "B": "错误，法律没有规定统一延迟至劳动合同解除后6个月内支付。", "C": "错误，经济补偿是用人单位的法定义务，不以劳动者另行提交书面请求作为支付条件。", "D": "正确，应在工作交接办结时支付。"}}, {"id": "1-13", "type": "single", "stem": "某公司与张某签订了离职后的竞业限制协议，约定在竞业限制期限内，公司每月向张某支付4000元经济补偿。张某离职后，公司想提前解除与张某的竞业限制协议，此时公司应向张某支付的补偿是（ ）。", "options": {"A": "12000元", "B": "8000元", "C": "16000元", "D": "4000元"}, "answer": "A", "analysis": "在竞业限制期限内，用人单位请求解除竞业限制协议时，劳动者可以请求用人单位额外支付3个月的竞业限制经济补偿。额外补偿＝每月竞业限制经济补偿×3个月＝4000×3＝12000元。", "optionAnalysis": {"A": "正确，为12000元。", "B": "错误，仅相当于2个月的补偿。", "C": "错误，相当于4个月的补偿。", "D": "错误，仅相当于1个月的补偿。"}}, {"id": "1-14", "type": "single", "stem": "下列收入类别中，全额免征个人所得税的是（ ）。", "options": {"A": "用人单位发给离职员工的生活补助费", "B": "员工从破产企业取得的一次性安置费收入", "C": "用人单位发给离职员工的经济补偿金", "D": "用人单位发给在职员工的奖金收入"}, "answer": "B", "analysis": "企业依照国家有关法律规定宣告破产，企业职工从该破产企业取得的一次性安置费收入，依法免征个人所得税。", "optionAnalysis": {"A": "错误。用人单位发给离职员工的生活补助费不能仅凭名称当然全额免税，应根据款项性质和税收规定判断。", "B": "正确，破产企业职工取得的一次性安置费收入全额免征个人所得税。", "C": "错误。个人因与用人单位解除劳动关系取得的一次性补偿收入，在当地上年职工平均工资一定倍数以内的部分可按规定免税，超过部分依法计算纳税，并非一律全额免税。", "D": "错误，在职员工取得的奖金收入一般属于个人所得税应税所得。"}}, {"id": "1-15", "type": "single", "stem": "关于用人单位劳动规章制度的说法，正确的是（ ）。", "options": {"A": "用人单位制定的劳动规章制度公示后，即对职工具有法律约束力", "B": "用人单位制定的劳动规章制度，无需告知职工即可实施", "C": "在劳动规章制度实施过程中，工会认为不适当的内容，用人单位应当按工会要求予以修改", "D": "用人单位制定的劳动规章制度违反法律规定，则由劳动行政部门责令改正"}, "answer": "D", "analysis": "直接涉及劳动者切身利益的规章制度，不仅需要内容合法，还应经过法定的民主制定程序，并向劳动者公示或者告知。用人单位的规章制度违反法律、法规规定的，劳动行政部门有权责令改正；给劳动者造成损害的，用人单位还应承担赔偿责任。", "optionAnalysis": {"A": "错误。规章制度并非只要公示就当然具有法律约束力，还需要内容合法、制定程序合法，并履行公示或者告知程序。", "B": "错误。直接涉及劳动者切身利益的规章制度应当公示或者告知劳动者。", "C": "错误。工会或者职工认为规章制度不适当的，有权向用人单位提出，通过协商予以修改完善，但不能理解为用人单位必须无条件按照工会的单方要求修改。", "D": "正确。劳动规章制度违反法律规定的，劳动行政部门可以责令改正，并可依法给予警告；造成损害的还应承担赔偿责任。"}}, {"id": "1-16", "type": "multi", "stem": "关于经营劳务派遣业务合规性的说法，正确的有（ ）。", "options": {"A": "公司可以设立劳务派遣单位向其下级子公司派遣劳动者", "B": "劳派经营许可证有效期为两年", "C": "经营劳派业务的应当依法申请行政许可", "D": "公司注册资本不得低于300万元", "E": "公司不得设立劳派单位向本公司派遣劳动者"}, "answer": "CE", "analysis": "经营劳务派遣业务应当依法申请行政许可，并满足注册资本、固定经营场所、设施和管理制度等法定条件。用人单位不得设立劳务派遣单位向本单位或者所属单位派遣劳动者。", "optionAnalysis": {"A": "错误，公司设立的劳务派遣单位不得向本公司或者所属单位派遣劳动者，下级子公司属于所属单位范围。", "B": "错误，劳务派遣经营许可证的有效期通常为3年，不是2年。", "C": "正确，经营劳务派遣业务必须依法申请行政许可。", "D": "错误，经营劳务派遣业务的注册资本不得少于人民币200万元，并非300万元。", "E": "正确，公司不得设立劳务派遣单位向本公司派遣劳动者。"}}, {"id": "1-17", "type": "multi", "stem": "关于劳务派遣的说法，错误的是（ ）。", "options": {"A": "按月或者按季度支付工资", "B": "不得约定试用期", "C": "被派遣者在无工作期间，按当地上年度月平均工资支付报酬", "D": "劳务派遣单位不得向被派遣劳动者收取费用", "E": "劳务派遣用工是我国企业基本用工形式"}, "answer": "ABCE", "analysis": "本题要求选择错误的说法。", "optionAnalysis": {"A": "错误。劳务派遣单位应当按月向被派遣劳动者支付劳动报酬，不能笼统地按季度支付。", "B": "错误。劳务派遣单位可以依法与同一被派遣劳动者约定一次试用期，并非绝对不得约定试用期。", "C": "错误。被派遣劳动者在无工作期间，劳务派遣单位应当按照所在地人民政府规定的最低工资标准，向其按月支付报酬，不是按照当地上年度月平均工资支付。", "D": "正确。劳务派遣单位和用工单位均不得向被派遣劳动者收取费用。", "E": "错误。劳动合同用工是我国企业的基本用工形式，劳务派遣用工属于补充形式，只能在临时性、辅助性或者替代性的工作岗位上实施。"}}, {"id": "1-18", "type": "multi", "stem": "关于劳务派遣劳动合同的说法，正确的有（ ）。", "options": {"A": "可以签订固定期限和以完成一定工作任务为期限的劳动合同", "B": "劳动合同中应当载明用工单位以及派遣期限等信息", "C": "劳务派遣单位与被派遣劳动者订立劳动合同", "D": "劳动合同中不得约定试用期", "E": "被派遣劳动者无工作期间，劳务派遣单位按照最低工资标准支付报酬"}, "answer": "BCE", "analysis": "", "optionAnalysis": {"A": "错误。劳务派遣单位应当与被派遣劳动者订立2年以上的固定期限劳动合同，不能以完成一定工作任务为期限的劳动合同替代该法定要求。", "B": "正确。劳务派遣劳动合同除应当具备一般劳动合同的必备条款外，还应载明被派遣劳动者的用工单位、派遣期限、工作岗位等情况。", "C": "正确。劳务派遣单位是法律上的用人单位，应当与被派遣劳动者订立劳动合同。", "D": "错误。劳务派遣单位可以依法与同一被派遣劳动者约定一次试用期，并非一律不得约定。", "E": "正确。被派遣劳动者在无工作期间，劳务派遣单位应当按照其所在地人民政府规定的最低工资标准，按月向其支付报酬。"}}, {"id": "1-19", "type": "multi", "stem": "关于非全日制用工的说法，符合法律规定的有（ ）。", "options": {"A": "一方当事人提前1日可以通知对方终止协议", "B": "以小时计酬为主", "C": "周工作时间累计不能超过24个小时", "D": "双方订立口头协议，劳动报酬支付周期不超过15日订立书面协议的，支付周期不超过20日", "E": "双方当事人不得约定试用期"}, "answer": "ABCE", "analysis": "非全日制用工以小时计酬为主，一般平均每日工作时间不超过4小时，每周累计工作时间不超过24小时。双方可以订立口头协议，不得约定试用期，任何一方均可以随时通知对方终止用工，劳动报酬结算支付周期最长不得超过15日。", "optionAnalysis": {"A": "正确。法律允许任何一方随时通知对方终止用工，因此提前1日通知也属于允许范围；但提前1日并非强制要求。", "B": "正确，非全日制用工以小时计酬为主。", "C": "正确，每周工作时间累计一般不超过24小时。", "D": "错误。无论双方采用口头协议还是书面协议，劳动报酬结算支付周期最长均不得超过15日，不存在书面协议可以延长至20日的规定。", "E": "正确，非全日制用工双方当事人不得约定试用期。"}}, {"id": "1-20", "type": "multi", "stem": "关于非全日制用工的说法，正确的有（ ）。", "options": {"A": "薪酬发放周期最长不得超过半年", "B": "劳动者可以选择是否约定试用期", "C": "劳动者可以在三个用人单位工作", "D": "双方可随时终止用工", "E": "必须订立书面劳动合同"}, "answer": "CD", "analysis": "", "optionAnalysis": {"A": "错误。非全日制用工劳动报酬结算支付周期最长不得超过15日，不是半年。", "B": "错误。非全日制用工双方当事人不得约定试用期，不属于可以自由选择的事项。", "C": "正确。从事非全日制用工的劳动者可以与一个或者一个以上用人单位订立劳动合同。因此，在不影响先订立劳动合同履行的前提下，可以同时在三个用人单位工作。", "D": "正确。非全日制用工双方当事人任何一方均可以随时通知对方终止用工，用人单位通常不向劳动者支付经济补偿。", "E": "错误。非全日制用工双方当事人可以订立口头协议，并非必须订立书面劳动合同。"}}, {"id": "1-21", "type": "single", "stem": "职工在两个用人单位同时就业时，关于工伤保险费缴纳的说法，正确的是（ ）。", "options": {"A": "如果是非全日制员工，两家单位都无需缴纳工伤保险费", "B": "如果是全日制员工，两家单位都必须缴纳工伤保险费", "C": "如果是全日制员工，选择一家单位缴纳工伤保险费", "D": "如果是非全日制员工，选择一家单位缴纳工伤保险费第二章社会保险法律"}, "answer": "B", "analysis": "职工同时在两个或者两个以上用人单位就业的，各用人单位应当分别为职工缴纳工伤保险费。职工发生工伤时，由职工受到伤害时工作的单位依法承担工伤保险责任。", "optionAnalysis": {"A": "错误。招用非全日制从业人员的用人单位，也应当依法为其缴纳工伤保险费，不能因属于非全日制用工而免除缴费义务。", "B": "正确。职工同时在两个单位就业的，各用人单位均应依法缴纳工伤保险费。", "C": "错误，不能仅选择一家单位缴纳。", "D": "错误，非全日制劳动者同时与多个单位建立劳动关系时，也不是任选一家缴纳，而应由各用人单位分别依法参保。"}}]}, {"id": 2, "title": "社会保险法律", "questions": [{"id": "2-1", "type": "single", "stem": "（ ）承担缴纳社会保险费的义务，是社会保险基金的主要缴纳者。", "options": {"A": "国家", "B": "税务机关", "C": "劳动者", "D": "用人单位"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误。国家承担建立和完善社会保险制度、提供财政支持以及实施监督管理等责任，但不是社会保险基金的主要缴纳者。", "B": "错误。税务机关按照职责承担社会保险费征收等工作，是社会保险费的征收机构之一，不是社会保险基金的主要缴纳者。", "C": "错误。劳动者依法承担个人应缴社会保险费的缴费义务，但从社会保险基金筹集结构以及用人单位承担的缴费责任看，劳动者不是本题所指的主要缴纳者。", "D": "正确。用人单位依法为职工办理社会保险登记，并按照规定缴纳社会保险费，是社会保险基金的主要缴纳者。因此，本题应选D。"}}, {"id": "2-2", "type": "single", "stem": "在社会保险法律关系中，投保人的法律义务包括（ ）。", "options": {"A": "支付社会保险待遇", "B": "缴纳社会保险费", "C": "管理社会保险基金", "D": "建立社会保险档案"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误。支付社会保险待遇通常是社会保险经办机构等社会保险人的职责，不是投保人的法律义务。", "B": "正确。在社会保险法律关系中，用人单位和劳动者等投保人应当依法参加社会保险，并按照规定缴纳社会保险费。", "C": "错误。社会保险基金管理由依法确定的社会保险行政部门、财政部门、社会保险经办机构及相关管理主体按照职责实施，不属于投保人的法律义务。", "D": "错误。建立社会保险档案属于社会保险经办机构办理社会保险登记、记录权益和提供经办服务等职责的内容，不是投保人的法律义务。因此，本题应选B。"}}, {"id": "2-3", "type": "single", "stem": "关于社会保险法律适用的基本规则的说法，正确的是（ ）。", "options": {"A": "同位法中特别规定与一般规定不一致时，适用特别规定", "B": "原则上法律和行政法规的效力等同", "C": "法律规定原则上要溯及既往", "D": "同位法中新的规定与旧的规定不一致时，适用旧的规定"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确。同一机关制定的同一效力层级的法律规范中，特别规定与一般规定不一致的，原则上适用特别规定，即特别法优于一般法。", "B": "错误。法律的效力高于行政法规，二者不属于效力等同的法律规范。行政法规不得与法律相抵触。", "C": "错误。法律规范原则上不溯及既往，即通常不适用于其生效前已经发生的事实和行为；法律另有规定的除外。", "D": "错误。同一机关制定的同一效力层级的法律规范中，新的规定与旧的规定不一致的，原则上适用新的规定，即新法优于旧法。因此，本题应选A。"}}, {"id": "2-4", "type": "multi", "stem": "社会保险法律适用的基本原则正确的是（ ）。", "options": {"A": "法律效力高于行政法规", "B": "同位法中特别规定与一般规定不一致时，适用于特别规定", "C": "地方性法规效力高于本级和下级政府规章", "D": "同位法中新的规定与旧的规定不一致，适用于新的规定", "E": "原则上追溯既往第三章社会保险体系"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确。根据法律规范的效力层级，法律的效力高于行政法规，行政法规不得与法律相抵触。", "B": "正确。同一效力层级的法律规范中，特别规定与一般规定不一致的，原则上适用特别规定，即特别法优于一般法。题目中的“适用于特别规定”应理解为“适用特别规定”。", "C": "正确。地方性法规的效力高于本级和下级地方政府规章。本级和下级地方政府制定的规章不得与地方性法规相抵触。", "D": "正确。同一机关制定的同一效力层级的法律规范中，新的规定与旧的规定不一致的，原则上适用新的规定，即新法优于旧法。题目中的“适用于新的规定”应理解为“适用新的规定”。", "E": "错误。法律规范通常遵循不溯及既往原则，即原则上不追溯适用于其生效以前已经发生的事实和行为；法律明确规定可以溯及既往等特殊情形除外。因此，本题应选A、B、C、D。"}}]}, {"id": 3, "title": "社会保险体系", "questions": [{"id": "3-1", "type": "multi", "stem": "灵活就业人员参加基本养老保险，所缴纳的基本养老保险费计入（ ）。", "options": {"A": "基本养老保险统筹基金", "B": "银行", "C": "财政", "D": "个人账户", "E": "税务局"}, "answer": "AD", "analysis": "灵活就业人员参加职工基本养老保险时，缴纳的基本养老保险费按规定分别计入基本养老保险统筹基金和个人账户。", "optionAnalysis": {"A": "正确：缴费中的统筹部分计入基本养老保险统筹基金，用于社会统筹支付。", "B": "错误：银行可能承担资金收付、存储等业务，但不是基本养老保险费的法定归集账户类别。", "C": "错误：财政可以依法对基本养老保险基金给予补助，但灵活就业人员缴纳的养老保险费并非直接计入财政。", "D": "正确：缴费中的个人账户部分计入参保人员的基本养老保险个人账户。", "E": "错误：税务部门可以依法负责社会保险费征收，但其属于征收机关，不是养老保险费最终计入的基金账户。"}}, {"id": "3-2", "type": "single", "stem": "已知当地上年度在岗职工月平均工资1万元，张某的月工资3.5万元。张某参加职工养老保险的月缴费工资基数应当为（ ）。", "options": {"A": "2万元", "B": "3万元", "C": "1万元", "D": "3.5万元"}, "answer": "B", "analysis": "职工基本养老保险缴费工资基数通常设有上下限，其中上限一般按照当地上年度职工月平均工资的300%确定。缴费基数上限＝1万元×300%＝3万元。张某实际月工资为3.5万元，高于3万元的缴费基数上限，因此应按3万元作为月缴费工资基数。", "optionAnalysis": {"A": "错误：2万元不是根据题中平均工资和法定上限计算得出的数额。", "B": "正确：张某的月缴费工资基数应按上限3万元确定。", "C": "错误：1万元是当地上年度在岗职工月平均工资，不是张某应采用的缴费基数。", "D": "错误：3.5万元超过缴费基数上限，不能全部作为缴费工资基数。"}}, {"id": "3-3", "type": "single", "stem": "职工退休时已缴养老20年，其基础养老金月标准计算公式为（ ）。", "options": {"A": "（当地上年度在岗职工月平均工资＋本人退休前12个月平均工资）÷2×20%", "B": "（当地上年度在岗职工月平均工资＋本人指数化月平均工资）÷2×15%", "C": "（当地上年度在岗职工月平均工资＋本人退休前12个月平均工资）÷2×15%", "D": "（当地上年度在岗职工月平均工资＋本人指数化月平均工资）÷2×20%"}, "answer": "D", "analysis": "基础养老金通常以当地上年度职工月平均工资和本人指数化月平均缴费工资的平均值为计发基数，缴费每满1年发给1%。缴费年限为20年，对应计发比例＝20×1%＝20%。基础养老金月标准＝（当地上年度在岗职工月平均工资＋本人指数化月平均工资）÷2×20%。", "optionAnalysis": {"A": "错误：计算时应采用本人指数化月平均缴费工资，而不是本人退休前12个月平均工资。", "B": "错误：工资指标正确，但20年缴费年限对应20%，不是15%。", "C": "错误：既错误使用退休前12个月平均工资，又错误采用15%的计发比例。", "D": "正确：工资指标和20%的计发比例均符合基础养老金计算规则。"}}, {"id": "3-4", "type": "single", "stem": "个人跨统筹地区就业，以下关于基本养老保险关系转移说法正确的是（ ）。", "options": {"A": "基本养老保险关系转移，缴费年限累计计算", "B": "基本养老保险关系转移，缴费年限重新计算", "C": "基本养老保险关系不转移，缴费年限累计计算", "D": "基本养老保险关系不转移，缴费年限重新计算"}, "answer": "A", "analysis": "个人跨统筹地区就业时，其基本养老保险关系随本人转移，缴费年限累计计算，个人账户储存额按规定累计。", "optionAnalysis": {"A": "正确：同时准确说明了养老保险关系转移和缴费年限累计计算两项规则。", "B": "错误：基本养老保险关系虽然应当转移，但已经形成的缴费年限不会重新计算。", "C": "错误：跨统筹地区就业时，基本养老保险关系应当按规定办理转移接续。", "D": "错误：既错误地认为保险关系不转移，又错误地认为缴费年限重新计算。"}}, {"id": "3-5", "type": "multi", "stem": "关于基本养老保险说法正确的是（ ）。", "options": {"A": "基本养老保险基金由用人单位和个人缴费组成", "B": "参保个人未达到法定退休年龄时因病或非因工死亡，其遗属可以领取丧葬补助金和抚恤金", "C": "基础养老金月标准以当地上年度职工月平均工资为基数，缴费每满1年发给1%", "D": "用人单位应按照国家规定的本单位职工工资总额的比例缴纳基本养老保险费，计入基本养老保险统筹基金", "E": "达到法定退休年龄累计缴费满30年，可以按月领取基本养老金"}, "answer": "BD", "analysis": "", "optionAnalysis": {"A": "错误：基本养老保险基金的资金来源不仅包括用人单位和个人缴费，还包括政府补贴等资金，选项表述不完整。", "B": "正确：参加基本养老保险的个人因病或者非因工死亡的，其遗属可以依法领取丧葬补助金和抚恤金。", "C": "错误：基础养老金不是只以当地上年度职工月平均工资为基数，而是以当地上年度职工月平均工资与本人指数化月平均缴费工资的平均值为计发基数，缴费每满1年发给1%。", "D": "正确：用人单位按照国家规定的本单位职工工资总额的一定比例缴纳基本养老保险费，单位缴费计入基本养老保险统筹基金。", "E": "错误：按月领取基本养老金的最低累计缴费年限并非30年。该选项把缴费年限条件错误表述为满30年。"}}, {"id": "3-6", "type": "multi", "stem": "城乡居民基本养老保险的覆盖范围（ ）。", "options": {"A": "是有工作在职的", "B": "是年满18岁的大学生", "C": "是35岁的城镇未就业青年", "D": "35岁在家务农的", "E": "入职事业单位的人员"}, "answer": "CD", "analysis": "城乡居民基本养老保险主要覆盖年满16周岁、不属于机关事业单位工作人员基本养老保险制度覆盖范围且未参加职工基本养老保险的城乡居民，在校学生通常不在其参保范围内。", "optionAnalysis": {"A": "错误：有工作且依法参加职工基本养老保险的在职人员，应参加职工基本养老保险，不属于城乡居民基本养老保险的一般覆盖对象。", "B": "错误：在校大学生属于在校学生，不属于城乡居民基本养老保险的一般参保范围。", "C": "正确：35岁的城镇未就业青年，如未参加职工基本养老保险且不属于其他排除情形，可以参加城乡居民基本养老保险。", "D": "正确：35岁在家务农的城乡居民，如未参加职工基本养老保险，可以参加城乡居民基本养老保险。", "E": "错误：事业单位工作人员属于机关事业单位基本养老保险制度的覆盖对象，不参加城乡居民基本养老保险。"}}, {"id": "3-7", "type": "multi", "stem": "关于城乡居民基本养老保险制度的说法，正确的有（ ）。", "options": {"A": "最高缴费档次标准原则上不超过当地灵活就业人员参加城镇职工基本养老保险的年缴费额", "B": "个人账户养老金月计发标准是个人账户储存额除以130", "C": "待遇由基础养老金和个人账户养老金构成", "D": "可以在户籍地参加城乡居民基本养老保险", "E": "在校学生可以参加城乡居民基本养老保险"}, "answer": "ACD", "analysis": "", "optionAnalysis": {"A": "正确：城乡居民基本养老保险缴费档次由各地结合实际设置，最高缴费档次标准原则上不超过当地灵活就业人员参加职工基本养老保险的年缴费额。", "B": "错误：个人账户养老金的月计发标准通常为个人账户全部储存额除以139，不是除以130。", "C": "正确：城乡居民基本养老保险待遇由基础养老金和个人账户养老金两部分构成，并按规定支付终身。", "D": "正确：符合参保条件的城乡居民可以在户籍地参加城乡居民基本养老保险。", "E": "错误：在校学生通常不属于城乡居民基本养老保险的参保范围。"}}, {"id": "3-8", "type": "single", "stem": "基本医疗保险说法正确的（ ）。", "options": {"A": "单位缴费比例是8%", "B": "抵御疾病风险的一种社会保险", "C": "个人缴费4%", "D": "单位缴纳的要划入个人账户"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误：职工基本医疗保险的单位缴费比例由统筹地区根据当地实际情况确定，不能一概认定为8%。", "B": "正确：基本医疗保险是通过社会互助共济方式分担参保人员疾病医疗费用、抵御疾病经济风险的一项社会保险制度。", "C": "错误：个人缴费比例不能笼统表述为4%，具体比例应按照国家及统筹地区规定执行。", "D": "错误：单位缴费主要纳入统筹基金。随着职工基本医疗保险门诊共济保障机制改革，单位缴费原则上不再按原有方式划入在职职工个人账户，不能表述为单位缴费都要划入个人账户。"}}, {"id": "3-9", "type": "multi", "stem": "在职工基本医疗保险普通门诊费用统筹中，个人账户可以支付的范围有（ ）。", "options": {"A": "参保人员及其配偶在定点零售药店购买药品发生的由个人负担的医疗费用", "B": "参保人员在定点医疗机构就医发生的由个人负担的医疗费用", "C": "参保人员用于个人养生保健的费用", "D": "参保人员需要承担的公共卫生费用", "E": "参保人员参加体育健身的费用"}, "answer": "AB", "analysis": "职工基本医疗保险个人账户主要用于支付参保人员本人及符合规定的家庭成员在定点医疗机构就医或者在定点零售药店购买药品、医疗器械、医用耗材等发生的由个人负担的费用。", "optionAnalysis": {"A": "正确：符合规定的家庭共济范围内，个人账户可以用于支付参保人员配偶在定点零售药店购买药品时由个人负担的医疗费用。", "B": "正确：参保人员在定点医疗机构就医发生的个人负担医疗费用，属于个人账户的支付范围。", "C": "错误：养生保健消费不属于基本医疗保险个人账户的支付范围。", "D": "错误：公共卫生费用不属于基本医疗保险个人账户的一般支付范围，依法应由公共卫生资金等渠道承担的费用不得转由个人账户支付。", "E": "错误：体育健身属于非医疗消费，不得使用基本医疗保险个人账户支付。"}}, {"id": "3-10", "type": "single", "stem": "关于工伤保险责任的说法，错误的是（ ）。", "options": {"A": "用人单位分立的，承继单位应当承担原用人单位的工伤保险责任", "B": "用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担", "C": "职工被借调期间受工伤事故伤害的，由原用人单位承担工伤保险责任", "D": "职工在两个用人单位同时就业时，职工发生工伤后，由与职工先建立劳动关系的单位承担工伤保险责任"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确：用人单位发生分立、合并、转让的，承继单位应当承担原用人单位的工伤保险责任。", "B": "正确：用人单位实行承包经营的，工伤保险责任由职工劳动关系所在单位承担。", "C": "正确：职工被借调期间受到工伤事故伤害的，原则上由原用人单位承担工伤保险责任，原用人单位与借调单位可以约定补偿办法。", "D": "错误：职工在两个或者两个以上用人单位同时就业的，各用人单位均应依法为其缴纳工伤保险费。职工发生工伤后，由其受到伤害时工作的单位依法承担工伤保险责任，并非一律由先建立劳动关系的单位承担。"}}, {"id": "3-11", "type": "single", "stem": "下列情形中，不得认定为工伤的是（ ）。", "options": {"A": "患职业病的", "B": "因工外出期间，由于工作原因受到伤害的", "C": "在工作时间和工作岗位，突发疾病死亡的", "D": "在上班途中，由于本人负主要责任的交通事故受到伤害的"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "可以认定为工伤：职工患职业病的，属于法定工伤认定情形。", "B": "可以认定为工伤：职工因工外出期间，由于工作原因受到伤害或者发生事故下落不明的，属于法定工伤认定情形。", "C": "可以视同工伤：职工在工作时间和工作岗位突发疾病死亡，或者在规定时限内经抢救无效死亡的，依法视同工伤。", "D": "不得认定为工伤：上下班途中受到非本人主要责任的交通事故或者规定类型的交通运输事故伤害，才属于工伤认定范围。题中明确由本人负主要责任，不符合该条件。"}}, {"id": "3-12", "type": "multi", "stem": "《工伤保险条例》规定，不得认定为工伤或者视同工伤的情形包括（ ）。", "options": {"A": "职工因故意犯罪遭受事故伤害的", "B": "职工因醉酒遭受事故伤害的", "C": "职工因操作失误遭受事故伤害的", "D": "职工因自残遭受事故伤害的", "E": "职工因工作疲劳遭受事故伤害的"}, "answer": "ABD", "analysis": "依法不得认定为工伤或者视同工伤的排除情形包括故意犯罪、醉酒或者吸毒、自残或者自杀。", "optionAnalysis": {"A": "正确：职工因故意犯罪遭受事故伤害的，不得认定为工伤或者视同工伤。", "B": "正确：职工因醉酒遭受事故伤害的，属于法定排除情形。", "C": "错误：一般操作失误不属于法定排除情形。只要事故与工作存在法定关联，不能仅因职工操作失误就排除工伤认定。", "D": "正确：职工因自残遭受伤害的，不得认定为工伤或者视同工伤。", "E": "错误：工作疲劳不是法定排除情形，应根据事故发生的时间、地点、原因及与工作的关联判断是否构成工伤。"}}, {"id": "3-13", "type": "multi", "stem": "关于劳动能力鉴定的说法，正确的有（ ）。", "options": {"A": "劳动能力鉴定可以由用人单位、工伤职工或其近亲属提出申请", "B": "劳动功能障碍分为10个伤残等级", "C": "生活自理障碍分为5个等级", "D": "劳动能力鉴定委员会建立医疗卫生专家库", "E": "劳动能力鉴定结论应当及时送达申请鉴定的单位和个人"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确：职工发生工伤，经治疗伤情相对稳定后存在残疾、影响劳动能力的，可以由用人单位、工伤职工或者其近亲属向劳动能力鉴定委员会提出申请。", "B": "正确：劳动功能障碍分为10个伤残等级，一级最重，十级最轻。", "C": "错误：生活自理障碍通常分为生活完全不能自理、生活大部分不能自理和生活部分不能自理3个等级，不是5个等级。", "D": "正确：劳动能力鉴定委员会依法建立医疗卫生专家库，鉴定时从专家库中抽取相关专家组成专家组提出鉴定意见。", "E": "正确：劳动能力鉴定委员会作出的鉴定结论应当及时送达申请鉴定的单位和个人。"}}, {"id": "3-14", "type": "single", "stem": "职工因工伤被评定为生活完全不能自理的，其生活护理费为统筹地区上年度职工月平均工资的（ ）。", "options": {"A": "30%", "B": "40%", "C": "60%", "D": "50%"}, "answer": "D", "analysis": "工伤职工经劳动能力鉴定委员会确认需要生活护理的，生活护理费按照生活自理障碍程度支付。生活完全不能自理的，生活护理费标准为统筹地区上年度职工月平均工资的50%；生活大部分不能自理的为40%；生活部分不能自理的为30%。", "optionAnalysis": {"A": "错误：30%对应生活部分不能自理。", "B": "错误：40%对应生活大部分不能自理。", "C": "错误：现行分档标准中不包括60%。", "D": "正确：生活完全不能自理的护理费标准为50%。"}}, {"id": "3-15", "type": "multi", "stem": "可以领取失业保险金的条件包括（ ）。", "options": {"A": "非本人意愿中断就业", "B": "已进行失业登记，并有求职要求", "C": "失业前用人单位和本人已经缴纳失业保险费满一年", "D": "本人与用人单位解除劳动合同之日起6个月以上", "E": "本人累计工作年限满五年"}, "answer": "ABC", "analysis": "失业人员领取失业保险金通常应同时具备以下条件：失业前用人单位和本人已缴纳失业保险费满一年；非因本人意愿中断就业；已经进行失业登记并有求职要求。", "optionAnalysis": {"A": "正确：非因本人意愿中断就业是领取失业保险金的法定条件之一。", "B": "正确：办理失业登记并有求职要求是法定条件之一。", "C": "正确：失业前用人单位和本人缴纳失业保险费满一年是法定缴费条件。", "D": "错误：法律并未规定必须在解除劳动合同之日起经过6个月才能领取失业保险金。", "E": "错误：累计工作年限满五年不是领取失业保险金的基本条件；缴费时间主要影响领取期限等事项。"}}, {"id": "3-16", "type": "single", "stem": "失业保险金的标准不得低于（ ）。", "options": {"A": "当地最低工资标准", "B": "当地月基本养老金水平", "C": "当地在岗职工月平均工资", "D": "城市居民最低生活保障标准"}, "answer": "D", "analysis": "失业保险金的标准由省、自治区、直辖市人民政府确定，其数额应当低于当地最低工资标准、高于城市居民最低生活保障标准。因此，就最低限度而言，不得低于城市居民最低生活保障标准。", "optionAnalysis": {"A": "错误：失业保险金一般应低于当地最低工资标准，而不是不得低于最低工资标准。", "B": "错误：基本养老金水平不是确定失业保险金最低标准的法定参照下限。", "C": "错误：当地在岗职工月平均工资也不是失业保险金的法定最低标准。", "D": "正确：失业保险金不得低于城市居民最低生活保障标准。"}}, {"id": "3-17", "type": "single", "stem": "生育津贴的计算标准（ ）。", "options": {"A": "当地上年度在岗职工月平均工资", "B": "用人单位上年度职工月平均工资", "C": "用人单位本年度职工月平均工资", "D": "当地本年度职工月平均工资"}, "answer": "B", "analysis": "职工生育津贴一般按照职工所在用人单位上年度职工月平均工资计发，具体支付天数按照生育保险政策确定。常用计算思路为：生育津贴＝用人单位上年度职工月平均工资÷计薪天数×依法确定的津贴天数。", "optionAnalysis": {"A": "错误：计算基数不是当地上年度在岗职工月平均工资。", "B": "正确：用人单位上年度职工月平均工资是生育津贴的法定计发基数。", "C": "错误：本年度职工月平均工资尚未形成完整年度统计数据，不是规定的计发基数。", "D": "错误：当地本年度职工月平均工资既不是用人单位口径，也不是规定的上年度口径。"}}, {"id": "3-18", "type": "multi", "stem": "关于企业年金的说法，正确的有（ ）。", "options": {"A": "企业缴费每年不超过本企业职工工资总额的8%", "B": "企业年金方案由企业与职工双方通过集体协商确定", "C": "职工个人缴费不超过职工工资总额的15%", "D": "企业年金方案应当提交当地工会组织和劳动行政部门批准", "E": "只有依法参加基本养老保险并履行缴费义务的企业才能建立企业年金"}, "answer": "ABE", "analysis": "", "optionAnalysis": {"A": "正确：企业缴费每年不超过本企业职工工资总额的8%。企业和职工个人缴费合计一般不超过本企业职工工资总额的12%。", "B": "正确：企业建立企业年金，应当与职工一方通过集体协商确定，并制定企业年金方案。", "C": "错误：企业年金制度并未规定职工个人缴费可以达到职工工资总额的15%；企业和职工个人缴费合计还受到不超过企业职工工资总额12%的限制。", "D": "错误：企业年金方案按照规定履行报送、备案等程序，并非必须同时提交当地工会组织和劳动行政部门批准。工会或者职工代表参与集体协商，但不等于由工会组织批准。", "E": "正确：建立企业年金的企业及其职工应当依法参加基本养老保险并履行缴费义务，企业年金是基本养老保险的补充养老保险制度。"}}, {"id": "3-19", "type": "multi", "stem": "关于企业年金发放的说法，正确的有（ ）。", "options": {"A": "企业年金只能按月领取", "B": "职工部分丧失劳动能力时，可以领取部分企业年金", "C": "职工完全丧失劳动能力时，可以领取企业年金", "D": "职工达到法定退休年龄时，可以领取企业年金", "E": "出国定居人员的企业年金个人账户资金，可以根据本人要求一次性支付给本人第四章劳动争议调解仲裁"}, "answer": "CDE", "analysis": "", "optionAnalysis": {"A": "错误：职工达到企业年金待遇领取条件后，可以按照企业年金方案规定按月、分次或者一次性领取，也可以依法用于购买商业养老保险产品，因此并非只能按月领取。", "B": "错误：部分丧失劳动能力通常不属于提前领取企业年金的法定情形。", "C": "正确：职工完全丧失劳动能力时，可以按照规定领取企业年金。", "D": "正确：职工达到国家规定的退休年龄时，可以从本人企业年金个人账户中领取企业年金。", "E": "正确：出国或者出境定居人员的企业年金个人账户资金，可以根据本人要求一次性支付给本人。"}}]}, {"id": 4, "title": "劳动争议调解仲裁", "questions": [{"id": "4-1", "type": "single", "stem": "下列情形中，不属于劳动争议的是（ ）。", "options": {"A": "确认劳动关系发生的争议", "B": "因用人单位支付工资发生的争议", "C": "因社保经办机构拒绝发放养老金发生的争议", "D": "用人单位解除劳动合同发生的争议"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误。因确认劳动关系发生的争议，属于劳动争议受案范围。", "B": "错误。工资属于劳动报酬，劳动者与用人单位因工资支付发生的争议属于劳动争议。", "C": "正确。社保经办机构拒绝发放养老金，是劳动者与社会保险经办机构之间因社会保险待遇行政管理产生的争议，不是劳动者与用人单位之间的劳动争议。劳动者可以依法申请行政复议或者提起行政诉讼。", "D": "错误。用人单位解除劳动合同产生的争议，属于因订立、履行、变更、解除和终止劳动合同发生的劳动争议。"}}, {"id": "4-2", "type": "single", "stem": "下列不属于劳动争议范围的是（ ）。", "options": {"A": "劳动者因与用人单位就赔偿金发生的争议", "B": "劳动者对工伤认定结果不服", "C": "劳动者因与用人单位因工作时长发生的争议", "D": "劳动者因社保缴费问题发生的争议"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误。劳动者与用人单位因解除或者终止劳动合同等事项产生赔偿金争议的，属于劳动争议。", "B": "正确。工伤认定由社会保险行政部门依法作出。劳动者对工伤认定结果不服，属于对行政机关具体行政行为不服，不属于劳动争议，可以依法申请行政复议或者提起行政诉讼。", "C": "错误。工作时长涉及工作时间、休息休假等劳动标准，劳动者与用人单位因此发生的争议属于劳动争议。", "D": "错误。劳动者与用人单位因是否依法办理社会保险、缴纳社会保险费等事项发生的争议，属于劳动争议。需要注意，这不同于劳动者与社会保险经办机构之间因行政管理或者待遇发放产生的争议。"}}, {"id": "4-3", "type": "single", "stem": "下列争议中，属于劳动争议仲裁范围的是（ ）。", "options": {"A": "家庭和家政服务人员因劳动报酬发生的争议", "B": "国家机关与公务员因岗位变动发生的争议", "C": "劳动者对职业病认定结论不服的", "D": "职业病诊断时，因确认在岗时间发生的争议"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误。家庭或者个人与直接为其提供家政服务的人员之间通常不构成劳动法意义上的用人单位与劳动者关系，由此产生的报酬纠纷一般不属于劳动争议仲裁范围。家政服务人员由依法设立的家政服务企业招聘并派出工作的，应根据实际用工关系另行判断。", "B": "错误。公务员与国家机关因岗位变动发生的人事争议，适用公务员申诉、控告等制度，不属于一般劳动争议仲裁范围。", "C": "错误。劳动者对职业病诊断、鉴定结论不服，应依照职业病诊断鉴定程序处理，不属于劳动争议仲裁委员会直接审理的劳动争议。", "D": "正确。在职业病诊断过程中，当事人对劳动关系、工种、工作岗位或者在岗时间存在争议的，可以依法申请劳动仲裁。该争议属于对劳动关系及其履行事实的确认，属于劳动争议仲裁范围。"}}, {"id": "4-4", "type": "single", "stem": "下列纠纷中，属于《劳动争议调解仲裁法》受案范围的是（ ）。", "options": {"A": "用人单位与劳动者因工伤医疗费发生的争议", "B": "劳动者与社会保险经办机构因发放社会保险金发生的争议", "C": "农村承包经营户与受雇人之间的纠纷", "D": "劳动者对劳动能力鉴定委员会伤残等级鉴定结论的异议纠纷"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确。用人单位与劳动者因工伤医疗费承担和支付发生的争议，属于因工伤医疗费等产生的劳动争议，可以依法申请劳动仲裁。", "B": "错误。劳动者与社会保险经办机构因社会保险金发放发生的争议，属于社会保险行政管理或者待遇支付争议，不是劳动者与用人单位之间的劳动争议。", "C": "错误。农村承包经营户通常不属于劳动法律规定的用人单位，其与受雇人之间的纠纷一般按照民事雇佣关系处理。", "D": "错误。劳动能力鉴定委员会作出的伤残等级鉴定结论属于专业鉴定结论。劳动者有异议的，应依法申请再次鉴定，而不能将鉴定委员会作为劳动争议相对方申请仲裁。"}}, {"id": "4-5", "type": "single", "stem": "劳动争议仲裁委员会的组成主体是（ ）。", "options": {"A": "劳动行政部门代表、工会代表和企业方面代表", "B": "劳动行政部门代表和企业方面代表", "C": "工会代表和企业方面代表", "D": "劳动行政部门代表和工会代表"}, "answer": "A", "analysis": "根据劳动争议调解仲裁制度，劳动争议仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。因此，", "optionAnalysis": {"A": "完整列明了三方组成主体。", "B": "错误，缺少工会代表。", "C": "错误，缺少劳动行政部门代表。", "D": "错误，缺少企业方面代表。"}}, {"id": "4-6", "type": "single", "stem": "组成劳动人事争议仲裁委员会的各方代表不包括（ ）。", "options": {"A": "工会代表", "B": "企业方代表", "C": "人民法院代表", "D": "劳动行政部门代表"}, "answer": "C", "analysis": "劳动人事争议仲裁委员会实行三方组成机制，其组成主体包括劳动行政部门代表、工会代表和企业方面代表。", "optionAnalysis": {"A": "属于仲裁委员会的组成主体。", "B": "属于仲裁委员会的组成主体。", "C": "不属于。人民法院依法审理劳动争议诉讼案件，但不是劳动人事争议仲裁委员会的组成主体。", "D": "属于仲裁委员会的组成主体。"}}, {"id": "4-7", "type": "single", "stem": "关于劳动人事争议仲裁委员会的说法，错误的是（ ）。", "options": {"A": "委员会之间并不具有行政隶属关系", "B": "委员会由劳动行政部门代表、工会代表和企业方面代表组成", "C": "直辖市可以设立若干个委员会", "D": "委员会按行政区划层层设立"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确。各劳动人事争议仲裁委员会之间相互独立，不具有行政隶属关系。", "B": "正确。仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。", "C": "正确。直辖市、设区的市可以依法设立一个或者若干个劳动争议仲裁委员会。", "D": "错误。劳动争议仲裁委员会并非按照行政区划层层设立，而是根据统筹规划、合理布局和适应实际需要的原则设立。"}}, {"id": "4-8", "type": "single", "stem": "张某2020年1月1日入职，2023年12月31日离职，期间2020年6月份工资有争议，公司一直未支付，如张某主张该月工资申请仲裁，仲裁时效截止时间是（ ）。", "options": {"A": "2024年6月30日", "B": "2024年12月31日", "C": "2021年6月30日", "D": "2020年12月31日"}, "answer": "B", "analysis": "劳动争议申请仲裁的一般时效期间为一年。但是，劳动关系存续期间因拖欠劳动报酬发生争议的，不受一般一年仲裁时效期间的限制；劳动关系终止的，应当自劳动关系终止之日起一年内提出。劳动关系终止日期：2023年12月31日。仲裁时效期间：自劳动关系终止之日起计算一年。仲裁时效截止日期：2023年12月31日＋1年＝2024年12月31日。因此，B项正确。", "optionAnalysis": {"A": "将时效错误地与2020年6月工资所属月份对应；C、D两项均未适用拖欠劳动报酬争议在劳动关系存续期间的特殊时效规则。"}}, {"id": "4-9", "type": "multi", "stem": "关于劳动争议仲裁时效的说法，正确的是（ ）。", "options": {"A": "因不可抗力，当事人不能在法定时效期间申请仲裁的，仲裁时效中止", "B": "劳动争议对方当事人在时效期间内同意履行义务的，仲裁时效中断", "C": "申请劳动争议仲裁的时效期间为一年", "D": "劳动关系存续期间因拖欠劳动报酬发生争议的，应当在劳动关系终止前提出仲裁申请", "E": "仲裁时效期间从当事人申请仲裁之日起计算"}, "answer": "ABC", "analysis": "", "optionAnalysis": {"A": "正确。因不可抗力或者有其他正当理由，当事人不能在规定的仲裁时效期间申请仲裁的，仲裁时效中止；从中止时效的原因消除之日起，仲裁时效期间继续计算。", "B": "正确。对方当事人同意履行义务，是仲裁时效中断的法定事由之一。时效中断后，仲裁时效期间重新计算。", "C": "正确。劳动争议申请仲裁的一般时效期间为一年。", "D": "错误。劳动关系存续期间因拖欠劳动报酬发生争议的，不受一般一年仲裁时效期间的限制，并非必须在劳动关系终止前申请仲裁；劳动关系终止的，应当自劳动关系终止之日起一年内提出。", "E": "错误。仲裁时效期间一般从当事人知道或者应当知道其权利被侵害之日起计算，而不是从申请仲裁之日起计算。"}}, {"id": "4-10", "type": "single", "stem": "关于劳动争议仲裁时效的说法，错误的是（ ）。", "options": {"A": "发生不可抗力导致无法申请仲裁的，仲裁时效中止", "B": "因解除劳动关系产生的争议，用人单位不能证明劳动者收到解除通知书时间的，劳动者主张权利之日即为劳动争议发生之日", "C": "对方当事人同意履行义务的，仲裁时效重新起算", "D": "因拖欠劳动报酬发生的争议不受仲裁时效限制"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确。不可抗力导致当事人不能在法定期间申请仲裁的，构成仲裁时效中止事由。", "B": "正确。因解除或者终止劳动关系产生争议，用人单位不能证明劳动者收到解除或者终止劳动关系书面通知时间的，可以按照劳动者主张权利的日期确定争议发生时间。", "C": "正确。对方当事人同意履行义务属于仲裁时效中断事由，仲裁时效期间从中断时起重新计算。", "D": "表述过于绝对。"}}, {"id": "4-11", "type": "single", "stem": "用人单位拖欠劳动报酬时，劳动者依法申请支付令的对象是（ ）。", "options": {"A": "人民法院", "B": "人民法院或劳动人事争议仲裁委员会", "C": "劳动行政部门", "D": "劳动人事争议仲裁委员会"}, "answer": "A", "analysis": "用人单位拖欠或者未足额支付劳动报酬的，劳动者可以依法向有管辖权的人民法院申请支付令。支付令属于人民法院依照督促程序作出的司法文书。", "optionAnalysis": {"A": "正确，人民法院是支付令的申请和作出机关。", "B": "错误，劳动人事争议仲裁委员会无权作出支付令。", "C": "错误，劳动行政部门可以依法监督检查并责令用人单位支付劳动报酬，但不负责签发支付令。", "D": "错误，劳动人事争议仲裁委员会负责处理劳动争议仲裁案件，不是支付令的作出机关。"}}, {"id": "4-12", "type": "multi", "stem": "关于劳动争议仲裁的说法，正确的是（ ）。", "options": {"A": "仲裁委员会按行政区层层设立", "B": "仲裁委员会由劳动行政部门代表、工会代表以及用人单位代表组成", "C": "劳动争议仲裁实行地域管辖", "D": "劳动争议仲裁审理期限最长不超过60日", "E": "劳动争议仲裁可以按规定收取仲裁费"}, "answer": "BCD", "analysis": "B项中的“用人单位代表”在本题语境下对应企业方面代表。", "optionAnalysis": {"A": "错误。劳动争议仲裁委员会不是按照行政区划层层设立，而是根据统筹规划、合理布局和适应实际需要的原则设立。", "B": "正确。仲裁委员会由劳动行政部门代表、工会代表和企业方面代表组成。题目所称“用人单位代表”应理解为企业方面代表。", "C": "正确。劳动争议由劳动合同履行地或者用人单位所在地的劳动争议仲裁委员会管辖，体现了地域管辖原则。双方分别申请的，由劳动合同履行地仲裁委员会管辖。", "D": "正确。仲裁庭一般应自受理仲裁申请之日起45日内结束案件；案情复杂需要延期的，经批准可以延长，但延长期限不得超过15日。因此，通常最长为45日＋15日＝60日。", "E": "错误。劳动争议仲裁不收费，劳动争议仲裁委员会的经费由财政予以保障。"}}, {"id": "4-13", "type": "multi", "stem": "用人单位与劳动者发生争议，用人单位应提供（ ）。", "options": {"A": "社会保险缴纳情况", "B": "是否存在劳动关系", "C": "劳动保护提供情况", "D": "劳动者档案", "E": "工资发放表"}, "answer": "ACDE", "analysis": "劳动争议处理一般适用“谁主张、谁举证”原则，但与争议事项有关且由用人单位掌握管理的证据，应当由用人单位提供；用人单位不提供的，应当承担不利后果。", "optionAnalysis": {"A": "正确。社会保险登记、申报和缴费记录通常由用人单位掌握，用人单位应当提供。", "B": "错误。是否存在劳动关系属于需要根据用工事实和有关证据综合认定的法律问题。劳动者主张存在劳动关系时，一般应先就实际用工等基本事实承担初步举证责任，不能笼统认为全部由用人单位证明。", "C": "正确。劳动保护用品发放、安全教育以及劳动条件保障等记录一般由用人单位制作和管理，应由用人单位提供。", "D": "正确。依法由用人单位建立、保管的劳动者档案属于用人单位掌握管理的证据，应由用人单位提供。", "E": "正确。工资表、工资发放记录以及工资支付凭证通常由用人单位制作和保管，应由用人单位提供。"}}, {"id": "4-14", "type": "multi", "stem": "关于劳动争议当事人举证责任的说法，正确的有（ ）。", "options": {"A": "实行“谁主张、谁举证”的原则", "B": "实行“谁作决定、谁举证”的原则", "C": "劳动者应当对工资支付情况进行举证", "D": "用人单位应当对社会保险费缴费情况进行举证", "E": "在法律没有具体规定举证责任的情形下，仲裁庭可以根据公平原则和诚信原则，综合当事人举证能力等因素将举证责任分配给劳动者"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确。劳动争议举证首先适用“谁主张、谁举证”的一般原则，当事人对自己提出的主张有责任提供证据。", "B": "正确。因用人单位作出的开除、除名、辞退、解除劳动合同、减少劳动报酬或者计算劳动者工作年限等决定发生争议的，相关决定及其依据由用人单位掌握，通常由用人单位承担举证责任，即体现“谁作决定、谁举证”。", "C": "错误。工资支付记录通常由用人单位制作、保管并掌握，用人单位应对工资支付情况承担相应举证责任。劳动者仍应对其主张的基本事实提供力所能及的初步证据，但不能将完整工资支付记录的举证责任全部转由劳动者承担。", "D": "正确。社会保险费申报、缴纳等资料由用人单位掌握，用人单位应当就社会保险费缴费情况提供证据。", "E": "正确。在法律、法规没有明确规定且依现有规则无法确定举证责任承担时，仲裁庭可以根据公平原则、诚实信用原则，并综合考虑当事人的举证能力、证据控制情况等因素合理分配举证责任。题目表述为“可以……分配给劳动者”，并非规定必须由劳动者承担，因而正确。"}}, {"id": "4-15", "type": "multi", "stem": "人民法院应当按照劳动关系处理的争议包括（ ）。", "options": {"A": "企业停薪留职人员与新的用人单位因工资报酬发生的争议", "B": "劳动者与用人单位因经济补偿发生的争议", "C": "下岗待岗人员与新的用人单位因休息休假发生的争议", "D": "企业员工之间因个人借贷发生的争议", "E": "领取退休金人员与新的用人单位因工资报酬发生的争议"}, "answer": "ABC", "analysis": "", "optionAnalysis": {"A": "正确。企业停薪留职人员与新的用人单位建立实际用工关系并发生工资报酬争议的，人民法院可以按照劳动关系处理。", "B": "正确。经济补偿是劳动合同解除、终止等制度中的劳动法责任，劳动者与用人单位因此发生的争议属于劳动争议，应按照劳动关系处理。", "C": "正确。下岗待岗人员与新的用人单位建立实际用工关系，因休息休假等劳动权利发生的争议，可以按照劳动关系处理。", "D": "错误。企业员工之间因个人借贷发生的争议，属于平等民事主体之间的民间借贷纠纷，与劳动关系的建立、履行、变更、解除或者终止无关，应按照民事关系处理。", "E": "错误。已经依法享受养老保险待遇或者领取退休金的人员与新的用人单位发生用工争议，通常按照劳务关系处理，而不是按照劳动关系处理。"}}, {"id": "4-16", "type": "single", "stem": "关于劳动争议诉讼当事人的说法，正确的是（ ）。", "options": {"A": "当事人双方对不服劳动争议仲裁委员会作出的同一裁决，向同一人民法院起诉，双方当事人为原告，劳动争议仲裁委员会为被告", "B": "用人单位以挂靠方式借用他人营业执照经营，用人单位和营业执照出借方为当事人", "C": "劳动者与其有字号的个体工商户产生的劳动争议诉讼，应当以业主为当事人", "D": "用人单位招用尚未解除合同的劳动者，原用人单位以新的用人单位侵权为由向人民法院起诉，新的用人单位和劳动者为共同被告第五章法律责任与行政执法"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误。劳动争议仲裁委员会是依法处理劳动争议的仲裁机构，不是劳动争议诉讼的被告。劳动者和用人单位均不服同一仲裁裁决并向同一人民法院起诉的，人民法院依法并案审理，双方互为原告和被告，而不是以仲裁委员会为被告。", "B": "正确。用人单位以挂靠等方式借用他人营业执照经营并与劳动者发生劳动争议的，实际用工主体和营业执照出借方均可能作为诉讼当事人，以保障劳动者权利并查明实际用工责任。", "C": "错误。有字号的个体工商户应当以营业执照上登记的字号为诉讼当事人，并注明经营者的基本信息，不能仅以业主个人作为当事人。", "D": "错误。用人单位招用尚未解除劳动合同的劳动者，给原用人单位造成经济损失的，新用人单位依法承担相应责任；劳动者是否作为共同被告，应根据原用人单位的具体诉讼请求和责任基础判断，不能一概表述为新的用人单位和劳动者必须作为共同被告。"}}]}, {"id": 5, "title": "法律责任与行政执法", "questions": [{"id": "5-1", "type": "single", "stem": "某企业因违法解除劳动合同应向劳动者支付赔偿金，计算赔偿金年限的起算点是（ ）。", "options": {"A": "签订劳动合同之日", "B": "用工之日起满一个月之后", "C": "解除劳动关系之日", "D": "用工之日"}, "answer": "D", "analysis": "依据《劳动合同法》，用人单位自用工之日起即与劳动者建立劳动关系。用人单位违法解除或者终止劳动合同时，赔偿金按照经济补偿标准的二倍计算；经济补偿所涉及的工作年限，应当按照劳动者在本单位工作的年限确定。因此，计算赔偿金年限应当从实际用工之日起计算。", "optionAnalysis": {"A": "错误：劳动关系建立的时间以实际用工之日为准，不以书面劳动合同的签订日期为准。劳动合同可能在用工前签订，也可能在用工后补签。", "B": "错误：用工之日起满一个月是用人单位未依法订立书面劳动合同可能承担相应责任的时间节点，不是赔偿金工作年限的起算点。", "C": "错误：解除劳动关系之日通常是工作年限计算的截止时间，而不是起算时间。", "D": "正确：实际用工之日是劳动关系建立之日，也是计算劳动者在本单位工作年限的起算点。"}}, {"id": "5-2", "type": "single", "stem": "企业未按时足额代扣代缴社会保险费的，应自欠缴之日起缴纳滞纳金，是（ ）。", "options": {"A": "按日加收万分之二", "B": "按日加收万分之三", "C": "按日加收万分之五", "D": "按日加收万分之四"}, "answer": "C", "analysis": "依据《社会保险法》，用人单位未按时足额缴纳社会保险费的，由社会保险费征收机构责令其限期缴纳或者补足，并自欠缴之日起按日加收万分之五的滞纳金；逾期仍不缴纳的，由有关行政部门处欠缴数额一倍以上三倍以下的罚款。滞纳金的一般计算方式为：滞纳金＝欠缴的社会保险费金额×万分之五×欠缴天数。例如，企业欠缴社会保险费100000元，欠缴30日，则应缴滞纳金为：100000×0.05%×30＝1500元。", "optionAnalysis": {"A": "错误：每日万分之二不是《社会保险法》规定的社会保险费滞纳金标准。", "B": "错误：每日万分之三不符合规定。", "C": "正确：法定标准为自欠缴之日起按日加收万分之五。", "D": "错误：每日万分之四不符合规定。"}}, {"id": "5-3", "type": "single", "stem": "关于劳动者应当承担的违反劳动法律责任的说法，正确的是（ ）。", "options": {"A": "劳动者违法解除劳动合同，无须承担法律责任", "B": "劳动者违反劳动合同中约定的保密义务，应当承担赔偿责任", "C": "劳动者解除约定有服务期的劳动合同，应当向用人单位支付赔偿金", "D": "劳动者违反劳动合同中有关竞业限制的约定，且给用人单位造成了损失，应当承担赔偿责任"}, "answer": "D", "analysis": "依据《劳动合同法》，劳动者违反法律规定解除劳动合同，或者违反劳动合同中约定的保密义务、竞业限制，给用人单位造成损失的，应当承担赔偿责任。承担赔偿责任通常以存在违法或者违约行为、用人单位实际发生损失以及行为与损失之间存在因果关系为条件。", "optionAnalysis": {"A": "错误：劳动者违反《劳动合同法》的规定解除劳动合同，并给用人单位造成损失的，应当承担赔偿责任，并非一律无须承担法律责任。", "B": "错误：仅表述“违反保密义务”尚不完整。劳动者违反保密义务并给用人单位造成损失的，才应依法承担相应赔偿责任。", "C": "错误：劳动者违反服务期约定时，依法承担的通常是违约金责任，而不是笼统表述为赔偿金。违约金的数额不得超过用人单位提供的培训费用，用人单位要求支付的违约金也不得超过服务期尚未履行部分所应分摊的培训费用。", "D": "正确：劳动者违反竞业限制约定并给用人单位造成损失的，应当依法承担赔偿责任。"}}, {"id": "5-4", "type": "multi", "stem": "劳动者（ ），给用人单位造成损失，应当承担赔偿责任。", "options": {"A": "不同意订立无固定期限劳动合同", "B": "虽提前30日通知用人单位解除劳动合同，但劳动合同尚有3年期限未履行", "C": "违反《劳动合同法》的规定解除劳动合同", "D": "违反劳动合同约定的保密义务", "E": "违反劳动合同约定的竞业限制"}, "answer": "CDE", "analysis": "依据《劳动合同法》，劳动者违反法律规定解除劳动合同，或者违反劳动合同中约定的保密义务、竞业限制，给用人单位造成损失的，应当承担赔偿责任。本题题干已经将“给用人单位造成损失”作为共同条件。", "optionAnalysis": {"A": "错误：劳动者不同意订立无固定期限劳动合同，本身不属于依法应当向用人单位承担赔偿责任的违法或者违约行为。是否订立无固定期限劳动合同，应当根据法定条件及双方依法协商的情况判断。", "B": "错误：劳动者依法提前30日以书面形式通知用人单位，可以解除劳动合同。劳动合同尚有未履行期限，不影响劳动者依法行使预告解除权，劳动者一般不因剩余期限未履行而承担赔偿责任。", "C": "正确：劳动者违反《劳动合同法》的规定解除劳动合同，并给用人单位造成损失的，应当承担赔偿责任。", "D": "正确：劳动者违反劳动合同约定的保密义务并造成损失的，应当承担赔偿责任。", "E": "正确：劳动者违反竞业限制约定并造成损失的，应当承担赔偿责任。"}}, {"id": "5-5", "type": "single", "stem": "在实施劳动监察时，劳动保障行政部门无权采取的措施是（ ）。", "options": {"A": "限制用人单位责任人员离开本地区", "B": "吊销许可证", "C": "没收违法所得", "D": "罚款"}, "answer": "A", "analysis": "劳动保障行政部门实施劳动保障监察时，可以依法进入用人单位工作场所检查，询问有关人员，要求提供相关材料，并可以对违法行为依法作出责令改正、罚款、没收违法所得等处理或者处罚。对依法应当由其他主管机关吊销许可证的，可以按照法定权限处理或者提请有权机关处理。但是，劳动保障行政部门无权通过限制责任人员离开本地区的方式实施劳动监察。", "optionAnalysis": {"A": "正确：限制人员离开本地区属于对人身自由或者行动自由的限制，必须具有明确的法律授权。劳动保障行政部门实施劳动监察时没有该项权力。", "B": "错误：对符合法定情形的违法行为，可以依法吊销由本部门颁发的许可证；不属于本部门权限的，可以建议有权机关依法处理。因此该项并非题目所指的绝对无权措施。", "C": "错误：法律、行政法规规定应当没收违法所得的，劳动保障行政部门可以依法作出没收违法所得的行政处罚。", "D": "错误：对用人单位的特定劳动保障违法行为，劳动保障行政部门有权依法作出罚款决定。"}}, {"id": "5-6", "type": "single", "stem": "关于劳动保障监察中调查期限的说法正确的是（ ）。", "options": {"A": "自立案之日起90个工作日内完成，情况复杂的，可以延长15个工作日", "B": "自立案之日起90个工作日内完成，情况复杂的，可以延长30个工作日", "C": "自立案之日起60个工作日内完成，情况复杂的，可以延长30个工作日", "D": "自立案之日起60个工作日内完成，情况复杂的，可以延长15个工作日"}, "answer": "C", "analysis": "依据《劳动保障监察条例》，劳动保障行政部门对违反劳动保障法律、法规或者规章行为的调查，应当自立案之日起60个工作日内完成；对情况复杂的，经劳动保障行政部门负责人批准，可以延长30个工作日。", "optionAnalysis": {"A": "错误：一般调查期限不是90个工作日，延长期限也不是15个工作日。", "B": "错误：延长30个工作日的表述正确，但一般调查期限错误，应为60个工作日。", "C": "正确：一般期限为自立案之日起60个工作日；情况复杂的，经批准可以延长30个工作日。", "D": "错误：一般期限60个工作日的表述正确，但延长期限错误，应为30个工作日。"}}, {"id": "5-7", "type": "multi", "stem": "关于劳动监察的说法，正确的有（ ）。", "options": {"A": "劳动行政部门无权对被依法吊销营业执照的单位实施劳动监察", "B": "劳动行政部门有权做出罚款决定", "C": "在紧急情况下，劳动行政部门可限制用人单位部分管理人员进出工作场所", "D": "劳动行政部门可以对职业培训机构实施劳动监察", "E": "劳动行政部门有权到用人单位工作场所进行检查"}, "answer": "BDE", "analysis": "劳动保障监察是劳动保障行政部门依法对用人单位及相关机构遵守劳动保障法律、法规和规章的情况进行监督检查，并对违法行为予以处理的行政执法活动。监察对象除一般用人单位外，还包括职业介绍机构、职业技能培训机构和职业技能考核鉴定机构等。", "optionAnalysis": {"A": "错误：单位被吊销营业执照，并不当然消灭其对吊销前劳动保障违法行为应承担的责任。劳动保障行政部门仍可依法对有关违法事实进行调查处理，不能据此认定其绝对无权实施劳动监察。", "B": "正确：对法律、法规规定应予罚款的劳动保障违法行为，劳动保障行政部门有权依法作出罚款决定。", "C": "错误：劳动保障行政部门有权进入工作场所检查，但无权限制用人单位管理人员进出工作场所。限制人员行动必须具有明确的法律依据，不能以情况紧急为由自行采取。", "D": "正确：职业技能培训机构遵守国家有关职业技能培训规定的情况，属于劳动保障监察的范围。", "E": "正确：劳动保障行政部门有权进入用人单位的劳动场所进行检查，并可依法询问有关人员、查阅或者复制有关资料。"}}, {"id": "5-8", "type": "multi", "stem": "下列事项中，不能申请行政复议的事项有（ ）。", "options": {"A": "劳动争议仲裁裁决", "B": "工伤认定结论", "C": "工伤保险待遇审核决定", "D": "劳动能力鉴定结论", "E": "行政处分"}, "answer": "ADE", "analysis": "行政复议主要审查行政机关作出的行政行为。劳动争议仲裁裁决、劳动能力鉴定结论和行政机关内部作出的行政处分，分别适用其他法定救济途径，不属于通常可以申请行政复议的事项。", "optionAnalysis": {"A": "正确：劳动争议仲裁裁决是劳动人事争议仲裁机构对劳动争议作出的裁决，不属于行政机关作出的行政行为。当事人不服的，应当依照劳动争议处理程序向人民法院提起诉讼；法律规定为终局裁决的，适用相应的特殊救济规定。", "B": "错误：工伤认定是社会保险行政部门作出的行政行为。有关单位或者个人对工伤认定决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。", "C": "错误：社会保险经办机构作出的工伤保险待遇审核决定影响参保主体的社会保险权益，相关当事人不服的，可以依法申请行政复议。", "D": "正确：劳动能力鉴定委员会作出的劳动能力鉴定结论属于专业技术鉴定结论，不属于行政复议审查的行政行为。当事人对初次鉴定结论不服的，应当在法定期限内向上一级劳动能力鉴定委员会申请再次鉴定。", "E": "正确：行政机关作出的行政处分属于内部人事管理行为，通常不能申请行政复议。受到处分的人员应当依法通过复核、申诉等途径寻求救济。"}}, {"id": "5-9", "type": "single", "stem": "用人单位可以依法申请行政复议的情形包括（ ）。", "options": {"A": "对劳动能力鉴定委员会做出的鉴定结论不服的", "B": "对社会保险经办机构确定的单位工伤保险费率不服的", "C": "对劳动人事争议仲裁委员会作出的裁决不服的", "D": "对人社部门作出的行政处分不服的第六章人才管理与开发政策"}, "answer": "B", "analysis": "用人单位认为社会保险经办机构确定的缴费基数、费率或者相关社会保险待遇审核决定侵犯其合法权益的，可以依法申请行政复议。不同性质的争议应当适用不同的救济程序，不能一律通过行政复议解决。", "optionAnalysis": {"A": "错误：劳动能力鉴定结论属于专业技术鉴定结论，不属于行政复议的审查对象。对初次鉴定结论不服的，应当在法定期限内向上一级劳动能力鉴定委员会申请再次鉴定。", "B": "正确：社会保险经办机构确定单位工伤保险费率的行为直接影响用人单位的缴费义务。用人单位对此不服的，可以依法申请行政复议。", "C": "错误：劳动人事争议仲裁委员会作出的仲裁裁决不属于行政行为，不能申请行政复议。用人单位不服非终局仲裁裁决的，可以依法向人民法院提起诉讼；对终局裁决有法定撤销事由的，可以依法申请撤销。", "D": "错误：行政处分属于行政机关内部人事管理行为，不属于行政复议受理范围，应当依法通过复核、申诉等内部救济程序处理。"}}]}, {"id": 6, "title": "人才管理与开发政策", "questions": [{"id": "6-1", "type": "single", "stem": "职称评审委员会按照（ ）组建。", "options": {"A": "行业", "B": "地区", "C": "职称系列或者专业", "D": "职业"}, "answer": "C", "analysis": "职称评审委员会应当按照职称系列或者专业组建，负责相应系列或者专业的职称评审工作。", "optionAnalysis": {"A": "错误：行业可以作为职称评审工作组织和管理的相关维度，但不是职称评审委员会的法定组建口径。", "B": "错误：地区可以设立职称评审机构，但评审委员会本身不是简单按照地区组建。", "C": "正确：职称评审委员会按照职称系列或者专业组建。", "D": "错误：职业与职称系列、专业并非同一概念，不是该委员会的法定组建口径。"}}, {"id": "6-2", "type": "multi", "stem": "下列关于职称审核的说法，正确的有（ ）。", "options": {"A": "针对海外高层次人才可以合理放宽资历、年限等条件限制", "B": "退休两年内的专业技术人才可以申报职称", "C": "长期在基层一线的专业技术人才，侧重考查其实际工作业绩，适当放宽学历要求", "D": "受处分期间的专业技术人员可以申报职称", "E": "具有重大技术研究突破的专业技术人才，可以直接申报高级职称"}, "answer": "ACE", "analysis": "职称评价强调破除唯学历、唯资历、唯年限等倾向，并对特殊人才建立相应的评价通道。", "optionAnalysis": {"A": "正确：对海外高层次人才和急需紧缺人才，可以合理放宽资历、年限等条件限制，不简单以常规资历条件进行评价。", "B": "错误：离退休人员原则上不得申报参加职称评审，并不存在“退休两年内可以申报”的一般规定。", "C": "正确：对长期在艰苦边远地区和基层一线工作的专业技术人才，职称评价应侧重实际工作业绩，并可以适当放宽学历、任职年限等要求。", "D": "错误：专业技术人员在受到有关处分的期间，通常不得申报参加职称评审。", "E": "正确：对取得重大基础研究和前沿技术突破、解决重大工程技术难题或者在经济社会事业发展中作出重大贡献的专业技术人才，可以通过特殊评价方式直接申报高级职称。"}}, {"id": "6-3", "type": "multi", "stem": "关于职称评审的说法，正确的有（ ）。", "options": {"A": "事业单位工作人员受记过以上处分的，在受处分期间不得申报参加职称评审", "B": "职称评审结果是专业技术人员聘用、考核、晋升等的重要依据", "C": "申报人不可以跨级申报参加职称评审", "D": "职称评审标准分为国家标准和单位标准", "E": "离退休人员可以申报参加职称评审"}, "answer": "AB", "analysis": "", "optionAnalysis": {"A": "正确：事业单位工作人员受到记过以上处分的，在受处分期间不得申报参加职称评审。", "B": "正确：职称评审结果是专业技术人才聘用、考核、晋升等工作的重要依据。", "C": "错误：一般情况下应当逐级申报，但对取得重大成果、作出突出贡献的专业技术人才，可以建立职称评审绿色通道，符合条件的可以突破常规限制申报，因此不能绝对表述为不可以跨级申报。", "D": "错误：职称评审标准通常包括国家标准、地区标准和单位标准，不仅包括国家标准和单位标准。", "E": "错误：离退休人员原则上不得申报参加职称评审。"}}, {"id": "6-4", "type": "single", "stem": "关于某大学毕业生应聘某岗位，关于其职业发展的说法，正确的是（ ）。", "options": {"A": "该岗位的最高职业技能等级是特级技师", "B": "该岗位的最高职业技能等级是首席技师", "C": "该岗位的最高职业技能等级是高级工", "D": "该岗位的最高职业技能等级是高级技师"}, "answer": "B", "analysis": "我国技能人才职业技能等级制度在原有五级技能等级的基础上，向下增设学徒工，向上增设特级技师和首席技师，形成由学徒工至首席技师的职业技能等级序列，其中首席技师属于最高职业技能等级。", "optionAnalysis": {"A": "错误：特级技师的等级低于首席技师。", "B": "正确：首席技师是现行职业技能等级序列中的最高等级。", "C": "错误：高级工属于三级职业技能等级，并非最高等级。", "D": "错误：高级技师属于一级职业技能等级，但在其上还设有特级技师和首席技师。"}}, {"id": "6-5", "type": "single", "stem": "某单位是国家设立的研究机构，关于该单位科技成果转化的说法，正确的是（ ）。", "options": {"A": "该单位科技成果转化的收入可以全部留归单位，纳入单位预算", "B": "该单位持有的所有科技成果，都可以自主决定转让，无需审批备案", "C": "该单位科研人员获得的科技成果转化现金奖励，要受绩效工资总量的限制", "D": "该单位可以提取科技成果转化净收入中的50%，用于奖励科技成果主要完成人"}, "answer": "A", "analysis": "国家设立的研究开发机构、高等院校取得的科技成果转化收入，原则上全部留归本单位，纳入单位预算，实行统一管理。", "optionAnalysis": {"A": "正确：科技成果转化收入可以全部留归单位，并纳入单位预算管理，不上缴国库。", "B": "错误：单位通常可以依法自主决定转让、许可或者作价投资，但涉及国家秘密、国家安全以及法律法规另有规定的科技成果，仍应按照有关规定办理，不能表述为所有成果均无需审批备案。", "C": "错误：依法给予科技人员的科技成果转化现金奖励，应当按照国家有关规定处理，通常不受本单位绩效工资总量限制，不纳入绩效工资总量基数。", "D": "错误：奖励比例应结合成果转化方式适用相应规则。通过转让、许可取得的净收入以及作价投资取得股份或者出资比例的奖励，通常强调不低于规定比例；自行实施或者与他人合作实施的奖励规则也不同。题干笼统表述为统一提取净收入的50%，不够准确。"}}, {"id": "6-6", "type": "single", "stem": "下列措施中，不利于科技人员开展创新活动的是（ ）。", "options": {"A": "简化科研项目资金的预算编制科目", "B": "建立学术助理制度", "C": "进一步提高财政项目中直接费用的比例", "D": "将项目聘用人员的社会保险补助纳入劳务费科目列支"}, "answer": "C", "analysis": "科研经费管理改革强调扩大科研项目经费管理自主权、简化预算编制，并合理提高间接费用比例，以补偿单位为科研活动提供的管理和资源支撑成本。", "optionAnalysis": {"A": "有利：简化预算编制科目能够减少科研人员事务性负担，提高经费使用效率。", "B": "有利：建立科研财务助理、学术助理等制度，可以减少科研人员承担的事务性工作，使其将更多精力用于科研创新。", "C": "不利：政策改革方向通常是合理提高间接费用比例，而不是进一步提高直接费用比例。提高间接费用比例有助于弥补科研单位的管理成本并体现科研人员的创新价值。", "D": "有利：将项目聘用人员的社会保险补助等纳入劳务费科目列支，有利于保障项目聘用人员权益并提高科研项目用工的灵活性。"}}, {"id": "6-7", "type": "single", "stem": "事业单位绩效工资的组成（ ）。", "options": {"A": "基础性绩效工资和奖励性绩效工资", "B": "基础性绩效工资和核心能力绩效工资", "C": "岗位性绩效和奖励性绩效工资", "D": "岗位性绩效和核心能力绩效工资"}, "answer": "A", "analysis": "事业单位绩效工资一般分为基础性绩效工资和奖励性绩效工资两部分。", "optionAnalysis": {"A": "正确：基础性绩效工资主要体现地区经济发展、物价水平、岗位职责等因素；奖励性绩效工资主要体现工作量和实际贡献等因素。", "B": "错误：“核心能力绩效工资”不是事业单位绩效工资的法定组成部分。", "C": "错误：“岗位性绩效”不是规范的组成名称。", "D": "错误：“岗位性绩效”和“核心能力绩效工资”均不属于规定的组成名称。"}}, {"id": "6-8", "type": "single", "stem": "事业单位的岗位分为（ ）。", "options": {"A": "管理岗位和专业技术岗位", "B": "管理岗位、专业技术岗位和特设岗位", "C": "管理岗位、专业技术岗位和工勤技能岗位", "D": "专业技术岗位和工勤技能岗位"}, "answer": "C", "analysis": "事业单位岗位分为管理岗位、专业技术岗位和工勤技能岗位三种类别。", "optionAnalysis": {"A": "错误：遗漏了工勤技能岗位。", "B": "错误：特设岗位是事业单位根据事业发展需要，经批准设置的非常设岗位，不属于与三类基本岗位并列的岗位类别。", "C": "正确：完整列明了事业单位的三类基本岗位。", "D": "错误：遗漏了管理岗位。"}}, {"id": "6-9", "type": "multi", "stem": "关于事业单位岗位设置的说法，正确的有（ ）。", "options": {"A": "管理岗位是担负领导职责或管理任务的工作岗位", "B": "事业单位可以设置特设岗位，用于聘用急需的高层次人才", "C": "对专业技术岗位实行最高岗位等级控制和结构比例控制", "D": "事业单位岗位分为管理岗位、专业技术岗位、工勤技能岗位三类", "E": "工勤技能岗位没有最高岗位等级控制和结构比例控制"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确：管理岗位是指担负领导职责或者管理任务的工作岗位。", "B": "正确：特设岗位是事业单位根据事业发展聘用急需的高层次人才等特殊需要，经批准设置的非常设岗位。", "C": "正确：专业技术岗位的设置实行最高岗位等级和结构比例控制。", "D": "正确：事业单位岗位包括管理岗位、专业技术岗位和工勤技能岗位三类。", "E": "错误：工勤技能岗位同样实行最高岗位等级和结构比例控制，并非没有相应控制。"}}, {"id": "6-10", "type": "multi", "stem": "关于事业单位工作人员处分的期限，正确的有（ ）。", "options": {"A": "记过处分的期限是12个月", "B": "撤职处分的期限是24个月", "C": "记大过处分的期限是18个月", "D": "降低岗位等级处分的期限是24个月", "E": "警告处分的期限是6个月"}, "answer": "ADE", "analysis": "事业单位工作人员处分的种类及期限应按照事业单位工作人员处分制度确定。", "optionAnalysis": {"A": "正确：记过处分的期限为12个月。", "B": "错误：事业单位工作人员处分种类中使用的是“降低岗位等级”，而不是将“撤职”作为此处对应的独立处分种类。", "C": "错误：事业单位工作人员处分种类中没有“记大过”这一档处分，因此不存在题述18个月的处分期限。", "D": "正确：降低岗位等级处分的期限为24个月。", "E": "正确：警告处分的期限为6个月。开除属于解除人事关系的处分，不设置处分期限。"}}, {"id": "6-11", "type": "single", "stem": "关于事业单位聘用合同的说法，正确的是（ ）。", "options": {"A": "事业单位与应届本科毕业生签订聘用合同的试用期不得低于6个月", "B": "事业单位工作人员连续旷工14个工作日，事业单位可以解除聘用合同", "C": "事业单位与新聘人员只能签订2年期的聘用合同", "D": "事业单位工作人员年度考核不合格且不同意调整工作岗位，事业单位提前30日书面通知，可以解除聘用合同"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误：事业单位与初次就业的工作人员订立的聘用合同期限在3年以上的，试用期通常为12个月，不能概括为不得低于6个月。", "B": "错误：工作人员连续旷工超过15个工作日，或者1年内累计旷工超过30个工作日的，事业单位可以解除聘用合同。连续旷工14个工作日尚未达到法定条件。", "C": "错误：事业单位聘用合同期限可以根据岗位和工作需要依法约定，并非只能签订2年期合同。", "D": "正确：工作人员年度考核不合格且不同意调整工作岗位，或者连续两年年度考核不合格的，事业单位可以提前30日书面通知其解除聘用合同。"}}, {"id": "6-12", "type": "single", "stem": "关于党政领导干部在企业（社会）团体兼职说法正确的是（ ）。", "options": {"A": "不担任现职的党政领导干部，可以在企业兼职取酬", "B": "经批准到企业兼职的党政领导干部，可以在企业领取报酬", "C": "已退休的党政领导干部，最多可以在1个社会团体兼职", "D": "辞去公职的党政领导干部到企业兼职，无需经过组织人事部门的审批备案"}, "answer": "C", "analysis": "党政领导干部在企业和社会组织兼职，应当遵守从严管理、审批备案以及不得违规取酬等规定。", "optionAnalysis": {"A": "错误：党政领导干部即使不担任现职，也不能据此当然在企业兼职取酬，仍应遵守有关审批和禁止违规取酬规定。", "B": "错误：经批准到企业兼职的党政领导干部不得在企业领取薪酬、奖金、津贴等报酬，也不得获取股权和其他额外利益。", "C": "正确：已退休的党政领导干部在社会团体兼职应当从严掌握，兼职数量原则上不得超过1个。", "D": "错误：辞去公职或者退（离）休的党政领导干部到企业兼职，仍可能受到任职回避、从业限制以及审批备案等规定约束，不能一概认为无需办理相关手续。"}}, {"id": "6-13", "type": "single", "stem": "下列专业技术人员参加的活动中，不可以计入继续教育学时的是（ ）。", "options": {"A": "单位组织的线上培训", "B": "单位组织的学术讲座", "C": "单位组织的科研项目评审会", "D": "行业内组织的技术交流活动"}, "answer": "C", "analysis": "专业技术人员继续教育的形式包括培训班、研修班或者进修班学习，参加远程教育，参加学术会议、学术讲座、学术访问以及有关实践活动等。", "optionAnalysis": {"A": "可以计入：符合要求的线上培训、远程教育属于继续教育形式。", "B": "可以计入：学术讲座属于继续教育的常见形式。", "C": "不可以计入：参加科研项目评审会主要属于履行评审职责，不等同于接受继续教育，通常不能直接计入继续教育学时。", "D": "可以计入：行业技术交流活动具有知识更新和专业能力提升属性，符合规定条件的可以计入继续教育学时。"}}, {"id": "6-14", "type": "single", "stem": "经营性人力资源服务机构承接人力资源外包，应当自开展业务（ ）日内向人力资源社会保障行政部门备案。", "options": {"A": "20", "B": "10", "C": "15", "D": "5"}, "answer": "C", "analysis": "经营性人力资源服务机构开展人力资源服务外包业务，应当自开展业务之日起15日内向住所地人力资源社会保障行政部门备案。", "optionAnalysis": {"A": "错误：20日不符合规定期限。", "B": "错误：10日不符合规定期限。", "C": "正确：规定的备案期限为自开展业务之日起15日内。", "D": "错误：5日不符合规定期限。"}}, {"id": "6-15", "type": "single", "stem": "在中国境内工作、具有博士研究生学历的外籍华人，申请在华永久居留的条件之一是每年实际居住时间不少于（ ）。", "options": {"A": "6个月", "B": "7个月", "C": "1个月", "D": "5个月"}, "answer": "A", "analysis": "符合有关条件、在中国境内工作的外籍华人申请永久居留时，除学历、工作经历和连续工作年限等条件外，还应满足规定的实际居住时间要求，其中每年实际居住时间不少于6个月。", "optionAnalysis": {"A": "正确：每年实际居住时间不少于6个月。", "B": "错误：规定并非7个月。", "C": "错误：1个月明显低于规定的实际居住期限。", "D": "错误：规定期限为6个月，而非5个月。"}}, {"id": "6-16", "type": "multi", "stem": "外籍人员获得中国永久居留资格后，可以享受的权益有（ ）。", "options": {"A": "可以在中国购房、并享受中国公民同等待遇", "B": "可以无限期在中国（境内）居留", "C": "在中国境内工作，可以不办理外国人来华工作许可", "D": "可以在中国境内申请驾照", "E": "在中国境内工作，可以不参加社会保险第七章组织激励理论及其应用"}, "answer": "ABCD", "analysis": "外国人获得中国永久居留资格后，可以凭外国人永久居留身份证在居留、就业、购房、办理机动车驾驶证等方面依法享受相应便利，但仍应履行社会保险等法定义务。", "optionAnalysis": {"A": "正确：永久居留外国人在符合国家有关规定的情况下，可以在中国境内购买自用、自住商品住房，并依法享受相应待遇。", "B": "正确：永久居留资格允许持有人在中国境内永久居留，但仍应遵守中国法律关于证件管理、出入境管理等规定。", "C": "正确：取得永久居留资格的外国人在中国境内工作，可以免办外国人来华工作许可。", "D": "正确：符合规定条件的，可以凭永久居留身份证等有效证件申请机动车驾驶证。", "E": "错误：在中国境内就业的永久居留外国人应当依法参加社会保险，不能因取得永久居留资格而免除参保义务。"}}]}, {"id": 7, "title": "组织激励理论及其应用", "questions": [{"id": "7-1", "type": "single", "stem": "按照组织行为学有关理论，内源性动机包括（ ）。", "options": {"A": "社会地位", "B": "挑战性工作", "C": "工资", "D": "表扬"}, "answer": "B", "analysis": "内源性动机是指由工作本身所产生的动机，员工从工作内容、完成过程或个人成长中获得满足。", "optionAnalysis": {"A": "错误，社会地位属于由工作之外的社会评价带来的外在结果。", "B": "正确，挑战性工作能够使员工从克服困难、发挥能力的过程中获得内在满足。", "C": "错误，工资是组织给予员工的外部物质报酬，属于外源性动机。", "D": "错误，表扬来自他人的评价和认可，也属于外源性动机。"}}, {"id": "7-2", "type": "single", "stem": "外源性动机包括（ ）。", "options": {"A": "让人觉得发挥自己潜能", "B": "让人觉得自己有成就感", "C": "让人得到较多奖金", "D": "让人觉得自己工作有意义"}, "answer": "C", "analysis": "外源性动机是由工作行为所带来的外部结果引起的动机，如工资、奖金、福利、晋升和表扬等。", "optionAnalysis": {"A": "错误，发挥个人潜能体现工作本身带来的成长和自我实现，属于内源性动机。", "B": "错误，成就感是员工完成工作后形成的内在心理满足。", "C": "正确，奖金是组织提供的外部物质报酬，属于典型的外源性动机。", "D": "错误，感受到工作有意义是由工作内容本身产生的内在满足。"}}, {"id": "7-3", "type": "single", "stem": "从激励对象的角度，激励可分为（ ）。", "options": {"A": "内在激励和外在激励", "B": "物质激励和精神激励", "C": "正向激励和负向激励", "D": "他人激励和自我激励"}, "answer": "D", "analysis": "从激励对象或激励主体作用于谁的角度，可以将激励分为他人激励和自我激励。", "optionAnalysis": {"A": "错误，内在激励和外在激励主要体现激励动力的来源。", "B": "错误，物质激励和精神激励是按照激励内容或手段进行的划分。", "C": "错误，正向激励和负向激励是从激励所起作用及行为导向角度进行的划分。", "D": "正确，他人激励是由外部主体施加的激励，自我激励则是个体主动调动自身积极性的过程。"}}, {"id": "7-4", "type": "single", "stem": "激励从所起作用的角度可划分为（ ）。", "options": {"A": "内在激励和外在激励", "B": "物质激励和精神激励", "C": "正向激励和负向激励", "D": "他人激励和自我激励"}, "answer": "C", "analysis": "从激励所起作用的角度，可以划分为正向激励和负向激励。", "optionAnalysis": {"A": "错误，内在激励和外在激励强调动机或激励力量的来源。", "B": "错误，物质激励和精神激励强调激励所采用的内容和方式。", "C": "正确，正向激励通过奖励、认可等方式强化组织期望的行为，负向激励通过批评、惩戒等方式抑制不符合要求的行为。", "D": "错误，他人激励和自我激励是从激励对象或主体关系角度划分的。"}}, {"id": "7-5", "type": "single", "stem": "按照马斯洛需要层次理论，自我实现的需要不包括（ ）。", "options": {"A": "个人充分成长的需要", "B": "发挥个人潜能的需要", "C": "自尊心得到满足的需要", "D": "实现个人理想的需要"}, "answer": "C", "analysis": "自我实现需要是个体追求充分发挥潜能、实现理想并不断成长的需要。", "optionAnalysis": {"A": "属于自我实现需要，体现个体追求充分发展。", "B": "属于自我实现需要，强调发挥个人潜能。", "C": "不属于自我实现需要，自尊心得到满足属于尊重需要，包括自尊以及获得他人尊重。", "D": "属于自我实现需要，体现个体希望实现自身理想和价值。"}}, {"id": "7-6", "type": "single", "stem": "按照马斯洛需要层次理论，尊重的需要包括（ ）。", "options": {"A": "实现个人理想", "B": "自尊心得到满足", "C": "个人充分成长", "D": "发挥个人潜能"}, "answer": "B", "analysis": "尊重需要包括自尊、自主、成就感以及获得他人的认可、地位和尊重。", "optionAnalysis": {"A": "错误，实现个人理想主要属于自我实现需要。", "B": "正确，自尊心得到满足是尊重需要的直接表现。", "C": "错误，个人充分成长属于自我实现需要。", "D": "错误，发挥个人潜能同样属于自我实现需要。"}}, {"id": "7-7", "type": "single", "stem": "根据马斯洛需要层次理论认为，属于高级需要的是（ ）。", "options": {"A": "食物和水", "B": "人际关系", "C": "归属感", "D": "成就感"}, "answer": "D", "analysis": "在马斯洛需要层次理论中，生理需要、安全需要和归属与爱的需要通常被归为较低层次需要，尊重需要和自我实现需要属于较高层次需要。", "optionAnalysis": {"A": "错误，食物和水属于生理需要。", "B": "错误，人际关系主要对应归属与爱的需要。", "C": "错误，归属感属于归属与爱的需要。", "D": "正确，成就感通常属于尊重需要的内容，是较高层次需要。"}}, {"id": "7-8", "type": "single", "stem": "根据双因素理论，激励因素包括（ ）", "options": {"A": "工作性质", "B": "人际关系", "C": "监督方式", "D": "组织政策"}, "answer": "A", "analysis": "赫茨伯格的双因素理论将影响员工工作态度的因素分为激励因素和保健因素。", "optionAnalysis": {"A": "正确，工作性质或工作本身能够带来成就感、责任感和成长机会，属于激励因素。", "B": "错误，人际关系属于工作环境方面的保健因素。", "C": "错误，监督方式属于保健因素。", "D": "错误，组织政策和管理制度属于保健因素。"}}, {"id": "7-9", "type": "single", "stem": "下列属于双因素理论中保健因素的是（ ）。", "options": {"A": "工作环境", "B": "别人的认可", "C": "晋升", "D": "成就感"}, "answer": "A", "analysis": "保健因素主要与工作条件和工作环境有关，其具备可以减少员工不满，但不一定能使员工产生满意。", "optionAnalysis": {"A": "正确，工作环境属于典型的保健因素。", "B": "错误，获得他人的认可属于激励因素。", "C": "错误，晋升能够带来成长和发展，属于激励因素。", "D": "错误，成就感来自工作本身及工作成果，属于激励因素。"}}, {"id": "7-10", "type": "single", "stem": "根据赫茨伯格的双因素理论，激励因素的缺失会导致员工（ ）。", "options": {"A": "满意", "B": "没有满意", "C": "不满", "D": "没有不满"}, "answer": "B", "analysis": "双因素理论认为，满意与不满意并不是同一连续体的两个端点。激励因素充分时，员工容易产生满意；激励因素缺失时，结果是“没有满意”，而不一定是“不满”。", "optionAnalysis": {"A": "错误，激励因素缺失不能使员工满意。", "B": "正确，符合“满意—没有满意”这一维度。", "C": "错误，不满通常与保健因素不足有关。", "D": "错误，“没有不满”是保健因素具备时产生的状态。"}}, {"id": "7-11", "type": "single", "stem": "根据赫兹伯格的双因素理论，保健因素的具备会导致员工（ ）。", "options": {"A": "满意", "B": "不满", "C": "没有满意", "D": "没有不满"}, "answer": "D", "analysis": "保健因素充分只能消除或减少员工的不满，并不能直接形成持久的工作满意。", "optionAnalysis": {"A": "错误，使员工产生满意主要依靠成就、认可、责任和成长等激励因素。", "B": "错误，保健因素具备有助于减少不满。", "C": "错误，“没有满意”描述的是激励因素缺失的结果。", "D": "正确，保健因素具备时，员工通常处于“没有不满”的状态。"}}, {"id": "7-12", "type": "multi", "stem": "根据奥尔德弗的ERG理论，人的核心需要包括（ ）。", "options": {"A": "成就需要", "B": "生存需要", "C": "关系需要", "D": "权力需要", "E": "成长需要"}, "answer": "BCE", "analysis": "ERG理论将人的核心需要概括为生存需要、关系需要和成长需要。", "optionAnalysis": {"A": "错误，成就需要是麦克利兰三重需要理论中的需要之一，不是ERG理论的独立类别。", "B": "正确，生存需要涉及维持生存所必需的物质条件。", "C": "正确，关系需要涉及与他人建立和维持重要人际关系。", "D": "错误，权力需要属于麦克利兰三重需要理论。", "E": "正确，成长需要体现个体发展、提高能力和实现潜能的愿望。"}}, {"id": "7-13", "type": "multi", "stem": "在需要层次理论中，对应ERG理论关系需要的有（ ）。", "options": {"A": "部分生理需要", "B": "部分安全需要", "C": "全部安全需要", "D": "部分尊重的需要", "E": "全部归属于爱的需要"}, "answer": "BDE", "analysis": "ERG理论中的关系需要强调人际交往、归属以及来自他人的尊重，与马斯洛理论中的部分安全需要、全部归属和爱的需要以及部分尊重需要相对应。", "optionAnalysis": {"A": "错误，生理需要主要对应生存需要。", "B": "正确，安全需要中与人际保障和关系稳定有关的部分可归入关系需要。", "C": "错误，并非全部安全需要都属于关系需要，物质安全等内容更接近生存需要。", "D": "正确，尊重需要中来自他人的认可和尊重属于关系需要。", "E": "正确，归属和爱的需要整体体现人际联系，属于关系需要。"}}, {"id": "7-14", "type": "multi", "stem": "ERG理论三种核心需要中的成长需要，大体对应马斯洛需要层次理论中的（ ）。", "options": {"A": "全部自我实现需要", "B": "部分尊重的需要", "C": "部分安全需要", "D": "全部归属和爱的需要", "E": "全部生存需要"}, "answer": "AB", "analysis": "ERG理论中的成长需要是个体追求能力提高、潜能发挥和个人发展的需要。", "optionAnalysis": {"A": "正确，马斯洛理论中的全部自我实现需要与成长需要相对应。", "B": "正确，尊重需要中与自尊、能力和个人成就有关的部分属于成长需要。", "C": "错误，安全需要主要对应生存需要或部分关系需要。", "D": "错误，归属和爱的需要对应关系需要。", "E": "错误，生存方面的需要对应ERG理论中的生存需要。"}}, {"id": "7-15", "type": "multi", "stem": "下列观点中，符合ERG理论的有（ ）。", "options": {"A": "各种需要可以同时具有激励作用", "B": "低层次需要实现是高层次需要满足的先决条件", "C": "在某些限制条件下，各种需要层次之间可以进行转化", "D": "某个层次的需要得到满足后就不再有激励作用", "E": "人们可以同时追求各种层次的需要"}, "answer": "ACE", "analysis": "ERG理论弱化了马斯洛理论严格的层级顺序，并提出“挫折—退化”观点。", "optionAnalysis": {"A": "正确，生存、关系和成长需要可以同时对个体产生激励作用。", "B": "错误，ERG理论不认为低层次需要的满足必然是追求高层次需要的先决条件。", "C": "正确，当较高层次需要受到挫折时，个体可能转而强化较低层次需要。", "D": "错误，已经得到一定满足的需要仍可能继续具有激励作用。", "E": "正确，个体可以同时追求不同层次的需要。"}}, {"id": "7-16", "type": "single", "stem": "心理学家麦克利兰提出的三种需要不包括（ ）。", "options": {"A": "安全需要", "B": "权力需要", "C": "亲和需要", "D": "成就需要"}, "answer": "A", "analysis": "麦克利兰的三重需要理论包括成就需要、权力需要和亲和需要。", "optionAnalysis": {"A": "正确，安全需要属于马斯洛需要层次理论，不属于三重需要理论。", "B": "属于麦克利兰提出的权力需要。", "C": "属于麦克利兰提出的亲和需要。", "D": "属于麦克利兰提出的成就需要。"}}, {"id": "7-17", "type": "single", "stem": "麦克利兰提出的三重需要理论，成就需要高的人具有的特点是（ ）。", "options": {"A": "不需要得到及时的反馈", "B": "需要别人顺从自己", "C": "更可能选择适度的风险", "D": "责任感一般"}, "answer": "C", "analysis": "高成就需要者通常愿意承担个人责任，偏好具有适度风险和挑战性的任务，并希望及时获得工作反馈。", "optionAnalysis": {"A": "错误，高成就需要者重视及时、明确的绩效反馈。", "B": "错误，希望别人顺从自己主要体现较高的权力需要。", "C": "正确，适度风险既具有挑战性，又能够使个人努力对结果产生较明显的影响。", "D": "错误，高成就需要者通常具有较强的责任感，而不是责任感一般。"}}, {"id": "7-18", "type": "single", "stem": "关于三重需要理论的说法，正确的是（ ）。", "options": {"A": "亲和需要高的不易受别人影响", "B": "成就需要高的人不喜欢及时反馈", "C": "权力需要高的人喜欢竞争", "D": "成就需要高的人喜欢高度冒险的工作"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，亲和需要高的人重视人际关系和他人评价，通常较容易受到群体和他人的影响。B项错误，成就需要高的人希望及时了解工作结果，以便判断自己的努力是否有效。", "C": "正确，权力需要高的人希望影响或控制他人，通常喜欢竞争并重视获得地位。", "D": "错误，成就需要高的人更偏好适度风险，而不是结果主要取决于偶然性的高度冒险工作。"}}, {"id": "7-19", "type": "single", "stem": "根据麦克里兰三重需要理论，亲和需要强的人（ ）。", "options": {"A": "一定能成为优秀的经理", "B": "希望能够得到及时的反馈", "C": "容易与他人形成良好的人际关系，因而往往在组织中担当管理者的角色", "D": "容易担任被管理者"}, "answer": "D", "analysis": "亲和需要强的人重视友好关系、归属感和他人的接纳，倾向于避免冲突，不愿作出可能损害人际关系的强硬决定，因此更容易适应被管理者或合作支持型角色。", "optionAnalysis": {"A": "错误，亲和需要高并不意味着一定能够成为优秀经理，过分重视关系还可能影响客观决策。", "B": "错误，希望得到及时反馈主要是高成就需要者的典型特征。", "C": "错误，虽然亲和需要强的人容易形成良好关系，但不能据此推出其往往担当管理者；管理岗位还要求决断、控制和承担冲突。", "D": "正确，符合亲和需要强者重视接纳、合作和关系和谐的特点。"}}, {"id": "7-20", "type": "multi", "stem": "员工进行公平比较的情形中，属于纵向比较的有（ ）。", "options": {"A": "员工将自己的工作和报酬与部门内其他员工进行比较", "B": "员工将自己的工作和报酬与其他组织中的员工进行比较", "C": "员工将自己在不同组织中的工作和待遇进行比较", "D": "员工将自己的工作和报酬与本组织中的其他员工进行比较", "E": "员工将自己同一组织中现在的工作和待遇与过去的相比较"}, "answer": "CE", "analysis": "纵向比较是员工将自己当前的投入和产出与自己过去的经历进行比较，可分为组织内自我比较和组织外自我比较。", "optionAnalysis": {"A": "错误，这是与部门内其他人进行的组织内他比，属于横向比较。", "B": "错误，这是与其他组织中的他人比较，属于组织外他比和横向比较。", "C": "正确，这是员工比较自己在不同组织中的经历，属于组织外自我比较。", "D": "错误，这是与本组织其他员工比较，属于组织内他比和横向比较。", "E": "正确，这是比较本人在同一组织中现在与过去的待遇，属于组织内自我比较。"}}, {"id": "7-21", "type": "single", "stem": "根据公平理论，员工将自己在不同组织中的工作和待遇进行比较的情况属于（ ）。", "options": {"A": "组织内自我比较", "B": "组织外他比", "C": "组织外自我比较", "D": "组织内他比"}, "answer": "C", "analysis": "题干中的比较对象是员工本人，比较范围涉及不同组织，因此属于组织外自我比较。", "optionAnalysis": {"A": "错误，组织内自我比较是将本人在同一组织中的现在情况与过去情况进行比较。", "B": "错误，组织外他比是将自己与其他组织中的其他员工进行比较。", "C": "正确，员工比较自己在不同组织中的工作和待遇，符合组织外自我比较。", "D": "错误，组织内他比是将自己与本组织中的其他员工进行比较。"}}, {"id": "7-22", "type": "multi", "stem": "根据公平理论，员工恢复因薪酬不足而导致的不公平感的措施有（ ）。", "options": {"A": "员工向上级反映薪酬高者工作没有自己努力", "B": "员工降低自己的努力程度", "C": "员工寻求法律援助", "D": "员工从其他组织寻求帮助", "E": "员工辞职"}, "answer": "ABE", "analysis": "员工感到报酬不足时，可能通过改变投入、改变产出、改变对自己或参照者的认知、改变参照对象或者离开组织等方式恢复公平感。", "optionAnalysis": {"A": "正确，员工向上级强调薪酬较高者的投入不足，是试图改变对参照对象投入的认知或影响组织评价。", "B": "正确，降低努力程度属于减少个人投入。", "C": "错误，寻求法律援助并非公平理论通常列举的心理和行为调整方式，除非另有违法事实，题干并未说明。", "D": "错误，从其他组织寻求帮助不是公平理论中恢复当前投入产出平衡的典型方式。", "E": "正确，辞职属于离开造成不公平感的情境。"}}, {"id": "7-23", "type": "single", "stem": "按照弗罗姆的期望理论，一名员工认为自己努力工作从而获得晋升的可能性为60%，则0.6是他的（ ）。", "options": {"A": "期望值", "B": "效价值", "C": "工具性", "D": "强化值"}, "answer": "A", "analysis": "期望值是个体对自己付出努力后能够达到某种绩效水平的概率判断。题干将“努力工作”与“获得晋升”直接联系起来，教材类题目通常将该可能性表述为员工的期望值。", "optionAnalysis": {"A": "正确，0.6表示员工认为努力能够带来目标结果的主观概率。", "B": "错误，效价表示员工对晋升结果价值大小的评价，而不是发生概率。", "C": "错误，工具性通常表示达到一定绩效后能够获得某种结果或报酬的可能性。", "D": "错误，强化值不是弗罗姆期望理论的核心概念。"}}, {"id": "7-24", "type": "single", "stem": "某公司为研发团队提供两项激励奖励选择：10万元现金和项目冠名权，工程师老赵认为行业认可比金钱更重要，主动选择冠名权。老赵对“项目冠名权”价值的判断，反映期望理论中的（ ）。", "options": {"A": "期望值", "B": "效价值", "C": "工具性", "D": "公平性"}, "answer": "B", "analysis": "效价是个体对某种结果或奖励价值的主观评价。同一种奖励对不同员工可能具有不同效价。A项错误，期望值反映努力能够达到某种绩效的主观可能性。B项正确，老赵认为项目冠名权比现金更重要，是在判断奖励对自己的吸引力和价值。C项错误，工具性反映绩效与获得奖励之间的关联程度。D项错误，公平性属于公平理论关注的内容，不是题干所体现的概念。", "optionAnalysis": {}}, {"id": "7-25", "type": "single", "stem": "期望理论可以用（ ）来加以表述。", "options": {"A": "结果＝效价×期望", "B": "动机＝效价×工具性", "C": "动机＝效价×期望×工具性", "D": "结果＝效价×期望×工具性"}, "answer": "C", "analysis": "弗罗姆期望理论认为，个体的动机水平取决于期望、工具性和效价三者的乘积，即动机＝效价×期望×工具性。", "optionAnalysis": {"A": "错误，公式的结果变量应为动机，而且缺少工具性。", "B": "错误，缺少努力达到绩效的期望因素。", "C": "正确，完整反映了努力—绩效、绩效—结果以及结果价值三个环节。", "D": "错误，乘积所说明的是动机水平，不是笼统的“结果”。由于采用乘法关系，任一因素接近零时，整体动机水平都会明显下降。"}}, {"id": "7-26", "type": "single", "stem": "基于期望理论对个体动机水平不产生直接影响的因素是（ ）。", "options": {"A": "公平", "B": "工具性", "C": "效价", "D": "期望"}, "answer": "A", "analysis": "期望理论中直接决定个体动机水平的因素是期望、工具性和效价。", "optionAnalysis": {"A": "正确，公平是公平理论的核心变量，不是期望理论公式中的直接因素。", "B": "错误，工具性直接影响员工对“绩效能否带来奖励”的判断。", "C": "错误，效价直接反映员工对奖励价值的评价。", "D": "错误，期望直接反映员工对“努力能否带来绩效”的判断。"}}, {"id": "7-27", "type": "single", "stem": "提出双因素理论的学者是（ ）。", "options": {"A": "马斯洛", "B": "赫兹伯格", "C": "麦克里兰", "D": "奥尔德弗"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，马斯洛提出需要层次理论。", "B": "正确，赫茨伯格提出双因素理论，将影响员工态度的因素分为激励因素和保健因素。", "C": "错误，麦克利兰提出三重需要理论。", "D": "错误，奥尔德弗提出ERG理论。"}}, {"id": "7-28", "type": "single", "stem": "三重需要理论提出者（ ）。", "options": {"A": "弗鲁姆", "B": "奥尔德弗", "C": "麦克利兰", "D": "马斯洛"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，弗鲁姆提出期望理论。", "B": "错误，奥尔德弗提出ERG理论。", "C": "正确，麦克利兰提出三重需要理论，包括成就需要、权力需要和亲和需要。", "D": "错误，马斯洛提出需要层次理论。"}}, {"id": "7-29", "type": "single", "stem": "在众多激励理论中，不考虑人的内在心态，而是注重行为及其结果的理论是（ ）。", "options": {"A": "强化理论", "B": "公平理论", "C": "期望理论", "D": "双因素理论"}, "answer": "A", "analysis": "强化理论建立在行为主义观点基础上，重点研究行为结果如何影响行为再次发生的可能性，不以人的内在心理过程为主要研究对象。", "optionAnalysis": {"A": "正确，强化理论关注行为及其后果。", "B": "错误，公平理论关注员工对投入产出比例是否公平的主观认知。", "C": "错误，期望理论关注期望、工具性和效价等心理判断。", "D": "错误，双因素理论关注员工满意与不满意的心理感受及其影响因素。"}}, {"id": "7-30", "type": "single", "stem": "关于激励理论中的强化理论的说法，正确的是（ ）。", "options": {"A": "它强调人的内在心理状态", "B": "它是一种人本主义的观点", "C": "它对解释行为没有帮助", "D": "它是一种行为主义的观点"}, "answer": "D", "analysis": "强化理论认为，行为后果会影响该行为未来发生的概率，是一种典型的行为主义理论。", "optionAnalysis": {"A": "错误，强化理论不以人的内在心理状态为研究重点。", "B": "错误，强化理论的理论基础是行为主义，而非人本主义。", "C": "错误，强化理论能够解释奖励、惩罚等行为后果如何塑造员工行为。", "D": "正确，准确说明了强化理论的理论属性。"}}, {"id": "7-31", "type": "single", "stem": "在管理实践中，最适合作为工作丰富化理论基础的是（ ）。", "options": {"A": "需要层次理论", "B": "三重需要理论", "C": "ERG理论", "D": "双因素理论"}, "answer": "D", "analysis": "工作丰富化强调增加工作的挑战性、完整性、责任感、自主性和反馈，使员工从工作本身获得成就和成长，直接体现双因素理论中激励因素的作用。", "optionAnalysis": {"A": "错误，需要层次理论能够解释一般需要，但不是工作丰富化最直接的理论基础。", "B": "错误，三重需要理论侧重成就、权力和亲和需要。", "C": "错误，ERG理论侧重生存、关系和成长需要之间的关系。", "D": "正确，工作丰富化正是通过强化工作本身、责任、认可和成长等激励因素来提高满意度。"}}, {"id": "7-32", "type": "multi", "stem": "目标管理的要素包括（ ）。", "options": {"A": "技能薪酬", "B": "不限期完成", "C": "参与决策", "D": "绩效反馈", "E": "目标具体化"}, "answer": "CDE", "analysis": "目标管理的基本要素通常包括目标具体化、参与决策、限期完成和绩效反馈。", "optionAnalysis": {"A": "错误，技能薪酬是一种薪酬制度，不是目标管理的基本要素。", "B": "错误，目标管理强调目标应在规定期限内完成，而不是不限期完成。", "C": "正确，员工参与目标制定能够增强对目标的认同。", "D": "正确，持续的绩效反馈有助于了解目标完成进度并及时调整。", "E": "正确，目标必须明确、具体并具有可衡量性。"}}, {"id": "7-33", "type": "single", "stem": "部门经理定期统计产量与销售额、编制进度报表，并将结果与最终目标进行比较，这属于目标管理中的（ ）。", "options": {"A": "限期完成", "B": "参与决策", "C": "目标具体化", "D": "绩效反馈"}, "answer": "D", "analysis": "题干强调定期统计实际结果、编制进度报表并与目标进行比较，其作用是使管理者和员工及时了解目标完成情况。", "optionAnalysis": {"A": "错误，限期完成强调为目标规定完成时间。", "B": "错误，参与决策强调上下级共同制定目标和评价标准。", "C": "错误，目标具体化强调目标明确、量化和可衡量。", "D": "正确，将实际绩效与目标进行比较并传递结果，属于绩效反馈。"}}, {"id": "7-34", "type": "single", "stem": "目标管理要求涉及目标的所有群体共同制定目标，并共同规定如何衡量目标的实现程度，这属于（ ）。", "options": {"A": "绩效反馈", "B": "限期完成", "C": "参与决策", "D": "目标具体化"}, "answer": "C", "analysis": "题干中的关键词是“共同制定目标”和“共同规定”，体现了员工及相关群体参与目标制定和衡量标准确定。", "optionAnalysis": {"A": "错误，绩效反馈是在执行过程中提供完成情况的信息。", "B": "错误，限期完成强调明确目标完成期限。", "C": "正确，符合目标管理中的参与决策要素。", "D": "错误，目标具体化强调目标本身明确、具体和可衡量，但题干重点是共同参与制定。"}}, {"id": "7-35", "type": "single", "stem": "若有效推行质量监督小组，需要满足的条件不包括（ ）。", "options": {"A": "员工有能力参与但不希望承担责任", "B": "组织文化必须支持员工参与", "C": "员工应有充裕的时间进行参与", "D": "员工参与的问题必须与自身利益相关"}, "answer": "A", "analysis": "质量监督小组属于参与管理的一种形式，其有效运行需要员工有参与能力和意愿，组织提供文化、时间及制度支持，并使参与事项与员工相关。", "optionAnalysis": {"A": "正确，员工不希望承担责任会削弱参与的主动性和质量，因此不是有效推行所需的条件。", "B": "错误，支持参与的组织文化能够保障员工提出意见并参与决策。", "C": "错误，参与活动需要必要的时间，否则容易流于形式。", "D": "错误，参与问题与员工利益相关时，员工更有动力投入并提供有价值的建议。"}}, {"id": "7-36", "type": "single", "stem": "关于参与管理的说法，错误的是（ ）。", "options": {"A": "职位越高的管理人员越容易接受参与管理理念", "B": "参与管理符合双因素理论主张", "C": "参与管理符合ERG理论的主张", "D": "参与管理是激励理论在实践中的一种应用"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误，参与管理意味着上级与下属分享一定的决策权，职位较高、权力较大的管理者不一定更容易接受，有些管理者可能因担心权力削弱而产生抵触。", "B": "正确，参与管理能够增强责任感、成就感和工作本身的意义，符合双因素理论中激励因素的主张。", "C": "正确，参与管理能够满足员工的关系需要和成长需要，符合ERG理论。", "D": "正确，参与管理是将需要理论和激励理论运用于组织管理实践的具体方式。"}}, {"id": "7-37", "type": "multi", "stem": "参与管理就是让下属实际分享上级的决策权。员工参与管理的好处有（ ）。", "options": {"A": "可以帮助员工成长", "B": "员工对做出的决定有认同感，有利于决策执行", "C": "促进管理者和员工沟通", "D": "可以提供外在奖赏", "E": "发挥员工专长，提高其对工作的兴趣"}, "answer": "ABCE", "analysis": "参与管理通过让员工分享决策权，能够满足员工成长、关系和自我实现等方面的需要。", "optionAnalysis": {"A": "正确，参与决策可以锻炼员工分析问题和解决问题的能力。", "B": "正确，员工参与形成的决定更容易获得其认同，从而提高执行意愿。", "C": "正确，参与过程增加了上下级交流，有助于信息共享和相互理解。", "D": "错误，参与管理主要提供内在激励，并不必然提供奖金、福利等外在奖赏。", "E": "正确，员工能够在决策中发挥专业知识和经验，从而提高工作兴趣和责任感。"}}, {"id": "7-38", "type": "single", "stem": "计件工资将员工的收入和产量直接挂钩，这种激励措施属于（ ）。", "options": {"A": "领导—成员交换理论", "B": "双因素理论", "C": "期望理论", "D": "ERG理论"}, "answer": "C", "analysis": "绩效薪金制的核心是将员工报酬与个人、团队或组织绩效联系起来。", "optionAnalysis": {"A": "错误，奖金只是绩效薪金的一种可能形式，不能完整概括计件工资。", "B": "错误，固定薪酬不随产量或绩效直接变化。", "C": "正确，计件工资按照员工完成的产品数量计算报酬，收入与绩效直接挂钩。", "D": "错误，补贴是对特定工作条件或支出的补偿，并非按照产量支付。"}}, {"id": "7-40", "type": "single", "stem": "有关斯坎伦计划错误的是（ ）。", "options": {"A": "员工是有能力而且愿意贡献出他们的想法和建议的", "B": "计划的成败取决于劳资双方是否能够相互信赖", "C": "企业回报率提高而增加的效益应当与员工分享", "D": "利润分享方案增加了劳动支出第八章领导行为理论及其应用"}, "answer": "D", "analysis": "斯坎伦计划是一种收益分享计划，强调员工参与、劳资合作以及将生产率提高所形成的收益与员工分享。", "optionAnalysis": {"A": "正确，斯坎伦计划以员工有能力且愿意提出改进建议为重要假设。", "B": "正确，劳资双方的信任与合作是计划有效实施的重要条件。", "C": "正确，组织因生产率或经营效率提高而形成的收益，应按约定方式与员工分享。", "D": "错误，收益分享奖金来源于效率提高所产生的新增收益，其目标不是单纯增加劳动支出，而是在控制成本、提高生产率的基础上实现组织与员工共享成果。"}}]}, {"id": 8, "title": "领导行为理论及其应用", "questions": [{"id": "8-1", "type": "multi", "stem": "按照领导理论的观点，领导具备的基本特点包括（ ）。", "options": {"A": "具有影响力", "B": "专业知识丰富", "C": "须有正式任命", "D": "具有指导能力", "E": "能够激励员工"}, "answer": "ADE", "analysis": "A正确，领导的核心是对他人产生影响，领导者必须具有影响力。B错误，专业知识有助于领导工作，但不是领导必然具备的基本特点。C错误，领导既可能来自正式任命，也可能凭借个人影响力自然形成。D正确，领导者需要对组织成员的行为进行引导和指导。E正确，领导者需要激励成员为实现组织目标而努力。", "optionAnalysis": {}}, {"id": "8-2", "type": "single", "stem": "下面不属于特质理论的缺陷是（ ）。", "options": {"A": "忽视了下属的需要", "B": "忽视了情境因素", "C": "没有指明各特质之间的相对重要性", "D": "过分强调原因和结果"}, "answer": "D", "analysis": "A错误，即该项属于特质理论的缺陷：特质理论主要关注领导者自身特质，忽视下属需要。B错误，忽视具体情境也是特质理论的缺陷。C错误，特质理论没有明确各种特质之间的相对重要性。D正确，特质理论的主要缺陷不包括“过分强调原因和结果”。", "optionAnalysis": {}}, {"id": "8-3", "type": "single", "stem": "根据美国心理学家伯恩斯的观点，属于交易型领导特征的是（ ）。", "options": {"A": "魅力", "B": "工作差错管理", "C": "智慧型刺激", "D": "个性化关怀"}, "answer": "B", "analysis": "A错误，魅力属于变革型领导的特征。B正确，工作差错管理即例外管理，领导者监督标准执行情况并纠正偏差，属于交易型领导。C错误，智慧型刺激属于变革型领导。D错误，个性化关怀也属于变革型领导。", "optionAnalysis": {}}, {"id": "8-4", "type": "single", "stem": "交易型领导的特征包括（ ）。", "options": {"A": "不关注与标准背离的行为", "B": "对员工有持续的高期望", "C": "通过个性化关怀来激励员工", "D": "承诺为高绩效提供奖赏，赏识成就"}, "answer": "D", "analysis": "A错误，交易型领导会通过例外管理关注并纠正与标准背离的行为。B错误，持续提出高期望更符合变革型领导。C错误，个性化关怀是变革型领导的典型特征。D正确，交易型领导以交换关系为基础，通过权变奖励承诺为高绩效提供奖赏。", "optionAnalysis": {}}, {"id": "8-5", "type": "multi", "stem": "关于交易型和变革型领导的说法，正确的（ ）。", "options": {"A": "交易型领导强调任务的明晰度、工作的标准和产出", "B": "交易型领导很关注任务的完成及员工的顺从", "C": "变革型领导更多依靠组织的奖励和惩罚来影响员工的绩效", "D": "变革型领导能为组织制定明确的愿景", "E": "变革型领导更多地通过自己的领导风格来影响员工和团队的绩效"}, "answer": "ABDE", "analysis": "A正确，交易型领导强调明确任务、标准和产出。B正确，交易型领导关注任务完成和员工对要求的遵从。C错误，主要依靠奖励和惩罚影响绩效的是交易型领导。D正确，变革型领导能够提出并传递清晰的组织愿景。E正确，变革型领导通过魅力、智慧型刺激和个性化关怀等方式影响员工及团队。", "optionAnalysis": {}}, {"id": "8-6", "type": "single", "stem": "魅力型领导道德特征包括（ ）。", "options": {"A": "使用权力为他人服务", "B": "单向沟通", "C": "遵循外在道德标准", "D": "提升自己的个人愿景"}, "answer": "A", "analysis": "A正确，道德型魅力领导者使用权力为他人和共同利益服务。B错误，单向沟通属于非道德型魅力领导的表现，道德型强调双向沟通。C错误，道德型魅力领导遵循内在道德标准。D错误，提升个人愿景、使组织服务于个人利益属于非道德特征。", "optionAnalysis": {}}, {"id": "8-7", "type": "multi", "stem": "魅力型领导的道德特征包括（ ）。", "options": {"A": "遵循外在道德标准", "B": "提升自己的个人愿景", "C": "双向沟通", "D": "从危机中思考与学习", "E": "使用权力为他人服务"}, "answer": "CDE", "analysis": "A错误，道德型魅力领导遵循内在道德标准。B错误，其强调共同愿景，而不是提升领导者个人愿景。C正确，道德型魅力领导重视开放、坦诚的双向沟通。D正确，其能够从危机和错误中反思与学习。E正确，其将权力用于服务他人和实现共同利益。", "optionAnalysis": {}}, {"id": "8-8", "type": "single", "stem": "作为公司领导，小明一直努力为员工建立舒适的工作环境，并且会根据员工的需求布置公司。依照豪斯关于领导理论的观点，小明属于（ ）。", "options": {"A": "指导式领导", "B": "支持型领导", "C": "成就取向式领导", "D": "参与式领导"}, "answer": "B", "analysis": "A错误，指导式领导主要明确任务、程序和标准。B正确，支持型领导关心下属需要和福利，并营造友善、舒适的工作环境。C错误，成就取向式领导强调挑战性目标和卓越绩效。D错误，参与式领导强调征求下属意见并让下属参与决策。", "optionAnalysis": {}}, {"id": "8-9", "type": "single", "stem": "市场部负责人小高工作负责，但是小高只关心工作绩效，不太注重与成员之间的沟通协作，要求一切事项都必须按照他的要求执行，从小高的表现可以看出，根据路径—目标理论，小高属于（ ）。", "options": {"A": "指导式领导", "B": "支持型领导", "C": "成就取向式领导", "D": "参与式领导"}, "answer": "A", "analysis": "A正确，指导式领导明确规定下属应做什么、如何做，并要求按标准和指令执行。B错误，支持型领导重视下属需要和友善氛围，与题干不符。C错误，成就取向式领导重在设定挑战性目标，而题干重点是指示和控制。D错误，参与式领导会征求下属意见，与题干相反。", "optionAnalysis": {}}, {"id": "8-10", "type": "multi", "stem": "罗伯特·豪斯在路径—目标理论中确定的领导行为包括（ ）。", "options": {"A": "支持型领导", "B": "参与式领导", "C": "成就取向式领导", "D": "指导式领导", "E": "权变型领导"}, "answer": "ABCD", "analysis": "A、B、C、D正确，路径—目标理论确定了指导式、支持型、参与式和成就取向式四种领导行为。E错误，路径—目标理论具有权变思想，但“权变型领导”不是该理论划分的具体领导行为。", "optionAnalysis": {}}, {"id": "8-11", "type": "single", "stem": "根据路径—目标理论，主动征求并采纳下属意见的领导属于（ ）。", "options": {"A": "成就取向式领导", "B": "参与式领导", "C": "支持型领导", "D": "指导式领导"}, "answer": "B", "analysis": "A错误，成就取向式领导强调挑战性目标和高绩效。B正确，参与式领导主动征求下属意见，并在决策时考虑或采纳这些意见。C错误，支持型领导主要关心下属需要和工作环境。D错误，指导式领导主要明确任务、方法和绩效标准。", "optionAnalysis": {}}, {"id": "8-12", "type": "single", "stem": "根据路径—目标理论，下属工作是结构化的，则（ ）类型领导可以带来高的绩效和满意度。", "options": {"A": "指导型", "B": "支持型", "C": "参与型", "D": "成就取向型"}, "answer": "B", "analysis": "A错误，任务已经结构化时，程序和要求较明确，过多指导可能形成重复控制。B正确，支持型领导能够缓解结构化工作的单调感，改善工作体验并提高满意度和绩效。C错误，参与型领导并非结构化任务下的典型最佳匹配。D错误，成就取向型更适合具有挑战性、复杂或非结构化的任务。", "optionAnalysis": {}}, {"id": "8-13", "type": "single", "stem": "关于路径—目标理论中领导行为与环境因素、个人特征匹配的说法，错误的是（ ）。", "options": {"A": "对能力强的员工采用指导式领导", "B": "对内控型员工采用参与式领导", "C": "对任务结构化程度高的员工采用支持型领导", "D": "对外控型员工采用指导式领导"}, "answer": "A", "analysis": "A错误，能力强、经验丰富的员工通常不需要过多指导，指导式领导可能降低其满意度。B正确，内控型员工相信结果主要由自身行为决定，通常偏好参与决策。C正确，任务结构化程度高时，支持型领导有助于改善工作体验。D正确，外控型员工通常更偏好明确的指示和规范，适合指导式领导。", "optionAnalysis": {}}, {"id": "8-14", "type": "single", "stem": "领导理论中的权变理论强调的情境性因素不包括（ ）。", "options": {"A": "领导与下属的关系", "B": "领导风格", "C": "工作结构", "D": "职权"}, "answer": "B", "analysis": "费德勒权变理论用领导与下属的关系、工作结构和领导者职权描述情境。A属于情境性因素。\nB不属于情境性因素，领导风格是需要与情境匹配的领导者特征。C属于情境性因素。D属于情境性因素。", "optionAnalysis": {}}, {"id": "8-15", "type": "single", "stem": "根据费德勒的权变理论，最适合于关系取向领导风格的情境是（ ）。", "options": {"A": "领导与下属关系较好，工作结构化程度较高，领导者职权较大", "B": "领导与下属关系较坏，工作结构化程度较低，领导者职权较大", "C": "领导与下属关系较坏，工作结构化程度较高，领导者职权较小", "D": "领导与下属关系较好，工作结构化程度较低，领导者职权较小"}, "answer": "D", "analysis": "费德勒认为，工作取向型领导在情境极有利或极不利时绩效较好，关系取向型领导在中等有利情境下绩效较好。A错误，关系好、工作结构高、职权大属于最有利情境，适合工作取向型。C通常属于较不利情境，按教材常见分类更偏向工作取向型。D属于中等有利情境。", "optionAnalysis": {}}, {"id": "8-16", "type": "multi", "stem": "依据领导权变理论的观点，能使工作取向型的绩效高的情境是（ ）。", "options": {"A": "上下级关系坏、工作结构低、领导者职权小", "B": "上下级关系好、工作结构高、领导者职权大", "C": "上下级关系坏、工作结构高、领导者职权大", "D": "上下级关系好、工作结构低、领导者职权大", "E": "上下级关系好、工作结构低、领导者职权小"}, "answer": "ABD", "analysis": "工作取向型领导在情境非常有利或非常不利时绩效较高。A正确，关系坏、结构低、职权小属于非常不利情境。B正确，关系好、结构高、职权大属于非常有利情境。C错误，属于中等有利情境，更适合关系取向型。D正确，按教材常用八种情境划分，属于工作取向型绩效较高的范围。E错误，属于中等有利情境，更适合关系取向型。", "optionAnalysis": {}}, {"id": "8-17", "type": "single", "stem": "权变理论认为，在工作结构高度程序化且领导与员工关系良好的情境中，有助于提升工作绩效的领导类型是（ ）。", "options": {"A": "高关系取向", "B": "高工作取向", "C": "高支持取向", "D": "高成就取向"}, "answer": "B", "analysis": "工作结构高度程序化且领导与员工关系良好，说明情境对领导者较为有利。A错误，高关系取向更适合中等有利情境。B正确，高工作取向适合非常有利或非常不利的情境。C、D错误，高支持取向和高成就取向属于路径—目标理论的相关表述，不是本题费德勒权变理论的领导类型。", "optionAnalysis": {}}, {"id": "8-18", "type": "single", "stem": "关于领导—成员交换理论的说法，错误的是（ ）。", "options": {"A": "领导成员交换是一个互惠的过程", "B": "“圈里人”通常比“圈外人”更具有工作责任感", "C": "领导倾向于对“圈里人”采用正式领导权威", "D": "领导把下属分成“圈里人”和“圈外人”"}, "answer": "C", "analysis": "A正确，领导与成员通过相互作用建立交换关系，是互惠过程。B正确，“圈里人”通常承担更多额外工作，责任感和绩效往往较高。C错误，领导对“圈里人”更多给予关心、信任并使用非正式影响，而不是主要采用正式权威。D正确，将成员区分为“圈里人”和“圈外人”是该理论的核心观点。", "optionAnalysis": {}}, {"id": "8-19", "type": "single", "stem": "关于领导—成员交换理论的说法，正确的是（ ）。", "options": {"A": "领导者在与下属确立关系的早期，就已经分出了“圈里人”和“圈外人”", "B": "领导者对于“圈里人”会投入更多的时间、感情以及更多的正式领导权威", "C": "在工作中，“圈外人”要比“圈里人”绩效更高", "D": "领导—成员交换的过程是单向的"}, "answer": "A", "analysis": "A正确，领导者在关系形成的早期就会区分“圈里人”和“圈外人”。B错误，领导会向“圈里人”投入更多时间和感情，并给予更多信任和非正式影响，而不是更多正式权威。C错误，通常“圈里人”的绩效和组织承诺更高。D错误，领导—成员交换是双方相互作用的互惠过程。", "optionAnalysis": {}}, {"id": "8-20", "type": "single", "stem": "以管理者为中心的X理论领导风格强调（ ）。", "options": {"A": "民主", "B": "产出", "C": "关怀", "D": "支持"}, "answer": "B", "analysis": "X理论对人性持较消极的假设，强调严格控制、监督和任务产出。A错误，民主参与更接近Y理论。B正确，X理论领导风格强调任务、控制和产出。C错误，关怀不是其核心。D错误，支持型领导重视员工需要，与X理论的控制取向不符。", "optionAnalysis": {}}, {"id": "8-21", "type": "single", "stem": "勒温在研究中发现，能让儿童产生最多攻击行为的领导类型是（ ）。", "options": {"A": "放任型", "B": "独裁型", "C": "民主型", "D": "交换型"}, "answer": "A", "analysis": "A正确，放任型领导缺少必要的规则、指导和控制，群体容易混乱，并产生较多攻击行为。B错误，独裁型会造成紧张和依赖等问题，但教材口径中攻击行为最多的是放任型。C错误，民主型重视参与和沟通，群体表现相对较好。D错误，交换型不属于勒温划分的三种领导类型。", "optionAnalysis": {}}, {"id": "8-22", "type": "single", "stem": "根据俄亥俄大学关于领导行为的研究，可以促使员工实现高绩效和高工作满意度的领导行为是（ ）。", "options": {"A": "高关心人和高工作管理", "B": "高关心人和低工作管理", "C": "低关心人和高工作管理", "D": "低关心人和低工作管理"}, "answer": "A", "analysis": "A正确，高关心人和高工作管理既明确任务及标准，又重视员工需要，更可能实现高绩效和高满意度。B错误，虽可能提高满意度，但工作管理低，未必实现高绩效。C错误，可能强调绩效，但忽视员工感受，难以保证高满意度。D错误，两方面均低，通常难以取得良好效果。", "optionAnalysis": {}}, {"id": "8-23", "type": "multi", "stem": "在密歇根模式中，用来描述领导行为的维度包括（ ）。", "options": {"A": "技能管理", "B": "关心人", "C": "员工取向", "D": "工作管理", "E": "生产取向"}, "answer": "CE", "analysis": "密歇根大学把领导行为概括为员工取向和生产取向。A错误，技能管理不是密歇根模式的维度。B错误，关心人是俄亥俄模式的维度。C正确，员工取向重视人际关系和员工需要。D错误，工作管理是俄亥俄模式的维度。E正确，生产取向强调任务、工作技术和生产效率。", "optionAnalysis": {}}, {"id": "8-24", "type": "single", "stem": "在管理方格图中，坐标（1，1）代表的领导风格是（ ）。", "options": {"A": "无为而治", "B": "中庸式", "C": "乡村俱乐部", "D": "任务领导风格"}, "answer": "A", "analysis": "A正确，（1，1）表示对生产和人的关心程度都很低，属于无为而治型。B错误，中庸式对应（5，5）。C错误，乡村俱乐部型对应（1，9）。D错误，任务型领导对应（9，1）。", "optionAnalysis": {}}, {"id": "8-25", "type": "single", "stem": "保罗·赫塞的领导者生命周期理论，个人对自己的行为负责任的能力和意愿就是指（ ）。", "options": {"A": "心理成熟度", "B": "能力成熟度", "C": "技能成熟度", "D": "工作成熟度"}, "answer": "A", "analysis": "保罗・赫塞（Hersey）的领导者生命周期理论（情境领导理论），将下属成熟度分为两类：\n1.心理成熟度：个人对自己的行为负责任的能力和意愿（自信心、责任心、动机、愿意承担责任）。\n2.工作成熟度：一个人的知识和技能，也就是完成任务的能力。\nB、C选项是干扰项；D工作成熟度只代表知识技能，不包含“意愿”，和题干描述不符。", "optionAnalysis": {}}, {"id": "8-26", "type": "single", "stem": "下列领导风格中，属于生命周期理论中“高工作取向—高关系取向”风格的是（ ）。", "options": {"A": "指导式领导", "B": "推销式领导", "C": "参与式领导", "D": "授权式领导"}, "answer": "B", "analysis": "A错误，指导式是高工作取向、低关系取向。B正确，推销式是高工作取向、高关系取向。C错误，参与式是低工作取向、高关系取向。D错误，授权式是低工作取向、低关系取向。", "optionAnalysis": {}}, {"id": "8-27", "type": "single", "stem": "根据生命周期理论，领导和下属共同决策的领导风格分为（ ）。", "options": {"A": "推销式", "B": "授权式", "C": "参与式", "D": "询问式"}, "answer": "C", "analysis": "A错误，推销式为高工作取向、高关系取向，领导者说明决策并争取下属接受。B错误，授权式由成熟下属承担决策和执行责任。C正确，参与式为低工作取向、高关系取向，领导者与下属共同参与决策。D错误，询问式不是生命周期理论划分的标准领导风格。", "optionAnalysis": {}}, {"id": "8-28", "type": "multi", "stem": "关于领导技能的说法，正确的有（ ）。", "options": {"A": "领导职位越高，技术技能的作用越重要", "B": "领导职位越高，概念技能的作用越重要", "C": "领导制定长期计划需要依赖概念技能", "D": "各层级领导都须具备良好的人际技能", "E": "不同层级领导需要的概念技能、人际技能和技术技能的比例不同"}, "answer": "BCDE", "analysis": "A错误，职位越高，技术技能的相对重要性通常越低。B正确，职位越高，越需要从组织整体和长远角度分析问题，概念技能越重要。C正确，制定长期计划需要把握组织内外部环境及各要素关系，依赖概念技能。D正确，各层级领导都需要与他人沟通协作，因此都需要人际技能。E正确，不同层级职责不同，对三类技能的需求比例也不同。", "optionAnalysis": {}}, {"id": "8-29", "type": "multi", "stem": "关于领导技能的说法，正确的有（ ）。", "options": {"A": "组织中任何层次的领导都需要有效的人际技能", "B": "领导者更加依靠的是下属的人际技能", "C": "制定长期计划需要用到概念技能", "D": "升职并担负领导责任后，技术技能就会显得相对不重要", "E": "管理职位越高，概念技能的作用就越重要"}, "answer": "ACDE", "analysis": "A正确，各管理层级都需要有效沟通、合作和激励他人的人际技能。B错误，领导者需要具备并运用自身的人际技能，不能主要依靠下属的人际技能。C正确，制定长期计划需要整体和长远分析，依赖概念技能。D正确，职位晋升、管理范围扩大后，技术技能的相对重要性下降。E正确，管理职位越高，战略决策越多，概念技能越重要。", "optionAnalysis": {}}, {"id": "8-30", "type": "single", "stem": "在西蒙的决策过程理论中，探索、研究和分析可能发生的行为系列属于（ ）。", "options": {"A": "智力活动阶段", "B": "选择活动阶段", "C": "设计活动阶段", "D": "确认活动阶段"}, "answer": "C", "analysis": "A错误，智力活动阶段主要是发现问题、识别机会和收集信息。B错误，选择活动阶段是在可行方案中进行评价和选择。C正确，设计活动阶段负责探索、研究和分析可能发生的行为系列，形成备选方案。D错误，确认活动阶段不是西蒙决策过程标准三阶段之一。", "optionAnalysis": {}}, {"id": "8-31", "type": "single", "stem": "按照明茨伯格的决策过程，个体搜寻现有的标准程序、解决方案，或者设计全新的、量身定做的解决方案的阶段，属于（ ）。", "options": {"A": "确认阶段", "B": "发展阶段", "C": "选择阶段", "D": "活动阶段"}, "answer": "B", "analysis": "A错误，确认阶段主要识别问题并诊断原因。B正确，发展阶段包括搜寻现有标准程序或现成方案，以及设计全新的解决方案。C错误，选择阶段是在已经形成的备选方案之间进行筛选和评价。D错误，活动阶段不是明茨伯格决策过程的标准阶段。", "optionAnalysis": {}}, {"id": "8-32", "type": "single", "stem": "根据理性模型，决策者在任何方面都是完全理性的，下列哪项不是决策者具备的特征（ ）。", "options": {"A": "存在完整的一致偏好的系统，使决策者在不同备选方案中进行选择", "B": "对计算复杂无限性，可以通过计算选择出最佳备选方案", "C": "无需知道所有备选方案", "D": "从目标意义上分析，决策完全理性"}, "answer": "C", "analysis": "A正确，即属于完全理性决策者的特征，其具有完整且一致的偏好体系。B正确，完全理性模型假定决策者不受计算复杂性的限制，能够找出最佳方案。C错误，即为本题答案，完全理性模型要求决策者知道所有可能的备选方案。D正确，该模型假定决策者围绕目标进行完全理性的选择。", "optionAnalysis": {}}, {"id": "8-33", "type": "multi", "stem": "按照理性决策模型，完全理性的决策者具有的特征包括（ ）。", "options": {"A": "从目标意义上分析，决策完全理性", "B": "对计算复杂性无限制", "C": "对于概率的计算不存在任何困难", "D": "存在不完全和不一致偏好系统", "E": "无须了解所有的决策方案"}, "answer": "ABC", "analysis": "A正确，理性模型假定决策者围绕既定目标进行完全理性的选择。B正确，假定决策者不受计算复杂性限制。C正确，假定决策者能够准确处理各种结果的概率。D错误，完全理性模型要求偏好系统完整且一致。E错误，完全理性模型要求了解所有可能的决策方案。", "optionAnalysis": {}}, {"id": "8-34", "type": "single", "stem": "按照西蒙的有限理性模型，决策者应采用的原则是（ ）。", "options": {"A": "满意原则", "B": "最大化原则", "C": "完全理性原则", "D": "心理投入原则"}, "answer": "A", "analysis": "A正确，有限理性模型认为决策者受到信息、认知能力和时间等限制，通常选择达到可接受标准的满意方案。B错误，最大化原则属于完全理性模型。C错误，有限理性模型正是对完全理性假设的修正。D错误，心理投入可用于解释决策者坚持错误决策的现象，不是有限理性模型的基本选择原则。", "optionAnalysis": {}}, {"id": "8-35", "type": "multi", "stem": "关于决策的有限理性模型的说法正确的有（ ）。", "options": {"A": "通过计算选择出最佳备选方案", "B": "决策或决策时追求利益最大化", "C": "决策者在进行选择时不必知道所有可能方案", "D": "决策者认知的世界是真实世界的简化模型", "E": "在选择备选方案时，决策者试图寻找令人满意的结果"}, "answer": "CDE", "analysis": "A错误，通过完整计算选出最佳方案属于完全理性模型。B错误，有限理性决策者追求满意结果，而非利益最大化。C正确，决策者不必也往往不可能掌握所有可能方案。D正确，受认知能力限制，决策者所认识的世界是真实世界的简化模型。E正确，决策者寻找达到可接受标准的满意方案，而不是绝对最优方案。", "optionAnalysis": {}}, {"id": "8-36", "type": "multi", "stem": "有些决策者有坚持错误决策的倾向，原因有（ ）。", "options": {"A": "心理因素", "B": "组织因素", "C": "压力因素", "D": "家庭因素", "E": "项目特点"}, "answer": "ABCE", "analysis": "A正确，维护自尊、避免承认失败和认知失调等心理因素会促使决策者继续投入。B正确，组织制度、责任归属、沟通方式和政治关系等可能导致决策升级。C正确，外部评价、竞争、期限等压力也可能使决策者坚持错误决策。D错误，家庭因素不属于教材归纳的主要原因类别。E正确，项目周期、投入规模、收益延迟等项目特点会影响继续投入的倾向。", "optionAnalysis": {}}, {"id": "8-37", "type": "single", "stem": "有些决策风格具有较低的模糊耐受水平，倾向于关注人和社会、这种决策风格属于（ ）。", "options": {"A": "行为类", "B": "指导类", "C": "分析类", "D": "概念类"}, "answer": "A", "analysis": "A正确，行为型的模糊耐受性较低，同时关注人和社会关系。B错误，指导型的模糊耐受性也较低，但更关注任务和技术问题。C错误，分析型关注任务和技术问题，且模糊耐受性较高。D错误，概念型关注人和社会，但模糊耐受性较高。", "optionAnalysis": {}}, {"id": "8-38", "type": "single", "stem": "决策者具有较高的模糊耐受性水平，倾向于关注人和社会，这种决策风格属于（ ）。", "options": {"A": "分析型", "B": "指导型", "C": "概念型", "D": "行为型"}, "answer": "C", "analysis": "A错误，分析型虽然具有较高的模糊耐受性，但主要关注任务和技术问题。B错误，指导型关注任务和技术问题，且模糊耐受性较低。C正确，概念型具有较高的模糊耐受性，并关注人和社会及长远影响。D错误，行为型关注人和社会，但模糊耐受性较低。", "optionAnalysis": {}}, {"id": "8-39", "type": "single", "stem": "一个独裁领导风格的人，其决策风格是（ ）。", "options": {"A": "指导型和分析型", "B": "指导型和概念型", "C": "概念型和行为型", "D": "分析型和行为型第九章组织设计与组织文化概述及其应用"}, "answer": "A", "analysis": "A正确，指导型和分析型均偏重任务、技术和理性分析，相对较少关注人和社会关系，更可能与独裁领导风格联系。B错误，概念型关注人和社会关系。C错误，概念型和行为型都偏向关注人和社会，更接近参与、沟通和支持取向。D错误，行为型重视他人感受和社会互动，不是独裁型领导的典型决策方式。", "optionAnalysis": {}}]}, {"id": 9, "title": "组织设计与组织文化概述及其应用", "questions": [{"id": "9-1", "type": "multi", "stem": "关于组织设计，描述正确的是（ ）。", "options": {"A": "静态设计只对组织结构设计", "B": "古典的设计是对组织结构的静态设计", "C": "动态设计只对组织运行制度的设计", "D": "动态设计是对组织机构和运行制度的设计", "E": "现代的组织设计是动态的"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确。静态组织设计主要研究组织结构本身，包括部门设置、管理层次、职权关系等。", "B": "正确。古典组织设计理论主要关注组织结构的设置，属于静态组织设计。", "C": "错误。动态组织设计并非只设计组织运行制度，而是同时考虑组织结构和运行制度。", "D": "正确。动态组织设计既研究组织机构，又研究规章制度、协调方式和运行机制。", "E": "正确。现代组织设计强调组织结构与运行机制的结合，并根据环境变化不断调整，具有动态性。"}}, {"id": "9-2", "type": "multi", "stem": "关于组织结构的说法，正确的有（ ）。", "options": {"A": "它本质上是企业员工的分工协作关系", "B": "它是实现组织目标的一种手段", "C": "它又称为权责结构", "D": "它在实际中通常以组织图或组织树的形式出现", "E": "它的设计理论须是动态的，而非静态的"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确。组织结构的本质是组织成员之间形成的分工协作关系。", "B": "正确。组织结构服务于组织目标，是实现组织目标的手段，而不是组织的最终目的。", "C": "正确。组织结构规定各部分的职责、权限及其相互关系，因此又称权责结构。", "D": "正确。实践中通常使用组织图或组织树直观表示组织中的部门、层级和隶属关系。", "E": "错误。组织设计理论既包括古典的静态组织设计，也包括现代的动态组织设计，不能笼统地说必须是动态而非静态。"}}, {"id": "9-3", "type": "single", "stem": "组织结构体系中的横向结构指的是（ ）。", "options": {"A": "职能结构", "B": "层次结构", "C": "部门结构", "D": "职权结构"}, "answer": "C", "analysis": "职能结构说明完成组织目标需要设置哪些职能及各职能之间的关系。\nB项错误。层次结构反映组织管理层级的构成，属于纵向结构。\nC项正确。部门结构反映各管理部门的构成及其相互关系，又称横向结构。\nD项错误。职权结构反映各层次、各部门在权力和责任方面的分工及相互关系。", "optionAnalysis": {}}, {"id": "9-4", "type": "single", "stem": "在组织结构体系中，层次结构又称为（ ）。", "options": {"A": "横向结构", "B": "职权结构", "C": "纵向结构", "D": "职能结构"}, "answer": "C", "analysis": "横向结构是部门结构，体现同一层级中部门的划分及相互关系。\nB项错误。职权结构体现权力和责任的分配关系。\nC项正确。层次结构反映组织从最高层到基层的管理层级，因此又称纵向结构。\nD项错误。职能结构反映组织各项业务职能的构成及其联系。", "optionAnalysis": {}}, {"id": "9-5", "type": "single", "stem": "在组织结构设计体系中，能够体现出组织的各管理层次、部门在权力和责任方面的分工和相互关系的是（ ）。", "options": {"A": "层次结构", "B": "部门结构", "C": "职能结构", "D": "职权结构"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误。层次结构主要反映管理层级的多少及上下级之间的纵向关系。", "B": "错误。部门结构主要反映部门的组成及部门之间的横向关系。", "C": "错误。职能结构主要反映组织目标所需职能及各职能之间的关系。", "D": "正确。职权结构专门反映各管理层次、各部门在权力和责任方面的分工及相互关系。"}}, {"id": "9-6", "type": "multi", "stem": "关于管理层次和管理幅度之间关系的说法，正确的是（ ）。", "options": {"A": "管理幅度与管理层次存在正相关关系", "B": "两者存在负相关关系", "C": "二者相互制约，其中管理幅度起主导作用", "D": "二者相互制约，其中管理层次起主导作用", "E": "管理幅度和管理层次都是组织结构的特征因素"}, "answer": "BCE", "analysis": "", "optionAnalysis": {"A": "错误。在组织规模和工作量基本确定的情况下，管理幅度越大，所需管理层次通常越少，二者不是正相关关系。", "B": "正确。管理幅度与管理层次一般呈反向变化，即负相关关系。", "C": "正确。管理幅度和管理层次相互制约，其中管理幅度的大小直接影响管理层次的多少，通常起主导作用。", "D": "错误。教材理论通常认为管理幅度起主导作用，而不是管理层次起主导作用。", "E": "正确。管理幅度和管理层次都属于衡量组织结构特征的重要因素。"}}, {"id": "9-7", "type": "single", "stem": "关于组织结构特征因素中的管理层次的说法错误的是（ ）。", "options": {"A": "管理层次也称为组织层次", "B": "管理层次越多，说明组织结构的纵向复杂程度越高", "C": "管理层次的多少取决于管理幅度的大小", "D": "管理层次是指一名管理者直接领导的下级人员的数量"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确。管理层次也称组织层次，是组织中从最高管理层到基层管理层的层级数量。", "B": "正确。管理层次越多，纵向分工越细，组织结构的纵向复杂程度越高。", "C": "正确。在组织规模相对稳定时，管理幅度越小，通常需要的管理层次越多；管理幅度越大，管理层次通常越少。", "D": "错误。一名管理者直接领导的下级人员数量是管理幅度的含义，不是管理层次的含义。题目要求选择错误说法，因此选D。"}}, {"id": "9-8", "type": "multi", "stem": "在组织结构设计的参数中，属于组织结构的权变因素的有（ ）。", "options": {"A": "组织生命周期", "B": "专业化程度", "C": "组织规模", "D": "制度化程度", "E": "规范化程度"}, "answer": "AC", "analysis": "", "optionAnalysis": {"A": "正确。组织在不同生命周期阶段面临的管理任务和环境不同，因此组织生命周期是组织结构设计的权变因素。", "B": "错误。专业化程度是组织结构自身的特征因素，反映组织中工作分工的细致程度。", "C": "正确。组织规模会影响部门设置、管理层次、规范化程度等，是重要的权变因素。", "D": "错误。制度化程度属于组织结构特征因素，反映组织依靠规章制度规范成员行为的程度。", "E": "错误。规范化程度属于组织结构特征因素，反映员工以同种方式完成相似工作的程度。"}}, {"id": "9-9", "type": "multi", "stem": "下列属于组织结构权变因素的有（ ）。", "options": {"A": "组织环境", "B": "组织战略", "C": "地区分布", "D": "组织规模", "E": "组织生命周期"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确。环境的复杂性和动态性会影响组织采用机械式结构还是有机式结构。", "B": "正确。组织结构应当与组织战略相匹配，因此组织战略是重要的权变因素。", "C": "错误。地区分布通常作为组织结构的特征因素，用于反映组织各机构在地域上的分布情况。", "D": "正确。组织规模会影响管理层次、专业化、规范化和部门设置。", "E": "正确。组织在创立、成长、成熟等不同阶段具有不同的结构要求，组织生命周期属于权变因素。"}}, {"id": "9-10", "type": "single", "stem": "员工以同种方式完成相似工作的程度是指（ ）。", "options": {"A": "制度化", "B": "集权度", "C": "专业化", "D": "规范化"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误。制度化强调组织依靠正式规章、程序和制度规范成员行为的程度。", "B": "错误。集权度反映组织中的决策权集中于较高管理层的程度。", "C": "错误。专业化反映组织工作被划分为不同岗位或任务的细致程度。", "D": "正确。规范化是指员工以相同方式完成相似工作的程度，通常通过工作标准、操作流程等实现。"}}, {"id": "9-11", "type": "single", "stem": "在组织结构设计的主要参数中，可以用员工接受正规教育和培训的程度来衡量的是（ ）。", "options": {"A": "制度化程度", "B": "集权化程度", "C": "规范化程度", "D": "职业化程度"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误。制度化程度主要通过组织中正式规章制度和程序的数量及约束程度衡量。", "B": "错误。集权化程度主要通过决策权在组织层级中的集中程度衡量。", "C": "错误。规范化程度主要通过相似工作是否按照统一标准和程序完成来衡量。", "D": "正确。职业化程度可以用员工接受正规教育和专业培训的程度来衡量，教育和培训程度越高，通常表明职业化程度越高。"}}, {"id": "9-12", "type": "single", "stem": "行政层级式设计形式最适用的环境类型是（ ）。", "options": {"A": "简单/动态环境", "B": "复杂/静态环境", "C": "简单/静态环境", "D": "复杂/动态环境"}, "answer": "B", "analysis": "简单但动态的环境需要组织具有一定灵活性，行政层级式结构的严格规则和层级控制可能妨碍快速反应。\nB项正确。行政层级式组织强调规章制度、专业分工和职权等级，适合环境因素较多但变化相对稳定的复杂、静态环境。\nC项错误。简单、静态环境更适合结构相对简明、权力较集中的组织形式。\nD项错误。复杂、动态环境需要较强的横向协调和快速应变能力，严格的行政层级式结构通常难以适应。", "optionAnalysis": {}}, {"id": "9-13", "type": "single", "stem": "职能制组织设计形式最适用的环境类型是（ ）。", "options": {"A": "复杂/动态环境", "B": "简单/静态环境", "C": "复杂/静态环境", "D": "简单/动态环境"}, "answer": "B", "analysis": "复杂、动态环境需要跨职能的快速协作，单纯职能制容易形成部门壁垒，适应性不足。\nB项正确。职能制按照专业职能划分部门，强调专业化和集中控制，最适合外部环境简单、变化稳定的组织。\nC项错误。复杂环境需要处理更多差异化信息，单一职能链条的协调能力可能不足。\nD项错误。动态环境要求快速响应，而职能制中的纵向沟通和部门分割可能降低响应速度。", "optionAnalysis": {}}, {"id": "9-14", "type": "single", "stem": "具有直线—参谋制特点的组织形式属于（ ）。", "options": {"A": "行政层级式", "B": "矩阵组织形式", "C": "职能制形式", "D": "事业部制形式"}, "answer": "C", "analysis": "行政层级式组织的核心特征是明确的职权等级、专业分工和规章制度，不以直线—参谋制作为其特定称谓。\nB项错误。矩阵组织同时按职能和产品或项目建立结构，员工通常接受双重领导。\nC项正确。职能制组织也称法约尔模型，其主要特点是职能分工和直线—参谋制。\nD项错误。事业部制主要按照产品、地区或顾客等设立相对独立的事业部，实行集中决策、分散经营。", "optionAnalysis": {}}, {"id": "9-15", "type": "single", "stem": "职能制组织说法错误的是（ ）。", "options": {"A": "直线—参谋制", "B": "强调职能分工", "C": "避免管理权力高度集中", "D": "法约尔模型"}, "answer": "C", "analysis": "职能制具有直线—参谋制的特点，直线管理人员统一指挥，职能专家提供专业支持。\nB项正确。职能制按照生产、财务、人力资源等专业职能划分部门，强调职能分工。\nC项错误。职能制通常具有较高的集权程度，重要决策集中于高层，并不能避免管理权力高度集中。题目要求选择错误说法，因此选C。\nD项正确。职能制组织又称法约尔模型。", "optionAnalysis": {}}, {"id": "9-16", "type": "single", "stem": "矩阵组织形式的主要特点不包括（ ）。", "options": {"A": "通常实行直线—参谋制", "B": "一名员工有两位领导", "C": "产品部门形成的横向联系灵活多样", "D": "组织内部有两个层次的协调"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "不属于矩阵组织的主要特点。直线—参谋制主要是职能制组织的特点，矩阵组织的核心是职能结构与产品或项目结构交叉结合。", "B": "属于矩阵组织的特点。员工通常同时接受职能经理和产品经理或项目经理的领导。", "C": "属于矩阵组织的特点。产品或项目部门形成横向联系，有利于跨职能协调，联系方式较灵活。", "D": "属于矩阵组织的特点。矩阵结构中既存在职能维度的协调，也存在产品或项目维度的协调，形成两个层次或两个方向的协调。"}}, {"id": "9-17", "type": "single", "stem": "矩阵组织形式最有效的适用环境为（ ）。", "options": {"A": "复杂/动态的", "B": "简单/静态的", "C": "复杂/静态的", "D": "简单/动态的"}, "answer": "A", "analysis": "复杂、动态环境中的任务变化快，涉及多个专业领域，需要加强职能部门与产品或项目部门之间的横向协调，矩阵组织最能发挥作用。\nB项错误。简单、静态环境不需要复杂的双重协调机制，采用矩阵结构会增加管理成本。\nC项错误。复杂但静态的环境更强调专业化和制度化管理，并非矩阵组织最有效的典型环境。\nD项错误。简单、动态环境虽然需要灵活性，但环境复杂程度不足以充分体现矩阵结构双重协调的必要性。", "optionAnalysis": {}}, {"id": "9-18", "type": "single", "stem": "矩阵组织形式的缺点不包括（ ）。", "options": {"A": "容易导致机构臃肿，用人较多", "B": "会导致组织的稳定性差", "C": "容易产生责任不清、多头指挥的混乱现象", "D": "会增加高层管理者的负担"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "属于矩阵组织的缺点。双重管理系统及协调岗位可能增加机构和人员数量，导致管理成本上升。", "B": "属于矩阵组织的缺点。产品或项目团队通常随任务设立和调整，可能使组织稳定性较差。", "C": "属于矩阵组织的缺点。员工接受双重领导，如果职权边界不清，容易出现责任不清和多头指挥。", "D": "不属于其典型缺点。矩阵组织通过产品或项目负责人承担横向协调工作，可以分担高层管理者的协调负担，而不是必然增加其负担。"}}, {"id": "9-19", "type": "single", "stem": "一个企业形成了有特色的组织文化对组织内部会产生很大影响，还对本地其他企业和社会公众产生了一定影响，这主要体现了组织文化的（ ）。", "options": {"A": "凝聚作用", "B": "规范作用", "C": "制约作用", "D": "辐射作用"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误。凝聚作用是指共同价值观把组织成员团结起来，增强其归属感和认同感，主要作用于组织内部。", "B": "错误。规范作用是指组织文化通过共同准则引导和规范成员行为。", "C": "错误。制约作用强调组织文化对不符合共同价值观的行为形成约束。", "D": "正确。组织文化不仅影响组织内部成员，还通过产品、服务、员工行为和社会形象影响其他企业及社会公众，体现的是辐射作用。"}}, {"id": "9-20", "type": "single", "stem": "能折射出组织的经营思想，工作作风和审美的外显标识的是（ ）。", "options": {"A": "物质层", "B": "中间层", "C": "精神层", "D": "制度层"}, "answer": "A", "analysis": "物质层是组织文化的外显部分，包括组织名称、标志、工作环境、产品外观、建筑风格等，能够折射组织的经营思想、工作作风和审美意识。\nB项错误。组织文化通常划分为物质层、制度层和精神层，“中间层”不是与三层结构并列的规范名称；制度层可被视为中间层次。\nC项错误。精神层是组织文化的核心和深层内容，包括共同价值观、经营哲学和组织精神，但不是题目所说的外显标识。\nD项错误。制度层包括规章制度、行为规范和组织结构等，具有规范和约束作用，不属于最直观的外显标识。", "optionAnalysis": {}}, {"id": "9-21", "type": "single", "stem": "关于组织文化的说法，错误的是（ ）。", "options": {"A": "它是指组织成员的共同价值观体系", "B": "它的形成在很大程度上取决于基层员工的行为方式", "C": "它具有凝聚作用", "D": "它的结构包括物质层、制度层和精神层三个层次"}, "answer": "B", "analysis": "组织文化的核心是组织成员共同认可和遵循的价值观体系。\nB项错误。组织文化的形成在很大程度上受组织创始人和最高管理层的价值观、经营理念及行为方式影响，并非主要取决于基层员工的行为方式。题目要求选择错误说法，因此选B。\nC项正确。共同价值观能够增强成员的归属感和认同感，使组织产生凝聚作用。\nD项正确。组织文化通常包括物质层、制度层和精神层，其中精神层是核心。", "optionAnalysis": {}}, {"id": "9-22", "type": "single", "stem": "按照桑南菲尔德的组织文化分类、堡垒型组织的主要特征是（ ）。", "options": {"A": "非常重视适应、忠诚感和承诺", "B": "着眼于公司的生存", "C": "鼓励冒险和革新", "D": "喜欢雇用年轻的大学毕业生，并为其提供专门的培训"}, "answer": "B", "analysis": "重视员工适应、忠诚感和承诺是俱乐部型组织文化的主要特征。\nB项正确。堡垒型组织通常处于经营压力较大或环境不稳定的状态，主要着眼于组织生存，工作保障程度较低。\nC项错误。鼓励冒险和革新、重视绩效与人才能力是棒球队型组织文化的特征。\nD项错误。喜欢招聘年轻大学毕业生并进行专门培训，重视员工长期发展，是学院型组织文化的特征。", "optionAnalysis": {}}, {"id": "9-23", "type": "single", "stem": "重视员工的适应、忠诚感和承诺的组织文化称为（ ）组织文化。", "options": {"A": "学院型", "B": "棒球队型", "C": "俱乐部型", "D": "堡垒型"}, "answer": "C", "analysis": "学院型组织重视员工的专业化成长，通常招聘年轻毕业生并通过培训使其沿专业路径发展。\nB项错误。棒球队型组织重视创新、冒险和个人能力，通常从外部吸引高水平人才。\nC项正确。俱乐部型组织强调员工对组织的适应、忠诚和承诺，重视资历及组织内部培养。\nD项错误。堡垒型组织关注组织生存，员工工作保障程度较低。", "optionAnalysis": {}}, {"id": "9-24", "type": "single", "stem": "关于企业文化类型中，喜欢冒险、具有革新精神的属于（ ）。", "options": {"A": "学院型", "B": "棒球队型", "C": "俱乐部型", "D": "堡垒型"}, "answer": "B", "analysis": "学院型组织注重专业训练和员工长期职业发展，并非主要突出冒险精神。\nB项正确。棒球队型组织重视人才、创新和绩效，鼓励员工冒险并发挥革新精神。\nC项错误。俱乐部型组织强调忠诚、承诺、适应性和组织内部培养。\nD项错误。堡垒型组织主要关注在困难环境中的生存，员工安全感相对较低。", "optionAnalysis": {}}, {"id": "9-25", "type": "multi", "stem": "关于组织设计与组织文化之间关系的说法，正确的是（ ）。", "options": {"A": "组织的制度化程度越高，组织文化就越倾向于严谨", "B": "强调等级制度的组织设计，很难形成公平、自由参与的组织文化", "C": "管理层次多、结构复杂的组织，有利于鼓励员工独立决策", "D": "级别差别很大的薪酬制度适合于强调等级的组织文化，不适合崇尚平等的组织文化", "E": "高度的规范化有利于形成鼓励多样化、创新的组织文化"}, "answer": "ABD", "analysis": "", "optionAnalysis": {"A": "正确。制度化程度越高，规章制度和正式程序越完善，组织文化通常越强调严谨、秩序和一致性。", "B": "正确。强调等级制度的组织通常权力距离较大，员工参与程度受到限制，较难形成强调公平、自由参与的文化。", "C": "错误。管理层次多、结构复杂通常会延长决策链条、强化纵向控制，不利于基层员工独立决策。", "D": "正确。级别差别较大的薪酬制度能够强化身份和等级差异，与强调等级的文化相适应，但与崇尚平等的文化不相匹配。", "E": "错误。高度规范化要求成员按照统一方式工作，会限制行为差异和自主探索，通常不利于形成鼓励多样化和创新的组织文化。"}}, {"id": "9-26", "type": "single", "stem": "在组织变革的方法中，调整组织管理层次和管理幅度的做法属于（ ）。", "options": {"A": "以结构为中心的变革", "B": "以人员为中心的变革", "C": "以文化为中心的变革", "D": "以技术为中心的变革"}, "answer": "A", "analysis": "管理层次和管理幅度是组织结构的基本要素，对其进行调整属于以结构为中心的组织变革。\nB项错误。以人员为中心的变革主要通过培训、沟通、激励和行为干预等方式改变员工态度与行为。\nC项错误。以文化为中心的变革主要调整组织共同价值观、行为规范和管理理念。\nD项错误。以技术为中心的变革主要涉及生产技术、设备、工作流程和信息系统等方面。", "optionAnalysis": {}}, {"id": "9-27", "type": "multi", "stem": "在组织发展方法中，属于结构技术类型的有（ ）。", "options": {"A": "调查反馈", "B": "敏感性训练", "C": "合并职能部门", "D": "实验室训练", "E": "工作再设计"}, "answer": "CE", "analysis": "", "optionAnalysis": {"A": "错误。调查反馈通过收集成员意见并反馈结果，促进沟通和行为改进，属于人文技术。", "B": "错误。敏感性训练通过群体互动提高成员对自己及他人行为的认识，属于人文技术。", "C": "正确。合并职能部门会直接改变部门设置和组织结构，属于结构技术。", "D": "错误。实验室训练主要通过人际互动和体验学习改善个人及群体行为，属于人文技术。", "E": "正确。工作再设计通过重新安排工作内容、职责和工作关系改变组织运行方式，属于结构技术。"}}, {"id": "9-28", "type": "multi", "stem": "组织发展方法中的人文技术，包括（ ）。", "options": {"A": "敏感性训练", "B": "工作再设计", "C": "调查反馈", "D": "质量圈", "E": "群体间关系的开发"}, "answer": "ACDE", "analysis": "", "optionAnalysis": {"A": "正确。敏感性训练通过群体互动提高成员的自我认知、人际敏感性和沟通能力，属于人文技术。", "B": "错误。工作再设计通过调整工作内容、职责和工作关系改变组织结构与运行方式，属于结构技术。", "C": "正确。调查反馈通过调查组织成员的态度和意见，并将结果反馈给有关人员以推动改进，属于人文技术。", "D": "正确。质量圈由员工自愿组成小组，分析并解决工作质量问题，强调员工参与和群体合作，属于人文技术。", "E": "正确。群体间关系的开发旨在改善不同群体之间的沟通、认知和合作关系，属于人文技术。"}}, {"id": "9-29", "type": "multi", "stem": "关于组织发展目的的说法，正确的有（ ）。", "options": {"A": "它重视对人的尊重", "B": "它重视合作与参与过程", "C": "它重视权力与控制", "D": "它重视质询精神", "E": "它重视人员和组织的成长第十章劳动力市场理论及其应用"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确。组织发展坚持以人为本，重视人的价值、尊严和需要。", "B": "正确。组织发展强调成员参与、团队合作和共同解决问题的过程。", "C": "错误。组织发展强调授权、信任、合作和参与，而不是强调权力集中与控制。", "D": "正确。组织发展鼓励成员以开放态度审视和质询既有观念、制度及工作方式，从而发现问题并推动变革。", "E": "正确。组织发展的目标包括促进员工个人成长、提高组织效能以及增强组织适应环境变化的能力。"}}]}, {"id": 10, "title": "劳动力市场理论及其应用", "questions": [{"id": "10-1", "type": "single", "stem": "劳动力市场是进行劳动力交易的一种（ ）市场。", "options": {"A": "期货", "B": "资本", "C": "要素", "D": "产品"}, "answer": "C", "analysis": "劳动力是生产过程中投入的一种重要生产要素，劳动力市场是对劳动力资源进行配置的要素市场。", "optionAnalysis": {"A": "错误，期货市场交易的是标准化期货合约；", "B": "错误，资本市场主要进行中长期资金及相关金融工具交易；", "C": "正确；", "D": "错误，产品市场交易的是最终产品或服务，而非劳动力这种生产要素。"}}, {"id": "10-2", "type": "single", "stem": "关于劳动力市场特征的说法，正确的是（ ）。", "options": {"A": "通过劳动力市场交易实现的是劳动力所有权的转移", "B": "劳动力市场交易的唯一条件是工资", "C": "劳动力市场在很多时候是无形的", "D": "劳动力市场实现的劳动力供求匹配是永久性的"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，劳动力依附于劳动者本人，交易中转移的是一定期限内的劳动力使用权，不是劳动力所有权。", "B": "错误，劳动者除工资外还会考虑工作时间、工作环境、福利、晋升机会和职业稳定性等非工资条件。", "C": "正确，劳动力供求双方可以通过招聘平台、广告、职业介绍和社会关系等方式完成匹配，通常不需要固定的有形交易场所。", "D": "错误，雇佣关系具有期限性和可变性，供求匹配并非永久不变。"}}, {"id": "10-3", "type": "multi", "stem": "关于劳动力市场的说法，正确的有（ ）。", "options": {"A": "它能够以一定的工资率将劳动力有效分配到不同的行业、职业、地区和企业之中", "B": "它是由各种局部性劳动力市场构成的一个总劳动力市场体系", "C": "它是特定的劳动力供求双方通过自由谈判达成劳动力使用权转让合约时所处的市场环境", "D": "它是在市场经济条件下对劳动力这种生产性资源进行有效配置的根本手段", "E": "它是一种特殊的产品市场"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，工资率及其他就业条件会引导劳动力在行业、职业、地区和企业之间配置。", "B": "正确，总劳动力市场由不同地区、职业、行业和层次的局部劳动力市场构成。", "C": "正确，劳动力市场是供求双方协商并订立劳动力使用权转让合约的市场环境。", "D": "正确，市场经济通过劳动力市场实现劳动力资源配置。", "E": "错误，劳动力市场属于生产要素市场，而不是产品市场。"}}, {"id": "10-4", "type": "multi", "stem": "关于劳动力市场的说法，正确的是（ ）。", "options": {"A": "劳动力市场是一种有形的市场", "B": "在劳动力市场的交易中转移的是劳动力所有权", "C": "劳动力市场交易的决定因素并非仅仅工资这一个条件", "D": "当劳动力市场上存在供小于求的情况时，劳动者的议价能力更强", "E": "对劳动力市场的交易对象进行测量并不困难"}, "answer": "CD", "analysis": "", "optionAnalysis": {"A": "错误，劳动力市场很多时候是无形市场，不以固定交易场所为必要条件。", "B": "错误，交易的是一定期限内的劳动力使用权。", "C": "正确，工资、福利、工作环境、职业发展和就业稳定性等都会影响交易。", "D": "正确，劳动力供不应求时，劳动者的稀缺性增强，通常具有更强的议价能力。", "E": "错误，劳动能力、努力程度和潜在生产率难以在雇用前被准确测量。"}}, {"id": "10-5", "type": "multi", "stem": "劳动力市场的特点包括（ ）。", "options": {"A": "劳动力市场是多样的", "B": "劳动力市场是有形的", "C": "劳动力购买方所处的地位更为不利", "D": "劳动力市场交易对象具有难以衡量性", "E": "劳动力市场交易具有延续性"}, "answer": "ADE", "analysis": "", "optionAnalysis": {"A": "正确，不同职业、技能、地区和行业会形成不同的劳动力市场。", "B": "错误，劳动力市场往往是无形的。", "C": "错误，劳动者通常无法储存劳动力，且寻找工作存在时间压力，因而劳动力购买方并非必然处于更不利地位。", "D": "正确，劳动者的能力、努力程度和实际生产率难以事先准确衡量。", "E": "正确，雇佣合同履行和人力资本积累通常持续较长时间，交易具有延续性。"}}, {"id": "10-6", "type": "single", "stem": "劳动力市场的多样性是指（ ）。", "options": {"A": "劳动力市场上有多种不同的职业介绍机构", "B": "劳动力市场的交易条件复杂多样", "C": "劳动力市场会促成很多不同的雇佣合同", "D": "不同类型的劳动力有不同的劳动力市场"}, "answer": "D", "analysis": "劳动力具有职业、技能、经验和地区等方面的差异，不同类型劳动力难以完全替代，因此会形成彼此有区别的劳动力市场。", "optionAnalysis": {"A": "只是求职渠道多样；", "B": "反映交易条件的复杂性；", "C": "是多样性的可能表现，但不是该特征的核心含义；", "D": "准确说明劳动力市场多样性的本质。"}}, {"id": "10-7", "type": "single", "stem": "劳动力市场的说法错误的有（ ）。", "options": {"A": "不同的技术能力和经验，说明了劳动力的多样性", "B": "劳动力市场交易的是劳动力所有权，体现了特殊性", "C": "劳动者找工作既看工资也看非工资就业条件，说明了复杂性", "D": "劳动者通过招聘广告等方式找工作，体现了不确定性"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，不同劳动者的技术、经验和生产能力存在差异，体现劳动力及其市场的多样性。B项错误，劳动力市场交易的是一定期限内的劳动力使用权，劳动力所有权仍属于劳动者本人。", "C": "正确，劳动力交易需要综合考虑工资和非工资就业条件，体现交易的复杂性。", "D": "正确，招聘广告等方式只能提供信息，劳动者最终能否找到适合的工作仍存在不确定性。"}}, {"id": "10-8", "type": "multi", "stem": "关于劳动力市场交易的延续性的说法，正确的有（ ）。", "options": {"A": "员工愿意继续留在公司的原因之一是企业中的某些特殊报酬项目与员工在企业中的连续服务年限有关", "B": "企业愿意选拔雇用老员工的原因之一是员工在工作后会积累一些有价值的工作经验", "C": "员工愿意继续留在公司的原因之一是他们在本企业中积累的特殊技能使他们在本企业中所获得的工资高于到其他企业所获得的工资", "D": "劳动力市场交易的延续性使雇佣双方之间的关系变得复杂", "E": "服务合同的续签主要是为了保护员工的利益，对企业价值不大"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，工龄工资、年金和长期服务奖励等会提高员工继续留任的收益。", "B": "正确，老员工积累的经验和企业专用知识具有价值，企业有保留和内部选拔老员工的动力。", "C": "正确，企业特殊技能在本企业中的回报通常更高，会降低员工离职意愿。", "D": "正确，长期雇佣涉及培训、晋升、激励和合同调整，使双方关系更复杂。", "E": "错误，续签合同既能保护员工，也能帮助企业保留经验和专用人力资本，对企业同样具有价值。"}}, {"id": "10-9", "type": "multi", "stem": "为了应对劳动力市场交易对象的难以衡量性问题，企业通常可以采取（ ）做法以判断求职者的质量。", "options": {"A": "提供高于市场水平的工资", "B": "利用受教育程度、工作经验等依据", "C": "加强对新员工的培训", "D": "利用面试、笔试和心理测试等手段", "E": "规定试用期"}, "answer": "BDE", "analysis": "", "optionAnalysis": {"A": "错误，支付高工资可能用于吸引和激励高生产率劳动者，但不是直接判断具体求职者质量的甄选手段。", "B": "正确，学历和工作经验可作为反映求职者能力的信号。", "C": "错误，培训主要用于提高员工能力，而不是在招聘阶段判断其原有质量。", "D": "正确，面试、笔试和心理测试可以收集求职者能力及特征信息。", "E": "正确，试用期便于企业通过实际工作表现进一步判断员工质量。"}}, {"id": "10-10", "type": "single", "stem": "优等劳动力市场和次等劳动力市场相对隔离的主要原因是（ ）。", "options": {"A": "两种劳动力市场存在工作条件差异", "B": "两种劳动力市场存在工资福利水平差异", "C": "两种劳动力市场存在技能要求差异", "D": "两种劳动力市场存在工作保障性差异"}, "answer": "C", "analysis": "优等劳动力市场通常要求较高的人力资本、专业技能和经验，次等劳动力市场的技能要求相对较低。劳动者取得相应技能需要教育、培训和经验积累，因此难以在两个市场之间自由流动。A、\nB、D项都是两个市场的常见差异或结果，但造成市场相对隔离的主要原因是技能要求不同。", "optionAnalysis": {}}, {"id": "10-11", "type": "single", "stem": "关于建立内部劳动力市场的企业具有的特点，错误的说法是（ ）。", "options": {"A": "员工流动性较高", "B": "员工为获得晋升通常会努力工作", "C": "管理人员原则上从组织内部产生", "D": "基本上只从外部劳动力市场雇佣基层员工"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误，内部劳动力市场强调长期雇佣、内部晋升和企业专用人力资本积累，员工流动性通常较低。", "B": "正确，内部晋升机会能够形成竞赛和激励。", "C": "正确，管理岗位通常优先从组织内部选拔。", "D": "正确，企业一般在入口岗位从外部招聘，再通过内部晋升填补较高层级岗位。"}}, {"id": "10-12", "type": "single", "stem": "若想通过向员工支付高工资确保他们达成高生产率，一个重要的前提条件是（ ）。", "options": {"A": "劳动者期望长期在企业中工作", "B": "企业只在短期中雇用劳动者", "C": "企业内部的工资差距足够大", "D": "企业对所有的员工都支付高工资"}, "answer": "A", "analysis": "效率工资发挥激励作用的重要条件是员工重视当前工作和未来工资收益。劳动者预期长期留在企业时，因偷懒或低绩效而失去高工资工作的机会成本较大，因此更愿意努力工作。B项会削弱长期激励；C项不是效率工资产生作用的必要前提；D项也不是必要条件，关键在于实际工资高于员工可获得的外部工资。", "optionAnalysis": {}}, {"id": "10-13", "type": "single", "stem": "企业支付超过市场均衡水平高工资的说法，错误的是（ ）。", "options": {"A": "企业支付的这种高工资称为绩效工资", "B": "这种高工资有助于吸引生产率更高的员工", "C": "这种高工资有助于降低员工的离职率", "D": "这种做法在员工期望与企业保持长期雇佣关系的情况下更有意义"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误，企业主动支付高于市场均衡水平的工资通常称为效率工资；绩效工资是与员工或组织绩效挂钩的报酬。", "B": "正确，高工资可以扩大应聘者范围并吸引能力较强的劳动者。", "C": "正确，高工资提高离职的机会成本，有助于降低离职率。", "D": "正确，长期雇佣预期能强化高工资对努力程度和忠诚度的激励作用。"}}, {"id": "10-14", "type": "multi", "stem": "关于晋升竞赛，下列说法正确的是（ ）。", "options": {"A": "候选人之间有较高的可比性，有助于激发候选人的最大努力", "B": "候选人在晋升竞赛过程中展现出来的优势越充分，获胜后得到的工资水平越高", "C": "晋升后各种职位和工资率通常是事先设计好的", "D": "晋升竞赛中可以同时有多位候选者", "E": "晋升后的工资差距太小可能会在一定程度上削弱竞赛参与者的努力动机"}, "answer": "ACDE", "analysis": "", "optionAnalysis": {"A": "正确，可比性较高能使竞赛结果更能反映相对绩效，并激励候选人努力。", "B": "错误，锦标赛理论中晋升后职位及工资通常预先确定，获胜者的工资并不随其领先幅度自动提高。", "C": "正确，预先确定的职位和工资差距构成竞赛奖励。", "D": "正确，多个候选人可以围绕有限晋升岗位展开竞争。", "E": "正确，晋升前后工资差距过小会降低获胜收益，削弱努力动机。"}}, {"id": "10-15", "type": "multi", "stem": "社会的劳动力供给总量的决定因素有（ ）。", "options": {"A": "工资水平", "B": "劳动力参与率", "C": "人口的平均受教育程度", "D": "人口总量", "E": "周工作时间"}, "answer": "BDE", "analysis": "社会劳动力供给总量可从人数和时间两个维度理解，主要取决于人口总量、劳动年龄人口的劳动力参与率以及劳动者平均工作时间。B项决定有多少劳动年龄人口进入劳动力市场；D项决定潜在劳动力规模；E项决定每名劳动者提供的劳动时间。", "optionAnalysis": {"A": "会影响个人供给决策，但不是教材在此处概括社会供给总量构成时列出的直接数量因素。", "C": "主要影响劳动力质量和结构，不直接决定劳动力供给总量。"}}, {"id": "10-16", "type": "single", "stem": "某国家，16岁以上的人口是600万，就业人口320万，失业人口40万，16岁以下的500万人，该国家的劳动参与率是（ ）。", "options": {"A": "50%", "B": "60%", "C": "75%", "D": "80%"}, "answer": "B", "analysis": "劳动力人口＝就业人口＋失业人口＝320＋40＝360（万人）。劳动参与率＝劳动力人口÷16岁以上人口×100%＝360÷600×100%＝60%。16岁以下人口不属于本题劳动参与率分母，不参与计算，因此选择B。", "optionAnalysis": {}}, {"id": "10-17", "type": "single", "stem": "人口1000w，低于16岁人口200w，就业人口550w，失业人口50w，劳动参与率是多少（ ）。", "options": {"A": "60%", "B": "80%", "C": "75%", "D": "55%"}, "answer": "C", "analysis": "16岁以上人口＝1000－200＝800（万人）；劳动力人口＝就业人口＋失业人口＝550＋50＝\n600（万人）。劳动参与率＝600÷800×100%＝75%，因此选择C。", "optionAnalysis": {}}, {"id": "10-18", "type": "single", "stem": "关于保留工资，说法错误的是（ ）。", "options": {"A": "劳动者的保留工资越高，劳动力参与率越低", "B": "保留工资就是本地最低工资", "C": "保留工资是一种工资的心理价位", "D": "每个人的保留工资存在差异"}, "answer": "B", "analysis": "保留工资是劳动者愿意接受市场工作的最低工资水平。", "optionAnalysis": {"A": "正确，其他条件相同时，保留工资越高，市场工资达到其接受标准的可能性越低，劳动参与率也越低。", "B": "错误，最低工资是法定工资标准，保留工资是劳动者个人的主观接受下限，两者并不相同。", "C": "正确，保留工资可理解为个人接受工作的工资心理价位。", "D": "正确，不同劳动者的非劳动收入、家庭责任、偏好和机会成本不同，保留工资也会不同。"}}, {"id": "10-19", "type": "single", "stem": "关于劳动者个人的劳动力供给的说法，正确的是（ ）。", "options": {"A": "工资率越低，劳动者的劳动力供给时间越多", "B": "工资率在很大程度上取决于劳动者的劳动力供给时间", "C": "劳动者的劳动力供给时间在很大程度上取决于工资率", "D": "工资率越高，劳动者的劳动力供给时间越多"}, "answer": "C", "analysis": "个人需要在市场工作时间和闲暇时间之间进行分配，工资率代表闲暇的机会成本，因此劳动供给时间在很大程度上受工资率影响。", "optionAnalysis": {"A": "把两者概括为单一反向关系，忽略收入效应和替代效应。B项颠倒了个人劳动供给分析中的主要因果方向。", "C": "正确。", "D": "也将关系简单化；工资较高时，收入效应可能超过替代效应，使劳动供给时间减少。"}}, {"id": "10-20", "type": "single", "stem": "关于劳动供给中的收入效应和替代效应的说法，正确的是（ ）。", "options": {"A": "其他条件一定，工资率下降的收入效应会导致劳动力供给增加", "B": "其他条件一定，工资率上升的替代效应会导致劳动力供给减少", "C": "工资率下降的收入效应和替代效应同时导致劳动力供给增加", "D": "工资率上升的收入效应和替代效应同时导致劳动力供给减少"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，工资率下降使劳动者实际收入减少；若闲暇是正常品，收入减少会促使其减少闲暇、增加工作时间，这就是工资下降的收入效应。", "B": "错误，工资上升会提高闲暇的机会成本，替代效应促使劳动者减少闲暇、增加劳动供给。", "C": "错误，工资下降的替代效应会使闲暇相对便宜，从而增加闲暇、减少劳动供给。", "D": "错误，工资上升的收入效应倾向于减少劳动供给，但替代效应倾向于增加劳动供给，两者方向相反。"}}, {"id": "10-21", "type": "single", "stem": "个人劳动力供给曲线的形状表明，在其他条件一定的情况下，劳动力供给与工资率变化之间的关系是（ ）。", "options": {"A": "劳动力供给先随工资率的上升而下降，后来随工资率上升而上升", "B": "劳动力供给随工资率的上升而下降", "C": "劳动力供给随工资率的上升而上升", "D": "劳动力供给先随工资率的上升而上升，后来随工资率上升而下降"}, "answer": "D", "analysis": "个人劳动力供给曲线通常呈向后弯曲形状。在工资率较低的阶段，替代效应较强，工资上升会促使劳动者增加工作时间；当工资达到较高水平后，收入效应可能超过替代效应，劳动者会购买更多闲暇，从而减少工作时间。因此劳动供给先上升、后下降，选择D。", "optionAnalysis": {}}, {"id": "10-22", "type": "single", "stem": "一些国家征收高额遗产税，目的之一在于（ ）。", "options": {"A": "抑制工资率上涨的收入效应对劳动力的供给产生不利影响", "B": "抑制非劳动收入对劳动力需求产生的不利影响", "C": "抑制上涨替代效应对劳动供给产生的不利影响", "D": "抑制非劳动收入对劳动力供给产生的不利影响"}, "answer": "D", "analysis": "遗产属于非劳动收入。非劳动收入增加会提高劳动者对闲暇的需求，可能降低其劳动参与意愿或劳动供给时间。征收较高遗产税可以在一定程度上减弱巨额非劳动收入对劳动供给的抑制作用。\nA、C项讨论工资变动效应，与遗产税的直接对象不符；B项错误，非劳动收入主要影响劳动者的供给决策，而不是企业的劳动力需求。", "optionAnalysis": {}}, {"id": "10-23", "type": "single", "stem": "当某地家政服务人员的工资率为每小时20元时，此类人员的供给人数为50万人，家政服务人员的工资率上升到每小时25元后，此类人员的月供给量为60万人，家政服务人员的劳动力供给是（ ）。", "options": {"A": "单位弹性的", "B": "无弹性的", "C": "富有弹性的", "D": "缺乏弹性的"}, "answer": "D", "analysis": "按题目通常采用的初始值计算法：劳动力供给量变动率＝（60－50）÷50×100%＝20%；工资率变动率＝（25－20）÷20×100%＝25%；劳动力供给弹性＝20%÷25%＝0.8。弹性绝对值小于1，说明供给量变动幅度小于工资率变动幅度，属于缺乏弹性，因此选择D。", "optionAnalysis": {}}, {"id": "10-24", "type": "multi", "stem": "家庭生产理论认为（ ）。", "options": {"A": "家庭可以用时间密集型和商品密集型两种方式生产家庭物品", "B": "家庭的可支配时间可以划分为市场工作时间和家庭生产时间两大类", "C": "家庭的直接效用的来源是整个家庭获得的总劳动收入", "D": "家庭需要决定消费哪些家庭物品", "E": "夫妻双方的劳动力供给决策是相互独立的"}, "answer": "ABD", "analysis": "", "optionAnalysis": {"A": "正确，家庭物品可以采用较多家庭时间投入的时间密集型方式，也可采用较多市场商品投入的商品密集型方式生产。", "B": "正确，家庭成员需要在市场工作和家庭生产之间配置可支配时间。", "C": "错误，家庭直接效用来自最终消费的家庭物品，而不是劳动收入本身；收入是购买市场商品的手段。D项正确，家庭需要决定家庭物品的种类、数量及生产方式。", "E": "错误，夫妻双方的市场工作和家庭生产分工会相互影响，劳动力供给决策并非相互独立。"}}, {"id": "10-25", "type": "single", "stem": "因为经济不景气，大学毕业的韩鹏被迫暂时选择从事外卖员的工作，同时他的母亲为了贴补家用，也出来工作。韩鹏母亲出来工作属于的是（ ）。", "options": {"A": "替代效应", "B": "收入效应", "C": "灰心丧气的劳动者效应", "D": "附加的劳动者效应"}, "answer": "D", "analysis": "家庭主要劳动者的就业状况或收入恶化后，原本不参加市场工作的其他家庭成员为了维持家庭收入而进入劳动力市场，这种现象称为附加的劳动者效应。韩鹏从事收入可能较低的临时性工作后，其母亲出来工作以贴补家用，符合该特征。灰心丧气的劳动者效应是求职者因长期找不到工作而退出劳动力市场，与题意相反。", "optionAnalysis": {}}, {"id": "10-26", "type": "single", "stem": "在经济周期中，有助于降低失业率的是（ ）。", "options": {"A": "附加的劳动者效应", "B": "灰心丧气的劳动者效应", "C": "收入效应", "D": "替代效应"}, "answer": "B", "analysis": "失业率＝失业人口÷劳动力人口×100%。在经济衰退期，一些失业者因认为找不到工作而停止求职并退出劳动力市场，不再被统计为失业人口，这就是灰心丧气的劳动者效应。它可能使统计失业率下降，但并不意味着就业状况真正改善。附加的劳动者效应会使更多家庭成员进入劳动力市场，短期内可能增加失业人口。", "optionAnalysis": {}}, {"id": "10-27", "type": "single", "stem": "（ ）是女性劳动力参与率下降的原因。", "options": {"A": "家务劳动时间减少", "B": "生育率下降", "C": "离婚率下降", "D": "工作机会增多"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "会释放女性用于市场工作的时间，通常提高劳动力参与率。", "B": "会减少生育和照料儿童所需时间，通常提高参与率。", "C": "正确，离婚率下降意味着婚姻稳定性提高，部分女性为应对婚姻破裂风险而参加工作的预防性动机可能减弱，从而可能降低参与率。", "D": "会增加女性进入劳动力市场的机会，通常提高参与率。"}}, {"id": "10-28", "type": "single", "stem": "关于劳动力需求的说法，错误的是（ ）。", "options": {"A": "劳动力需求是一种派生需求", "B": "其他条件一定，工资率上升必然导致劳动力需求数量下降", "C": "劳动力需求与资本价格无关", "D": "在长期中，工资率变动会对劳动力需求同时产生规模效应和替代效应"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "正确，企业雇用劳动者是为了生产产品或服务，劳动力需求由产品需求派生而来。", "B": "正确，沿既定劳动力需求曲线，其他条件不变时，工资率上升会使劳动力需求量下降。", "C": "错误，资本价格变化会通过规模效应和替代效应影响劳动力需求。", "D": "正确，在长期中企业可以调整劳动和资本投入，工资变化会同时产生规模效应与替代效应。"}}, {"id": "10-29", "type": "single", "stem": "在其他条件一定的情况下，关于劳动力需求的说法，正确的是（ ）。", "options": {"A": "在工资率上升时，劳动力需求量会下降", "B": "在劳动力供给增加时，劳动力需求数量下降", "C": "在产品需求增加时，劳动力需求数量会下降", "D": "资本的价格对于劳动力需求数量不会产生影响"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，在其他条件不变时，工资率上升会提高用工成本，劳动力需求量沿需求曲线下降。", "B": "错误，劳动力供给增加主要影响市场均衡工资和就业量，不能直接得出需求数量必然下降。", "C": "错误，产品需求增加通常会提高产量并增加派生的劳动力需求。", "D": "错误，资本价格会通过劳动与资本之间的替代关系以及生产成本变化影响劳动力需求。"}}, {"id": "10-30", "type": "single", "stem": "在其他条件不变的情况下，会导致劳动力需求量上升的是（ ）。", "options": {"A": "资本价格下降的收入效应", "B": "资本价格上升的替代效应", "C": "资本价格下降的替代效应", "D": "资本价格上升的规模效应"}, "answer": "B", "analysis": "资本价格上升时，资本相对于劳动变得更昂贵，企业会以劳动替代部分资本，资本价格上升的替代效应会增加劳动力需求，因此B项正确。", "optionAnalysis": {"A": "表述不规范。", "C": "错误，资本价格下降的替代效应会促使企业用资本替代劳动，减少劳动力需求。", "D": "错误，资本价格上升会提高生产成本、缩小生产规模，其规模效应会减少劳动力需求。"}}, {"id": "10-31", "type": "multi", "stem": "在其他条件一定的情况下，必然导致劳动力需求下降的是（ ）。", "options": {"A": "工资率下降的替代效应", "B": "工资率下降的规模效应", "C": "工资率上升的规模效应", "D": "工资率上升的替代效应", "E": "工资率下降的收入效应"}, "answer": "CD", "analysis": "工资率上升会产生两个方向一致的效应：其一，劳动相对于其他生产要素变得更昂贵，企业用其他要素替代劳动，替代效应使劳动力需求下降；其二，生产成本上升导致产品价格和生产规模受到影响，规模效应也使劳动力需求下降，因此C、D正确。工资率下降的替代效应和规模效应都会增加劳动力需求，A、B错误。E项“收入效应”不是劳动力需求分析中的规范概念，错误。", "optionAnalysis": {}}, {"id": "10-32", "type": "single", "stem": "某地区汽车生产工人工资率从每小时30元上升到33元，该地区汽车制造商对汽车生产工人的劳动力需求将会从原来的1000人减少到800人，则该地区汽车生产工人的劳动力需求自身工资弹性属于（ ）。", "options": {"A": "缺乏弹性", "B": "富有弹性", "C": "单位弹性", "D": "无弹性"}, "answer": "B", "analysis": "按初始值计算：工资率变动率＝（33－30）÷30×100%＝10%；劳动力需求量变动率＝（800\n－1000）÷1000×100%＝－20%。劳动力需求自身工资弹性＝－20%÷10%＝－2，其绝对值为2，大于1，说明劳动力需求量的变动幅度大于工资率的变动幅度，属于富有弹性，因此选择B。", "optionAnalysis": {}}, {"id": "10-33", "type": "single", "stem": "某地养老护理人员现在的市场工资水平为每小时50元，当地平均每天的劳动力需求量为10小时，当此类人员的工资率提高到每小时60元，平均每天的劳动力需求量为8小时，该地养老护理人员的劳动力需求是（ ）。", "options": {"A": "无弹性的", "B": "单位弹性的", "C": "缺乏弹性的", "D": "富有弹性的"}, "answer": "B", "analysis": "按初始值计算：工资率变动率＝（60－50）÷50×100%＝20%；劳动力需求量变动率＝（8－\n10）÷10×100%＝－20%。劳动力需求自身工资弹性＝－20%÷20%＝－1，其绝对值等于1，属于单位弹性，因此选择B。", "optionAnalysis": {}}, {"id": "10-34", "type": "multi", "stem": "根据派生需求定理，会对劳动力需求弹性产生影响的因素包括（ ）。", "options": {"A": "劳动力生产的最终产品的需求价格弹性", "B": "用其他要素替代劳动力的难易度", "C": "企业使用的劳动力数量", "D": "劳动力成本在总成本中的占比", "E": "其他生产要素的供给弹性"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确，最终产品需求越有弹性，工资变化引起的产品价格和销量变化越大，劳动力需求通常越有弹性。", "B": "正确，其他生产要素越容易替代劳动，劳动力需求越有弹性。", "C": "错误，企业使用劳动力的绝对数量不是派生需求定理列出的决定因素。", "D": "正确，劳动力成本占总成本比重越大，工资变化对总成本影响越大，劳动力需求越有弹性。", "E": "正确，其他生产要素供给越有弹性，企业越容易调整要素投入，劳动力需求通常越有弹性。"}}, {"id": "10-35", "type": "single", "stem": "在其他条件一定的情况下，若（ ），则劳动力需求的自身工资弹性就越小", "options": {"A": "劳动力所生产的最终产品的需求价格弹性越大", "B": "其他生产要素替代劳动力的难度越小", "C": "其他生产要素的供给弹性越大", "D": "劳动力成本在总成本中所占的比重越小"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "会使最终产品销量对价格变化反应更敏感，从而使劳动力需求弹性增大。", "B": "意味着其他要素更容易替代劳动，会增大劳动力需求弹性。", "C": "意味着企业更容易获得并调整其他生产要素，也会增大劳动力需求弹性。", "D": "正确，劳动力成本占总成本的比重越小，工资变化对企业总成本和产量决策的影响越小，劳动力需求的自身工资弹性越小。"}}, {"id": "10-36", "type": "single", "stem": "在其他条件不变的条件下，某国青年劳动力的工资率上涨2%会导致老年劳动力的就业量下降0.8%，这表明该国这两种劳动力之间存在（ ）关系。", "options": {"A": "替代", "B": "互补", "C": "总替代", "D": "总互补"}, "answer": "D", "analysis": "老年劳动力就业量对青年劳动力工资率的交叉工资弹性＝－0.8%÷2%＝－0.4。交叉工资弹性为负，表示青年劳动力工资上涨时，老年劳动力的需求也下降，两类劳动力在总体效应上属于总互补关系，因此选择D。“总替代”和“总互补”综合反映替代效应与规模效应共同作用后的结果。", "optionAnalysis": {}}, {"id": "10-37", "type": "single", "stem": "如果硕士毕业生的工资水平每上升1%，本科毕业生的劳动力需求便会上升0.2%，则在硕士毕业生和本科毕业生之间存在（ ）关系。", "options": {"A": "替代", "B": "互补", "C": "总替代", "D": "总互补"}, "answer": "C", "analysis": "本科毕业生劳动力需求对硕士毕业生工资率的交叉工资弹性＝0.2%÷1%＝0.2。交叉工资弹性为正，说明硕士毕业生工资上升后，企业增加了对本科毕业生的需求，综合替代效应和规模效应后，两类劳动力表现为总替代关系，因此选择C。", "optionAnalysis": {}}, {"id": "10-38", "type": "single", "stem": "在劳动力市场均衡分析图形中，如果劳动力供给曲线不变，出口下降导致劳动力需求曲线向左移动，则可能出现的情况是（ ）。", "options": {"A": "均衡工资率下降，均衡就业率上升", "B": "均衡工资率上升，均衡就业率下降", "C": "均衡工资率和均衡就业率同时上升", "D": "均衡工资率和均衡就业率同时下降"}, "answer": "D", "analysis": "出口下降会减少相关产品的市场需求，企业产量下降，派生的劳动力需求也随之减少，劳动力需求曲线向左移动。在劳动力供给曲线不变的情况下，新均衡点对应更低的均衡工资率和更低的均衡就业量。因此D项正确，A、B、C项均不符合需求曲线左移的均衡结果。", "optionAnalysis": {}}, {"id": "10-39", "type": "single", "stem": "某地区软件开发人员的劳动力市场目前处于均衡状态，且在未来几年中，软件开发行业的劳动力需求不会出现太大变化，但是在前些年计算机热，报考计算机专业的大批大学毕业生即将进入该地区劳动力市场，这种情况可能导致该地区软件开发人员（ ）。", "options": {"A": "工资率有所下降，就业量会有所上升", "B": "工资率会有所上升，就业量会有所下降", "C": "工资率和就业量均上升", "D": "工资率和就业量均下降"}, "answer": "A", "analysis": "大批计算机专业毕业生进入市场会增加软件开发人员的劳动力供给，使供给曲线向右移动。题目说明劳动力需求基本不变，因此新均衡点表现为均衡工资率下降、均衡就业量上升，选择A。", "optionAnalysis": {}}, {"id": "10-40", "type": "single", "stem": "在劳动力市场均衡分析图形中，假定劳动力需求曲线不变，而劳动力供给却由于退休人口增加和新成长劳动力不足而出现了下降，则可能出现的情况是（ ）。", "options": {"A": "均衡工资率和均衡就业量同时下降", "B": "均衡工资率上升，均衡就业量下降", "C": "均衡工资率和均衡就业量同时上升", "D": "均衡工资率下降，均衡就业量上升"}, "answer": "B", "analysis": "退休人口增加和新成长劳动力不足会减少劳动力供给，使供给曲线向左移动。在劳动力需求曲线不变的情况下，劳动力变得更稀缺，新均衡工资率上升，均衡就业量下降，因此选择B。", "optionAnalysis": {}}, {"id": "10-41", "type": "single", "stem": "关于劳动力需求方面临劳动力市场摩擦力的具体表现，说法错误的是（ ）。", "options": {"A": "企业的劳动力需求数量会受到劳动力供给的影响", "B": "企业调整雇用人数会产生一定的成本", "C": "企业未必根据市场工资水平的变化迅速调整雇用人数", "D": "企业并非一定按照市场工资水平支付工资"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误，在基本劳动力市场模型中，劳动力需求由工资率、产品需求、生产技术及其他要素价格等因素决定，不能把劳动力供给直接表述为企业劳动力需求数量的决定因素。", "B": "正确，招聘、解雇和培训都会产生调整成本。", "C": "正确，受调整成本和信息限制影响，企业不会立即调整雇用人数。D项正确，效率工资、内部工资制度和长期合同等会使企业工资偏离市场通行水平。"}}, {"id": "10-42", "type": "single", "stem": "劳动力市场上的摩擦力会导致劳动力市场非均衡，这种摩擦力不包括（ ）。", "options": {"A": "企业调整雇佣人数会产生成本", "B": "市场工资水平会发生变化", "C": "有些企业支付超出市场通行水平的高工资率", "D": "劳动力流动会产生成本"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "属于需求方调整成本，会阻碍企业迅速达到理想用工数量。", "C": "反映工资并不总是等于市场出清工资，可能导致非均衡。", "D": "属于劳动者跨地区、跨企业或跨职业流动的成本，会阻碍劳动力自由流动。", "B": "只是市场变量的正常变化，本身不是造成劳动力市场非均衡的摩擦力。"}}, {"id": "10-43", "type": "single", "stem": "导致劳动力市场非均衡现象出现的原因不包括（ ）。", "options": {"A": "有些企业可能会支付超过市场通行水平的工资", "B": "劳动者跨企业流动是有成本的", "C": "劳动力对工资率的反应是极其敏感的", "D": "企业往往并不能随意调整所雇用的员工人数"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "会造成工资偏离市场出清水平，是非均衡的可能原因。", "B": "中的流动成本会阻碍劳动者根据工资差异迅速流动。", "D": "中的用工调整成本和制度限制会使企业无法迅速调整雇用人数。", "C": "错误，劳动力对工资反应极其敏感意味着调整较迅速，通常有助于恢复均衡，不是劳动力市场摩擦的典型表现。"}}, {"id": "10-44", "type": "single", "stem": "导致劳动力市场非均衡的原因，不包括（ ）。", "options": {"A": "劳动者在企业之间的流动是有成本的", "B": "企业能够自由调整用工人数", "C": "有些企业会支付高于市场通行工资率的工资水平", "D": "在劳动力市场上存在工资刚性现象"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "中的流动成本会延缓劳动力向工资较高或需求较大的企业流动，导致非均衡。", "B": "不属于非均衡原因；企业若能自由、无成本地调整用工人数，反而有利于市场恢复均衡。", "C": "会使实际工资偏离市场出清工资。", "D": "中的工资刚性会使工资不能随供求变化及时调整，也是非均衡的重要原因。"}}, {"id": "10-45", "type": "single", "stem": "国家制定工资指导线的做法属于（ ）。", "options": {"A": "人力资源", "B": "财政政策", "C": "收入政策", "D": "货币政策"}, "answer": "C", "analysis": "工资指导线是政府对企业工资增长进行宏观指导和调控的政策工具，主要用于协调工资增长、劳动生产率和物价水平之间的关系，属于收入政策。", "optionAnalysis": {"A": "不是此处规范的宏观政策类别；", "B": "主要通过政府支出和税收调节经济；", "D": "主要通过货币供应量、利率等工具进行调控。"}}, {"id": "10-46", "type": "single", "stem": "下列政策类型中，不利于促进就业的政策是（ ）。", "options": {"A": "人力政策", "B": "扩张性财政政策", "C": "重点发展资本密集型产业的产业政策", "D": "宽松性货币政策第十一章工资与就业理论及其应用"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "可通过职业培训、就业服务和劳动力流动支持等措施改善劳动者就业能力，有利于就业。", "B": "可扩大社会总需求和产出，增加派生的劳动力需求。", "C": "正确，资本密集型产业单位产出使用的劳动相对较少，若重点发展此类产业，吸纳就业的能力通常弱于劳动密集型产业，不利于扩大就业。", "D": "可通过降低融资成本、刺激投资和总需求促进就业。"}}]}, {"id": 11, "title": "工资与就业理论及其应用", "questions": [{"id": "11-1", "type": "single", "stem": "相对于货币工资而言，实际工资是指（ ）。", "options": {"A": "劳动者获得的税前工资", "B": "劳动者的税后工资和社会保险缴费之和", "C": "劳动者获得的货币工资能够购买到的商品和服务数量", "D": "劳动者实际获得的税后工资"}, "answer": "C", "analysis": "实际工资反映货币工资的实际购买力，即劳动者取得的货币工资在既定物价水平下能够购买的商品和服务数量。", "optionAnalysis": {"A": "属于税前货币工资；", "B": "是对税后工资与社会保险缴费的组合描述，不是实际工资的定义；", "C": "准确体现了工资购买力，正确；", "D": "属于实际拿到手的税后货币收入，但“实际拿到”不等同于经济学意义上的实际工资。"}}, {"id": "11-2", "type": "single", "stem": "劳动者进行劳动力供给决策最关心的是（ ）。", "options": {"A": "名义工资", "B": "物价指数", "C": "实际工资", "D": "货币工资"}, "answer": "C", "analysis": "劳动者在决定是否提供劳动以及提供多少劳动时，重点考虑工资收入能够换取多少商品和服务，因此最关心实际工资。", "optionAnalysis": {"A": "名义工资与", "D": "货币工资主要反映以货币表示的工资数额，未扣除物价变动的影响；", "B": "物价指数只是计算实际工资的重要因素之一；", "C": "综合反映货币工资和物价水平，能够体现真实购买力。"}}, {"id": "11-3", "type": "multi", "stem": "关于工资水平的说法，正确的有（ ）。", "options": {"A": "实际工资就是指员工实际拿到手的货币工资", "B": "实际工资就是指名义工资", "C": "企业在确定工资水平时必须了解实际工资水平", "D": "货币工资上涨时，实际工资有可能是下降的", "E": "物价指数越高，相同的货币工资代表的实际工资水平越低"}, "answer": "CDE", "analysis": "实际工资通常可理解为货币工资经物价水平调整后的购买力。", "optionAnalysis": {"A": "错误，员工实际拿到手的工资仍是货币收入概念，不等于实际工资；", "B": "错误，名义工资未反映物价变化；", "C": "正确，企业确定工资水平时需要关注工资的实际购买力；", "D": "正确，如果物价上涨幅度高于货币工资上涨幅度，实际工资会下降；", "E": "正确，在货币工资不变时，物价指数越高，其购买力越低。"}}, {"id": "11-4", "type": "single", "stem": "在劳动力市场上，能够反映企业雇用劳动力的迫切程度的是（ ）。", "options": {"A": "劳动力供给", "B": "工资差别", "C": "法定最低工资水平", "D": "劳动力需求"}, "answer": "D", "analysis": "劳动力需求是企业在一定工资水平下愿意并能够雇用的劳动力数量，能够反映企业对劳动者的需要及雇用迫切程度。", "optionAnalysis": {"A": "反映劳动者愿意提供的劳动数量；", "B": "反映不同劳动者、职业或企业之间的工资差异；", "C": "是政府规定的工资下限；", "D": "直接体现企业的雇用意愿和雇用能力。"}}, {"id": "11-5", "type": "single", "stem": "同工同酬是指（ ）。", "options": {"A": "同一家企业中的同一工种的劳动者拿大体相同的工资", "B": "在不同企业中完成价值相同工作的劳动者拿大体相同的工资", "C": "所有的劳动者拿大体相同的工资", "D": "在同一家企业中完成价值相同工作的劳动者拿大体相同的工资"}, "answer": "D", "analysis": "同工同酬强调在同一部门或单位内部，对完成同等价值工作的劳动者支付大体相同的工资。A项只强调工种相同，未考虑工作的价值和劳动贡献；B项跨越不同企业，而不同企业的生产率、支付能力等可能不同；C项否认合理的工资差别；D项同时限定同一企业和价值相同的工作，符合教材中的基本含义。", "optionAnalysis": {}}, {"id": "11-6", "type": "single", "stem": "下列选项关于同工同酬的说法错误的是（ ）。", "options": {"A": "在同一部门或单位内部贯彻的可能性比较大", "B": "是指不同职业的男女职工应支付相同工资", "C": "是指创造相同价值工作职位应有同等水平的工作", "D": "在有劳动力流动壁垒的情况下难以实现"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，同一部门或单位内部的工作评价标准和工资制度相对统一，更容易贯彻同工同酬；", "B": "错误，同工同酬不是要求不同职业的男女职工一律取得相同工资，而是要求从事相同或同等价值工作的劳动者获得同等报酬；", "C": "表述虽不够严谨，但其核心是同等价值的工作应获得同等水平的工资，符合原则；", "D": "正确，劳动力流动壁垒会阻碍工资水平趋同。"}}, {"id": "11-7", "type": "single", "stem": "决定一个部门或一家企业工资支付能力的主要因素是（ ）。", "options": {"A": "部门或企业的生产率", "B": "竞争对手支付的工资水平", "C": "劳动者个人及其家庭的生活费用", "D": "企业员工人数"}, "answer": "A", "analysis": "企业或部门的生产率决定单位劳动所创造的产出和价值，是形成持续工资支付能力的主要经济基础。B项会影响企业工资水平的外部竞争性，但不能直接决定支付能力；C项会影响劳动者对工资的要求以及劳动力供给，却不直接决定企业能支付多少工资；D项员工人数影响工资总额，但不是决定单位工资支付能力的主要因素。", "optionAnalysis": {}}, {"id": "11-8", "type": "single", "stem": "导致不同产业部门之间形成工资差别的主要原因不包括（ ）。", "options": {"A": "劳动力规模", "B": "熟练劳动力所占的比重", "C": "技术经济特点", "D": "所处的发展阶段"}, "answer": "A", "analysis": "产业工资差别通常与产业的技术经济特点、发展阶段以及熟练劳动力所占比重有关。B项会影响岗位技能要求和劳动生产率；C项会影响资本密集程度、劳动条件和生产效率；D项会影响产业盈利能力、增长速度和工资支付能力。", "optionAnalysis": {"A": "劳动力规模本身不能直接说明劳动生产率、技能结构或工资支付能力，因而不属于主要原因。"}}, {"id": "11-9", "type": "single", "stem": "关于工资差别的说法错误的是（ ）。", "options": {"A": "人们不仅关心工资水平，也关心工资差别", "B": "工资差别具有重新配置人力资源的功能", "C": "工资差别的形成，原因之一在于劳动者的素质和技能并不完全相同", "D": "政府应努力消除不同企业的同类劳动者之间存在的工资差别"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，劳动者既关注绝对工资水平，也关注相对工资及公平性；", "B": "正确，工资差别能够引导劳动者在职业、行业和地区之间流动；", "C": "正确，劳动者在人力资本、技能和生产率方面的差异会形成合理工资差别；", "D": "错误，不同企业的生产率、经营状况、劳动条件和支付能力不同，同类劳动者之间存在一定工资差别具有客观原因，政府不应简单消除所有差别。"}}, {"id": "11-10", "type": "single", "stem": "关于垄断性工资差别的说法，错误的是（ ）。", "options": {"A": "垄断性工资差别对劳动者是不公平的", "B": "国家可以通过税收政策对垄断性工资收入进行适当的调整", "C": "在某种劳动力供给几乎无弹性的情况下可能产生垄断性工资差别", "D": "因制度性原因造成的垄断性工资差别对提高经济效率有影响"}, "answer": "A", "analysis": "垄断性工资差别是因劳动者具有特殊禀赋、劳动力供给受限或制度性壁垒等形成的工资差别，不能笼统认定其对劳动者必然不公平，因此", "optionAnalysis": {"A": "错误。", "B": "正确，国家可通过税收政策对过高的垄断性收入进行调节；", "C": "正确，某类劳动力供给几乎无弹性时容易形成经济租金；", "D": "正确，制度性垄断工资差别会影响劳动力流动和资源配置，进而影响经济效率。"}}, {"id": "11-11", "type": "single", "stem": "大型公司的制度规范更多，为此，公司给员工提供的工资属于（ ）。", "options": {"A": "垄断性工资", "B": "补偿性工资", "C": "竞争性工资", "D": "技能性工资"}, "answer": "B", "analysis": "大型公司通常制度规范较多，劳动者可能承受更严格的管理、程序约束和较低的工作自主性。企业为补偿这些不利或不令人愉快的工作特征而支付的较高工资，属于补偿性工资。", "optionAnalysis": {"A": "源于劳动力供给受限或制度垄断；", "C": "不是本题所述工资差别的标准类型；", "D": "强调因技能水平不同而形成的工资差别。"}}, {"id": "11-12", "type": "multi", "stem": "补偿性工资差别是由于不同的职业在（ ）方面存在差异造成的", "options": {"A": "劳动强度", "B": "从业者需要具备的从业能力", "C": "劳动条件", "D": "令人愉快程度", "E": "从业者需承担的责任"}, "answer": "ACDE", "analysis": "补偿性工资差别用于补偿不同职业在非货币特征方面的不利差异。", "optionAnalysis": {"A": "正确，劳动强度越高，通常需要工资补偿；", "B": "错误，从业能力差异主要涉及人力资本和技能性工资差别；", "C": "正确，危险、艰苦等劳动条件会产生补偿要求；", "D": "正确，工作越不令人愉快，通常越需要较高工资补偿；", "E": "正确，责任越重，劳动者承担的压力和风险越大，也可能形成补偿性工资差别。"}}, {"id": "11-13", "type": "multi", "stem": "关于工资差别的说法，正确的有（ ）。", "options": {"A": "能力相同但在不同产业中工作的劳动者之间存在一定的工资差别是合理的", "B": "工资差别起到了引导劳动力资源在全社会范围内重新配置的作用", "C": "劳动者体力不同，成为工资差别的来源之一", "D": "同一产业内不同企业间的工资差别越小越好", "E": "劳动者的能力和素质差异可导致工资差别"}, "answer": "ABCE", "analysis": "", "optionAnalysis": {"A": "正确，不同产业的生产率、技术特点、劳动条件和发展阶段不同，能力相同的劳动者也可能取得不同工资；", "B": "正确，工资差别能够向劳动者传递稀缺程度和就业机会信息；", "C": "正确，体力差异可能造成劳动生产率和岗位适应能力差异；", "D": "错误，不同企业在效率、经营状况和工作条件方面存在差异，工资差别并非越小越好；", "E": "正确，能力和素质差异是工资差别的重要来源。"}}, {"id": "11-14", "type": "single", "stem": "下列做法中，属于工资歧视的是（ ）。", "options": {"A": "对于生产率存在差异的劳动者支付不同水平的工资", "B": "对于其他条件均相同且从事相同工作的不同性别劳动者支付不同的工资", "C": "故意将女性劳动者安排到低工资的职业或岗位上去", "D": "对于从事相同工作但所处地理位置不同的劳动者支付不同水平的工资"}, "answer": "B", "analysis": "工资歧视是指生产率特征和工作条件相同的劳动者，仅因性别、年龄等人口特征不同而取得不同工资。", "optionAnalysis": {"A": "工资差别以生产率差异为依据，不属于歧视；", "B": "在其他条件相同的情况下仅因性别不同而支付不同工资，属于工资歧视；", "C": "属于职业歧视，即限制特定群体进入高工资职业或岗位；", "D": "可能源于地区生活成本和劳动力市场条件差异，不能据此直接认定为工资歧视。"}}, {"id": "11-15", "type": "single", "stem": "关于劳动力市场歧视的说法，错误的是（ ）。", "options": {"A": "运用求职者所述的特殊群体的特征预测某位求职者未来生产率的做法，会产生统计性歧视", "B": "雇主、员工和客户都有可能成为劳动力市场歧视的主体", "C": "生产率特征相同的劳动力因人口类型不同而受到区别对待的情况属于歧视", "D": "两类人员之间存在的工资性报酬区别若不能得到明确解释，就可以归为工资歧视"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，统计性歧视是依据某一群体的平均特征推断个体生产率；", "B": "正确，雇主、其他员工和客户的偏好都可能导致歧视；", "C": "正确，生产率特征相同却因人口特征不同而受到区别对待，符合歧视的基本界定；", "D": "错误，无法解释的工资差异只能作为可能存在歧视的线索，还可能受到未被观察到的能力、经验、岗位责任等因素影响，不能直接全部归为工资歧视。"}}, {"id": "11-16", "type": "multi", "stem": "某垄断企业工资水平高，但实施薪酬保密，而让那些能力相同的其他人从事工资较低的岗位，该企业对能力相同且在同一岗位上的人确定不同的工资水平，同时故意将高工资岗位留给有关系的人，以上存在的劳动力市场歧视包括（ ）。", "options": {"A": "职业歧视", "B": "统计性歧视", "C": "工资歧视", "D": "客户歧视", "E": "雇主歧视"}, "answer": "AC", "analysis": "故意让能力相同的其他人从事低工资岗位，并把高工资岗位留给特定关系人员，体现了在职业或岗位进入机会上的差别对待，属于职业歧视，", "optionAnalysis": {"A": "正确；对能力相同且在同一岗位上的人确定不同工资，属于工资歧视，", "C": "正确。题干没有表明企业依据群体平均特征推断个人生产率，", "B": "不选；没有客户偏好导致区别对待的信息，", "D": "不选；“有关系”属于岗位机会上的偏向，但题干未体现教材所界定的因雇主对特定人口群体存在厌恶而产生的雇主歧视，", "E": "不选。"}}, {"id": "11-17", "type": "single", "stem": "研究人员发现，某地男性劳动者和女性劳动者在职业分布上存在很大差异，进而造成男女之间的工资性报酬存在较大差别，这表明在该地劳动力市场上存在较为严重的（ ）。", "options": {"A": "工资歧视", "B": "职业歧视", "C": "性别歧视", "D": "统计性歧视"}, "answer": "B", "analysis": "题干强调男性和女性在不同职业或岗位中的分布存在明显差异，并由此产生工资差别，其直接表现是特定性别进入某些职业或高工资岗位的机会受到限制，属于职业歧视。", "optionAnalysis": {"A": "工资歧视要求在相同工作和相同生产率条件下支付不同工资；", "C": "是较宽泛的概念，不如职业歧视准确；", "D": "强调依据群体平均特征推断个体生产率，题干未体现这一点。"}}, {"id": "11-18", "type": "single", "stem": "在我国关于不充分就业人员的统计标准中，不属于必要条件的是（ ）。", "options": {"A": "调查周内工作时间不到20个小时", "B": "本人要求的工资超过当地社会平均工资水平", "C": "本人愿意从事更长时间的工作", "D": "工作时间短并非个人原因造成"}, "answer": "B", "analysis": "不充分就业通常关注劳动者已经就业但工作时间不足，并且愿意且能够从事更多工作的状态。", "optionAnalysis": {"A": "属于对工作时间不足的判断条件；", "C": "反映劳动者具有增加工作时间的意愿；", "D": "说明工作时间短并非劳动者主动选择。", "B": "涉及劳动者的工资要求是否超过社会平均工资，与不充分就业的统计认定没有直接关系，因此不是必要条件。"}}, {"id": "11-19", "type": "single", "stem": "根据国家统计局实施的劳动力调查制度，就业人口的必备条件不包括（ ）。", "options": {"A": "在调查周内的工作时间达到或超过1小时", "B": "从事的是全职工作", "C": "年龄达到16周岁以上", "D": "工作的目的是收到报酬或者经营收入"}, "answer": "B", "analysis": "就业人口的统计并不以是否从事全职工作为必要条件，符合标准的兼职工作者同样可以计入就业人口。", "optionAnalysis": {"A": "符合调查周内为取得报酬或经营收入工作达到规定时间的统计要求；", "C": "属于我国劳动力调查相关年龄条件；", "D": "体现就业活动的经济目的。", "B": "将就业限定为全职工作，排除了符合就业标准的兼职劳动者，因此不是必备条件。"}}, {"id": "11-20", "type": "multi", "stem": "根据国际劳工组织的定义，下列人员中，属于就业人口的有（ ）。", "options": {"A": "因为工伤目前正在家中休养的某公司员工", "B": "刚毕业就找到工作开始上班的大学毕业生", "C": "毕业后自己开网店的大学毕业生", "D": "目前正处于休假状态的某小企业员工", "E": "毕业后全职在家照顾父母的大学毕业生"}, "answer": "ABCD", "analysis": "国际劳工组织关于就业人口的统计既包括在参考期内从事有报酬工作或经营活动的人，也包括因休假、疾病、工伤等原因暂时未工作但仍与工作岗位保持联系的人。", "optionAnalysis": {"A": "仍与公司保持劳动关系，属于暂时离岗就业者；", "B": "已经开始工作，属于就业人口；", "C": "从事个体经营，属于就业人口；", "D": "处于休假状态但仍保有工作，属于就业人口；", "E": "仅从事无报酬的家庭照料活动，不属于就业人口。"}}, {"id": "11-21", "type": "multi", "stem": "在我国的失业人员统计中，失业人员必须满足的条件包括（ ）。", "options": {"A": "要求就业", "B": "在法定劳动年龄内", "C": "有工作能力", "D": "未能就业", "E": "工资水平低于社会平均工资低收入群体"}, "answer": "ABCD", "analysis": "我国失业人员通常是指在法定劳动年龄内、具有劳动能力、没有工作并且有就业要求的人员。", "optionAnalysis": {"A": "体现就业意愿；", "B": "是年龄条件；", "C": "是从事劳动的能力条件；", "D": "体现当前没有实现就业。E项错误，工资低于社会平均水平只能说明收入相对较低，只要已经就业，就不能仅因工资较低而被统计为失业人员。"}}, {"id": "11-22", "type": "single", "stem": "关于我国在就业和失业方面规定的说法，错误的是（ ）。", "options": {"A": "虽然从事一定社会劳动，但劳动报酬低于当地城乡居民最低生活保障标准的情况视同失业", "B": "超出法定劳动年龄的劳动者外出找工作，但没找到的情况，不属于失业", "C": "16周岁以上各类学校毕业或肄业的学生，初次寻找工作但未找到，不属于失业人员", "D": "劳动者获得的劳动报酬达到和超过当地最低工资标准的，属于充分就业"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "符合相关就业服务和失业认定口径中对特定低报酬劳动状态的处理；", "B": "正确，失业统计通常要求处于法定劳动年龄范围内，超出该范围而求职未果一般不列入失业人员；", "C": "错误，达到规定年龄的学校毕业生或肄业学生，如果具有劳动能力、有就业要求并且尚未就业，可以被认定为失业人员；", "D": "符合教材对劳动报酬达到当地最低工资标准时相关就业状态的表述。"}}, {"id": "11-23", "type": "single", "stem": "城镇登记失业率界定条件不包括（ ）。", "options": {"A": "在城镇有房屋", "B": "16岁至退休年龄", "C": "有劳动能力", "D": "在公共就业服务机构进行失业登记"}, "answer": "A", "analysis": "城镇登记失业人员的认定重点包括处于规定劳动年龄、具有劳动能力、有就业要求、处于无业状态，并在公共就业服务机构进行失业登记。B项属于年龄条件；C项属于劳动能力条件；D项是“登记失业”的必要程序。", "optionAnalysis": {"A": "是否在城镇拥有房屋与劳动者的失业状态无直接关系，不是城镇登记失业率的界定条件。"}}, {"id": "11-24", "type": "single", "stem": "如果其他条件不变，会导致失业率下降的是（ ）。", "options": {"A": "失业人口增加", "B": "人口增加", "C": "就业人口增加", "D": "非劳动力人口增加"}, "answer": "C", "analysis": "失业率＝失业人口÷劳动力人口×100%，其中劳动力人口＝就业人口＋失业人口。", "optionAnalysis": {"A": "失业人口增加，在其他条件不变时会使失业率上升；", "B": "总人口增加不一定改变劳动力人口及其内部结构，不能确定失业率变化；", "C": "就业人口增加且失业人口不变时，劳动力人口扩大而失业人口占比下降，失业率下降；", "D": "非劳动力人口增加不必然影响失业人口和劳动力人口，无法确定失业率下降。"}}, {"id": "11-25", "type": "single", "stem": "在其他相同的情况下，会导致失业率上升的情形是（ ）。", "options": {"A": "因退休而退出劳动力市场的人数增加", "B": "找到工作的失业者人数迅速上升", "C": "绝大部分应届大中专毕业生都找到工作", "D": "一部分长时间找不到工作的失业者决定放弃寻找工作"}, "answer": "A", "analysis": "失业率＝失业人口÷劳动力人口。当退休者主要从就业人口中退出劳动力市场时，失业人口不变而劳动力人口减少，失业人口所占比例上升，因此", "optionAnalysis": {"A": "会导致失业率上升。", "B": "使失业者转为就业者，失业率下降；", "C": "意味着新增劳动力中的就业比例较高，有利于降低失业率；", "D": "中放弃寻找工作者会退出劳动力人口，失业人口与劳动力人口同时减少，通常会使统计失业率下降而非上升。"}}, {"id": "11-26", "type": "single", "stem": "某市去年底人口总量为120万人，其中就业人口为95万人，非劳动力人口20万人。该市去年年底的失业率为（ ）。", "options": {"A": "2%", "B": "4.17%", "C": "5%", "D": "1.67%"}, "answer": "C", "analysis": "先计算失业人口：失业人口＝人口总量－就业人口－非劳动力人口＝120－95－20＝5（万人）。再计算劳动力人口：劳动力人口＝就业人口＋失业人口＝95＋5＝100（万人）。因此，失业率＝失业人口÷劳动力人口×100%＝5÷100×100%＝5%，应选择C。A、B、D均不是按照失业人口占劳动力人口的比重计算得到的结果。", "optionAnalysis": {}}, {"id": "11-27", "type": "single", "stem": "为减少摩擦性失业，政府可采用的政策是（ ）。", "options": {"A": "加快劳动力市场信息传递", "B": "出台刺激经济增长的政策", "C": "对失业者进行免费培训", "D": "出台强化薪酬保密的法律法规"}, "answer": "A", "analysis": "摩擦性失业主要产生于劳动者转换工作以及劳动力供求双方搜寻、匹配需要时间。", "optionAnalysis": {"A": "通过加快职位空缺和求职信息传递，可以缩短匹配时间，直接减少摩擦性失业；", "B": "主要用于缓解总需求不足导致的周期性失业；", "C": "更适合缓解技能不匹配导致的结构性或技术性失业；", "D": "会降低工资信息透明度，不利于劳动力市场匹配。"}}, {"id": "11-28", "type": "single", "stem": "关于技术性失业的说法，错误的是（ ）。", "options": {"A": "政府为失业者提供培训有助于应对技术性失业", "B": "政府为失业者提供企业用工需求信息是解决技术性失业的有效手段", "C": "技术性失业经常出现在产业结构调整时期", "D": "技术性失业属于一种结构性失业"}, "answer": "B", "analysis": "技术性失业是技术进步、生产方式变化等导致原有岗位减少，而劳动者技能不能及时适应新岗位要求所形成的失业，属于结构性失业。", "optionAnalysis": {"A": "正确，职业培训可以帮助劳动者掌握新技能；", "B": "错误，单纯提供用工信息主要缓解信息不充分造成的摩擦性失业，不能解决劳动者技能与岗位要求不匹配的问题；", "C": "正确，产业结构调整时期技术和岗位变化较快；", "D": "正确，技术性失业是结构性失业的一种表现。"}}, {"id": "11-29", "type": "single", "stem": "对充分就业产生显著影响的非正常性失业类型是（ ）。", "options": {"A": "周期性失业", "B": "结构性失业", "C": "竞争性失业", "D": "季节性失业"}, "answer": "A", "analysis": "充分就业并不意味着失业率为零，摩擦性失业、结构性失业等在劳动力市场正常运行中难以完全避免。周期性失业由经济周期波动和社会总需求不足引起，属于非正常性失业，会导致实际就业水平明显低于充分就业水平。B项结构性失业与产业和技能结构不匹配有关；C项不是教材中常用的标准失业类型；D项由行业生产经营的季节变化引起。", "optionAnalysis": {}}, {"id": "11-30", "type": "single", "stem": "下列关于周期性失业的说法，错误的是（ ）。", "options": {"A": "是一种正常性失业", "B": "产生周期性失业的基本原因是总需求量不足", "C": "经济周期对投资性商品生产行业的影响最重", "D": "在周期性经济波动不能得到克服的情况下，周期性失业就在所难免"}, "answer": "A", "analysis": "周期性失业是经济衰退阶段社会总需求不足、企业减产和裁员所造成的失业，属于非正常性失业，因此", "optionAnalysis": {"A": "错误。", "B": "正确，总需求不足是周期性失业产生的基本原因；", "C": "正确，投资性商品需求对经济周期更敏感，相关行业通常受到较大冲击；", "D": "正确，只要经济存在无法完全消除的周期性波动，周期性失业就可能发生。"}}, {"id": "11-31", "type": "multi", "stem": "关于失业的说法，正确的是（ ）。", "options": {"A": "结构性失业容易通过劳动力市场信息转述得到缓解", "B": "季节性失业主要源自一些行业或部门的劳动力要求具有季节性", "C": "耐用消费品行业的劳动者受到周期性失业打击的可能性更大", "D": "政府通过提供更好的职业指导和职业供求预测有助于缓解结构性失业", "E": "失业和职位空缺并存的情况下存在的失业都是技术性失业第十二章人力资本投资理论及其应用"}, "answer": "BCD", "analysis": "", "optionAnalysis": {"A": "错误，结构性失业的核心是劳动者技能、地区或职业结构与岗位需求不匹配，仅加快信息传递通常不足以解决；", "B": "正确，农业、旅游等行业的劳动力需求具有季节性，容易形成季节性失业；", "C": "正确，耐用消费品购买具有较强的可推迟性，其生产行业在经济衰退时更容易受到周期性失业冲击；", "D": "正确，职业指导和供求预测有助于劳动者选择适应市场需求的职业和技能；", "E": "错误，失业与职位空缺并存可能源于多种结构性不匹配，并非全部属于技术性失业。"}}]}, {"id": 12, "title": "人力资本投资理论及其应用", "questions": [{"id": "12-1", "type": "single", "stem": "关于人力资本与人力资本投资的说法，错误的是（ ）。", "options": {"A": "人力资本投资的收益产生在未来", "B": "人力资本投资的基本原理与物力资本投资完全不同", "C": "一个国家的资本在一定程度上包括社会全体成员的能力", "D": "人的劳动能力储备应当被视为一种资本"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：人力资本投资通常先发生教育、培训、迁移等成本，相关收益主要在未来逐步实现。", "B": "错误：人力资本投资与物质资本投资的基本分析原理相同，都需要比较当前成本与未来收益，只是投资载体和收益表现形式有所不同。", "C": "正确：社会成员所拥有的知识、技能和能力属于一国人力资本的重要组成部分。", "D": "正确：劳动者通过教育、培训等形成的劳动能力储备能够在未来创造收益，因此可以被视为资本。"}}, {"id": "12-2", "type": "single", "stem": "关于人力资本投资的说法，错误的是（ ）。", "options": {"A": "人力资本投资与一般投资原理是相同的", "B": "劳动者为获得更高工资而换工作的行为不属于人力资本投资", "C": "人力资本投资往往会在长期中持续带来收益", "D": "教育和培训是人力资本投资的形式之一"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：人力资本投资同样遵循成本收益比较原则。", "B": "错误：劳动者为寻找更高工资或更适合的工作而进行职业流动，需要付出搜寻、迁移及放弃原有收入等成本，并可能获得未来收益，属于人力资本投资。", "C": "正确：教育、培训等形成的知识和技能通常能够在较长时期内提高劳动者收入和就业能力。", "D": "正确：教育和在职培训是最典型的人力资本投资形式。"}}, {"id": "12-3", "type": "multi", "stem": "下列属于人力资本投资的有（ ）。", "options": {"A": "用人单位的岗位培训", "B": "给子女支付学费", "C": "员工为了获得更高的薪酬到其他企业去求职", "D": "用人单位给解除劳动合同的员工支付经济补偿金", "E": "资助贫困家庭的儿童继续学业"}, "answer": "ABCE", "analysis": "", "optionAnalysis": {"A": "正确：岗位培训能够提高员工的知识、技能和生产率，属于在职培训投资。", "B": "正确：支付学费是教育投资的直接成本，属于人力资本投资。", "C": "正确：为获得更高薪酬而求职属于劳动力流动投资，需要付出求职成本并预期取得未来收益。", "D": "错误：解除劳动合同的经济补偿金是劳动关系解除所产生的补偿支出，不以提高劳动者未来生产能力为目的，不属于人力资本投资。", "E": "正确：资助儿童继续学业属于教育投资，有助于提高其未来劳动能力和收入水平。"}}, {"id": "12-4", "type": "single", "stem": "关于人力资本投资的说法，错误的是（ ）。", "options": {"A": "人力资本投资的内部收益率越高越有利可图", "B": "人力资本投资合理与否的判断标准与针对物质资本投资的不同", "C": "人力资本投资产生的终身收益现值至少应超过投资成本才有利可图", "D": "人力资本投资的成本支出和取得收益的时间不同"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：在其他条件不变的情况下，内部收益率越高，投资的经济吸引力越强。", "B": "错误：人力资本投资与物质资本投资都要比较投资成本和未来收益现值，基本判断标准并无本质区别。", "C": "正确：只有未来增量收益的现值大于投资成本，投资的净现值才为正，因而具有经济合理性。", "D": "正确：人力资本投资的成本通常发生在当前，收益则主要在未来取得，二者存在时间差异。"}}, {"id": "12-5", "type": "single", "stem": "关于人力资本投资的内部收益率的说法，错误的是（ ）。", "options": {"A": "它代表的是人力资本投资可以承受的最高贴现率", "B": "它代表的是人力资本投资的实际收益率", "C": "当它高于其他投资的收益率时，人力资本投资是有利可图的", "D": "它是使人力资本投资的收益现值与成本相等时的投资回报率"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：内部收益率是使投资净现值等于零的贴现率，可理解为该投资所能承受的最高贴现率。", "B": "错误：内部收益率是根据预期成本和预期收益计算出的临界投资回报率，不等同于投资最终实现的实际收益率。", "C": "正确：若人力资本投资的内部收益率高于其他可选择投资的收益率或必要报酬率，则进行人力资本投资更有利。", "D": "正确：内部收益率正是使未来收益现值与投资成本相等的贴现率。"}}, {"id": "12-6", "type": "single", "stem": "若其他条件不变，会使人力资本投资更具经济合理性的情况是（ ）。", "options": {"A": "人力资本投资成本高", "B": "人力资本投资的收益时间短", "C": "人力资本投资的内部收益率高", "D": "人力资本投资收益的贴现率高"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误：投资成本上升会降低净收益，使投资吸引力下降。", "B": "错误：收益持续时间缩短会减少未来收益总额及其现值。", "C": "正确：内部收益率越高，说明投资能够带来的回报越高，经济合理性越强。", "D": "错误：贴现率越高，未来收益折算到当前的现值越低，投资价值越低。"}}, {"id": "12-7", "type": "single", "stem": "导致上大学的机会成本上升的因素是（ ）。", "options": {"A": "高中毕业生的市场工资水平上涨", "B": "大学学费上涨", "C": "上大学的人数增加", "D": "大学毕业生的市场工资水平上涨"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确：上大学的机会成本主要是因学习而放弃的工作收入。高中毕业生可以获得的市场工资越高，放弃的收入越多，机会成本越高。", "B": "错误：大学学费属于上大学的直接成本，而非机会成本。", "C": "错误：上大学人数本身不能直接决定个人因求学而放弃的收入。", "D": "错误：大学毕业生工资上涨会提高上大学的预期收益，而不是提高上大学期间的机会成本。"}}, {"id": "12-8", "type": "single", "stem": "李某大学毕业因为经济不景气，工资水平低，放弃工作去选择读研究生，关于李某上大学说法正确的是（ ）。", "options": {"A": "机会成本更低", "B": "固定成本更低", "C": "高的贴现率", "D": "高的内部收益率"}, "answer": "A", "analysis": "题干所述实质是李某在经济不景气、可获得工资较低时选择继续接受研究生教育。", "optionAnalysis": {"A": "正确：继续学习所放弃的工资收入较低，因而教育投资的机会成本较低。", "B": "错误：学费、资料费等直接成本不会因可获得工资较低而必然下降。", "C": "错误：经济不景气和当前工资低不能直接说明李某采用了较高贴现率；贴现率高反而会降低未来收益现值。", "D": "错误：机会成本降低可能提高教育投资的相对吸引力，但仅凭题干不能直接认定其内部收益率必然较高。"}}, {"id": "12-9", "type": "single", "stem": "人力资本投资理论认为，在其他条件相同的情况下，上大学后的收入增量流越长，高中毕业生上大学的愿望越强，能够支持这一理论的社会现象是（ ）。", "options": {"A": "上大学的基本上都是年轻人", "B": "女性上大学的积极性比男性高", "C": "大学毕业生与高中毕业生的工资性报酬差距较大时，愿意上大学的高中毕业生比例上升", "D": "经济危机时期愿意上大学的高中毕业生比例有所上升"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确：年轻人完成大学教育后剩余的工作年限更长，能够获得教育收入增量的时间更长，因此更愿意投资高等教育。", "B": "错误：该表述并非收入增量持续期限理论所能直接推出的结论。", "C": "错误：该现象说明收入增量的数额会影响教育选择，而不是收入增量持续时间的长短产生影响。", "D": "错误：经济危机时期上大学意愿增强，主要可由就业机会减少、放弃工资下降，即机会成本降低来解释。"}}, {"id": "12-10", "type": "single", "stem": "在其他条件相同的情况下，使高等教育投资的价值变得越高的情形不包括（ ）。", "options": {"A": "大学毕业生比高中毕业生的工资性报酬高出越多", "B": "上大学期间的劳动力市场工资水平越高", "C": "上大学的学费越低", "D": "大学毕业后工作的年限越长"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "包括在内：大学与高中学历的工资差额越大，接受高等教育带来的收入增量越高。", "B": "不包括：上大学期间劳动力市场工资越高，学生因上学而放弃的工资越多，机会成本越高，高等教育投资价值反而下降。", "C": "包括在内：学费越低，教育投资的直接成本越低。", "D": "包括在内：大学毕业后工作年限越长，获得教育增量收益的时间越长。"}}, {"id": "12-11", "type": "multi", "stem": "关于上大学的收益的说法，正确的有（ ）。", "options": {"A": "上大学的收益主要表现为大学毕业后获得的终身工资性报酬", "B": "上大学的收益等于一个人在上大学和不上大学两种情况下的终身工资性报酬差异", "C": "一个人大学毕业后工作的时间越长，通过上大学获得的收益通常越高", "D": "一个人上大学的直接成本越低，通过上大学获得的收益越高", "E": "一个人上大学的机会成本越低，通过上大学获得的收益越高"}, "answer": "BC", "analysis": "", "optionAnalysis": {"A": "错误：上大学的货币收益不是大学毕业后的全部终身工资，而是上大学与不上大学两种情况下终身工资性报酬的增量。", "B": "正确：高等教育的工资收益应以接受高等教育和不接受高等教育的终身工资性报酬之差来衡量。", "C": "正确：毕业后工作的时间越长，取得大学教育工资增量的期限通常越长，总收益越高。", "D": "错误：直接成本下降会提高投资的净收益或投资价值，但不会改变教育本身带来的工资收益额。", "E": "错误：机会成本下降同样会降低投资成本、提高净收益，但不等于上大学所带来的收入收益本身提高。"}}, {"id": "12-12", "type": "single", "stem": "关于接受高等教育的最佳年限的说法，正确的是（ ）。", "options": {"A": "接受高等教育的最佳年限的决定条件是上大学的边际成本等于边际收益", "B": "不存在一个接受高等教育的最佳年限", "C": "接受高等教育的年限越长越好", "D": "每个人接受高等教育的最佳年限是相同的"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确：根据边际分析原理，当增加一年教育带来的边际收益等于边际成本时，教育投资达到最优年限。", "B": "错误：在成本和收益可以比较的情况下，可以确定经济意义上的最佳教育年限。", "C": "错误：教育年限增加既会增加收益，也会增加直接成本和机会成本，并非越长越好。", "D": "错误：个人能力、家庭条件、教育成本、预期工资和贴现率等不同，因此最佳教育年限也会不同。"}}, {"id": "12-13", "type": "multi", "stem": "教育投资能够带来的社会收益包括（ ）。", "options": {"A": "提高整个社会的道德水平和信用水平", "B": "起到预防犯罪的作用，减少执行法律的支出", "C": "提高政策决策过程的质量和决策效率", "D": "提高受教育者的终身工资性报酬收入", "E": "降低失业率，减少失业福利支出"}, "answer": "ABCE", "analysis": "", "optionAnalysis": {"A": "正确：教育能够提升社会成员的规则意识、道德水平和信用水平，形成正外部性。", "B": "正确：教育有助于减少犯罪，降低社会治安和法律执行成本。", "C": "正确：受教育程度提高有助于改善公众参与和政策决策质量。", "D": "错误：受教育者终身工资性报酬提高主要属于教育的私人收益，而不是社会收益。", "E": "正确：教育有助于增强就业能力、降低失业率，并减少社会失业福利支出。"}}, {"id": "12-14", "type": "single", "stem": "为研究教育的回报率，经济学家做了一组同卵双胞胎的对比：双胞胎都是一个人上了大学，而另外一个人因各种原因没上大学，研究结果发现，这些双胞胎中上大学的人比那些没上大学的人获得的工作报酬明显更高。这项调查最能排除的是（ ）。", "options": {"A": "低估偏差", "B": "平均偏差", "C": "选择性偏差", "D": "高估偏差"}, "answer": "D", "analysis": "同卵双胞胎在遗传能力、家庭背景等方面高度相似，比较其中一人上大学、另一人不上大学后的收入差异，可以较大程度控制先天能力和家庭条件的影响。因此，这项研究最能排除因大学生原本能力较强而把能力造成的收入差异误算为教育收益所形成的高估偏差。", "optionAnalysis": {"A": "错误：低估偏差通常源于遗漏福利性、非货币性等教育收益，双胞胎研究不能直接排除。", "B": "错误：“平均偏差”不是本题所针对的核心估计偏差。", "C": "错误：该方法能够减弱选择性因素的干扰，但题目从教育回报率被能力等因素高估的结果角度，最直接对应的是高估偏差。", "D": "正确。"}}, {"id": "12-15", "type": "multi", "stem": "在估计上大学的私人收益的时候，往往容易出现低估偏差，这是因为经济学家往往会忽略了上大学会得到的（ ）。", "options": {"A": "福利性收益", "B": "非货币性收益", "C": "特权收益", "D": "生产率的提高", "E": "工资性报酬收益"}, "answer": "ABC", "analysis": "", "optionAnalysis": {"A": "正确：工作福利、较好的工作环境等福利性收益不一定完整反映在工资中，容易被遗漏。", "B": "正确：教育还可能带来健康改善、工作满意度提高、社会地位提升等非货币性收益，难以准确计量。", "C": "正确：教育可能使个人获得某些职业准入、社会资源或选择机会等特权性收益，这类收益也容易被忽略。", "D": "错误：生产率提高是教育发挥作用的中间机制，不是本题所指通常被遗漏的私人收益项目。", "E": "错误：工资性报酬差异是估计高等教育私人收益时最常使用的核心指标，通常不会被忽略。"}}, {"id": "12-16", "type": "single", "stem": "高等教育投资私人收益估计的选择性偏差观点认为（ ）。", "options": {"A": "大学毕业生即使不上大学，也能挣到比没上大学的人更高的终身工资性报酬", "B": "大学毕业生如果不上大学，能挣到的终身工资性报酬会比高中毕业生更低", "C": "大学毕业生即使不上大学，也能挣到与没上大学的人相同的终身工资性报酬", "D": "对任何人来说，上大学都比不上大学要好"}, "answer": "B", "analysis": "", "optionAnalysis": {}}, {"id": "12-17", "type": "multi", "stem": "在高等教育投资收益估计中可能存在选择性偏差的原因有（ ）。", "options": {"A": "在上大学的收益中还包括无法被计算的心理收益", "B": "大学毕业生即使不上大学，也能比高中毕业就工作的人获得更多的工资性报酬", "C": "高中毕业就工作的人即使上大学，其工资性报酬可能也比实际的大学毕业生更低", "D": "大学毕业生如果不上大学，其工资性报酬可能会比高中毕业就工作的人更低", "E": "高中毕业就工作的人如果上了大学，也能获得与大学毕业生相同的工资性报酬"}, "answer": "CD", "analysis": "", "optionAnalysis": {}}, {"id": "12-18", "type": "single", "stem": "关于高等教育的信号模型的说法，错误的是（ ）。", "options": {"A": "大学文凭可以表明文凭持有者具有较高的生产率", "B": "高等教育投资没有为接受高等教育者提供任何有价值的信号", "C": "利用高等教育文凭这种信号来筛选员工是有道理的", "D": "高等教育投资没有提高高等教育接受者的劳动生产率"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：信号模型认为，大学文凭能够向企业传递持有者具有较高能力或生产率的信息。", "B": "错误：高等教育信号模型恰恰强调学历和文凭能够提供有价值的生产率信号。", "C": "正确：当企业不能在招聘时直接观察求职者生产率时，利用学历文凭进行筛选具有一定合理性。", "D": "正确：按照纯粹的信号模型，高等教育未必直接提高生产率，而是帮助原本具有较高生产率的人向企业传递信号。"}}, {"id": "12-19", "type": "single", "stem": "关于高等教育信号模型的观点认为（ ）。", "options": {"A": "企业不应该将大学文凭作为筛选员工的工具", "B": "拿到大学文凭的人和没有拿到文凭的人，生产率是一样高的", "C": "大学文凭是一种能够表明其持有者具有高生产率的信号", "D": "企业在招人时，即使不看求职者是否有大学文凭也能准确判断其实际生产率"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误：信号模型认为文凭能够降低企业识别劳动者生产率的信息成本，可以作为筛选工具。", "B": "错误：信号模型认为取得大学文凭的人通常能够借此表明自己具有较高潜在生产率，并非认为两类人的生产率相同。", "C": "正确：这是高等教育信号模型的核心观点。", "D": "错误：企业通常无法在招聘阶段准确观察求职者的真实生产率，因此才需要借助学历文凭等信号。"}}, {"id": "12-20", "type": "multi", "stem": "企业实施在职培训的机会成本包括（ ）。", "options": {"A": "在职培训支付的场地费", "B": "邀请外部讲师提供培训的讲课费", "C": "受训员工因为参加培训而无法全力工作的损失", "D": "利用本企业的机器和资源向员工提供培训而导致的工作效率损失", "E": "购买培训材料的费用"}, "answer": "CD", "analysis": "", "optionAnalysis": {"A": "错误：场地费属于企业为培训实际支付的直接成本。", "B": "错误：外部讲师的讲课费属于直接货币支出。", "C": "正确：员工参加培训而不能正常工作所放弃的产出属于机会成本。", "D": "正确：机器、设备和其他资源用于培训后不能充分用于正常生产，由此造成的效率或产出损失属于机会成本。", "E": "错误：培训材料费用属于直接成本。"}}, {"id": "12-21", "type": "single", "stem": "关于一般培训和特殊培训的说法，错误的是（ ）。", "options": {"A": "公司组织的培训中，一般培训和特殊培训是很容易区分的", "B": "一般在职培训之后，员工可以在其他公司工作中获益", "C": "特殊在职培训之后，员工只能在当前的公司获得收益", "D": "一般培训的成本由员工个人承担"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误：实际培训通常同时包含一般性和企业特殊性内容，两者往往难以截然区分。", "B": "正确：一般培训形成的知识和技能可在多家企业使用，因此员工转到其他企业后仍能获益。", "C": "正确：特殊培训形成的技能主要或仅对当前企业有价值，其收益依赖现有劳动关系。", "D": "正确：在完全竞争的劳动力市场中，一般培训的收益可被员工带到其他企业，企业难以独占收益，因此其成本通常由员工通过培训期间接受较低工资等方式承担。"}}, {"id": "12-22", "type": "single", "stem": "从人力资本投资的角度看，在职培训不包括（ ）。", "options": {"A": "新员工通过观察有经验同事的工作过程提升自己的专业技能", "B": "大学毕业生因就业困难重新去上技工学校", "C": "企业组织的学徒计划", "D": "资深员工在工作过程中对新员工提供的指导"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "包括：员工在工作场所通过观察和边干边学提升技能，属于非正式在职培训。", "B": "不包括：重新进入技工学校属于学校教育或职业教育投资，不是在任职过程中接受的在职培训。", "C": "包括：企业学徒计划是正式在职培训的一种形式。", "D": "包括：资深员工对新员工的工作指导属于典型的非正式在职培训。"}}, {"id": "12-23", "type": "single", "stem": "关于在职培训的说法，错误的是（ ）。", "options": {"A": "在职培训可以通过边干边学的方式实现", "B": "在职培训是人力资本投资的重要形式之一", "C": "在职培训的方式之一是有经验的员工对新员工进行指导", "D": "在职培训都是以非正式的方式开展的"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确：边工作边学习是非正式在职培训的重要实现方式。", "B": "正确：在职培训能够提高员工的知识、技能和生产率，是人力资本投资的重要形式。", "C": "正确：有经验员工对新员工进行示范和指导属于在职培训。", "D": "错误：在职培训既可以采取非正式方式，也可以通过企业课程、学徒计划、集中培训等正式方式开展。"}}, {"id": "12-24", "type": "single", "stem": "关于在职培训对企业和员工行为的影响，说法不正确的是（ ）。", "options": {"A": "在职培训的成本实际上都是由企业承担的", "B": "企业通常更希望留住接受过特殊在职培训的员工", "C": "通常情况下，年轻员工比年纪较大的员工更愿意进行在职培训投资", "D": "接受过培训的员工通常愿意在企业中工作较长的时间"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "不正确：培训成本可能由企业和员工共同承担；尤其是一般培训，员工往往通过接受较低的培训期工资等方式承担部分或全部成本。", "B": "正确：特殊培训只能或主要在当前企业产生收益，企业更希望留住接受过此类培训的员工。", "C": "正确：年轻员工未来工作年限较长，能够在更长时期内取得培训收益，因此投资意愿通常更强。", "D": "正确：培训增加了员工与企业之间的匹配收益，尤其是特殊培训会提高双方维持长期劳动关系的意愿。"}}, {"id": "12-25", "type": "single", "stem": "关于在职培训对企业和员工产生的影响的说法，错误的是（ ）。", "options": {"A": "接受特殊在职培训较多的员工通常离职动机更强", "B": "企业在经济衰退时期也会尽可能避免解雇受过大量特殊在职培训的员工", "C": "接受一般在职培训较多的员工更容易在其他企业中找到工作，因为流动更容易", "D": "劳动者年龄越大，对在职培训进行投资的意愿往往越弱"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误：特殊培训形成的技能在当前企业中的价值更高，员工离开企业后可能无法继续取得相同收益，因此其离职动机通常更弱。", "B": "正确：企业已在特殊培训上投入成本，解雇员工会使部分投资损失，因此经济衰退时也更倾向于保留此类员工。", "C": "正确：一般培训形成的技能可在其他企业使用，员工的外部就业能力和流动性较强。", "D": "正确：年龄越大，剩余工作年限越短，可取得培训收益的时期越短，投资意愿通常越弱。"}}, {"id": "12-26", "type": "single", "stem": "关于劳动力流动的说法，正确的是（ ）。", "options": {"A": "对企业和劳动者双方来说，劳动力流动率都是越低越好", "B": "年轻劳动者的流动意愿通常强于年纪大的劳动者", "C": "劳动力流动对劳动者有利，对企业不利", "D": "劳动力流动对企业有利，对劳动者不利"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误：劳动力流动既有成本也有收益，流动率过高或过低都可能产生问题，应保持合理限度。", "B": "正确：年轻劳动者剩余职业生涯较长，更容易收回流动成本，也通常较少受到家庭和地域因素约束，因此流动意愿更强。", "C": "错误：流动可能使劳动者获得更好工作，也可能产生失业、迁移等成本；对企业同样可能有利或不利。", "D": "错误：劳动力流动的影响不能简单概括为只对企业有利、对劳动者不利。"}}, {"id": "12-27", "type": "single", "stem": "关于劳动力流动对企业和员工的影响的说法，错误的是（ ）。", "options": {"A": "劳动力流动可能会导致企业提供的一部分培训投资损失", "B": "劳动力流动对员工来说是收益大于成本的", "C": "无论对企业还是劳动者而言，劳动力流动都应有一个合理的限度", "D": "劳动力流动可能会使企业增加培训新员工的成本"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：受训员工离职可能使企业尚未收回的培训投资发生损失。", "B": "错误：员工流动能否获益取决于工资增长、发展机会与求职、迁移、失业风险等成本的比较，不能笼统认为收益一定大于成本。", "C": "正确：流动不足会妨碍劳动力合理配置，流动过度则会增加企业和个人成本，因此应保持合理限度。", "D": "正确：员工离职后，企业可能需要重新招聘并培训替代人员，从而增加培训成本。"}}, {"id": "12-28", "type": "single", "stem": "通常规模越大的企业劳动力流动率越低，关于产生这种现象原因的说法，错误的是（ ）。", "options": {"A": "大企业提供的大多是特殊在职培训，这使员工流动到其他企业无利可图", "B": "大企业往往提供较高水平的工资，导致员工流动到其他企业的成本较高", "C": "大企业能够为劳动者提供较多的工作轮换机会", "D": "大企业能够为劳动者提供较多的垂直晋升机会"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误：不能笼统认定大企业提供的培训大多属于特殊培训，也不能认为员工流向其他企业必然无利可图，该表述过于绝对。", "B": "正确：大企业通常能提供较高工资和较完善福利，员工离职所放弃的收益较多，流动成本较高。", "C": "正确：大企业内部岗位较多，员工可通过内部轮换解决岗位匹配问题，减少外部流动。", "D": "正确：大企业管理层级和职位较多，垂直晋升机会较多，员工留任意愿较强。"}}, {"id": "12-29", "type": "single", "stem": "企业规模越大人员流动率越低的原因不包括（ ）。", "options": {"A": "大型企业有更多内部轮岗", "B": "大企业员工有更大的晋升空间", "C": "大企业的纪律更宽松", "D": "大企业提供的更高水平工资"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "包括：内部岗位较多、轮岗机会较多，可以满足员工改变工作的需求，减少外部流动。", "B": "包括：更大的晋升空间能够提高员工长期留任的预期收益。", "C": "不包括：大型企业通常管理制度和劳动纪律更加规范，并不能一般性地认为纪律更宽松。", "D": "包括：较高工资提高了员工离职的机会成本，有助于降低流动率。"}}, {"id": "12-30", "type": "single", "stem": "其他条件一定，更有可能导致员工提出离职的情形是（ ）。", "options": {"A": "劳动力流动成本高", "B": "劳动者目前任职企业的管理水平高", "C": "劳动者在当前企业任职年限长", "D": "劳动力市场紧张"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误：流动成本越高，员工离职需要付出的代价越大，离职可能性越低。", "B": "错误：较高的企业管理水平通常会改善工作体验，降低离职意愿。", "C": "错误：任职年限越长，员工积累的企业特殊人力资本、资历和福利越多，流动成本通常越高。", "D": "正确：劳动力市场紧张意味着劳动力需求较旺盛、职位空缺较多，员工更容易找到新工作，离职可能性提高。"}}, {"id": "12-31", "type": "single", "stem": "关于劳动力流动的说法，错误的是（ ）。", "options": {"A": "领导风格等非经济因素会对劳动力流动产生影响", "B": "劳动力市场越宽松，劳动力流动越频繁", "C": "劳动者工资水平越低，流动的可能性越大", "D": "女性劳动者离职率相对较高的原因之一是需要考虑家庭角色分工"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确：领导风格、工作氛围、企业文化和工作满意度等非经济因素会影响员工的离职决定。", "B": "错误：劳动力市场宽松通常意味着劳动力供给相对充足、职位空缺较少，劳动者找到新工作的难度较大，流动通常不会更频繁。", "C": "正确：在其他条件相同的情况下，当前工资越低，外部工作机会的相对吸引力越强，流动可能性越大。", "D": "正确：家庭照料责任和家庭角色分工可能影响女性劳动者的工作连续性和地域选择，从而影响离职率。"}}, {"id": "12-32", "type": "single", "stem": "经济不景气时，会有白领劳动者失业后去当网约车司机或送外卖等，这在职业流动中属于（ ）。", "options": {"A": "向下流动", "B": "向上流动", "C": "水平流动", "D": "随机流动"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确：题干所述劳动者由通常具有较高职业地位、技能要求或收入预期的白领岗位，转向职业地位或技能要求相对较低的岗位，属于向下职业流动。", "B": "错误：向上流动是转向职业地位、收入或技能要求更高的职业。", "C": "错误：水平流动是职业层次大体相当的岗位之间流动。", "D": "错误：职业流动通常按向上、向下或水平等方向分类，“随机流动”不是此处的准确类型。"}}, {"id": "12-33", "type": "single", "stem": "关于劳动力跨职业流动的说法，正确的是（ ）。", "options": {"A": "跨职业流动都是自愿性的", "B": "劳动者跨职业流动的目的并不一定是为了获得更高的经济收入", "C": "跨职业流动只能自下而上流动，而不是反过来", "D": "家庭两代人之间的跨职业流动程度越低，表明劳动力市场功能的有效性越高"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误：跨职业流动既可能是劳动者主动选择，也可能因失业、行业衰退、技术变化等被迫发生。", "B": "正确：劳动者还可能为了工作兴趣、职业发展、工作环境、家庭需要或地域选择而转换职业，并非只追求更高收入。", "C": "错误：跨职业流动既可能向上，也可能向下，还可能是水平流动。", "D": "错误：代际职业流动程度过低通常说明家庭背景对职业选择的限制较强，劳动力市场配置功能较弱。"}}, {"id": "12-34", "type": "single", "stem": "关于劳动力流动的说法中，错误的是（ ）。", "options": {"A": "劳动力净流入的职业一定是收入高于或接近市场工资水平中值的职业", "B": "家庭代际职业转移的难度越大，表明劳动力市场的作用越弱", "C": "迁移成本会对劳动力的跨地区流动产生影响", "D": "劳动力从农业部门向工业部门的转移速度取决于工农部门之间的工资差距以及工业部门提供的就业机会多少"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误：劳动力是否净流入不仅取决于工资，还受到就业机会、职业前景、工作环境、准入条件和个人偏好等因素影响，不能认定净流入职业的收入一定高于或接近市场工资中值。", "B": "正确：代际职业转移越困难，说明家庭背景等因素对职业配置的限制越强，劳动力市场发挥配置作用的程度越弱。", "C": "正确：交通、搬迁、住房、信息搜寻和家庭适应等迁移成本会抑制跨地区流动。", "D": "正确：农业劳动力向工业部门转移既受部门工资差距影响，也取决于工业部门实际能够提供多少就业岗位。"}}, {"id": "12-35", "type": "multi", "stem": "关于劳动力流动的说法，正确的有（ ）。", "options": {"A": "劳动力流动有助于减少与结构性变化相关的失业", "B": "劳动力流动的受益者是企业和社会，对劳动者是不利的", "C": "劳动力流动有助于缓解地区之间的就业不平衡", "D": "劳动力流动有助于实现劳动力的有效利用", "E": "劳动力流动有可能导致企业培训投资的流失第十三章战略性人力资源管理"}, "answer": "ACDE", "analysis": "", "optionAnalysis": {"A": "正确：劳动者在行业、职业和地区之间合理流动，有助于使劳动力适应产业结构和需求结构变化，减少结构性失业。", "B": "错误：劳动力流动可能使劳动者获得更高工资、更合适的岗位和更好的发展机会，不能认为只对企业和社会有利而对劳动者不利。", "C": "正确：劳动力由就业机会不足地区流向需求较旺盛地区，有助于缓解地区就业不平衡。", "D": "正确：合理流动能够改善劳动者与岗位之间的匹配，提高劳动力资源配置效率。", "E": "正确：受训员工离职可能使企业无法继续取得培训投资的预期收益，从而导致部分培训投资流失。"}}]}, {"id": 13, "title": "战略性人力资源管理", "questions": [{"id": "13-1", "type": "multi", "stem": "关于战略性人力资源管理的说法，正确的有（ ）。", "options": {"A": "人力资源管理通过提高员工能力，帮助组织赢得竞争优势", "B": "人力资源管理应帮助组织实现战略目标", "C": "人力资源管理应以服务为导向", "D": "人力资源管理应重点关注成本控制", "E": "人力资源管理应为组织目标做出贡献"}, "answer": "ABE", "analysis": "战略性人力资源管理强调人力资源管理活动必须与组织战略相匹配，并通过员工能力、态度和行为促进组织目标实现。", "optionAnalysis": {"A": "正确，提高员工的知识、技能和能力能够形成竞争对手不易模仿的人力资本优势。", "B": "正确，人力资源管理应服务于组织战略的制定与执行，帮助组织实现战略目标。", "C": "错误，战略性人力资源管理强调以战略和组织绩效为导向，而不是仅仅以提供事务性服务为导向。", "D": "错误，成本控制只是管理目标之一，不能成为战略性人力资源管理的唯一或重点关注内容。", "E": "正确，人力资源管理必须能够对组织目标和经营绩效作出实际贡献。因此答案为ABE。"}}, {"id": "13-2", "type": "single", "stem": "战略性人力资源管理的理念，不包括（ ）。", "options": {"A": "要对人力资源管理活动的成本和收益进行分析和评价", "B": "人力资源管理是“成本中心”而不是利润中心", "C": "要对人力资源管理职能人员进行培训和提升", "D": "人力资源管理战略要和组织战略保持一致"}, "answer": "B", "analysis": "战略性人力资源管理要求人力资源部门从单纯的行政事务部门转变为能够创造价值的战略伙伴。", "optionAnalysis": {"A": "属于其理念，应通过成本收益分析评价人力资源管理活动的效果。", "B": "不属于其理念，战略性人力资源管理并不把人力资源部门简单视为成本中心，而是强调其能够创造价值并对组织绩效作出贡献。", "C": "属于其理念，人力资源管理人员需要提升专业能力和战略管理能力。", "D": "属于其核心理念，人力资源管理战略必须与组织战略保持一致。因此答案为B。"}}, {"id": "13-3", "type": "single", "stem": "在战略的三个层次中，组织战略需要回答的核心问题是（ ）。", "options": {"A": "凭借什么来进行竞争", "B": "如何进行竞争", "C": "到哪里去竞争", "D": "如何管理组织资源"}, "answer": "C", "analysis": "组织战略又称公司战略，主要确定组织经营范围以及应当进入、维持或退出哪些业务领域，回答的是“到哪里去竞争”的问题。", "optionAnalysis": {"A": "和", "B": "主要涉及竞争战略，即组织在选定的业务领域中依靠什么以及如何与竞争对手竞争。", "C": "正确，对应组织战略所解决的业务范围和发展方向问题。", "D": "主要涉及职能战略，即人力资源、财务、市场等职能如何配置和管理资源。因此答案为C。"}}, {"id": "13-4", "type": "single", "stem": "对于一家企业来说，经营何种产品以及进入何种领域属于（ ）。", "options": {"A": "组织战略", "B": "人力资源战略", "C": "竞争战略", "D": "职能战略"}, "answer": "A", "analysis": "经营何种产品以及进入何种领域，是对企业业务范围和发展方向作出的总体选择，属于组织战略。", "optionAnalysis": {"A": "正确，组织战略解决企业经营范围以及进入、维持或退出哪些领域的问题。", "B": "是围绕人才获取、开发、激励和保留制定的职能战略。", "C": "解决企业在特定市场中如何取得竞争优势的问题。", "D": "是各职能部门为支持组织战略和竞争战略而制定的具体战略。因此答案为A。"}}, {"id": "13-5", "type": "single", "stem": "某高科技公司认为区块链技术的未来前景巨大，于是做出了进入该领域的战略决策，属于（ ）。", "options": {"A": "职能战略", "B": "竞争战略", "C": "组织战略", "D": "差异化战略"}, "answer": "C", "analysis": "企业决定进入区块链这一新的业务领域，涉及经营范围和业务组合的调整，属于组织战略。A项职能战略关注人力资源、财务、营销等职能领域如何支持上层战略。B项竞争战略关注进入某一业务领域后如何与竞争对手竞争。C项正确，因为该决策回答了企业准备进入什么领域的问题。D项差异化战略是竞争战略的一种，强调通过产品或服务的独特性取得竞争优势，题干并未体现这一内容。因此答案为C。", "optionAnalysis": {}}, {"id": "13-6", "type": "multi", "stem": "根据组织战略层次的划分，下列战略类型中属于组织发展战略的有（ ）。", "options": {"A": "收缩战略", "B": "竞争战略", "C": "差异化战略", "D": "成长战略", "E": "稳定战略"}, "answer": "ADE", "analysis": "组织发展战略反映组织整体规模和经营范围的发展方向，通常包括成长战略、稳定战略和收缩战略。", "optionAnalysis": {"A": "正确，收缩战略是缩小经营范围或经营规模的发展战略。", "B": "错误，竞争战略是与组织战略并列的另一战略层次，主要回答如何竞争。", "C": "错误，差异化战略是竞争战略的一种具体类型。", "D": "正确，成长战略强调扩大规模、市场或业务范围。", "E": "正确，稳定战略强调维持现有经营范围和发展状态。因此答案为ADE。"}}, {"id": "13-7", "type": "multi", "stem": "下列与收缩战略相匹配的人力资源管理活动，说法正确的是（ ）。", "options": {"A": "关注点在于组织精简和裁员之后留在组织中的员工士气", "B": "不断补充各类人才", "C": "人员的知识和技能需要更新，培训压力大", "D": "鼓励员工与组织共担风险", "E": "员工福利水平比较高"}, "answer": "ACD", "analysis": "收缩战略通常伴随组织精简、业务调整、职位合并或裁员，人力资源管理需要妥善处理员工关系并提高剩余人员的适应能力。", "optionAnalysis": {"A": "正确，裁员可能导致留任员工产生不安全感和士气下降，因此需要重点关注。", "B": "错误，大量补充各类人才更符合成长战略，收缩战略通常会控制招聘规模。", "C": "正确，业务和岗位调整会使员工承担新的工作职责，需要更新知识和技能，培训压力较大。", "D": "正确，收缩期经营风险较高，可以通过风险共担型薪酬或其他机制增强员工与组织的利益一致性。", "E": "错误，收缩战略通常面临成本压力，难以维持较高的福利水平。因此答案为ACD。"}}, {"id": "13-8", "type": "single", "stem": "下列人力资源管理举措中，与外部成长战略相匹配的是（ ）。", "options": {"A": "为组织招募大量新员工", "B": "强调以最小的代价进行组织精简和裁员", "C": "绩效管理的重心是实现绩效管理的多元化", "D": "注重人力资源的重新配置与组织文化的整合"}, "answer": "D", "analysis": "外部成长战略通常通过兼并、收购、战略联盟等方式扩大组织规模，其突出问题是不同组织之间人员、制度和文化的整合。", "optionAnalysis": {"A": "更符合内部成长战略，内部扩张通常需要大量招聘新员工。", "B": "符合收缩战略，需要控制精简和裁员成本。", "C": "不是外部成长战略最具代表性的管理要求。", "D": "正确，兼并或收购后需要重新配置人力资源，并处理不同组织文化之间的冲突与融合。因此答案为D。"}}, {"id": "13-9", "type": "single", "stem": "组织战略层次中，确定如何与竞争对手展开有效竞争。确立竞争优势的战略是（ ）。", "options": {"A": "人才战略", "B": "组织战略", "C": "职能战略", "D": "竞争战略"}, "answer": "D", "analysis": "竞争战略主要解决组织在已经选择的业务领域中如何同竞争对手竞争并建立竞争优势的问题。", "optionAnalysis": {"A": "人才战略属于人力资源领域的具体战略。", "B": "组织战略主要决定经营范围和进入哪些领域。C项职能战略说明各职能部门如何支持组织战略和竞争战略。", "D": "正确，直接对应如何竞争和如何确立竞争优势。因此答案为D。"}}, {"id": "13-10", "type": "multi", "stem": "按照哈佛大学波特教授的划分方法，竞争战略通常划分为（ ）。", "options": {"A": "成长战略", "B": "成本领先战略", "C": "差异化战略", "D": "市场集中战略", "E": "稳定战略"}, "answer": "BCD", "analysis": "按照波特的基本竞争战略理论，企业可采用成本领先战略、差异化战略和集中战略。其中集中战略也常被表述为市场集中战略。", "optionAnalysis": {"A": "错误，成长战略属于组织发展战略。", "B": "正确，成本领先战略通过较低成本取得竞争优势。", "C": "正确，差异化战略通过产品、服务或品牌等方面的独特性取得优势。", "D": "正确，市场集中战略聚焦特定细分市场，并在该市场中形成成本或差异化优势。", "E": "错误，稳定战略属于组织发展战略。因此答案为BCD。"}}, {"id": "13-11", "type": "single", "stem": "某公司采用的战略是在确保产品质量的基础上尽可能地降低成本，这种战略属于（ ）。", "options": {"A": "组织战略", "B": "人力资源管理战略", "C": "职能战略", "D": "竞争战略"}, "answer": "D", "analysis": "题干描述的是企业通过降低成本来取得市场竞争优势，具体体现为成本领先战略，而成本领先战略属于竞争战略。", "optionAnalysis": {"A": "组织战略解决进入哪些业务领域的问题。", "B": "人力资源管理战略主要涉及人才获取、开发、绩效和薪酬等安排。", "C": "职能战略是各职能部门支持上层战略的具体战略。", "D": "正确，因为题干所述战略直接回答企业如何与竞争对手竞争。虽然其具体类型是成本领先战略，但选项中对应的战略层次为竞争战略。因此答案为D。"}}, {"id": "13-12", "type": "single", "stem": "某互联网公司专注于产品创新、不断推出新功能、满足用户个性化需求，该公司招聘时应重点关注的候选人特质是（ ）。", "options": {"A": "技术操作技能", "B": "成本控制能力", "C": "富有创新精神和敢于承担风险", "D": "严格遵守工作流程的能力"}, "answer": "C", "analysis": "该公司通过持续创新和满足个性化需求形成差异化竞争优势，其人力资源管理应重点吸引具有创造力、灵活性和风险承担意愿的人才。", "optionAnalysis": {"A": "技术操作技能可能是岗位所需的基础能力，但不能充分体现差异化创新战略的核心要求。", "B": "更符合成本领先战略对成本效率的关注。", "C": "正确，创新精神和风险承担意愿有助于开发新产品、新功能并满足差异化需求。", "D": "过度强调严格遵守固定流程，可能限制创新和灵活性，更适合标准化程度较高的成本控制型工作。因此答案为C。"}}, {"id": "13-13", "type": "single", "stem": "根据战略层次的划分，人力资源战略属于（ ）。", "options": {"A": "组织战略", "B": "竞争战略", "C": "经营战略", "D": "职能战略"}, "answer": "D", "analysis": "战略一般可以分为组织战略、竞争战略和职能战略。人力资源战略是人力资源管理职能为支持组织战略和竞争战略而制定的具体安排，属于职能战略。", "optionAnalysis": {"A": "决定组织总体发展方向和经营范围。B项或", "C": "主要决定组织在具体业务领域中如何竞争。", "D": "正确，人力资源战略与财务战略、市场营销战略等共同构成职能战略。因此答案为D。"}}, {"id": "13-14", "type": "single", "stem": "某互联网公司的公司简介中有如下三个表述：“成为最受尊敬的互联网企业”；“通过互联网提升人类生活品质”；“正直、进取、合作、创新”，它们分别是这家公司的（ ）。", "options": {"A": "愿景、使命、价值观", "B": "使命、愿景、价值观", "C": "使命、价值观、愿景", "D": "价值观、愿景、使命"}, "answer": "A", "analysis": "愿景描述组织希望在未来成为什么样的组织；使命说明组织存在的根本目的以及为社会或顾客创造什么价值；价值观规定组织及其成员共同遵循的基本信念和行为准则。“成为最受尊敬的互联网企业”描绘未来理想状态，属于愿景；“通过互联网提升人类生活品质”说明企业存在的目的，属于使命；“正直、进取、合作、创新”属于组织倡导的价值观。因此", "optionAnalysis": {"A": "正确，B、C、D三项均将三个概念的对应顺序混淆。"}}, {"id": "13-15", "type": "single", "stem": "某人工智能企业的口号是“让人工智能技术更好地提升人类生活品质”，该口号是企业的（ ）。", "options": {"A": "使命", "B": "愿景", "C": "价值观", "D": "战略"}, "answer": "A", "analysis": "使命说明组织存在的根本目的以及准备为顾客和社会创造何种价值。", "optionAnalysis": {"A": "正确，“通过人工智能技术提升人类生活品质”说明企业存在的目的和社会价值，属于使命。", "B": "愿景描述企业未来希望达到的理想状态，通常回答“将来要成为什么”。", "C": "价值观是组织成员应遵循的基本信念和行为规范。", "D": "战略是实现使命和愿景的总体行动方案，题干中的口号没有说明具体竞争路径。因此答案为A。"}}, {"id": "13-16", "type": "single", "stem": "在企业实现战略目标过程中，需要坚持基本行为规范和道德伦理是指该企业的（ ）。", "options": {"A": "使命", "B": "愿景", "C": "宗旨", "D": "价值观"}, "answer": "D", "analysis": "价值观是组织在经营管理和实现战略目标过程中所坚持的基本信念、行为规范及道德伦理。A项使命回答企业为什么存在以及承担什么责任。B项愿景描述企业未来希望达到的状态。C项宗旨与企业存在目的相关，但不能准确对应具体的行为规范和道德伦理。D项正确，价值观能够为组织成员判断是非和选择行为方式提供标准。因此答案为D。", "optionAnalysis": {}}, {"id": "13-17", "type": "single", "stem": "组织进行战略规划用到SWOT分析方法，其中的S主要是指（ ）。", "options": {"A": "潜在人力资源短缺的威胁", "B": "外部技术进步带来的机遇", "C": "竞争对手进入市场的威胁", "D": "组织内部的财务、技术及人力资源等优势"}, "answer": "D", "analysis": "SWOT中的S是Strengths，即组织内部优势；W是Weaknesses，即内部劣势；O是Opportunities，即外部机会；T是Threats，即外部威胁。", "optionAnalysis": {"A": "属于外部威胁，对应T。", "B": "属于外部机会，对应O。", "C": "属于外部威胁，对应T。", "D": "正确，组织内部拥有的财务、技术及人力资源优势属于S。因此答案为D。"}}, {"id": "13-18", "type": "single", "stem": "企业在进行SWOT分析，分析竞争对手的技术创新的内容属于（ ）。", "options": {"A": "战略机遇分析", "B": "组织劣势分析", "C": "组织优势分析", "D": "战略威胁分析"}, "answer": "D", "analysis": "竞争对手属于企业外部环境。竞争对手的技术创新可能削弱本企业的竞争地位，因此通常应作为外部威胁进行分析。", "optionAnalysis": {"A": "错误，只有当外部变化有利于本企业发展时才属于战略机遇。", "B": "和", "C": "分别是组织内部劣势与内部优势分析，竞争对手的行为不属于组织内部因素。", "D": "正确，竞争对手的技术创新构成企业可能面临的战略威胁。因此答案为D。"}}, {"id": "13-19", "type": "single", "stem": "在制定战略规划阶段，关于人力资源管理与战略规划之间联系的说法，错误的是（ ）。", "options": {"A": "所谓单向联系，是指人力资源部门能够参与战略制定的过程", "B": "所谓双向联系，是指战略规划和人力资源管理之间形成了互动联系", "C": "所谓一体化联系，是指战略规划与人力资源管理之间的互动是动态和全方位的", "D": "所谓行政管理联系，是指人力资源部门不参与组织战略"}, "answer": "A", "analysis": "人力资源管理与战略规划之间的联系通常包括行政管理联系、单向联系、双向联系和一体化联系。", "optionAnalysis": {"A": "错误，单向联系是组织先制定战略规划，再由人力资源部门根据既定战略制定人力资源计划，人力资源部门通常不参与战略制定。", "B": "正确，双向联系强调战略规划部门与人力资源部门之间存在相互反馈。", "C": "正确，一体化联系中的互动具有动态性、持续性和全方位性，人力资源高层通常是战略规划团队成员。", "D": "正确，行政管理联系下人力资源部门主要承担日常行政事务，基本不参与组织战略规划。因此答案为A。"}}, {"id": "13-20", "type": "multi", "stem": "关于不同类型的组织与人力资源管理之间联系的说法，正确的有（ ）。", "options": {"A": "双向联系是理想状态下最具战略性的联系方式", "B": "行政管理联系下，人力资源部门不参与战略规划，仅从事与核心经营无关的日常行政工作", "C": "一体化联系下，人力资源高层作为战略规划团队成员，全程参与动态互动", "D": "单向联系下，人力资源部门参与战略规划的制定过程，并为战略选择提供人力需求分析", "E": "双向联系下，人力资源高层会分析不同战略对人力的需求并反馈给战略规划组，影响战略决策"}, "answer": "BCE", "analysis": "", "optionAnalysis": {"A": "错误，一体化联系而不是双向联系，是理想状态下最具战略性的联系方式。", "B": "正确，行政管理联系下，人力资源部门主要承担工资、档案等日常行政事务，不参与战略规划。", "C": "正确，一体化联系下，人力资源高层进入战略规划团队，持续参与战略制定和执行过程中的动态互动。", "D": "错误，单向联系下战略规划先行，人力资源部门只根据已经形成的战略制定人力资源计划，不参与战略选择。", "E": "正确，双向联系包括先分析不同战略方案对人力资源的要求并反馈给战略规划组，再根据最终战略制定人力资源计划。因此答案为BCE。"}}, {"id": "13-21", "type": "multi", "stem": "战略执行过程中，人力资源管理职能负有主要责任活动有（ ）。", "options": {"A": "开展工作设计", "B": "开发组织的信息系统", "C": "形成完备的培训和开发体系", "D": "配备合适的人员", "E": "设计薪酬管理"}, "answer": "ACDE", "analysis": "战略执行需要通过组织结构、任务安排和员工行为将战略转化为实际行动，人力资源管理承担工作设计、人员配置、培训开发、绩效和薪酬等重要职责。", "optionAnalysis": {"A": "正确，工作设计决定任务如何划分和承担。", "B": "错误，组织信息系统的开发通常主要属于信息技术或相关管理职能，人力资源部门可以参与但不负主要责任。", "C": "正确，培训和开发能够使员工获得执行战略所需的能力。", "D": "正确，招聘、选拔和配置合适人员是人力资源管理的核心职责。", "E": "正确，薪酬管理可以引导和激励员工表现出符合战略要求的行为。因此答案为ACDE。"}}, {"id": "13-22", "type": "single", "stem": "对战略性人力资源管理指标进行量化的方法是（ ）。", "options": {"A": "平衡计分卡", "B": "人力资源计分卡", "C": "关键绩效指标", "D": "战略地图"}, "answer": "B", "analysis": "人力资源计分卡用于将人力资源管理活动、员工行为和组织战略结果联系起来，并通过指标体系量化人力资源管理对战略实施的贡献。", "optionAnalysis": {"A": "平衡计分卡是组织整体绩效管理工具，通常从财务、客户、内部流程、学习与成长等维度评价绩效。", "B": "正确，它是对战略性人力资源管理活动及其结果进行量化的重要工具。", "C": "关键绩效指标是一类指标选择方法，不是题干所指的完整战略性人力资源管理量化工具。", "D": "战略地图主要以图示方式展示战略目标和关键活动之间的因果关系。因此答案为B。"}}, {"id": "13-23", "type": "single", "stem": "作为一种战略性人力资源管理工具，数字仪表盘的作用是（ ）。", "options": {"A": "监控战略执行情况和指标进展", "B": "培训和发展员工", "C": "分解组织战略", "D": "制定人力资源战略"}, "answer": "A", "analysis": "数字仪表盘通过集中、直观地展示关键指标及其变化情况，帮助管理者及时了解战略执行进度并发现偏差。", "optionAnalysis": {"A": "正确，它的核心作用是实时或定期监控指标进展和战略执行情况。", "B": "培训和发展属于具体的人力资源管理活动，不是数字仪表盘的直接功能。", "C": "战略分解通常借助战略地图、平衡计分卡等工具完成。", "D": "人力资源战略需要依据组织战略和环境分析制定，数字仪表盘主要承担监控功能。因此答案为A。"}}, {"id": "13-24", "type": "single", "stem": "战略性人力资源中，实现战略而必须完成的各类关键活动及其相互之间的驱动关系，所使用的工具是（ ）。", "options": {"A": "战略地图", "B": "人力资源计分卡", "C": "数字仪表盘", "D": "胜任素质模型"}, "answer": "A", "analysis": "战略地图以图形方式展示实现战略目标所需的关键活动以及这些活动之间的因果或驱动关系。", "optionAnalysis": {"A": "正确，与题干对“关键活动及其相互驱动关系”的描述一致。", "B": "人力资源计分卡主要用于建立和量化人力资源管理指标。", "C": "数字仪表盘主要用于展示和监控指标进展。", "D": "胜任素质模型描述特定岗位或人员取得高绩效所需的知识、技能、能力和其他特征。因此答案为A。"}}, {"id": "13-25", "type": "multi", "stem": "高绩效工作系统的说法正确的有（ ）。", "options": {"A": "美国早期的高绩效工作系统研究主要集中在服务业", "B": "是能够帮助组织成为高绩效组织的一整套人力资源管理政策", "C": "关注社会系统和技术系统", "D": "组织的人力资源管理系统必须与组织的战略和目标保持一致并且确保后者的实现", "E": "是特定的人力资源管理方法和思路"}, "answer": "BCDE", "analysis": "高绩效工作系统强调将相互配合的人力资源管理政策和实践整合为系统，并使其与组织战略及工作技术相匹配。", "optionAnalysis": {"A": "错误，美国早期相关研究主要集中在制造业，而非服务业。", "B": "正确，高绩效工作系统是一整套能够提高员工能力、动机和参与机会，进而促进组织绩效的人力资源管理政策与实践。", "C": "正确，该系统体现社会技术系统思想，同时关注人员、关系等社会系统和设备、流程等技术系统。", "D": "正确，人力资源管理系统必须与组织战略和目标保持一致，并支持战略实现。", "E": "正确，高绩效工作系统代表一类强调人力资源实践相互配合并促进高绩效的管理方法和思路。因此答案为BCDE。"}}, {"id": "13-26", "type": "single", "stem": "下列关于人才管理的说法，错误的是（ ）。", "options": {"A": "人才管理要求多途径获取人才", "B": "人才管理要求人才工作具有前瞻性和主动性", "C": "人才管理重在一次性大规模招聘优秀人才", "D": "人才管理重视人才开发的投资回报率"}, "answer": "C", "analysis": "人才管理强调根据组织未来战略需要，以系统和持续的方式吸引、开发、配置及保留关键人才。", "optionAnalysis": {"A": "正确，组织可以通过内部培养、外部招聘、合作等多种途径获取人才。", "B": "正确，人才管理需要预测未来人才需求并提前采取行动。", "C": "错误，人才管理不是一次性、大规模招聘优秀人才，而是持续进行需求预测、人才获取、培养、配置和保留。", "D": "正确，人才开发需要关注投入产出效果，提高人才培养投资的回报率。因此答案为C。"}}, {"id": "13-27", "type": "single", "stem": "根据人才管理的理念，组织中的中高层领导扮演的角色应该是（ ）。", "options": {"A": "命令型领导", "B": "指挥型领导", "C": "严格型领导", "D": "影响型领导"}, "answer": "D", "analysis": "人才管理强调赋能、协作、人才培养和组织影响，中高层领导应通过愿景、价值观、沟通和示范行为影响员工，而不是仅依靠职位权力发布命令。", "optionAnalysis": {"A": "和", "B": "都过度强调自上而下的命令与控制，不符合现代人才管理对员工自主性和参与感的要求。", "C": "只强调管理严格程度，不能体现人才开发和影响员工的核心职责。", "D": "正确，影响型领导通过沟通、激励、辅导和榜样作用吸引并发展人才。因此答案为D。"}}, {"id": "13-28", "type": "single", "stem": "关于人才管理中的人才“零库存”模式的观点，错误的是（ ）。", "options": {"A": "“购买”人才比“制造人才”更重要", "B": "需小规模，多批次的培养人才", "C": "提高人才开发投资回报率", "D": "组织应适应人才需求的不确定性"}, "answer": "A", "analysis": "人才“零库存”模式借鉴供应链管理思想，目的在于减少人才供给过剩或短缺，通过灵活获取和分批培养适应需求的不确定性。", "optionAnalysis": {"A": "错误，该模式并不简单主张外部“购买”人才比内部“制造”人才更重要，而是要求根据成本、岗位和需求变化合理选择内部培养与外部获取。", "B": "正确，小规模、多批次培养能够减少一次性大量培养带来的供需错配。", "C": "正确，避免无效储备有利于提高人才开发投资回报率。", "D": "正确，该模式正是为了应对组织未来人才需求的不确定性。因此答案为A。"}}, {"id": "13-29", "type": "multi", "stem": "关于人才管理的说法，正确的有（ ）。", "options": {"A": "它主张通过供应链管理原则实现人才的“零库存”配置", "B": "它是传统人力资源管理中的一个模块", "C": "它主张加强人力资源管理能力建设", "D": "它主要关注绩效最为顶尖的A类人才的开发", "E": "它聚焦对组织成功起到关键作用的核心岗位上的员工第十四章人力资源规划"}, "answer": "ACE", "analysis": "人才管理是一种以组织战略和关键岗位人才需求为核心的系统管理理念。", "optionAnalysis": {"A": "正确，人才管理借鉴供应链管理原则，通过预测需求、灵活获取和分批培养等方式实现人才的“零库存”配置。", "B": "错误，人才管理不是传统人力资源管理中的单一模块，而是贯穿人才吸引、开发、配置和保留过程的系统性管理理念。", "C": "正确，人才管理要求提升人力资源部门和直线管理者识别、获取、培养及保留人才的能力。", "D": "错误，人才管理并非只关注当前绩效最顶尖的A类人才，还关注关键岗位、人才潜力和未来战略需要。", "E": "正确，现代人才管理强调识别对组织成功具有关键作用的岗位，并重点管理这些岗位上的人才。因此答案为ACE。"}}]}, {"id": 14, "title": "人力资源规划", "questions": [{"id": "14-1", "type": "single", "stem": "关于人力资源规划流程的说法，错误的是（ ）。", "options": {"A": "通过对组织战略规划的细致分析明确企业在规划期内的人力资源需求", "B": "对组织外部的劳动力市场形势以及内部的人员供给情况进行分析", "C": "人力资源供求平衡分析是根据前两个步骤预测出的人力资源需求和人力资源供给情况，得出组织在规划期内可能会出现的人力资源供求平衡情况", "D": "实施人力资源供求平衡计划是根据前两个步骤预测出的人力资源需求和人力资源供给情况，得出组织在规划期内可能会出现的人力资源供求平衡情况"}, "answer": "D", "analysis": "人力资源规划通常包括人力资源需求预测、人力资源供给预测、供求匹配分析以及制定并实施供求平衡计划等环节。", "optionAnalysis": {"A": "正确，组织战略及经营目标是预测人力资源需求的重要依据。", "B": "正确，供给预测既要分析内部人员状况，也要考虑外部劳动力市场。", "C": "正确，供求平衡分析是将需求预测结果与供给预测结果进行比较，判断是否存在数量或结构上的短缺、过剩或平衡。", "D": "错误，其表述实际上仍是供求平衡分析的内容；实施供求平衡计划是针对分析发现的短缺、过剩或结构不匹配采取招聘、培训、调配、裁员、外包等措施。"}}, {"id": "14-2", "type": "single", "stem": "关于人力资源规划的说法，正确的是（ ）。", "options": {"A": "人力资源规划必须在内外部环境稳定的情况下才能开展", "B": "人力资源规划可以不考虑控制人工成本的因素", "C": "人力资源规划是组织主动应对环境变化的过程", "D": "人力资源规划对组织战略目标实现的作用不大"}, "answer": "C", "analysis": "人力资源规划是组织根据战略目标和环境变化，对未来人力资源需求与供给进行预测并采取相应措施的过程。", "optionAnalysis": {"A": "错误，环境越具有变化性和不确定性，组织越需要通过规划提前识别风险并准备应对方案，而不是只有环境稳定时才能规划。", "B": "错误，人力资源规划需要兼顾人员配置效率、人工成本控制和组织经营目标。", "C": "正确，人力资源规划具有前瞻性和主动性，能够帮助组织应对技术、市场及劳动力供给等变化。", "D": "错误，人力资源是组织战略落地的重要保障，人力资源规划对战略目标实现具有重要作用。"}}, {"id": "14-3", "type": "single", "stem": "电子化交易程序的广泛运用，使得证券交易公司对传统证券交易员的需求减少。这体现了人力资源需求的重要影响因素之一是（ ）。", "options": {"A": "产品和服务变化", "B": "组织结构调整", "C": "组织的技术变革", "D": "组织战略定位调整"}, "answer": "C", "analysis": "电子化交易程序替代了传统证券交易员的部分重复性工作，直接改变了完成业务所需的人员数量和技能结构，属于技术变革对人力资源需求的影响。", "optionAnalysis": {"A": "不符合题意，材料强调的是交易方式和工具的技术变化，而不是产品或服务种类的变化。", "B": "不符合题意，材料未体现部门设置、管理层级或权责关系调整。", "C": "正确，新技术能够替代部分人工劳动，并产生新的技能需求。", "D": "不符合题意，材料未说明企业目标市场、竞争方式或战略方向发生调整。"}}, {"id": "14-4", "type": "multi", "stem": "影响人力资源需求预测的因素包括（ ）。", "options": {"A": "组织结构调整情况", "B": "组织的技术变革", "C": "劳动力市场就业情况", "D": "组织经营产品的市场情况", "E": "组织的战略定位"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确，组织结构调整会改变部门设置、管理层级和岗位数量，从而影响人员需求。", "B": "正确，技术变革可能替代部分劳动，也可能产生新的岗位和技能需求。", "C": "错误，劳动力市场就业情况主要影响组织能够获得多少外部劳动力，通常属于人力资源供给预测的影响因素。", "D": "正确，产品市场需求会影响业务量、生产经营规模以及相应的用工数量。", "E": "正确，组织战略定位决定业务发展方向、经营规模和核心能力要求，是需求预测的重要依据。"}}, {"id": "14-5", "type": "multi", "stem": "以下人力资源需求预测的方法属于定性方法的是（ ）。", "options": {"A": "经验判断法", "B": "德尔菲法", "C": "比率分析法", "D": "趋势预测法", "E": "回归分析法"}, "answer": "AB", "analysis": "", "optionAnalysis": {"A": "正确，经验判断法主要依靠管理者根据经验和业务认识作出判断，属于定性预测方法。B项正确，德尔菲法通过多轮匿名征询专家意见并逐步形成较一致的判断，属于定性预测方法。", "C": "错误，比率分析法根据业务量与人员数量之间的比例关系进行预测，属于定量方法。", "D": "错误，趋势预测法利用历史人员数量的变化趋势推测未来需求，属于定量方法。", "E": "错误，回归分析法借助统计模型分析人员需求与相关变量之间的数量关系，属于定量方法。"}}, {"id": "14-6", "type": "single", "stem": "在进行人力资源需求预测时采用经验判断法，下列说法错误的是（ ）。", "options": {"A": "经验判断法适用于长期预测", "B": "经验判断法是一种最简单的人力资源需求预测方法", "C": "经验判断法要求管理者具有丰富的工作经验", "D": "经验判断法是一种定性的方法"}, "answer": "A", "analysis": "经验判断法主要依靠管理者对业务量、人员配置和组织状况的了解进行判断，通常适用于规模较小、经营环境较稳定以及短期预测。", "optionAnalysis": {"A": "错误，预测期间越长，不确定因素越多，仅依赖个人经验的可靠性越低，因此该方法通常不适合长期预测。", "B": "正确，经验判断法操作较为简单，不需要复杂的统计模型。", "C": "正确，预测质量在很大程度上取决于管理者的经验、判断能力和对业务的熟悉程度。D项正确，该方法以主观判断为主，属于定性预测方法。"}}, {"id": "14-7", "type": "single", "stem": "德尔菲法具有一些明显的优点，其中不包括（ ）。", "options": {"A": "花费时间较短", "B": "避免了从众的行为", "C": "具有较高的准确性", "D": "能吸取和综合众多专家的意见"}, "answer": "A", "analysis": "德尔菲法通常需要经过多轮专家意见征询、反馈、修正和汇总，因此耗费时间相对较长，花费时间较短并不是其优点。", "optionAnalysis": {"A": "符合题意。", "B": "属于德尔菲法的优点，专家通常匿名、彼此不直接讨论，可以降低权威压力和从众行为。", "C": "属于其优点，通过多轮反馈和意见修正，预测结果一般比单个专家的判断更稳定。", "D": "属于其优点，该方法可以汇集不同领域专家的知识和经验。"}}, {"id": "14-8", "type": "multi", "stem": "关于人力资源需求预测中的德尔菲法的说法，正确的有（ ）。", "options": {"A": "德尔菲法是一种定量的预测方法", "B": "德尔菲法要求挑选出来的专家具有代表性", "C": "德尔菲法要求专家彼此不见面、不沟通", "D": "德尔菲法要求专家人数不能多于10位", "E": "德尔菲法需要进行多轮预测"}, "answer": "BCE", "analysis": "", "optionAnalysis": {"A": "错误，德尔菲法主要依靠专家的知识、经验和判断，属于定性预测方法。", "B": "正确，专家应当熟悉预测问题并具有一定代表性，才能从不同角度提供有效意见。", "C": "正确，德尔菲法通常采用匿名、背对背的方式征询意见，专家彼此不直接见面或讨论，以减少从众和权威影响。", "D": "错误，德尔菲法没有专家人数不得超过10位的固定要求，人数应根据问题复杂程度和专家代表性确定。", "E": "正确，德尔菲法通常进行多轮征询，并把上一轮汇总结果反馈给专家修正判断。"}}, {"id": "14-9", "type": "single", "stem": "关于人力资源需求预测方法中主观判断法的说法，错误的是（ ）。", "options": {"A": "德尔菲法一般要进行多轮预测", "B": "德尔菲法能够避免从众行为", "C": "经验判断法适用于规模较小或环境稳定的组织", "D": "经验判断法适用于长期的预测"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，德尔菲法通过多轮征询、反馈和修正逐步形成预测意见。", "B": "正确，专家匿名并彼此隔离作答，可以降低群体压力和从众现象。", "C": "正确，规模较小或环境较稳定的组织，其人员需求关系相对简单，管理者经验通常具有较高参考价值。", "D": "错误，长期预测面临较多不确定因素，单纯依靠个人经验容易产生偏差，经验判断法更适合短期预测。"}}, {"id": "14-10", "type": "single", "stem": "幼儿园通过幼师幼儿比确定需要招聘的幼师人数是（ ）。", "options": {"A": "比率分析", "B": "趋势分析", "C": "经验法", "D": "相关分析"}, "answer": "A", "analysis": "幼师幼儿比反映幼师人数与幼儿人数之间的比例关系。幼儿园可以根据预计幼儿人数和合理的幼师幼儿比计算所需幼师人数，因此属于比率分析法。例如，预计有300名幼儿，合理比例为1∶\n15，则所需幼师人数为300÷15＝20人；再将20人与现有可用幼师人数比较，即可确定招聘数量。B项趋势分析依据历史人员数量的变化趋势预测未来需求。C项经验法主要依靠管理者的主观经验。D项相关分析强调变量之间的统计相关关系，不是本题所述的固定比例计算。", "optionAnalysis": {}}, {"id": "14-11", "type": "single", "stem": "关于企业人力资源供给预测的说法，错误的是（ ）。", "options": {"A": "经济发展形势和毕业生规模会对企业的人力资源供给产生影响", "B": "企业人力资源供给预测的是外部人力资源状况", "C": "企业人力资源供给情况会受到外部劳动力市场供给情况的影响", "D": "企业人力资源供给预测需综合考虑人力资源供给的数量、质量和结构等情况"}, "answer": "B", "analysis": "企业人力资源供给预测既包括内部供给预测，也包括外部供给预测。", "optionAnalysis": {"A": "正确，宏观经济形势、教育发展情况和毕业生规模等都会影响外部劳动力供给。", "B": "错误，其将供给预测片面限定为外部人力资源状况，忽略了组织内部现有员工的晋升、调动、离职、退休及能力变化。", "C": "正确，企业从外部招聘人员的数量和质量会受到劳动力市场状况影响。", "D": "正确，供给预测不仅要关注人数，还要关注人员质量、技能和职位结构能否满足需要。"}}, {"id": "14-12", "type": "multi", "stem": "关于人力资源供给预测方法中人员替换分析法的说法，正确的是（ ）。", "options": {"A": "有利于激励员工士气，同时降低招聘成本", "B": "有助于为未来的职位需求提前做好准备", "C": "需要对候选人的能力水平和晋升潜力进行评估", "D": "强调从组织外部招聘员工中填补职位空缺", "E": "主要用于组织内特定职位上的合格候选人确定"}, "answer": "ABCE", "analysis": "人员替换分析法通常通过人员替换图或职位替换卡，识别组织内部能够接替关键职位的候选人。", "optionAnalysis": {"A": "正确，优先从内部选拔能够为员工提供晋升机会、提高士气，并减少部分外部招聘成本。", "B": "正确，该方法能够提前识别关键职位的后备人员，为未来职位空缺做好准备。", "C": "正确，确定替补人员时需要评估其当前绩效、能力水平、发展需求和晋升潜力。", "D": "错误，该方法强调分析和开发组织内部候选人，而不是强调外部招聘。", "E": "正确，其主要用途就是确定组织内特定职位的合格替补人选。"}}, {"id": "14-13", "type": "multi", "stem": "关于人力资源供给预测中的马尔科夫分析法的说法，正确的有（ ）。", "options": {"A": "它可以预测组织在未来的人力资源供给状况", "B": "它主要用于对外部劳动力市场上的劳动力供给趋势的分析", "C": "它是于单一职位上的员工流动情况进行内部劳动力供给预测", "D": "它能够帮助预测员工在组织中的职业发展通道", "E": "它会分析员工在不同时间点上在组织内不同职位类型间的转换情况"}, "answer": "ADE", "analysis": "马尔科夫分析法利用不同职位或职位类别之间的人员转移概率，预测未来各职位类别的内部人员供给。", "optionAnalysis": {"A": "正确，将期初各职位人数与转移概率矩阵结合，可以预测未来内部人员分布。", "B": "错误，该方法主要分析组织内部不同职位之间以及在职与离职状态之间的转移，不是外部劳动力市场趋势分析方法。", "C": "错误，马尔科夫分析并非只考察单一职位，而是考察多个职位或状态之间的流动。D项正确，职位之间的转移路径可以反映员工可能的晋升、调动和职业发展通道。", "E": "正确，转移矩阵的核心就是描述不同时间点上人员在不同职位状态之间的转换概率。"}}, {"id": "14-14", "type": "single", "stem": "企业人力资源需求小于供给时，企业适合采取的策略（ ）。", "options": {"A": "鼓励员工加班", "B": "招募人员", "C": "裁员", "D": "非核心业务外包"}, "answer": "C", "analysis": "当人力资源需求小于供给时，说明组织存在劳动力过剩，应采取减少人员供给或降低人员成本的措施。", "optionAnalysis": {"A": "错误，加班用于在人员短缺时增加现有员工的工作投入。", "B": "错误，继续招聘会进一步扩大人员过剩。", "C": "正确，裁员能够较快减少劳动力供给，但对员工伤害较大，实施时应依法合规并评估长期影响。", "D": "错误，非核心业务外包通常用于应对人员短缺、控制新增人员规模或获取外部专业能力，并非已有人员过剩时最直接的措施。"}}, {"id": "14-15", "type": "multi", "stem": "企业在面临需求大于供给时，通常可采取的对策有（ ）。", "options": {"A": "冻结雇佣，通过自然减员平衡状况", "B": "延长现有员工的工作时间", "C": "扩大外部招募范围，加大招募投入", "D": "鼓励员工提前退休", "E": "通过培训提升现有员工工作效率"}, "answer": "BCE", "analysis": "需求大于供给意味着组织存在劳动力短缺，应增加可用劳动力或提高劳动生产率。", "optionAnalysis": {"A": "错误，冻结雇用和自然减员会减少人员供给，适用于劳动力过剩。", "B": "正确，延长工作时间能够在短期内快速增加劳动投入。", "C": "正确，扩大招聘范围和投入有助于增加外部人员供给。", "D": "错误，提前退休会减少现有人员，不利于缓解短缺。", "E": "正确，通过培训改进技能和工作方法，可以提高现有员工的工作效率，从而缓解人员数量或能力不足。"}}, {"id": "14-16", "type": "multi", "stem": "人力资源需求与供给结构不匹配的组织对策有（ ）。", "options": {"A": "加强对现有人员的培训开发，适应工作需要", "B": "延长现有员工的工作时间", "C": "将组织的部分非核心的业务外包出去", "D": "将不适合的员工裁掉，重新招用合适的员工", "E": "将原来的一些技能不足的老员工逐渐替换到一些辅助性的工作岗位上"}, "answer": "ADE", "analysis": "结构不匹配是指人员总量可能基本平衡，但员工的专业、技能、职位层级或岗位分布与组织需要不一致。", "optionAnalysis": {"A": "正确，培训开发可以帮助现有人员获得目标岗位需要的知识和技能。", "B": "错误，延长工作时间主要解决短期人员数量不足，不能从根本上解决技能或职位结构不匹配。", "C": "错误，业务外包主要用于减少内部用工需求或解决短期、非核心业务的人员不足，不是调整内部人员结构的主要措施。", "D": "正确，当部分员工无法通过培训适应岗位要求时，可以依法调整或裁减并重新招聘合适人员。", "E": "正确，将技能不足人员调至与其能力相适应的辅助岗位，有助于优化内部岗位配置。"}}, {"id": "14-17", "type": "multi", "stem": "企业劳动力过剩，解决问题速度快但是对员工伤害性高的措施（ ）。", "options": {"A": "降级", "B": "冻结雇用", "C": "裁员", "D": "降薪", "E": "鼓励提前退休"}, "answer": "ACD", "analysis": "", "optionAnalysis": {"A": "正确，降级可以较快调整职位和人工成本，但会影响员工地位、收入及职业发展，对员工伤害较大。", "B": "错误，冻结雇用主要依靠岗位自然空缺逐步减少人员，见效通常较慢，对现有员工伤害相对较低。", "C": "正确，裁员减少人员的速度快，但会直接导致员工失业，也可能损害留任员工的安全感。", "D": "正确，降薪能够较快降低人工成本，但直接影响员工收入，伤害程度较高。", "E": "错误，鼓励提前退休通常属于相对温和的人员缩减方式，对员工的强制性和伤害程度一般低于裁员、降级和降薪。"}}, {"id": "14-18", "type": "single", "stem": "关于企业减少劳动力过剩的方法的说法，正确的是（ ）。", "options": {"A": "鼓励提前退休的方法员工受伤害程度高", "B": "冻结雇用的方法见效速度快", "C": "自然减员的方法员工受伤害程度低", "D": "职位分享的方法见效速度慢"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，鼓励提前退休通常通过补偿和自愿选择减少人员，员工受伤害程度相对较低。", "B": "错误，冻结雇用需要等待员工离职、退休或岗位自然空缺，见效速度通常较慢。", "C": "正确，自然减员是通过员工正常退休、辞职等方式逐步减少人数，一般不直接解雇员工，因此伤害程度较低，但见效较慢。", "D": "错误，职位分享通过由两名或多名员工共同承担一个全职岗位，可以较快降低单个员工的工作时间和组织的总劳动投入，并非典型的见效缓慢措施。"}}, {"id": "14-19", "type": "single", "stem": "如果企业的人力资源需求增长是长期性的，那么适合采取的对策是（ ）。", "options": {"A": "让现有员工多加班", "B": "雇用一些临时工", "C": "招聘新员工", "D": "鼓励员工进行职位分享"}, "answer": "C", "analysis": "长期性人力资源需求增长意味着新增工作量具有持续性，企业需要形成稳定的人员供给。", "optionAnalysis": {"A": "错误，长期加班容易导致疲劳、成本上升和工作生活失衡，更适合解决短期需求。", "B": "错误，临时工适合季节性、临时性或不确定的用工需求。", "C": "正确，招聘正式新员工能够形成较稳定的长期人员供给，并便于持续培训和组织能力建设。", "D": "错误，职位分享会减少单个员工承担的工作时间，通常用于处理劳动力过剩或满足灵活就业需要，不能有效解决长期人员短缺。"}}, {"id": "14-20", "type": "single", "stem": "劳动力短缺，见效快，可撤回程度高的是（ ）。", "options": {"A": "培训转岗", "B": "招新员工", "C": "延长工作时间", "D": "进行技术创新"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，培训转岗需要进行人员选择和技能培养，见效通常不是最快，但有助于解决结构性短缺。", "B": "错误，招聘新员工需要招募、甄选和入职培养，且形成劳动关系后撤回成本较高。", "C": "正确，安排现有员工加班可以迅速增加劳动投入；短缺缓解后可以停止加班，因此可撤回程度较高。", "D": "错误，技术创新可能长期提高生产率、减少人员需求，但研发、引进和实施通常需要较长时间，且投入后不容易撤回。"}}, {"id": "14-21", "type": "single", "stem": "某电商企业在“双十一”期间订单量暴增、工作量大大增加，导致短期内出现了明显的人力资源需求大于人力资源供给的情况，该企业最适合采取的应对措施是（ ）。", "options": {"A": "延长现有员工的工作时间", "B": "大规模招聘全职员工", "C": "冻结所有岗位的人员录用", "D": "鼓励部分老员工提前退休"}, "answer": "A", "analysis": "材料明确说明人员短缺是“双十一”期间订单暴增造成的短期、季节性短缺，企业应优先采用见效快且容易撤回的措施。", "optionAnalysis": {"A": "正确，适度延长现有员工工作时间能够迅速增加劳动投入，业务高峰结束后即可停止，但企业应依法支付加班报酬并保障员工休息。", "B": "错误，大规模招聘全职员工会形成长期用工成本，高峰结束后可能出现人员过剩。", "C": "错误，冻结录用会进一步限制人员供给。", "D": "错误，提前退休会减少现有人员，与缓解短期短缺的目标相反。"}}, {"id": "14-22", "type": "single", "stem": "下列关于裁员的说法，错误的是（ ）。", "options": {"A": "管理不当的裁员有可能产生长期性的负面作用", "B": "许多企业在裁员过程中放走的一些员工实际上属于根本无法替代的企业重要资产", "C": "研发密集型公司进行裁员不会降低企业的长期利润", "D": "那些在裁员过程中侥幸得以留在企业里的员工会对企业心存戒备，他们的工作积极性可能会大幅下降"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "正确，管理不当的裁员可能破坏员工信任、组织声誉和知识积累，并产生长期负面影响。", "B": "正确，企业若只按短期成本标准裁员，可能流失掌握关键技术、客户关系或隐性知识的重要员工。", "C": "错误，研发密集型企业依赖专业人才、团队协作和知识积累，裁员可能削弱创新能力并降低长期利润，不能断言不会产生影响。", "D": "正确，留任员工可能出现不安全感和“幸存者综合征”，对企业产生戒备，工作投入和积极性可能下降。"}}, {"id": "14-23", "type": "single", "stem": "一些美国公司将原本设在本土的客户呼叫服务中心迁往印度，这种做法属于（ ）。", "options": {"A": "离岸经营", "B": "培训转岗", "C": "临用工", "D": "工作分享"}, "answer": "A", "analysis": "离岸经营是将原来在本国完成的工作转移到其他国家或地区完成，通常是为了利用成本、人才或时区等方面的优势。", "optionAnalysis": {"A": "正确，将美国本土的呼叫服务中心迁往印度符合离岸经营的特征。", "B": "错误，培训转岗是通过培训使现有员工转移到其他岗位。", "C": "错误，临时用工强调劳动关系或用工期限的临时性，材料强调的是工作地点跨国转移。", "D": "错误，工作分享是由多名员工共同承担一个全职岗位的工作时间和职责。"}}, {"id": "14-24", "type": "single", "stem": "关于离岸经营的说法，错误的是（ ）。", "options": {"A": "对模块化的工作岗位比较适合采取离岸经营的做法", "B": "离岸经营会将工作岗位转移到其他国家", "C": "对高技能工作岗位不适宜采取离岸经营的做法", "D": "对生产类及呼叫中心等服务岗位采取离岸经营做法的情况较多"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "正确，流程标准化、任务可分割和成果易衡量的模块化岗位更便于跨国转移和远程协作。", "B": "正确，离岸经营的基本特征就是将部分工作岗位或业务活动转移到其他国家。", "C": "错误，离岸经营并不限于低技能岗位，软件开发、工程设计、财务分析等部分高技能工作在具备人才、技术和管理条件时也可以离岸完成。", "D": "正确，生产加工、后台处理和客户呼叫中心等标准化程度较高的业务是较常见的离岸经营对象。14-25"}}, {"id": "14-25", "type": "case", "material": "近年来，F公司每年都会进行人力资源规划工作，积累了丰富的公司人员和职位数据。公司发现，进行人力资源供给预测时，利用转移矩阵的方法比较有效。\n\n岗位调动概率表（行=上年度岗位，列=本年度岗位）：\n销售经理→销售经理0.95、不在企业0.05\n销售代表→销售经理0.05、销售代表0.60、不在企业0.35\n见习销售→销售代表0.20、见习销售0.50、不在企业0.30\n厂长助理→厂长助理0.90、生产管理0.05、不在企业0.05\n生产管理→厂长助理0.10、生产管理0.75、不在企业0.15\n生产操作→生产管理0.10、生产操作0.80、不在企业0.10\n行政事务→行政事务0.70、不在企业0.30\n不在企业→销售代表0.20、见习销售0.50、厂长助理0.00、生产管理0.10、生产操作0.20、行政事务0.30\n\n根据以上材料回答下列问题", "subQuestions": [{"stem": "该公司所采用的利用转移矩阵进行人力资源供给预测分析的方法属于（ ）。", "options": {"A": "人员替换分析法", "B": "马尔科夫分析法", "C": "比率分析法", "D": "回归分析法"}, "id": "14-25-1", "type": "multi", "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，人员替换分析法主要用于确定某一关键职位的内部接替候选人，通常通过人员替换图或职位替换卡呈现。", "B": "正确，马尔科夫分析法利用人员在不同职位状态之间的转移概率构建转移矩阵，并据此预测未来各职位的人力资源供给。", "C": "错误，比率分析法根据业务量与人员数量之间的比例关系进行预测。", "D": "错误，回归分析法通过统计模型研究人力资源需求与相关变量之间的数量关系。"}}, {"stem": "该公司工作岗位中，本年度仍然在原岗位比率最高的有（ ）。", "options": {"A": "行政事务", "B": "生产操作", "C": "生产管理", "D": "销售经理"}, "id": "14-25-2", "type": "multi", "answer": "D", "analysis": "判断员工仍在原岗位的比率，应查看转移矩阵中各岗位对应的主对角线概率。行政事务留在原岗位的概率为0.70，即70%；生产操作为0.80，即80%；生产管理为0.75，即75%；销售经理为0.95，即95%。比较结果为95%＞80%＞75%＞70%，因此销售经理留在原岗位的比率最高。", "optionAnalysis": {"A": "为70%，不是最高；", "B": "为80%，低于销售经理；", "C": "为75%，低于销售经理；", "D": "为95%，正确。"}}, {"stem": "没有上升空间的职位有（ ）。", "options": {"A": "见习销售员", "B": "销售代表", "C": "行政事务", "D": "生产管理"}, "id": "14-25-3", "type": "multi", "answer": "C", "analysis": "应根据转移矩阵判断某职位人员是否存在向更高层级岗位转移的路径。", "optionAnalysis": {"A": "错误，见习销售员有0.20的概率转为销售代表，存在上升通道。", "B": "错误，销售代表有0.05的概率转为销售经理，存在上升通道。", "C": "正确，行政事务人员只有留在行政事务岗位或离开企业两种状态，矩阵中没有显示其向更高职位转移的路径。", "D": "错误，生产管理人员有0.10的概率转为厂长助理，存在上升空间。"}}, {"stem": "要培养销售代表，该公司可采取的应对措施有（ ）。", "options": {"A": "努力降低该职位员工的流失率", "B": "加快见习销售员的培训和成长力度", "C": "扩大对该类员工的外部招募规模", "D": "缩短工作时间，进行工作分享第十五章甄选"}, "id": "14-25-4", "type": "multi", "answer": "ABC", "analysis": "根据转移矩阵，上年度销售代表中有0.60留在原岗位、0.05晋升为销售经理、0.35离开企业，流失率较高；见习销售员中有0.20转为销售代表；企业外部人员也可以进入销售代表岗位。", "optionAnalysis": {"A": "正确，降低销售代表35%的流失率能够直接稳定该岗位的内部供给。", "B": "正确，加强见习销售员培训，提高其成长和晋升速度，可以增加内部销售代表供给。", "C": "正确，扩大外部招聘可以从组织外部补充销售代表。", "D": "错误，缩短工作时间和工作分享会减少现有人员的有效劳动投入，通常用于应对劳动力过剩或满足灵活工作需要，不能增加销售代表的人员供给。"}}], "analysis": ""}]}, {"id": 15, "title": "甄选", "questions": [{"id": "15-1", "type": "single", "stem": "关于信度与效度的关系的说法，正确的是（ ）。", "options": {"A": "信度与效度的含义相同", "B": "一个测验有效却不一定可信", "C": "信度和效度互为必要且充分条件", "D": "一个测验可信但不一定有效"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，信度反映测试结果的一致性和稳定性，效度反映测试能否准确测量其intendedconstruct，即是否测到了应当测量的内容，二者含义不同。", "B": "错误，信度是效度的必要条件。一个测试如果缺乏稳定性和一致性，就不可能具有较高效度，因此有效的测试通常必须具备一定信度。", "C": "错误，信度是效度的必要条件，但不是充分条件；测试结果稳定并不代表测试内容一定有效。", "D": "正确，一个测试可能多次测量结果非常稳定，但测量的并不是目标内容，因此可能可信而无效。"}}, {"id": "15-2", "type": "single", "stem": "对同一群人用同一种测试工具测试多次所得到的一致性程度又称（ ）。", "options": {"A": "内部一致性信度", "B": "复本信度", "C": "评价者信度", "D": "重测信度"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，内部一致性信度考察同一测试内部各题目之间的一致程度。", "B": "错误，复本信度考察两个等值测试版本所得结果的一致程度。", "C": "错误，评价者信度考察不同评价者使用同一工具进行评价时评分结果的一致程度。", "D": "正确，重测信度是对同一组被测试者在不同时间使用同一种测试工具进行重复测试，并比较多次测试结果的一致性。"}}, {"id": "15-3", "type": "single", "stem": "同一测试内容多个题目得分的一致性属于（ ）。", "options": {"A": "内部一致性信度", "B": "构想效度", "C": "评价者信度", "D": "效标效度"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，内部一致性信度反映同一测试中多个题目是否共同测量相同或相近的内容，以及各题得分之间的一致程度。", "B": "错误，构想效度反映测试能否有效测量某一理论构想或心理特质。", "C": "错误，评价者信度反映不同评价者评分结果的一致性。", "D": "错误，效标效度反映测试结果与外部效标之间的相关程度。"}}, {"id": "15-4", "type": "single", "stem": "不同评价者在使用同一种测试工具时所给出的分数之间的一致性程度，称为（ ）。", "options": {"A": "内部一致性信度", "B": "评价者信度", "C": "复本信度", "D": "重测信度"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，内部一致性信度关注同一测试内部不同题目的得分是否一致。", "B": "正确，评价者信度是不同评价者依据同一种工具或标准对同一对象评分时，评分结果之间的一致程度。", "C": "错误，复本信度比较的是两个等值测试版本的结果。", "D": "错误，重测信度比较的是同一测试在不同时间重复施测的结果。"}}, {"id": "15-5", "type": "single", "stem": "某个测试的目的是测试求职者的逻辑推理能力，测试设计的题目却主要围绕文字写作能力展开。该测试的（ ）比较低。", "options": {"A": "内部一致性信度", "B": "效标效度", "C": "内容效度", "D": "复本信度"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，即使测试题目之间具有较高一致性，也不能说明这些题目覆盖了应当测量的逻辑推理能力。", "B": "错误，题干没有说明测试结果与工作绩效等外部效标之间的关系。", "C": "正确，内容效度考察测试内容是否具有代表性，能否覆盖拟测量的知识、技能或能力领域。测试目标是逻辑推理能力，题目却主要考查文字写作能力，说明测试内容与测试目标不匹配，内容效度较低。", "D": "错误，题干没有涉及两个等值版本测试结果之间的一致性。"}}, {"id": "15-6", "type": "single", "stem": "关于内容效度的说法，正确的是（ ）。", "options": {"A": "内容效度的检验主要采用专家判断方法", "B": "内容效度是指能够测量出理论构想的程度", "C": "内容效度反映的是不同评价人员评价结果的一致性", "D": "内容效度反映的是两个测验在内容上的等值性程度"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，内容效度通常由相关领域专家对测试内容的代表性、覆盖范围及其与测试目标的匹配程度进行判断。", "B": "错误，能够测量出理论构想的程度属于构想效度。", "C": "错误，不同评价人员评价结果的一致性属于评价者信度。", "D": "错误，两个等值测试版本所得结果的一致程度属于复本信度，不是内容效度。"}}, {"id": "15-7", "type": "multi", "stem": "下列属于效标效度的是（ ）。", "options": {"A": "内容效度", "B": "构想效度", "C": "预测效度", "D": "同时效度", "E": "分半效度"}, "answer": "CD", "analysis": "", "optionAnalysis": {"A": "错误，内容效度关注测试内容是否代表拟测量的内容领域，不属于效标效度。", "B": "错误，构想效度关注测试能否测量理论上的心理构想或特质，不属于效标效度。", "C": "正确，预测效度是用当前测试结果预测被测试者未来表现的准确程度，属于效标效度。", "D": "正确，同时效度是将测试结果与同一时间取得的效标结果进行比较，属于效标效度。", "E": "错误，分半效度通常称为分半信度，是内部一致性信度的一种检验方法，不属于效度。"}}, {"id": "15-8", "type": "single", "stem": "招聘时表现好的人在实际工作中却表现一般，这表明该公司甄选测试的（ ）比较低。", "options": {"A": "构想效度", "B": "分半信度", "C": "重测信度", "D": "预测效度"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，题干强调测试结果无法预测未来工作表现，并非测试是否测量了某种理论构想。", "B": "错误，分半信度反映测试内部两部分题目结果的一致性，与未来绩效预测无关。", "C": "错误，重测信度反映不同时间重复测试所得结果的稳定性。", "D": "正确，预测效度反映甄选测试对求职者未来工作绩效的预测能力。招聘测试表现好但实际绩效一般，说明测试的预测效度较低。"}}, {"id": "15-9", "type": "single", "stem": "预测出求职者在未来的工作中取得成功或招致失败的程度的是（ ）。", "options": {"A": "复本信度", "B": "重测信度", "C": "效标效度", "D": "构想效度"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，复本信度反映两个等值版本测试结果的一致程度。", "B": "错误，重测信度反映同一测试在不同时间测量结果的稳定程度。", "C": "正确，效标效度反映测试结果与工作绩效等外部效标之间的关系，其中预测效度能够评价测试对求职者未来工作成功或失败的预测程度。", "D": "错误，构想效度反映测试能否准确测量某种理论构想。"}}, {"id": "15-10", "type": "single", "stem": "首先提供一组描述人的个性或特质的词或句子，然后让其他人通过对被测试者的观察，对被测试者的人格或特质做出评价，这种方法叫作（ ）。", "options": {"A": "自陈量表法", "B": "评价量表法", "C": "投射法", "D": "“大五”人格测试法"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，自陈量表法由被测试者本人根据题目对自己的行为、态度或人格特质作出回答。", "B": "正确，评价量表法由熟悉被测试者或能够观察其行为的人，根据描述人格或特质的词句对被测试者作出评价。", "C": "错误，投射法是向被测试者提供意义模糊的刺激情境，让其自由解释或反应，据此分析人格特征。", "D": "错误，“大五”人格理论是人格特质分类框架，不是题干所描述的具体测量方法。"}}, {"id": "15-11", "type": "single", "stem": "某公司招聘新员工时采用了人格测试，具体方式是向求职者提供一些刺激情境，然后让求职者自由地表达对刺激情境的认识和理解，这种方法称为（ ）。", "options": {"A": "标杆法", "B": "投射法", "C": "评价量表法", "D": "自陈量表法"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，标杆法不是题干所描述的人格测试方法。", "B": "正确，投射法通过向被测试者呈现模糊、开放的刺激情境，让其自由表达认识、想象或感受，并根据其反应推断人格特征。", "C": "错误，评价量表法通常由他人通过观察对被测试者的人格或行为进行评价。", "D": "错误，自陈量表法要求被测试者直接报告自己的态度、行为或人格特征，不依赖模糊刺激情境。"}}, {"id": "15-12", "type": "single", "stem": "MBTI人格测试中，“判断—感知”维度反映的是人的行为风格中的（ ）。", "options": {"A": "注意力集中的方向", "B": "对待外界的方式", "C": "处理信息和决策的方式", "D": "获取信息的方式"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，注意力和心理能量集中的方向由“外倾—内倾”维度反映。", "B": "正确，“判断—感知”维度反映个体对待外部世界的方式。判断型偏好计划、秩序和确定性，感知型偏好灵活、开放和适应变化。", "C": "错误，处理信息并作出决策的偏好主要由“思考—情感”维度反映。", "D": "错误，获取信息的方式主要由“感觉—直觉”维度反映。"}}, {"id": "15-13", "type": "single", "stem": "MBTI人格类型测试在对人格类型进行划分时，依托的主要维度是（ ）。", "options": {"A": "外倾—内倾、感觉—直觉、思考—情感、判断—知觉", "B": "外向性、愉悦性、尽责性、神经质、开放性", "C": "环境—任务—行为—结果", "D": "语言能力、数学能力、推理能力、记忆能力"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，MBTI以外倾—内倾、感觉—直觉、思考—情感、判断—知觉四个维度划分人格类型，每个维度包含两种相对偏好。", "B": "错误，这五个维度属于“大五”人格模型。", "C": "错误，这不是MBTI的人格分类维度。", "D": "错误，这些属于认知能力或智力测试可能涉及的能力，不属于MBTI人格维度。"}}, {"id": "15-14", "type": "multi", "stem": "根据“大五”人格理论，人格特质的基本维度包括（ ）。", "options": {"A": "愉悦性", "B": "神经质", "C": "判断性", "D": "开放性", "E": "外向性"}, "answer": "ABDE", "analysis": "", "optionAnalysis": {"A": "正确，愉悦性反映个体是否友善、合作、信任他人以及富有同情心。", "B": "正确，神经质反映个体情绪稳定程度及产生焦虑、紧张等消极情绪的倾向。", "C": "错误，判断性是MBTI“判断—知觉”维度中的一种偏好，不是“大五”人格的基本维度。", "D": "正确，开放性反映个体对新经验、新思想和多样性持开放态度的程度。", "E": "正确，外向性反映个体活跃、合群、善于交往和寻求刺激的程度。“大五”人格的另外一个基本维度是尽责性。"}}, {"id": "15-15", "type": "single", "stem": "根据霍兰德的职业兴趣测试理论，喜欢与人争辩、说服别人接受自己观点的职业兴趣类型是（ ）。", "options": {"A": "社会型", "B": "常规型", "C": "企业型", "D": "艺术型"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，社会型偏好帮助、教导、咨询和服务他人，强调合作和人际支持。", "B": "错误，常规型偏好有秩序、规则明确的数据处理和行政事务工作。", "C": "正确，企业型偏好通过影响、说服和领导他人实现组织、政治或经济目标，通常具有冒险、支配和进取倾向。", "D": "错误，艺术型偏好创造性表达和非结构化活动，重视想象力与个性。"}}, {"id": "15-16", "type": "single", "stem": "有些人喜欢与具体物体（如工具、机械、电子设备等）打交道，偏好有规则的具体劳动，不喜欢与人打交道，根据霍兰德职业兴趣理论，这种人的职业兴趣类型是（ ）。", "options": {"A": "企业型", "B": "现实型", "C": "艺术型", "D": "社会型"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，企业型偏好领导、影响和说服他人的活动。", "B": "正确，现实型偏好与工具、机械、设备、材料等具体事物打交道，喜欢明确、有规则的操作性工作，通常不偏好高度人际互动的职业活动。", "C": "错误，艺术型偏好创造、想象以及较少规则约束的活动。", "D": "错误，社会型偏好通过沟通、教导和帮助等方式与人交往。"}}, {"id": "15-17", "type": "single", "stem": "根据霍兰德的职业兴趣理论，有一种职业兴趣的主要表现是偏好与他人合作、善于社交，喜欢教导和帮助他人，但不喜欢与工具、机械等实物打交道。这种职业兴趣类型称为（ ）。", "options": {"A": "社会型", "B": "常规型", "C": "现实型", "D": "企业型"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，社会型偏好与人合作，善于沟通，喜欢教导、帮助、训练和服务他人，通常不喜欢以工具和机械为主要对象的工作。", "B": "错误，常规型偏好规则明确、秩序性强的文书、数据和行政工作。", "C": "错误，现实型恰恰偏好与工具、机械和具体物体打交道。", "D": "错误，企业型虽然也经常与人交往，但核心特征是影响、领导和说服他人，以获得组织、政治或经济方面的成就。"}}, {"id": "15-18", "type": "multi", "stem": "根据霍兰德职业兴趣理论，关于各种职业兴趣类型的核心特征的说法，正确的有（ ）。", "options": {"A": "研究型注重抽象分析，但缺乏组织和领导才能", "B": "常规型偏好灵活处理问题，不喜欢明确的常规性管理工作", "C": "社会型偏好合作、善于言谈，喜欢教导和培训别人", "D": "企业型追求政治经济成就，擅长说服他人接受观点", "E": "艺术型重视秩序和系统性，厌恶模糊和非结构化活动"}, "answer": "ACD", "analysis": "", "optionAnalysis": {"A": "正确，研究型偏好观察、分析、推理和解决抽象问题，通常不以组织、领导和说服他人为优势。", "B": "错误，常规型偏好结构清晰、程序明确、秩序性强的工作，通常喜欢按照既定规则处理数据和行政事务，并非排斥常规性管理工作。", "C": "正确，社会型偏好与他人合作和交往，善于沟通，喜欢教导、培训、咨询和帮助他人。", "D": "正确，企业型重视权力、地位及政治经济成就，擅长领导、影响和说服他人。", "E": "错误，艺术型偏好自由、创造性和非结构化活动，通常能够容忍模糊性；重视秩序、系统性并排斥非结构化活动更符合常规型特征。"}}, {"id": "15-19", "type": "multi", "stem": "霍兰德职业兴趣六边型人格中，与企业型相邻的是（ ）。", "options": {"A": "常规型", "B": "社会型", "C": "研究型", "D": "艺术型", "E": "现实型"}, "answer": "AB", "analysis": "霍兰德职业兴趣六边形通常按照现实型、研究型、艺术型、社会型、企业型、常规型的顺序排列。相邻类型在兴趣和行为特征上相似程度较高。", "optionAnalysis": {"A": "正确，常规型与企业型相邻。", "B": "正确，社会型与企业型相邻。", "C": "错误，研究型与企业型并不相邻，二者特征差异较大。", "D": "错误，艺术型与企业型不直接相邻。", "E": "错误，现实型与企业型不直接相邻。"}}, {"id": "15-20", "type": "single", "stem": "根据甄选测试的分类，初级经济师的考试属于（ ）。", "options": {"A": "认知能力测试", "B": "评价中心技术", "C": "心理测试", "D": "知识测试"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，认知能力测试主要考察语言、数学、推理、记忆等一般认知能力。", "B": "错误，评价中心技术通常综合运用公文筐测试、无领导小组讨论、角色扮演等方法评价管理能力。", "C": "错误，心理测试主要用于测量人格、能力、兴趣等心理特征。", "D": "正确，初级经济师考试主要考察应试者对经济专业知识及相关实务知识的掌握程度，属于知识测试。"}}, {"id": "15-21", "type": "single", "stem": "对计算机编程人员实施的编程测试属于（ ）。", "options": {"A": "工作样本测试", "B": "评价中心技术", "C": "知识测试", "D": "外语测试"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，让求职者完成实际编程任务，直接观察其能否完成目标岗位的代表性工作活动，属于工作样本测试。", "B": "错误，评价中心技术是多种情境模拟测评方法的综合应用，常用于管理人员甄选。", "C": "错误，如果仅以笔试形式考察编程知识，可以属于知识测试；题干强调实施编程测试，更侧重实际操作和工作行为样本。", "D": "错误，该测试与外语能力无关。"}}, {"id": "15-22", "type": "multi", "stem": "关于工作样本测试的说法，正确的有（ ）。", "options": {"A": "工作样本测试具有通用性，不需针对不同职位专门开发", "B": "工作样本测试的开发成本相对较高", "C": "工作样本测试是在模拟实际的工作环境中进行的", "D": "工作样本测试是一种成就测试", "E": "工作样本测试的效标效度和内容效度通常较高"}, "answer": "BCDE", "analysis": "", "optionAnalysis": {"A": "错误，工作样本测试必须根据目标职位的实际工作内容和关键任务进行专门设计，职位针对性较强，通用性较低。", "B": "正确，工作样本测试需要分析岗位、设计代表性任务并准备相应设备和场景，开发成本通常较高。", "C": "正确，工作样本测试一般要求被测试者在真实或高度模拟的工作环境中完成实际任务。", "D": "正确，工作样本测试测量被测试者已经掌握的工作技能和完成任务的水平，属于成就测试。", "E": "正确，由于测试内容直接来源于工作任务，工作样本测试通常具有较高内容效度，并且对实际工作绩效具有较好的预测作用，效标效度通常也较高。"}}, {"id": "15-23", "type": "single", "stem": "关于公文筐测试，说法正确的是（ ）。", "options": {"A": "适合于对管理人员进行测试", "B": "开发成本低", "C": "评分简单", "D": "能体现测试人员的团队合作能力"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，公文筐测试模拟管理人员处理文件、信息和突发事项的工作情境，适合评价管理人员的计划、决策、授权和问题解决等能力。", "B": "错误，公文筐测试需要针对职位开发大量情境材料，开发成本较高。", "C": "错误，被测试者可能采用不同处理思路，评分标准的设计和评分过程较为复杂，对评价者要求较高。", "D": "错误，传统公文筐测试通常由被测试者独立完成，主要考察个人的行政管理、决策和问题解决能力，难以直接体现团队合作能力。"}}, {"id": "15-24", "type": "multi", "stem": "评价中心中的公文筐测试法，可以测试出的能力包括（ ）。", "options": {"A": "领导能力", "B": "问题解决能力", "C": "人际交往能力", "D": "行政管理能力", "E": "压力承受能力"}, "answer": "ABD", "analysis": "", "optionAnalysis": {"A": "正确，通过任务排序、授权、资源配置和决策等行为，可以评价被测试者的领导与管理能力。", "B": "正确，被测试者需要识别公文中的问题、分析信息并提出处理方案，因此能够测试问题解决能力。", "C": "错误，公文筐测试以个人书面处理公文为主，缺少真实的双向人际互动，不能充分直接考察人际交往能力。", "D": "正确，公文筐测试能够评价计划安排、文件处理、信息利用、决策和授权等行政管理能力。", "E": "错误，测试可能具有时间压力，但其核心测评维度通常不包括压力承受能力；压力承受能力更适合通过压力面试等方法进行专门评价。"}}, {"id": "15-25", "type": "multi", "stem": "关于无领导小组讨论的说法，正确的有（ ）。", "options": {"A": "它不适合应届大学毕业生", "B": "它可以考察被测试者的领导能力和人际交往能力", "C": "它对测试题目的要求比较高", "D": "它对评价者的评分技术要求比较高", "E": "它可以彻底避免被测试者掩饰自己的行为"}, "answer": "BCD", "analysis": "", "optionAnalysis": {"A": "错误，无领导小组讨论可以用于应届大学毕业生的甄选，尤其适合在缺少长期工作经历材料时观察候选人的现场行为表现。", "B": "正确，讨论过程中能够观察候选人提出观点、影响他人、组织协调、倾听和处理冲突等行为，从而评价领导能力和人际交往能力。", "C": "正确，题目需要具有适当难度、开放性和争议性，并能够引发充分讨论，因此对测试题目设计要求较高。", "D": "正确，评价者需要在多人互动中同步观察、记录并区分不同维度的行为表现，对评分技术要求较高。", "E": "错误，无领导小组讨论能增加行为观察机会，但不能彻底消除伪装、表演或印象管理行为。"}}, {"id": "15-26", "type": "single", "stem": "下列测试类型中，能够考查求职者人际交往能力的是（ ）。", "options": {"A": "知识测试", "B": "角色扮演", "C": "公文筐测试", "D": "人格测试"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，知识测试主要考察专业知识或一般知识的掌握程度，不能直接观察人际互动行为。", "B": "正确，角色扮演要求被测试者在模拟情境中与他人进行沟通、协调、说服或处理冲突，能够直接考查人际交往能力。", "C": "错误，公文筐测试通常由个人独立处理书面材料，主要评价行政管理、计划和问题解决能力。", "D": "错误，人格测试可以间接了解与社交有关的人格倾向，但不能像角色扮演一样直接考查实际人际交往行为。"}}, {"id": "15-27", "type": "single", "stem": "某企业求职人员大多，一个人一个人面试的组织效率太低，影响面试效果。如果想同时对多位候选人进行面试，该公司应当采取的面试组织形式为（ ）。", "options": {"A": "系列面试", "B": "单独面试", "C": "个体面试", "D": "集体面试"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，系列面试是同一候选人依次接受多位面试考官或多个环节的面试，重点不是同时面试多位候选人。", "B": "错误，单独面试通常是一名面试考官与一名候选人进行面谈。", "C": "错误，个体面试的对象是单个候选人，不能解决同时面试多位候选人的需求。", "D": "正确，集体面试是由面试考官同时对多位候选人进行面试，能够提高组织效率，并便于观察候选人的语言表达和人际互动表现。"}}, {"id": "15-28", "type": "single", "stem": "关于按组织形式划分的面试类型的优缺点，表述错误的是（ ）。", "options": {"A": "单独面试双方对话不顺利时，容易出现比较尴尬的场面", "B": "系列面试能够比较快速、准确的做出评价", "C": "小组面试可以使各面试考官在提问题的时候注意互相补充", "D": "集体面试能够考查候选人的人际关系能力和语言表达能力"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，单独面试仅有一名考官和一名候选人，双方如果缺少互动或对话不顺畅，较容易出现尴尬场面。", "B": "错误，系列面试由候选人依次接受多位面试考官的面试，能够从多个角度获得评价，但耗时较长，不能体现“比较快速”的优势。", "C": "正确，小组面试由多名考官同时面试一名候选人，各考官可以围绕不同方面提问并相互补充。", "D": "正确，集体面试同时安排多位候选人参与，能够观察候选人的表达、倾听和人际互动等能力。"}}, {"id": "15-29", "type": "single", "stem": "关于传记资料分析技术说法错误的是（ ）。", "options": {"A": "传记资料信息真实", "B": "信息与工作有关", "C": "传记资料信息必须全面", "D": "基本假设是人的行为具有可变化性"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，传记资料分析所使用的信息应当是真实、可核实的历史资料，否则难以形成有效预测。", "B": "正确，纳入分析的传记资料应与目标职位及工作绩效相关，避免使用与工作无关的信息。", "C": "正确，传记资料应尽可能全面地反映与工作有关的重要经历，避免因信息缺失而影响判断。这里的“全面”应理解为与工作相关的重要信息覆盖充分，而不是无限收集个人信息。", "D": "错误，传记资料分析的核心假设是人的行为具有一致性，即过去的行为和经历能够在一定程度上预测未来行为，而不是强调人的行为具有可变化性。"}}, {"id": "15-30", "type": "multi", "stem": "关于甄选中的传记资料分析技术的说法，正确的有（ ）。", "options": {"A": "传记资料分析主要适用于企业，不适用于政府", "B": "传记资料分析技术的最新发展是目标履历分析法", "C": "传记资料分析通过分析求职者的历史工作经历预测其未来工作表现", "D": "传记资料分析的核心假设是“人的行为具有一致性”", "E": "为提高传记资料分析效率，可忽略那些看上去不重要的履历细节"}, "answer": "BCD", "analysis": "", "optionAnalysis": {"A": "错误，传记资料分析既可以用于企业人员甄选，也可以用于政府及其他组织的人员选拔，并非只适用于企业。", "B": "正确，目标履历分析法是传记资料分析技术的发展形式，它根据目标职位和绩效要求有针对性地分析履历信息。", "C": "正确，传记资料分析通过考察求职者过去的教育、工作和行为经历，预测其未来工作表现。", "D": "正确，该方法的核心假设是人的行为具有一定一致性，过去的行为模式能够为预测未来行为提供依据。", "E": "错误，看似不重要的履历细节也可能包含与未来绩效有关的信息，不能仅凭主观印象随意忽略，应按照统一且与工作相关的标准分析。"}}, {"id": "15-31", "type": "single", "stem": "某公司进行招聘时，面试官使用一份标准化问题清单，对所有求职者提问相同的问题，并统一评分标准打分这种面试类型是（ ）。", "options": {"A": "非结构化面试", "B": "半结构化面试", "C": "结构化面试", "D": "压力面试"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，非结构化面试没有统一的问题清单和严格固定的评分标准，面试灵活性较大。", "B": "错误，半结构化面试通常既有预先设计的问题，又允许面试官根据现场情况追问，标准化程度低于结构化面试。", "C": "正确，结构化面试要求使用标准化问题，对不同候选人按照相同程序提问，并依据统一评分标准作出评价。", "D": "错误，压力面试通过制造紧张或具有挑战性的情境观察候选人的情绪和应对方式，题干未体现这一特征。"}}, {"id": "15-32", "type": "single", "stem": "下列面试问题中，属于“过去导向型”的情境化结构面试问题的有（ ）。", "options": {"A": "“你具备哪些优势能满足本岗位的需要”", "B": "“你是否曾经带领团队完成一个有挑战性的目标，是如何做的”", "C": "“你有哪些兴趣爱好”", "D": "“假设你有一个想法，但是其他同事有所犹豫，你将如何推动大家按你的想法行动”"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，该问题要求候选人概括自身优势，未要求描述过去发生的具体行为情境。", "B": "正确，该问题要求候选人回顾曾经发生的团队领导经历，并说明具体做法，属于以过去实际行为为依据的过去导向型问题。", "C": "错误，该问题询问一般个人兴趣，不属于情境化问题，也不直接考察过去工作行为。", "D": "错误，该问题设置假设情境，要求候选人说明未来可能采取的行动，属于未来导向型情境问题。"}}, {"id": "15-33", "type": "multi", "stem": "下列属于情境化面试的是（ ）。", "options": {"A": "你最大的优点是？", "B": "请回顾下你过去的工作成绩", "C": "交给你这个项目，你采用怎样的方法和手段去实施？", "D": "在某项工作中，你遇到困难，应该怎样去做？", "E": "如果客户投诉你的某位下属存在工作态度问题，你会怎么做？"}, "answer": "CDE", "analysis": "", "optionAnalysis": {"A": "错误，该问题是一般性的自我评价问题，没有设置具体工作情境。", "B": "错误，该问题虽然指向过去，但表述较为宽泛，没有呈现具体情境或要求围绕特定行为作答。", "C": "正确，该问题设置了承接项目的工作情境，要求候选人说明将采用的方法和实施步骤，属于情境化面试问题。", "D": "正确，该问题围绕工作中遇到困难的具体情境，考察候选人的应对思路和解决问题方式。", "E": "正确，该问题设置客户投诉下属的管理情境，能够考察候选人的沟通、管理和问题解决能力。"}}, {"id": "15-34", "type": "single", "stem": "情境化结构面试通常遵循“STAR”原则，其中字母“T”代表的含义是（ ）。", "options": {"A": "任务（Task）", "B": "技术（Technology）", "C": "时间（Time）", "D": "团队（Team）第十六章绩效管理"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，STAR原则中的T代表任务（Task），即候选人在特定情境中承担的职责、目标或需要完成的任务。", "B": "错误，Technology不是STAR原则中的构成要素。", "C": "错误，Time不是STAR原则中的构成要素。", "D": "错误，Team不是STAR原则中的构成要素。STAR分别代表情境（Situation）、任务（Task）、行动（Action）和结果（Result），用于引导候选人完整描述过去的行为经历。"}}]}, {"id": 16, "title": "绩效管理", "questions": [{"id": "16-1", "type": "single", "stem": "关于绩效管理与绩效考核关系的说法，正确的是（ ）。", "options": {"A": "绩效管理重点关注绩效提高，绩效考核重点关注绩效衡量", "B": "绩效管理是绩效考核的前提", "C": "绩效管理是绩效考核的一个重要环节", "D": "绩效管理与绩效考核是等价的"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，绩效管理是一个持续改进员工和组织绩效的完整管理过程，重点在于绩效的提升；绩效考核主要对一定时期内的工作绩效进行识别、衡量和评价。", "B": "错误，绩效考核是绩效管理的重要组成部分，不能笼统地说绩效管理只是绩效考核的前提。", "C": "错误，关系表述颠倒，应当是绩效考核属于绩效管理的重要环节。", "D": "错误，二者在范围、目的和实施过程等方面均不相同，不能等同。"}}, {"id": "16-2", "type": "single", "stem": "关于绩效考核与绩效管理的说法，错误的是（ ）。", "options": {"A": "绩效管理有助于企业战略目标的实现", "B": "绩效管理的有效性在一定程度上取决于绩效考核的科学性", "C": "绩效考核侧重绩效的识别", "D": "绩效管理侧重绩效的判断"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，绩效管理通过目标分解、过程监控、绩效评价和反馈改进，推动组织战略目标落地。", "B": "正确，科学的绩效考核能够提供可靠的绩效信息，是提高绩效管理有效性的重要基础。", "C": "正确，绩效考核侧重对员工绩效进行识别、衡量和判断。", "D": "错误，侧重绩效判断的是绩效考核；绩效管理更加关注持续沟通、绩效改进以及员工和组织绩效的提升。"}}, {"id": "16-3", "type": "single", "stem": "建立和维护绩效管理体系的成本应小于该体系带来的收益，这体现出绩效管理的特征是（ ）。", "options": {"A": "敏感性", "B": "可靠性", "C": "实用性", "D": "可接受性"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，敏感性是指绩效管理体系能够有效区分高绩效员工和低绩效员工。", "B": "错误，可靠性是指不同评价者、不同时间或不同评价方式所得结果具有较高的一致性。", "C": "正确，实用性强调绩效管理体系的收益应当大于其建立、运行和维护成本，且体系能够实际应用。", "D": "错误，可接受性强调绩效管理体系能够获得管理者和员工等相关主体的理解、支持与认可。"}}, {"id": "16-4", "type": "single", "stem": "“不同评价者对同一员工的评价基本相同”体现的有效绩效管理的特征是（ ）。", "options": {"A": "敏感性", "B": "可靠性", "C": "实用性", "D": "可接受性"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，敏感性体现为体系能够区分不同绩效水平的员工。", "B": "正确，不同评价者对同一员工得出基本相同的评价结果，说明评价结果具有较高的一致性和稳定性，体现了可靠性。", "C": "错误，实用性关注体系带来的收益、成本及实际操作价值。", "D": "错误，可接受性关注评价体系是否能够得到相关人员认可。"}}, {"id": "16-5", "type": "single", "stem": "绩效管理系统关键影响因素不包含（ ）。", "options": {"A": "绩效考核系统对其他企业的适用程度", "B": "人力资源管理部门的尽责程度", "C": "绩效指标和目标制定的合理性", "D": "管理层对其支持程度"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "不属于关键影响因素，企业应根据自身战略、组织结构和岗位特点设计绩效管理系统，其他企业是否适用不能直接决定本企业绩效管理的效果。", "B": "属于影响因素，人力资源管理部门需要承担制度设计、培训、协调和监督等职责。", "C": "属于影响因素，指标和目标是否合理会直接影响考核的有效性。", "D": "属于影响因素，管理层的重视和支持是绩效管理制度有效实施的重要保障。"}}, {"id": "16-6", "type": "multi", "stem": "影响绩效管理效果的主要因素有（ ）。", "options": {"A": "员工的年龄结构", "B": "管理者对绩效管理的认知程度", "C": "人力资源管理部门的尽责程度", "D": "企业的办公环境", "E": "员工对绩效管理的态度"}, "answer": "BCE", "analysis": "", "optionAnalysis": {"A": "错误，员工年龄结构通常不是教材所列的绩效管理效果关键影响因素。", "B": "正确，管理者对绩效管理的理解程度会影响目标制定、沟通辅导和评价反馈的质量。", "C": "正确，人力资源管理部门是否尽责会影响制度设计、实施培训、过程监督和结果运用。", "D": "错误，一般办公环境并非影响绩效管理效果的主要制度性因素。", "E": "正确，员工是否认同并积极参与绩效管理，会直接影响绩效计划执行、沟通反馈及改进行动。"}}, {"id": "16-7", "type": "multi", "stem": "适用于不同竞争态势战略的绩效管理的说法，正确的有（ ）。", "options": {"A": "分析者战略可以采用标杆超越法", "B": "分析者战略应尽量采用平衡计分卡法作为绩效管理工具", "C": "防御者战略可以将考核周期与奖金发放周期保持一致", "D": "探索者战略组织采用行为导向的评价方法", "E": "防御者战略可以采用系统化的评价方法，多角度选择考核指标"}, "answer": "ACE", "analysis": "", "optionAnalysis": {"A": "正确，分析者战略兼顾维持现有市场和探索新市场，可以通过标杆超越吸收其他组织的优秀实践。", "B": "错误，分析者战略并非必须或应尽量采用平衡计分卡，绩效工具应结合组织实际选择。C项正确，防御者战略强调效率、稳定和成本控制，可以使考核周期与奖金发放周期保持一致，以强化绩效结果与报酬之间的联系。", "D": "错误，探索者战略强调创新和新市场开发，通常更适合采用结果导向而非强调标准化行为过程的评价方法。", "E": "正确，防御者战略需要保证组织内部运行稳定和高效，可以运用系统化评价方法并从多个角度选择考核指标。"}}, {"id": "16-8", "type": "single", "stem": "关于不同竞争战略下的绩效管理策略的说法，正确的是（ ）。", "options": {"A": "企业在采用探索者战略时，绩效考核应尽量采用以内部流程为导向的评价方法", "B": "企业在采用分析者战略时，绩效考核应尽量采用平衡计分卡法", "C": "企业在采用探索者战略时，绩效考核应尽量采用以行为导向的评价方法", "D": "企业在采用防御者战略时，绩效考核应尽量采用多角度地选择考核指标"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，探索者战略重视创新、市场机会和新产品开发，不宜主要采用以内部流程为导向的评价方法。", "B": "错误，分析者战略需要兼顾稳定业务和创新业务，但不能据此认定其应当尽量采用平衡计分卡。", "C": "错误，探索者战略更关注创新成果和市场结果，不宜过度采用行为导向评价。", "D": "正确，防御者战略强调现有领域内的稳定经营和效率提升，可以采取系统化评价，并从多角度选择考核指标。"}}, {"id": "16-9", "type": "single", "stem": "关于成本领先战略下绩效管理的说法，不正确的是（ ）。", "options": {"A": "仅选择直接上级作为评价主体", "B": "尽量选择以行为为导向的评价方法", "C": "多选择客观的财务指标引导员工的工作行为", "D": "应避免考核频次过高"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，成本领先战略强调管理效率和降低评价成本，可以主要选择直接上级作为评价主体。", "B": "错误，该战略更加重视成本、效率和结果，通常应选择结果导向的评价方法，而不是尽量采用行为导向评价。", "C": "正确，客观财务指标有利于引导员工控制成本并提高效率。", "D": "正确，过高的考核频次会增加管理成本，与成本领先战略的要求不符。"}}, {"id": "16-10", "type": "single", "stem": "与差异化战略相适应的绩效管理特点是（ ）。", "options": {"A": "注重对员工创新能力的评估", "B": "对所有岗位上的员工都实施量化考核", "C": "关注企业的短期财务指标", "D": "相对于结果评价，更加注重工作过程的考核"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，差异化战略依靠创新、质量、品牌或服务形成竞争优势，因此需要重视员工创新能力和创新成果。", "B": "错误，不同岗位的工作性质不同，不能不加区分地全部实施量化考核。", "C": "错误，差异化战略通常需要关注创新和长期竞争优势，不能只关注短期财务指标。", "D": "错误，差异化战略强调创新结果和市场效果，并非普遍表现为更加重视过程而轻视结果。"}}, {"id": "16-11", "type": "multi", "stem": "关于根据成本领先战略确定绩效管理策略的说法，正确的有（ ）。", "options": {"A": "仅选择直接上级作为评价主体即可", "B": "可以选择标杆超越法改进绩效", "C": "可以多选择一些主观性指标进行评价", "D": "应尽量选择行为导向的评价方法", "E": "应避免考核频次过高"}, "answer": "ABE", "analysis": "", "optionAnalysis": {"A": "正确，主要由直接上级评价可以减少评价主体数量，降低绩效管理成本。", "B": "正确，企业可以通过标杆超越寻找成本控制和效率提升方面的最佳实践。", "C": "错误，成本领先战略更适合采用成本、产量和效率等客观指标，不宜大量采用主观性指标。", "D": "错误，该战略通常更重视能够反映成本与效率的结果导向评价。", "E": "正确，考核频次过高会增加制度运行成本，因此应合理控制考核频次。"}}, {"id": "16-12", "type": "single", "stem": "关于绩效计划说法错误的是（ ）。", "options": {"A": "制定自上而下过程", "B": "是绩效管理过程的起点", "C": "是将组织绩效目标分解为个人绩效目标的过程", "D": "绩效计划的发展目标描述了员工为达到目标而改进的能力"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，绩效目标通常依据组织战略逐级分解，具有自上而下的特点，同时实际制定中也需要管理者与员工沟通参与。", "B": "正确，绩效计划确定考核周期内的目标、标准和行动安排，是绩效管理的起点。", "C": "正确，绩效计划承担将组织目标分解到部门和个人的作用。", "D": "错误，发展目标侧重员工在知识、技能和能力等方面需要达到的改进或发展要求，不能简单表述为“为达到目标而改进的能力”。"}}, {"id": "16-13", "type": "multi", "stem": "绩效计划的制定原则有（ ）。", "options": {"A": "敏感性原则", "B": "可测量性原则", "C": "经济性原则", "D": "系统化原则", "E": "全员参与原则"}, "answer": "BDE", "analysis": "", "optionAnalysis": {"A": "错误，敏感性属于评价有效性相关特征，不属于绩效计划制定的主要原则。", "B": "正确，绩效目标和标准应当尽可能明确、具体并可衡量。", "C": "错误，经济性不是教材所列绩效计划制定的主要原则。", "D": "正确，绩效计划应与组织战略、部门职责和个人岗位目标形成系统联系。", "E": "正确，绩效计划需要管理者和员工共同参与，以提高目标认同度和执行意愿。"}}, {"id": "16-14", "type": "single", "stem": "关于绩效监控与绩效辅导的说法，正确的是（ ）。", "options": {"A": "绩效辅导是管理者为掌握下属的工作绩效情况进行的一系列活动", "B": "绩效辅导是绩效监控的基础", "C": "绩效监控是在已经掌握下属工作绩效前提下，为提高绩效水平进行的一系列活动", "D": "绩效辅导贯穿于绩效实施的整个过程"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，该表述属于绩效监控，绩效辅导是在掌握绩效情况后帮助员工解决问题、改进绩效的活动。", "B": "错误，管理者通常先通过绩效监控掌握绩效情况，再开展有针对性的绩效辅导，因此绩效监控是绩效辅导的重要基础。", "C": "错误，该表述属于绩效辅导，而不是绩效监控。", "D": "正确，绩效辅导不是期末一次性活动，而应贯穿绩效实施全过程。"}}, {"id": "16-15", "type": "multi", "stem": "典型的绩效辅导活动内容包括（ ）。", "options": {"A": "寻找改进绩效的方法", "B": "探讨绩效的现状", "C": "设定绩效指标", "D": "调整绩效计划", "E": "制定绩效计划"}, "answer": "AB", "analysis": "", "optionAnalysis": {"A": "正确，绩效辅导需要针对绩效差距共同寻找可操作的改进方法。", "B": "正确，管理者与员工应首先讨论当前绩效状况、存在的问题及其原因。", "C": "错误，设定绩效指标主要属于绩效计划阶段。D项错误，必要时可以根据客观变化调整绩效计划，但其不是典型绩效辅导活动的核心内容。", "E": "错误，制定绩效计划发生在绩效周期开始阶段，不属于实施过程中的典型辅导活动。"}}, {"id": "16-16", "type": "single", "stem": "在绩效辅导时，首先要做的是（ ）。", "options": {"A": "调整计划", "B": "寻找改进方法", "C": "收集资料", "D": "制定计划"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，在没有掌握实际绩效信息和问题原因之前，不能直接调整计划。", "B": "错误，寻找改进方法需要以充分了解绩效现状为基础。", "C": "正确，绩效辅导首先要收集员工实际工作表现、目标完成情况和相关环境因素等资料，以形成客观判断。", "D": "错误，绩效计划一般在绩效周期开始时制定，不是绩效辅导的首要步骤。"}}, {"id": "16-17", "type": "multi", "stem": "下列关于绩效评价技术的说法，正确的有（ ）。", "options": {"A": "行为锚定法具有较低的信度", "B": "行为锚定法的开发成本较低", "C": "图尺度评价法无法为员工改进工作提供具体指导", "D": "图尺度评价法往往只有模糊的绩效标准", "E": "行为观察量表法的内部一致性较好"}, "answer": "CDE", "analysis": "", "optionAnalysis": {"A": "错误，行为锚定法通过典型行为描述明确不同绩效等级，计量较为准确，评价结果通常具有较高信度。", "B": "错误，行为锚定法需要收集关键事件、提炼行为并确定等级锚点，开发过程复杂且成本较高。", "C": "正确，图尺度评价法通常只给出一般性维度和等级，难以向员工提供具体的行为改进指导。", "D": "正确，图尺度评价法的评价尺度和绩效标准可能较为笼统、模糊。", "E": "正确，行为观察量表围绕具体行为及其出现频率进行评价，通常具有较好的内部一致性。"}}, {"id": "16-18", "type": "multi", "stem": "属于量表法的是（ ）。", "options": {"A": "行为锚定法", "B": "行为观察量表法", "C": "图尺度法", "D": "关键事件法", "E": "描述法"}, "answer": "ABC", "analysis": "", "optionAnalysis": {"A": "正确，行为锚定法利用描述性关键行为作为不同绩效等级的锚点，属于量表法。", "B": "正确，行为观察量表法按照某些行为出现的频率或程度进行量表评价。", "C": "正确，图尺度法通过预先确定的评价维度和等级尺度进行评分，是典型量表法。", "D": "错误，关键事件法主要记录员工特别有效或无效的关键行为，不属于量表法。", "E": "错误，描述法以文字描述员工绩效为主，不属于量表法。"}}, {"id": "16-19", "type": "single", "stem": "下列绩效评价技术中，不属于比较法的是（ ）。", "options": {"A": "配对比较法", "B": "排序法", "C": "强制分布法", "D": "不良事故评价法"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "属于比较法，通过员工之间的两两比较确定相对绩效。", "B": "属于比较法，通过比较员工整体绩效进行排序。", "C": "属于比较法，按照预先规定的比例将员工分配到不同绩效等级。", "D": "不属于比较法，它主要依据员工发生的不良事故及其影响进行评价，没有将员工绩效进行相互比较。"}}, {"id": "16-20", "type": "multi", "stem": "关于绩效评价技术的说法，正确的是（ ）。", "options": {"A": "行为观察量表法开发成本较低，且应用者较为普遍", "B": "行为锚定法的计量方法更为准确，评估结果具有较高的信度", "C": "配对比较法在人数较少的情况下，能快速比较出员工的绩效水平", "D": "强制分布法可有效避免考核结果的趋中趋势", "E": "关键事件法可以高效地衡量员工的绩效水平，降低绩效评估成本"}, "answer": "BCD", "analysis": "", "optionAnalysis": {"A": "错误，行为观察量表需要识别关键行为并设计频率尺度，开发成本通常较高，应用范围也会受到限制。", "B": "正确，行为锚定法使用具体行为作为评价尺度的锚点，标准较清晰，计量准确性和信度较高。", "C": "正确，员工人数较少时，配对比较的组合数量有限，可以较快确定员工相对绩效水平。D项正确，强制分布法要求按照一定比例划分绩效等级，能够减少所有人员集中在中间等级的趋中现象。", "E": "错误，关键事件法需要持续观察和记录关键行为，耗时较多，不能简单认为可以高效衡量绩效并降低成本。"}}, {"id": "16-21", "type": "single", "stem": "关于绩效评价技术的说法，正确的是（ ）。", "options": {"A": "根据某项评价标准，将每位员工逐一与其他员工比较选出优胜者，最后根据每位员工获胜的次数进行绩效排序，这种绩效评价方法是配对比较法", "B": "列出评估指标，要求评估者在观察的基础上将员工的工作行为与评价标准进行对照，以判断该行为出现的频率或完成程度，这种绩效评价方法是交替排序法", "C": "将每项工作的特定行为用一张等级表（从最积极的行为到最消极的行为）进行反映，评估者只需将员工的行为对号入座，这种绩效评价方法是行为观察量表法", "D": "采取“掐头去尾”和“逐级评价”的方法最终获得员工业绩排序，这种绩效评价方法是行为锚定法"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，配对比较法是按照评价标准将员工两两比较，根据每位员工获胜次数确定排序。B项错误，按照具体工作行为出现的频率或完成程度进行评价属于行为观察量表法，不是交替排序法。C项错误，将具体行为按照从积极到消极的等级作为量表锚点，属于行为锚定法。", "D": "错误，先选出最好者和最差者，再依次选出次优者和次差者的“掐头去尾”方法属于交替排序法，不是行为锚定法。"}}, {"id": "16-22", "type": "single", "stem": "对一个人进行评价时，因为某一特质强烈清晰的感知，而掩盖了其他的品质，这一误区是（ ）。", "options": {"A": "盲点效应", "B": "年资或职位倾向", "C": "刻板印象", "D": "晕轮效应"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，盲点效应是评价者难以发现与自己相似的缺点，或者因自身具有某种缺点而忽视被评价者的同类问题。", "B": "错误，年资或职位倾向是因员工年龄、资历或职位高低而影响绩效判断。", "C": "错误，刻板印象是根据员工所属群体的固定看法评价个人。", "D": "正确，晕轮效应是评价者因员工某一突出特征形成整体印象，从而掩盖或影响对其其他方面的评价。"}}, {"id": "16-23", "type": "single", "stem": "关于绩效评价误区的说法，正确的是（ ）。", "options": {"A": "上级根据过宽或过严的标准对员工进行绩效评价的误区，称为趋中效应", "B": "上级根据对员工的最初印象做出绩效评价的误区，称为晕轮效应", "C": "上级根据对员工的最终印象做出绩效评价的误区，称为近因效应", "D": "上级对员工的某种强烈而清晰的特质感知导致其忽略了员工在其他方面的表现，这种评价误区称为盲点效应"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，采用过宽或过严的评价标准分别属于过宽或过严倾向；趋中效应是评价结果过度集中于中间等级。", "B": "错误，根据最初印象进行评价属于首因效应，不是晕轮效应。", "C": "正确，评价者过分重视员工近期或最后阶段的表现，而忽略整个评价周期的表现，属于近因效应。", "D": "错误，该描述属于晕轮效应，不是盲点效应。"}}, {"id": "16-24", "type": "single", "stem": "关于目标管理法的说法，错误的是（ ）。", "options": {"A": "该方法过程中通常很少存在主观偏见", "B": "该方法可能增加企业管理成本", "C": "通过该方法设定的指标通常是可量化的客观标准", "D": "该方法倾向于聚焦长期目标"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，目标管理以事先协商确定的目标及其完成情况作为主要评价依据，能够减少主观偏见。", "B": "正确，目标制定、分解、沟通和检查需要投入较多时间和管理资源，可能增加管理成本。", "C": "正确，目标管理通常要求目标明确、具体并可衡量，因此多采用客观、可量化的标准。", "D": "错误，目标管理容易聚焦可测量的短期目标，并可能因此忽视组织的长期利益。"}}, {"id": "16-25", "type": "multi", "stem": "关于绩效管理工具中目标管理法的说法，正确的有（ ）。", "options": {"A": "它的假设之一是员工是不愿意工作的", "B": "它聚焦于短期目标", "C": "它较为公平", "D": "它适用于企业战略在一定时期内相对稳定的企业", "E": "它可能增加企业的管理成本"}, "answer": "BCDE", "analysis": "", "optionAnalysis": {"A": "错误，目标管理建立在员工愿意承担责任并通过参与目标制定提高积极性的假设基础上，并非假设员工天然不愿工作。", "B": "正确，目标管理容易把注意力集中在具体且可测量的短期目标上。C项正确，员工参与目标制定并按照事先确定的客观标准评价，通常具有较好的公平性。", "D": "正确，企业战略相对稳定时，目标能够逐级分解并保持一致，较适合采用目标管理法。", "E": "正确，反复协商、分解、跟踪和修订目标可能提高管理成本。"}}, {"id": "16-26", "type": "single", "stem": "关于关键绩效指标的说法，正确的是（ ）。", "options": {"A": "关键绩效指标是由主管人员决定的", "B": "关键绩效指标应该覆盖所有的业务流程活动", "C": "关键绩效指标应当是可量化的或可行为化的", "D": "关键绩效指标一旦确定，就不应随着企业的战略调整而变动"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，关键绩效指标应依据组织战略和关键成功因素，通过科学分析和上下沟通确定，不能仅由主管人员单方面决定。", "B": "错误，关键绩效指标突出“关键”，只需要反映对战略目标实现具有重要作用的环节，不应覆盖全部业务活动。", "C": "正确，指标应当能够量化；无法直接量化时，也应转化为可以观察和评价的行为标准。", "D": "错误，关键绩效指标必须与企业战略保持一致，战略调整后指标也应相应调整。"}}, {"id": "16-27", "type": "single", "stem": "关于绩效管理工具的说法，正确的是（ ）。", "options": {"A": "平衡计分卡法因实施成本较低而得到广泛应用", "B": "目标管理法通过持续沟通将企业目标逐层分解", "C": "标杆超越法通过分析个体的高绩效表现实现评价指标的量化", "D": "关键绩效指标法通过在企业内部制定质量管理体系提升企业绩效"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，平衡计分卡的设计和实施较为复杂，需要较高的管理基础和实施成本。", "B": "正确，目标管理法通过管理者和员工的持续沟通，将组织目标逐层分解为部门目标和个人目标。", "C": "错误，标杆超越法是通过寻找和比较最佳实践改进组织绩效；分析个体高绩效表现并提炼行为指标不是其基本含义。", "D": "错误，建立质量管理体系属于ISO质量管理等方法的内容，不是关键绩效指标法的主要机制。"}}, {"id": "16-28", "type": "multi", "stem": "关于绩效管理工具，正确的是（ ）。", "options": {"A": "关键绩效指标是反映团队绩效指标贡献的", "B": "标杆超越法通过分析个体的高绩效表现实现评价指标的量化", "C": "平衡计分卡适用组织战略稳定时期", "D": "平衡计分卡关注财务、客户、内部流程、学习与发展四个角度", "E": "目标管理法是客观可量化的指标"}, "answer": "DE", "analysis": "", "optionAnalysis": {"A": "错误，关键绩效指标是从组织战略和关键成功因素中提炼出的关键衡量指标，并非仅用于反映团队对绩效指标的贡献。", "B": "错误，标杆超越法通过寻找行业内外的最佳实践或最佳标准进行比较和改进，不是单纯分析个体高绩效表现。", "C": "错误，战略相对稳定更符合目标管理法实施条件；平衡计分卡的核心是将战略转化为多维度指标体系。", "D": "正确，平衡计分卡从财务、客户、内部流程、学习与发展四个角度衡量组织绩效。", "E": "正确，目标管理法通常采用事先协商确定的、明确且可量化的客观目标作为评价依据。"}}, {"id": "16-29", "type": "single", "stem": "关于绩效管理工具的说法，错误的是（ ）。", "options": {"A": "目标管理法在考核过程中存在大量的主观偏见", "B": "标杆超越法容易导致企业失去自身特色", "C": "目标管理法可能会牺牲企业的长远利益", "D": "标杆超越法中的标杆指的是最佳实践或最佳标准"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误，目标管理法主要按照事先确定的客观目标及其完成情况进行评价，通常能够减少而不是增加主观偏见。", "B": "正确，企业如果机械模仿标杆对象，可能忽视自身资源、文化和战略特点，进而失去自身特色。", "C": "正确，过度关注短期、可量化目标可能使企业忽视长期能力建设和长远利益。D项正确，标杆可以是行业内外值得学习的最佳实践、最佳标准或优秀流程。"}}, {"id": "16-30", "type": "single", "stem": "绩效反馈面谈的目的不包括（ ）。", "options": {"A": "弄清员工绩效不合格的原因", "B": "掌握下属的工作绩效情况", "C": "向员工传递组织远景目标", "D": "向员工反馈绩效考核结果"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "属于绩效反馈面谈目的，通过面谈可以分析绩效差距及不合格原因。", "B": "不属于绩效反馈面谈的主要目的，管理者应当在绩效监控和评价过程中掌握员工绩效，不能等到反馈面谈时才掌握。C项属于面谈目的，管理者可以借助反馈面谈帮助员工理解组织目标和未来方向。", "D": "属于面谈的直接目的，即向员工说明评价结果及其依据。"}}, {"id": "16-31", "type": "multi", "stem": "绩效面谈的目的包括（ ）。", "options": {"A": "向员工反馈绩效的结果", "B": "进行不良业绩的诊断", "C": "商讨下一年工作目标", "D": "与员工达成改善共识", "E": "提高员工的工资水平"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，绩效面谈需要向员工说明考核结果和评价依据。", "B": "正确，面谈应分析绩效差距及其形成原因，对不良业绩进行诊断。", "C": "正确，面谈可以在总结本周期绩效的基础上协商下一绩效周期的工作目标。", "D": "正确，管理者与员工应就绩效改进方向、措施和支持条件达成共识。", "E": "错误，工资调整可能参考绩效结果，但提高工资水平并不是绩效面谈本身的必然目的。"}}, {"id": "16-32", "type": "multi", "stem": "绩效改进方法包括（ ）。", "options": {"A": "六西格玛管理", "B": "ISO质量管理", "C": "卓越绩效管理", "D": "标杆超越法", "E": "关键绩效指标"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，六西格玛管理通过减少业务流程偏差和缺陷改进组织绩效。", "B": "正确，ISO质量管理通过规范产品或服务的生产与管理过程实现持续改进。", "C": "正确，卓越绩效管理以系统的卓越绩效标准推动组织整体管理水平提升。", "D": "正确，标杆超越法通过比较最佳实践识别差距并实施改进。", "E": "错误，关键绩效指标主要是一种战略绩效衡量和管理工具，不属于本题所列的组织绩效改进方法。"}}, {"id": "16-33", "type": "single", "stem": "通过减少企业业务流程中的偏差，提升组织绩效水平的绩效改进方法是（ ）。", "options": {"A": "卓越绩效管理", "B": "ISO质量管理体系", "C": "六西格玛管理", "D": "标杆超越"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，卓越绩效管理从领导、战略、顾客、测量分析、人员和过程等方面系统提升组织管理水平。", "B": "错误，ISO质量管理体系重点是建立规范化、标准化的质量管理和生产过程。", "C": "正确，六西格玛管理以数据和统计分析为基础，重点减少业务流程中的波动、偏差和缺陷。", "D": "错误，标杆超越通过与最佳实践比较，发现差距并进行改进。"}}, {"id": "16-34", "type": "single", "stem": "关于绩效管理工具的说法，错误的是（ ）。", "options": {"A": "卓越绩效标准关注组织的管理理念", "B": "六西格玛管理关注组织业务流程的误差率", "C": "ISO质量管理体系关注组织产品或服务的生产过程", "D": "标杆超越法中的企业标杆必须是管理水平相当，业绩相近的企业"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，卓越绩效标准强调组织整体管理理念、领导方式和系统管理能力。", "B": "正确，六西格玛管理关注流程偏差、缺陷和误差率，并通过数据分析降低波动。", "C": "正确，ISO质量管理体系重视对产品或服务实现过程的规范和控制。", "D": "错误，标杆对象不必与本企业管理水平相当或业绩相近，可以选择行业内外具有最佳实践、最佳流程或最佳标准的组织。"}}, {"id": "16-35", "type": "single", "stem": "关于绩效考核结果的分析与应用说法错误的是（ ）。", "options": {"A": "绩效考核结果可为员工晋升决策提供支持", "B": "绩效考核结果可用于职位评价", "C": "绩效考核结果可用于衡量培训的有效性", "D": "绩效考核结果可用于员工的职业生涯规划"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，绩效结果能够反映员工的工作表现，可为晋升、调动等人事决策提供依据。", "B": "错误，职位评价针对职位本身的责任、技能要求、工作条件和相对价值，不应依据任职者的绩效考核结果进行。", "C": "正确，通过比较培训前后的绩效变化，可以评价培训效果。", "D": "正确，绩效结果有助于识别员工优势、短板和发展潜力，为职业生涯规划提供依据。"}}, {"id": "16-36", "type": "single", "stem": "关于对绩效考核结果的应用，下列做法有误的是（ ）。", "options": {"A": "对于贡献型，给予奖励", "B": "对于安分型，培训", "C": "对于堕落型，惩罚", "D": "对于冲锋型，绩效考核"}, "answer": "D", "analysis": "绩效考核结果可以结合工作能力或发展潜力对员工进行分类并采取差异化措施。", "optionAnalysis": {"A": "正确，贡献型员工绩效和工作能力均较高，应给予奖励并重点保留。", "B": "正确，安分型员工通常工作能力较强但绩效较低，应通过培训、沟通或激励改善其绩效。", "C": "正确，堕落型员工绩效和能力均较低，可以采取警告、惩罚、调岗或解除关系等措施。", "D": "错误，冲锋型员工通常绩效较高但能力或发展基础相对不足，应重点进行能力提升、培训和职业发展辅导，而“绩效考核”不是针对该类型员工的改进措施。"}}, {"id": "16-37", "type": "single", "stem": "关于团队绩效考核实施方式的说法，错误的是（ ）。", "options": {"A": "团队层面绩效考核指标的确定是团队绩效考核指标设计的关键", "B": "应根据团队负责人的评优结果确定团队成员的评优结果", "C": "由人力资源部门负责与员工就绩效考核结果进行沟通", "D": "在对团队成员进行评价时，被评价员工本人也应参与其中"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "正确，团队层面指标决定团队共同努力的方向，是团队绩效指标体系设计的重要环节。B项正确，团队成员的评价结果需要与团队整体及团队负责人的评价结果保持合理联系，避免个人评价与团队结果脱节。", "C": "错误，与员工就具体绩效结果进行沟通通常应由其直接上级或团队负责人承担，人力资源部门主要负责制度设计、协调、培训和监督。", "D": "正确，团队成员评价可以吸收被评价员工本人参与，通过自评与其他评价主体的信息相互补充。"}}, {"id": "16-38", "type": "multi", "stem": "关于知识型团队绩效考核的说法，正确的有（ ）。", "options": {"A": "对团队的考核应以结果为导向", "B": "评估不确定性风险对团队及其成员的危害程度时，应采用风险型指标", "C": "评估团队工作过程和工作结果对客户的长远影响时，应采用递延型指标", "D": "对团队的考核应以行为为导向", "E": "评估团队的产出满足客户需求的程度时，应采用效率型指标第十七章薪酬管理"}, "answer": "ABC", "analysis": "", "optionAnalysis": {"A": "正确，知识型团队的工作过程具有较强自主性和创造性，难以进行严密过程控制，因此绩效考核通常应以结果为导向。", "B": "正确，风险型指标用于评价不确定性风险对团队及其成员可能造成的危害程度。", "C": "正确，递延型指标用于评价团队工作过程和工作结果对客户、组织或社会产生的长期影响。", "D": "错误，知识型团队的行为过程较难标准化和直接观察，通常不宜以行为导向作为主要考核方式。", "E": "错误，团队产出满足客户需求的程度主要体现效果或效益，而效率型指标侧重投入与产出的比例关系，二者不能混同。"}}]}, {"id": 17, "title": "薪酬管理", "questions": [{"id": "17-1", "type": "multi", "stem": "下列与收缩战略相匹配的人力资源管理活动，说法正确的是（ ）。", "options": {"A": "关注点在于组织精简和裁员之后留在组织中的员工士气", "B": "不断补充各类人才", "C": "人员的知识和技能需要更新，培训压力大", "D": "鼓励员工与组织共担风险", "E": "员工福利水平比较高"}, "answer": "ACD", "analysis": "收缩战略强调控制成本、缩减规模和提高组织效率。", "optionAnalysis": {"A": "正确，裁员和组织精简容易影响留任员工的安全感、信任感和工作士气，因此需要重点关注。", "B": "错误，不断补充各类人才通常与成长战略相匹配，收缩战略一般会控制招聘或冻结雇用。", "C": "正确，组织收缩后员工可能需要承担更综合的职责，原有知识和技能需要更新，培训和转岗压力较大。", "D": "正确，收缩战略下企业通常会强化员工与组织的风险共担机制，提高浮动薪酬或绩效薪酬的作用。", "E": "错误，收缩战略强调成本控制，通常不会维持较高的福利水平。"}}, {"id": "17-2", "type": "single", "stem": "薪酬结构上基本薪酬和福利所占的比重较大，一般低于或略高于市场水平的薪酬，但短期内不会有太大的增长的战略是（ ）。", "options": {"A": "稳定战略", "B": "成长战略", "C": "收缩战略", "D": "竞争战略"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，稳定战略下企业经营环境和人员需求相对稳定，薪酬结构中基本薪酬和福利所占比重较大，薪酬水平通常采取市场跟随或略高于市场水平的政策，短期增长幅度不大。", "B": "错误，成长战略通常强调吸引人才和快速扩张，更重视具有竞争力的薪酬以及与发展结果相关的激励。", "C": "错误，收缩战略更加重视成本控制和风险共担，基本薪酬及福利的保障性特征不是题干描述的核心。", "D": "错误，“竞争战略”是上位概念，不能准确对应题干所述特征。"}}, {"id": "17-3", "type": "single", "stem": "关于不同战略下公司的薪酬管理特征的说法，正确的是（ ）。", "options": {"A": "采取成长战略的企业往往在短期内提供较高水平的基本薪酬", "B": "采取稳定战略的企业薪酬结构中的基本薪酬和福利，所占比重通常较小", "C": "采取稳定战略的企业一般采取市场跟随或略高于市场水平的薪酬", "D": "采取收缩战略的企业薪酬结构中的基本薪酬所占比例通常较高"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，成长战略企业虽然需要吸引人才，但通常更强调薪酬的激励性和未来收益，不一定在短期内提供很高的基本薪酬。", "B": "错误，稳定战略下基本薪酬和福利所占比重通常较大。", "C": "正确，稳定战略下企业薪酬政策较为平稳，一般采取市场跟随或略高于市场水平的策略。", "D": "错误，收缩战略强调控制固定人工成本和风险共担，基本薪酬所占比例通常不会设置得过高。"}}, {"id": "17-4", "type": "single", "stem": "与组织的成本领先战略薪酬管理相匹配的活动是（ ）。", "options": {"A": "通过降低产品质量来压缩成本", "B": "降低薪酬体系中浮动薪酬的比重", "C": "奖励员工在成本节约方面的成绩", "D": "为员工提供大幅高于竞争水平的薪资水平"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，成本领先战略是在保证必要质量和价值的基础上提高效率、降低成本，并非通过降低产品质量实现。", "B": "错误，成本领先战略通常会重视浮动薪酬，使薪酬与成本、效率和绩效结果挂钩。", "C": "正确，对员工在降低成本、减少浪费和提高生产率方面取得的成绩给予奖励，能够支持成本领先战略。", "D": "错误，大幅高于市场水平的薪资会增加固定人工成本，通常不符合成本领先战略。"}}, {"id": "17-5", "type": "single", "stem": "关于差异化战略薪酬结构的表述，正确的是（ ）。", "options": {"A": "基本薪酬在薪酬体系中占有主导性", "B": "基本薪酬低于其他企业", "C": "基本薪酬在市场中要具有竞争性", "D": "薪酬具有稳定性"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，差异化战略强调创新、质量和独特价值，不是简单以基本薪酬占主导为特征。", "B": "错误，为吸引和保留具有创新能力、专业能力的人才，基本薪酬通常不能明显低于竞争对手。", "C": "正确，差异化战略需要高素质和稀缺人才支持，因此基本薪酬应在劳动力市场中具有竞争性。", "D": "错误，差异化战略下薪酬通常与创新、质量和绩效成果相联系，不能仅以稳定性概括。"}}, {"id": "17-6", "type": "single", "stem": "关于不同企业竞争战略下的薪酬管理特征的说法，正确的是（ ）。", "options": {"A": "企业若采用成本领先战略，薪酬水平应当比竞争对手相对更高", "B": "企业若采用差异化战略，基本薪酬应略低于劳动力市场通行工资水平", "C": "企业若采用市场集中战略，应根据员工的工作年限支付报酬", "D": "企业若采用成本领先战略，奖金在薪资结构中所占比例应相对较大"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，成本领先战略强调人工成本控制，整体薪酬水平一般不会显著高于竞争对手。", "B": "错误，差异化战略依赖专业人才和创新人才，基本薪酬应具有市场竞争力，而不是略低于市场水平。C项错误，市场集中战略应围绕特定市场和客户需求配置薪酬，不能仅根据工作年限支付报酬。", "D": "正确，成本领先战略需要使员工收入与成本、效率和绩效结果挂钩，因此奖金等浮动薪酬所占比例可以相对较大。"}}, {"id": "17-7", "type": "single", "stem": "薪酬调查的作用不包括（ ）。", "options": {"A": "薪酬差距的调整", "B": "薪酬晋升政策的调整", "C": "薪酬内部公平性的调整", "D": "整体薪酬水平的调整"}, "answer": "C", "analysis": "薪酬调查主要收集外部劳动力市场的薪酬信息，用于判断企业薪酬的外部竞争性。", "optionAnalysis": {"A": "属于薪酬调查的应用，可以根据市场差距调整不同职位或层级的薪酬差距。", "B": "属于其应用，市场薪酬变化可以为薪酬晋升政策调整提供依据。", "C": "不属于，薪酬内部公平性主要通过工作分析、职位评价和内部薪酬结构设计解决。", "D": "属于薪酬调查的重要作用，可以据此确定或调整企业整体薪酬水平。"}}, {"id": "17-8", "type": "single", "stem": "薪酬结构设计的有效标准是（ ）。", "options": {"A": "内部一致性、系统性", "B": "系统性、实用性", "C": "内部一致性、外部竞争性", "D": "战略性、外部竞争性"}, "answer": "C", "analysis": "有效的薪酬结构既要体现组织内部不同职位相对价值之间的合理关系，即内部一致性；又要与外部劳动力市场的薪酬水平保持适当关系，即外部竞争性。A、B两项中的“系统性、实用性”属于一般管理要求，不能完整体现薪酬结构设计的核心标准。D项中的战略性虽然重要，但缺少对内部公平和内部职位价值关系的直接体现。", "optionAnalysis": {}}, {"id": "17-9", "type": "single", "stem": "关于职位评价法错误的是（ ）。", "options": {"A": "职位评价是确定薪酬水平的依据", "B": "职位评价主要解决薪酬外部性竞争问题", "C": "职位评价能确定各职位的相对价值", "D": "是对目前而非过去或未来职位状况的评价"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，职位评价结果是建立职位等级和确定内部薪酬结构的重要依据。", "B": "错误，职位评价主要解决不同职位之间的相对价值和薪酬内部公平性问题；薪酬外部竞争性主要通过薪酬调查解决。", "C": "正确，职位评价的核心目的就是确定组织内部各职位的相对价值。", "D": "正确，职位评价针对职位当前的正常状态进行评价，不评价过去或未来可能出现的职位状态。"}}, {"id": "17-10", "type": "multi", "stem": "关于职位评价，正确的说法有（ ）。", "options": {"A": "职位评价是在工作分析的基础上，系统地对各职位的价值进行评价", "B": "职位评价是对职位的评价而非对任职者的评价", "C": "职位评价是对正常或一般水平的评价而非特殊业绩的评价", "D": "职位评价是对目前职位状况的评价", "E": "职位评价是对过去或未来职位状况的评价"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，工作分析提供职位职责、任职条件和工作关系等信息，是职位评价的基础。", "B": "正确，职位评价的对象是职位本身，而不是具体任职者的能力或表现。", "C": "正确，评价针对职位在正常情况下的职责和要求，不评价任职者的特殊业绩。", "D": "正确，评价以职位目前的客观状况为依据。", "E": "错误，职位评价不以已经消失的过去状态或尚未形成的未来状态为评价对象。"}}, {"id": "17-11", "type": "single", "stem": "关于职位评价的说法，正确的是（ ）。", "options": {"A": "职位评价是组织确定内部各职位相对价值的一种手段", "B": "职位评价是对任职者履职能力所做的评价", "C": "职位评价是工作分析的前提", "D": "职位评价是对特殊业绩而非一般业绩所做的评价"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，职位评价用于系统判断组织内部各职位的相对价值，是建立职位等级和薪酬结构的基础。", "B": "错误，对任职者履职能力的评价属于人员评价或绩效、能力评价，不属于职位评价。", "C": "错误，工作分析是职位评价的前提，职位评价应建立在工作分析结果之上。", "D": "错误，职位评价针对职位的正常职责和一般工作状态，不评价任职者的特殊业绩。"}}, {"id": "17-12", "type": "single", "stem": "职位评价的原则不包括（ ）。", "options": {"A": "体系先进原则", "B": "员工参与原则", "C": "战略性原则", "D": "标准化原则"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "不属于职位评价的基本原则。职位评价体系应当实用、有效并符合组织实际，不能单纯追求所谓最先进的评价体系。", "B": "属于职位评价原则，适当吸收员工参与有利于提高评价结果的认可度。", "C": "属于职位评价原则，评价体系应与组织战略和薪酬战略相协调。", "D": "属于职位评价原则，应采用统一、规范的评价标准和程序，以提高结果的一致性和可比性。"}}, {"id": "17-13", "type": "multi", "stem": "关于职位评价的原则，表达正确的是（ ）。", "options": {"A": "组织应该选择最先进的评价体系", "B": "职位评价标准和职位等级结构应该公开化", "C": "员工不能参与职位评价工作", "D": "工作分析是职位评价与薪酬设计相联系的桥梁，具有承上启下的作用", "E": "职位评价的选择应具有实用有效性"}, "answer": "BE", "analysis": "", "optionAnalysis": {"A": "错误，职位评价方法并非越先进越好，应选择与组织规模、职位特点和管理基础相适应的方法。", "B": "正确，公开评价标准和职位等级结构有利于增强透明度及员工认同。", "C": "错误，职位评价强调员工参与，员工代表或相关人员的参与有助于提高评价结果的可接受性。", "D": "错误，职位评价是工作分析与薪酬设计之间的桥梁；题干将这一桥梁作用错误地归于工作分析。", "E": "正确，评价体系必须具有实用性和有效性，能够在组织中稳定实施并产生可信结果。"}}, {"id": "17-14", "type": "single", "stem": "关于职位评价中排序法的说法，正确的是（ ）。", "options": {"A": "排序法适用于职位类型较多的企业", "B": "适用于规模较大的企业", "C": "属于定性方法", "D": "属于职位尺度比较法"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，排序法适合职位数量较少、职位类型较简单的组织，不适合职位类型较多的企业。", "B": "错误，大型企业职位数量多、差异复杂，采用排序法容易出现判断困难。", "C": "正确，排序法主要依据评价人员的整体判断对职位进行排列，属于定性评价方法。", "D": "错误，排序法属于直接职位比较法，而非职位尺度比较法。"}}, {"id": "17-15", "type": "single", "stem": "关于职位评价方法分类的说法，正确的是（ ）。", "options": {"A": "职位尺度比较法包括要素计点法和分类法", "B": "定量方法包括要素计点法和排序法", "C": "直接职位比较法包括因素比较法和分类法", "D": "定性方法包括因素比较法和分类法"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，按比较基础分类，职位尺度比较法包括分类法和要素计点法，二者均借助预先设定的等级或尺度评价职位。", "B": "错误，排序法属于定性方法，要素计点法属于定量方法。", "C": "错误，直接职位比较法主要包括排序法和因素比较法，分类法属于职位尺度比较法。", "D": "错误，分类法属于定性方法，但因素比较法属于定量方法，不能将二者都归为定性方法。"}}, {"id": "17-16", "type": "single", "stem": "关于各类职位评价方法的说法，错误的是（ ）。", "options": {"A": "因素比较法的设计难度低，易于理解", "B": "分类法需要设定一套供参考的职位等级标准", "C": "要素计点法是一种定量的职位评价方法", "D": "排序法不适用于规模较大、职位类型多的企业"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "错误，因素比较法需要选择基准职位、确定报酬要素并分配各要素的工资率，设计复杂、操作难度较高，也不容易被普通员工理解。", "B": "正确，分类法需要预先建立职位等级及其标准，再将职位归入相应等级。", "C": "正确，要素计点法对报酬要素设定权重和点数，属于定量方法。", "D": "正确，排序法依赖整体判断，职位数量和类型较多时评价难度明显增加。"}}, {"id": "17-17", "type": "single", "stem": "关于股票期权的说法，错误的是（ ）。", "options": {"A": "股票期权是一种权利", "B": "当股票期权的行权价低于行权时股票的市场价时才有价值", "C": "股票期权是一种义务", "D": "股票期权是公司无偿给予激励对象的"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "正确，股票期权赋予激励对象在规定时期内按约定价格购买公司股票的权利。", "B": "正确，只有市场价格高于行权价格时，行权才具有正的价差收益。", "C": "错误，股票期权不是必须履行的义务，激励对象可以根据市场情况选择行权或放弃。", "D": "正确，授予股票期权本身通常不要求激励对象支付对价，实际行权购买股票时才需要支付行权价款。"}}, {"id": "17-18", "type": "single", "stem": "关于股票期权的说法，正确的是（ ）。", "options": {"A": "股票期权受益人须在规定时期内购买公司股票", "B": "股票期权适用于非上市公司", "C": "股票期权是一种权利，也是一种义务", "D": "股票期权是企业无偿给予经营者等激励对象的"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，激励对象有权选择是否行权，并非必须购买公司股票。", "B": "错误，在本章股权激励模式的分类中，股票期权主要适用于上市公司，非上市公司通常采用股份期权、虚拟股票期权或业绩股份等方式。", "C": "错误，股票期权是一种权利，不是义务。", "D": "正确，企业无偿授予经营者等激励对象在未来按照约定条件购买股票的权利。"}}, {"id": "17-19", "type": "single", "stem": "关于我国股票期权的说法，正确的是（ ）。", "options": {"A": "激励对象可以同时参加两个上市公司的股权激励计划", "B": "激励对象包括独立董事，监事", "C": "股票期权只适用于上市公司", "D": "激励对象数量可以超过员工总数的10%"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，按照相关股权激励规则，同一激励对象不应同时参加两个或两个以上上市公司的股权激励计划。", "B": "错误，独立董事、监事通常不属于股票期权的激励对象范围。", "C": "正确，本章所称股票期权模式主要适用于上市公司，因为行权收益需要以公开交易股票的市场价格为基础。", "D": "错误，激励对象人数通常受到员工总数一定比例的限制，不能任意超过规定比例。"}}, {"id": "17-20", "type": "multi", "stem": "关于股票期权计划的陈述，正确的是（ ）。", "options": {"A": "对于上市公司和非上市公司，都可以采用股票期权计划", "B": "股票期权获授人到期可以行权也可放弃", "C": "股票期权既是员工的权利又是员工的义务", "D": "股票期权行使期限一般超过10年", "E": "只有在行权价低于行权时本企业股票的市场价格的情况下，股票期权才有价值"}, "answer": "BE", "analysis": "", "optionAnalysis": {"A": "错误，股票期权通常以可公开交易的上市公司股票为标的，非上市公司一般采用股份期权等替代方式。", "B": "正确，股票期权属于选择权，获授人满足条件后可以行权，也可以放弃。", "C": "错误，股票期权是权利而不是义务。", "D": "错误，股票期权的有效期或行权期限通常存在上限，一般不超过10年，不能表述为一般超过10年。", "E": "正确，当股票市场价格高于行权价格时，激励对象才能获得价差收益。"}}, {"id": "17-21", "type": "single", "stem": "关于我国上市公司限制性股票的说法，错误的是（ ）。", "options": {"A": "若激励对象的业绩目标未达成，公司有权按激励对象购买时的价格回购股票", "B": "若激励对象的工作年限未满足约定要求，公司有权收回免费赠予的限制性股票", "C": "激励对象可以低价获得一定数量的公司限制性股票", "D": "激励对象获得公司限制性股票后可以自由转让"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "正确，未达到约定业绩条件时，公司可以依照激励计划回购尚未解除限制的股票。", "B": "正确，未满足服务期限等条件时，公司可以按照约定收回或回购限制性股票。", "C": "正确，限制性股票通常以较低价格授予，部分计划也可能采取无偿授予方式。", "D": "错误，限制性股票在限售期和解锁条件满足前不得自由转让，只有满足规定条件并解除限售后才能依法处置。"}}, {"id": "17-22", "type": "single", "stem": "根据中国证监会规定，适用于现金流比较充裕且股价比较稳定的境外上市公司的股权激励模式是（ ）。", "options": {"A": "股份期权", "B": "股票增值权", "C": "限制性股票", "D": "股票期权"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "股份期权主要用于非上市公司，不符合题干所述境外上市公司情形。", "B": "正确，股票增值权一般以股票价格上涨形成的差额作为激励收益，通常需要企业以现金兑现，因此更适合现金流充裕、股价较稳定的境外上市公司。", "C": "限制性股票需要实际授予股票并设置限售条件，不是题干所指模式。", "D": "股票期权一般由激励对象支付行权价购买股票，企业所承受的直接现金支付压力相对较小。"}}, {"id": "17-23", "type": "single", "stem": "关于股票增值权的说法，错误的是（ ）。", "options": {"A": "股票增值权的行权期一般超过任期", "B": "股票增值权行权时需要全额兑现", "C": "股票增值权在行权时不必实际买卖股票", "D": "股票增值权实质上是企业奖金的延期支付"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "正确，股票增值权的行权安排通常具有中长期特征，其行权期可以延续至经营者任期以后，以形成长期约束。", "B": "错误，行权收益通常按照规定分期兑现或保留一定比例，不要求在行权时一次性全额兑现。", "C": "正确，股票增值权以股票价格上涨产生的差额为收益基础，不需要激励对象实际购买或出售股票。", "D": "正确，其经济实质是将与企业价值增长挂钩的奖金延后支付。"}}, {"id": "17-24", "type": "single", "stem": "关于上市公司各类股权激励模式特点的说法，正确的是（ ）。", "options": {"A": "股票增值权模式对公司现金压力较小", "B": "限制性股票模式下有利于科学地确定股价", "C": "限制性股票模式对现金流压力较小", "D": "股票期权模式能降低委托代理成本"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，股票增值权通常由公司以现金支付股票增值收益，可能带来较大的现金压力。", "B": "错误，限制性股票的授予价格和评价基础可能受到市场波动等因素影响，不能据此认为一定有利于科学确定股价。", "C": "错误，限制性股票可能涉及股票授予、回购及相应资金安排，不能概括为对现金流压力较小。", "D": "正确，股票期权将经营者收益与公司股价和长期价值联系起来，有助于协调股东与经营者利益，降低委托代理成本。"}}, {"id": "17-25", "type": "single", "stem": "关于各类上市公司股权激励方式的说法，正确的是（ ）。", "options": {"A": "股票期权会在短期很快产生激励效果", "B": "股票增值权会给公司造成较大的现金压力", "C": "股票期权会增加企业的委托代理成本", "D": "股票增值权适用于境内上市公司"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "错误，股票期权通常设置等待期、行权条件和行权期限，属于中长期激励，不会必然在短期迅速产生效果。", "B": "正确，股票增值权的收益通常由企业以现金支付，股票价格上涨较多或激励对象较多时会形成较大现金支出。", "C": "错误，股票期权有助于使经营者与股东的长期利益趋于一致，从而降低委托代理成本。", "D": "错误，教材所述股票增值权主要适用于现金流充裕、股价稳定的境外上市公司。"}}, {"id": "17-26", "type": "multi", "stem": "下列哪些属于非上市公司股权激励方式的有（ ）。", "options": {"A": "限制性股票", "B": "股票增值权", "C": "虚拟股票期权", "D": "业绩股份", "E": "股份期权"}, "answer": "CDE", "analysis": "", "optionAnalysis": {"A": "不选，限制性股票属于上市公司常用的股权激励模式。", "B": "不选，股票增值权主要应用于符合特定条件的境外上市公司。", "C": "应选，虚拟股票期权不需要实际发行或交易股票，适合非上市公司。", "D": "应选，业绩股份根据经营业绩向激励对象授予股份或相应权益，是非上市公司可采用的方式。", "E": "应选，股份期权以非上市公司的股份为标的，是非上市公司常用的股权激励方式。"}}, {"id": "17-27", "type": "single", "stem": "关于虚拟股票期权，说法正确的是（ ）。", "options": {"A": "拥有股票的表决权", "B": "持有的股份可以进行转让和出售", "C": "取决于公司股票的价格", "D": "只是在名义上拥有而非真正购买公司股票"}, "answer": "D", "analysis": "", "optionAnalysis": {"A": "错误，虚拟股票期权不是真实股权，持有人通常不具有股东表决权。", "B": "错误，激励对象没有取得可实际转让的公司股份，因此不能像真实股票一样自由转让和出售。", "C": "表述不准确，非上市公司通常不存在公开市场股价，虚拟权益收益主要依据公司价值、内部评估价格或经营业绩计算。", "D": "正确，虚拟股票期权只是在名义上赋予与股份价值相联系的权益，激励对象并未真正购买和持有公司股票。"}}, {"id": "17-28", "type": "single", "stem": "关于员工持股计划的说法，正确的是（ ）。", "options": {"A": "科学合理的员工持股计划能够降低企业融资成本", "B": "员工持股计划的认购者可以是本企业员工，也可以是企业外部人士", "C": "员工持股计划中员工所认购的股份进行转让不受限制", "D": "员工持股计划会显著增加企业的税务负担"}, "answer": "A", "analysis": "", "optionAnalysis": {"A": "正确，员工持股可以为企业提供相对稳定、长期和成本较低的资金来源，从而降低融资成本。", "B": "错误，员工持股计划的参与者和认购者应当是本企业符合条件的员工，而不是企业外部人士。", "C": "错误，员工持股计划通常设有锁定期及转让、退出等限制。", "D": "错误，合理设计的员工持股计划可能获得相应税收政策支持，并非必然显著增加企业税务负担。"}}, {"id": "17-29", "type": "multi", "stem": "关于员工持股计划的说法正确的是（ ）。", "options": {"A": "员工持股计划既能激励员工努力工作，也能吸引人才", "B": "员工持股计划可以使企业获得低成本的资金来源", "C": "持股人和认购者可以是本企业员工，也可以是外部人员", "D": "认购者认购的股份在转让和交易方面不受限制", "E": "员工持股计划可以为企业提供稳定、长期且能够减轻企业税务负担的资金"}, "answer": "ABE", "analysis": "", "optionAnalysis": {"A": "正确，员工成为企业利益相关者后，其个人收益与企业发展联系更紧密，既能产生激励作用，也有助于吸引和保留人才。", "B": "正确，员工投入的持股资金可以成为企业成本较低的融资来源。C项错误，员工持股计划面向本企业符合条件的员工，外部人员不能作为一般认购者。", "D": "错误，员工持股通常设置锁定期和转让限制。", "E": "正确，员工持股资金具有相对稳定和长期的特点，符合条件的计划还可能享受相应税收安排，从而减轻税务负担。"}}, {"id": "17-30", "type": "multi", "stem": "关于员工持股计划的股份设置及持股比例的说法，正确的是（ ）。", "options": {"A": "参与员工持股计划的员工不得高于企业员工总数的90%", "B": "只有本企业正式聘用的员工才能参与员工持股", "C": "参与员工持股计划的员工能购买的企业股票数量由本人工资在员工全体薪金总额的比例确定", "D": "员工持股占企业总股本的20%", "E": "一般企业高管人员与一般职工在员工持股中的认购比例不得低于10∶1"}, "answer": "BC", "analysis": "", "optionAnalysis": {"A": "错误，教材相关规则强调员工持股计划应具有广泛参与性，参与人数通常应达到规定的最低比例，而不是不得高于90%。", "B": "正确，员工持股计划原则上面向与本企业存在正式劳动关系的员工。", "C": "正确，在有关持股分配方式中，可以根据员工本人工资占全体员工薪金总额的比例确定可认购的股票数量。", "D": "错误，员工持股总额通常应控制在规定上限以内，不能直接表述为固定占企业总股本的20%。", "E": "错误，为避免持股过度向高管集中，高管与一般职工的认购比例通常受到最高比例限制，题干所说“不得低于10∶1”方向错误。"}}, {"id": "17-31", "type": "multi", "stem": "关于年薪制的说法，正确的有（ ）。", "options": {"A": "年薪制在年薪结构中降低了风险收入的比例", "B": "年薪制依靠约束和激励互相制衡的机制", "C": "年薪制根据企业经济效益计发薪酬", "D": "年薪制的设计比较灵活", "E": "年薪制容易导致经营者的短期行为"}, "answer": "BDE", "analysis": "", "optionAnalysis": {"A": "错误，年薪制通常由基本年薪和风险收入构成，并通过提高与经营业绩挂钩的风险收入比例发挥激励作用。", "B": "正确，年薪制既通过业绩报酬激励经营者，又通过考核、延期支付和风险收入等机制进行约束。", "C": "表述不完整，年薪制主要根据经营者的经营业绩、责任和贡献确定报酬，不能简单等同于仅按企业经济效益计发。", "D": "正确，基本年薪、绩效年薪和风险收入等部分可以根据企业实际灵活设计。", "E": "正确，如果考核周期和指标设计不合理，经营者可能为提高当期年薪而追求短期业绩。"}}, {"id": "17-32", "type": "multi", "stem": "关于年薪制的说法，正确的是（ ）。", "options": {"A": "年薪制是一种高稳定、低风险的薪酬制度", "B": "年薪制根据经营者业绩好坏而计发薪酬", "C": "年薪制可以把年薪收入的一部分直接转化为股权激励形式", "D": "年薪制可以根据企业经营者年度的经营业绩，灵活确定与其贡献相当的年度薪酬", "E": "年薪制通常会确保经营者有一个最低薪酬"}, "answer": "BCDE", "analysis": "", "optionAnalysis": {"A": "错误，年薪制包含与经营业绩挂钩的风险收入，具有较强的浮动性，不能概括为高稳定、低风险。", "B": "正确，经营者业绩是确定绩效年薪和风险收入的重要依据。", "C": "正确，为形成长期激励，可以将部分年薪收入转化为股票、股份或其他股权激励。", "D": "正确，年薪制能够结合年度经营业绩和经营者贡献灵活确定报酬。", "E": "正确，基本年薪通常发挥基本保障作用，使经营者获得一定的最低薪酬。"}}, {"id": "17-33", "type": "single", "stem": "某公司销售人员的薪酬由基本工资和销售提成组成，这种薪酬方案称为（ ）。", "options": {"A": "纯佣金制", "B": "基本薪酬加佣金制", "C": "基本薪酬加奖金制", "D": "基本薪酬加佣金加奖金制"}, "answer": "B", "analysis": "题干明确包含“基本工资”和“销售提成”两个组成部分，销售提成属于佣金，因此该方案是基本薪酬加佣金制。", "optionAnalysis": {"A": "纯佣金制不包含固定基本工资。", "C": "基本薪酬加奖金制中的奖金通常根据综合目标完成情况发放，不等同于按销售额或销售量计算的提成。", "D": "还应包含独立的奖金部分，而题干未提及奖金。"}}, {"id": "17-34", "type": "multi", "stem": "关于销售人员薪酬的说法，正确的有（ ）。", "options": {"A": "销售人员的薪酬应主要以行为为导向", "B": "纯佣金制因将销售人员的薪酬收入与其工作业绩直接挂钩而使薪酬管理成本较低", "C": "产品具有较高技术含量的企业会对销售人员采用高佣金加低基本薪酬的薪酬制度", "D": "纯佣金制会导致销售人员的薪酬缺乏稳定性", "E": "纯佣金制不利于培养销售人员对企业的归属感"}, "answer": "BDE", "analysis": "", "optionAnalysis": {"A": "错误，销售人员的工作结果通常较容易用销售额、销售量等指标衡量，其薪酬应更多以结果或业绩为导向。", "B": "正确，纯佣金制把收入直接与销售业绩挂钩，计算和管理相对简单，管理成本较低。", "C": "错误，技术含量较高的产品需要销售人员提供专业咨询、客户服务和团队协作，通常更适合较高基本薪酬、较低佣金的组合。", "D": "正确，纯佣金制没有固定收入保障，销售波动会导致薪酬不稳定。", "E": "正确，销售人员收入主要依赖短期销售结果，容易弱化其对企业的长期认同和归属感。"}}, {"id": "17-35", "type": "multi", "stem": "薪酬成本控制的主要策略包括（ ）。", "options": {"A": "控制福利支出", "B": "控制雇佣量", "C": "控制基本薪酬", "D": "控制奖金", "E": "控制市场薪酬水平"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，调整福利项目、福利标准和福利成本分担方式可以控制薪酬成本。", "B": "正确，冻结招聘、减少雇用数量或优化人员配置能够控制人工成本总量。", "C": "正确，控制基本薪酬增长、调整薪酬等级和起薪水平是重要手段。", "D": "正确，奖金属于可变薪酬，可以通过调整奖金预算、标准和发放条件控制成本。", "E": "错误，市场薪酬水平由劳动力市场供求、行业状况等外部因素决定，单个企业不能直接控制，只能根据市场水平调整自身薪酬政策。"}}, {"id": "17-36", "type": "multi", "stem": "薪酬成本控制的方法（ ）。", "options": {"A": "冻结雇用", "B": "控制基本薪酬", "C": "减少奖金", "D": "压缩福利费用", "E": "加班加点"}, "answer": "ABCD", "analysis": "", "optionAnalysis": {"A": "正确，冻结雇用可以限制员工数量增长，减少新增人工成本。", "B": "正确，控制基本薪酬水平和增长幅度可以控制固定薪酬成本。", "C": "正确，在符合法律规定和企业制度的前提下，适当减少奖金预算可以降低可变薪酬支出。", "D": "正确，优化福利项目、减少非必要福利费用可以控制总体薪酬成本。", "E": "错误，加班加点可能产生加班工资并增加员工疲劳及管理风险，不属于一般意义上的薪酬成本控制方法。"}}, {"id": "17-37", "type": "single", "stem": "在人工成本的分析指标中，可以体现企业的人工成本与产出之间的相对关系的指标是（ ）。", "options": {"A": "人工成本总量指标", "B": "人工成本分析比率型指标", "C": "人工成本结构指标", "D": "人工成本增速指标"}, "answer": "B", "analysis": "", "optionAnalysis": {"A": "人工成本总量指标反映企业人工成本的绝对规模，不能直接体现人工成本与产出的相对关系。", "B": "正确，人工成本分析比率型指标通过人工成本与销售收入、增加值、总成本等产出或经营指标进行比较，能够反映投入与产出的相对关系。", "C": "人工成本结构指标反映各项人工成本在人工成本总额中的构成。", "D": "人工成本增速指标反映人工成本随时间变化的速度，不能直接反映其与产出的相对关系。"}}, {"id": "17-38", "type": "single", "stem": "关于企业人工成本的说法，正确的是（ ）。", "options": {"A": "人工成本分析比率型指标能够显示本企业员工平均收入的高低", "B": "人工成本结构指标通常用于对企业的支付能力进行分析和控制", "C": "企业人工成本既包括直接费用也包括间接费用", "D": "人工成本总量指标能够反映人工成本投入构成的情况与合理性第十八章培训与开发"}, "answer": "C", "analysis": "", "optionAnalysis": {"A": "错误，员工平均收入水平主要通过人工成本总量及人均人工成本等指标反映；比率型指标主要反映人工成本与产出、收入等指标的相对关系。", "B": "错误，企业支付能力通常通过人工成本分析比率型指标进行分析和控制；结构指标主要反映人工成本各组成项目的比例。", "C": "正确，企业人工成本既包括直接支付给员工的工资、奖金等直接费用，也包括社会保险、福利、培训等相关间接费用。", "D": "错误，反映人工成本投入构成及其合理性的是人工成本结构指标，而不是总量指标。"}}]}, {"id": 18, "title": "培训与开发", "questions": [{"id": "18-1", "type": "single", "stem": "关于培训与开发效果评估中的结果评估的说法，错误的是（ ）。", "options": {"A": "它是培训与开发效果评估中最受组织高管层关心的内容", "B": "它是组织进行培训与开发效果评估的最重要内容", "C": "它重点评估受训人员对培训与开发的主观感受和看法", "D": "它是最具有说服力的培训与开发效果评价指标"}, "answer": "C", "analysis": "结果评估主要考察培训与开发给组织带来的最终成效，如产出、质量、成本、时间、员工工作态度以及投资收益等。受训人员对培训内容、形式和讲师的主观感受属于反应评估，而不是结果评估。", "optionAnalysis": {"A": "正确。组织高管层通常最关心培训能否改善经营结果和组织绩效，因此结果评估是其最关心的内容。", "B": "正确。结果评估能够反映培训与开发是否真正转化为组织层面的成果，是培训效果评估中的重要内容。", "C": "错误。对培训与开发的主观感受和看法是反应评估的重点。", "D": "正确。结果评估直接反映培训带来的组织成果，通常被认为是最有说服力的评价指标。"}}, {"id": "18-2", "type": "multi", "stem": "关于培训与开发效果评估中的反应评估的说法，正确的有（ ）。", "options": {"A": "它评估的是受训人员对培训与开发的主观感受与看法", "B": "它包括对培训与开发的内容、形式等方面的满意度评估", "C": "它易于进行评估", "D": "它通常采用访谈、问卷调查等方法进行评估", "E": "它是组织高管层最关心的评估内容"}, "answer": "ABCD", "analysis": "反应评估主要了解受训人员对培训项目的主观感受和满意程度，一般在培训结束后通过问卷、访谈等方式实施。该层次的数据较容易获得，但受训人员表示满意，并不必然意味着其真正掌握了知识或改善了工作绩效。", "optionAnalysis": {"A": "正确。反应评估直接考察受训人员对培训与开发的感受和看法。", "B": "正确。评估内容通常包括课程内容、培训形式、培训师、设施条件和组织安排等方面的满意度。", "C": "正确。反应评估通常可以在培训结束后迅速开展，实施相对容易。", "D": "正确。问卷调查和访谈是反应评估的常用方法。", "E": "错误。组织高管层通常更关心培训给组织带来的最终结果，即结果评估。"}}, {"id": "18-3", "type": "multi", "stem": "在培训与开发效果评估中，结果评估的软指标包括（ ）。", "options": {"A": "工作满意度", "B": "主动性", "C": "产出", "D": "工作习惯", "E": "成本"}, "answer": "ABD", "analysis": "结果评估指标可以分为硬指标和软指标。硬指标通常具有客观、可量化的特点，如产出、质量、成本和时间；软指标主要反映员工态度、行为倾向和工作状态，如工作满意度、主动性及工作习惯等。", "optionAnalysis": {"A": "正确。工作满意度反映员工的主观态度，属于软指标。", "B": "正确。主动性反映员工的工作态度和行为倾向，属于软指标。", "C": "错误。产出可以通过数量或业务结果进行客观衡量，属于硬指标。", "D": "正确。工作习惯属于员工行为状态方面的指标，属于软指标。", "E": "错误。成本通常可以直接用货币金额衡量，属于硬指标。"}}, {"id": "18-4", "type": "multi", "stem": "在培训开发与评估里，属于结果评估中的硬指标的是（ ）。", "options": {"A": "时间", "B": "质量", "C": "成本", "D": "产出", "E": "客户满意度"}, "answer": "ABCD", "analysis": "硬指标是能够用客观数据直接测量和核实的结果指标，主要包括产出、质量、成本和时间。软指标则更多涉及态度、满意程度、主动性和工作习惯等主观或行为层面的结果。", "optionAnalysis": {"A": "正确。完成工作所用的时间、工时或交付周期可以客观计量，属于硬指标。", "B": "正确。产品合格率、差错率和返工率等质量指标能够量化，属于硬指标。", "C": "正确。生产成本、人工成本和损耗等可以用货币数据衡量，属于硬指标。", "D": "正确。产量、销售量等产出数据能够直接统计，属于硬指标。", "E": "错误。按照本题所依据的教材分类，客户满意度主要反映客户的主观评价，属于软指标。"}}, {"id": "18-5", "type": "multi", "stem": "在培训与开发效果评估中，结果评估的主要指标是（ ）。", "options": {"A": "产量", "B": "培训与开发的投资收益", "C": "产品质量", "D": "生产力水平", "E": "投诉率"}, "answer": "ACDE", "analysis": "结果评估关注培训后组织经营和员工工作成果是否发生变化，其主要指标包括产量、质量、生产力、缺勤率、离职率、事故率、投诉率等。培训与开发的投资收益属于更进一步的投资收益评估内容，不属于本题所问的结果评估主要指标。", "optionAnalysis": {"A": "正确。产量能够直接反映培训后员工或组织的产出变化。", "B": "错误。培训与开发的投资收益通常通过培训收益与培训成本的比较进行评价，属于投资收益评估，不是本题所列的结果评估主要指标。", "C": "正确。产品质量能够反映员工知识、技能改善后形成的工作成果。", "D": "正确。生产力水平是衡量培训是否促进工作效率和组织绩效的重要指标。", "E": "正确。投诉率能够反映服务质量和工作结果的变化，是结果评估可以采用的指标。"}}, {"id": "18-6", "type": "single", "stem": "在评估培训与开发效果时，能够排除非培训开发因素对员工绩效所产生的影响的方法是（ ）。", "options": {"A": "问卷调查法", "B": "控制实验法", "C": "面谈", "D": "行为评价量表"}, "answer": "B", "analysis": "控制实验法通常设置实验组和控制组，并对两组在培训前后的绩效变化进行比较。由于控制组未接受培训，比较结果有助于排除市场环境、管理政策、设备更新等非培训因素对员工绩效的影响。", "optionAnalysis": {"A": "错误。问卷调查法可以收集受训人员的态度和意见，但难以有效分离培训因素与其他因素的影响。", "B": "正确。控制实验法通过实验组与控制组的对照，能够较好地排除非培训因素的干扰。", "C": "错误。面谈可以深入了解受训人员的感受和行为变化，但不能严格控制其他影响因素。", "D": "错误。行为评价量表主要用于记录和评价行为表现，不能单独排除其他因素对绩效的影响。"}}, {"id": "18-7", "type": "single", "stem": "关于控制实验法的说法错误的是（ ）。", "options": {"A": "可以提高评估的准确性", "B": "操作比较复杂", "C": "开发成本高", "D": "适用于管理技能等难以量化的评估"}, "answer": "D", "analysis": "控制实验法通过设置实验组和控制组，比较培训前后的变化，可以提高因果判断的准确性。但该方法需要进行分组、前测、后测以及条件控制，操作较复杂，成本也相对较高，通常更适合能够客观量化的培训结果。", "optionAnalysis": {"A": "正确。控制实验能够减少其他因素的干扰，提高培训效果评估的准确性。", "B": "正确。实验组和控制组的选择、测试及条件控制会增加操作难度。", "C": "正确。实施实验设计和持续收集数据通常需要较多时间、人力和资金，开发成本较高。", "D": "错误。管理技能等内容较难客观量化，也很难保证实验组和控制组所处环境完全一致，因此一般不适合采用控制实验法进行评估。"}}, {"id": "18-8", "type": "single", "stem": "组织层次的职业生涯管理方法不包括（ ）。", "options": {"A": "工作轮换", "B": "建立职业生涯信息中心", "C": "成立潜能评价中心", "D": "实行利润分享"}, "answer": "D", "analysis": "组织层次的职业生涯管理，是组织为帮助员工了解发展机会、评价个人潜能并积累职业经验而采取的制度和活动。常见方法包括工作轮换、建立职业生涯信息中心、成立潜能评价中心、实行双通道或“双肩挑”等。", "optionAnalysis": {"A": "属于。工作轮换可以帮助员工获得不同岗位的工作经验，拓宽其职业发展空间。", "B": "属于。职业生涯信息中心可以向员工提供职位空缺、任职资格和发展路径等信息。", "C": "属于。潜能评价中心可以评价员工的能力和发展潜力，为职业发展与人员配置提供依据。", "D": "不属于。利润分享是一种员工薪酬激励或收益分享制度，并非职业生涯管理方法。"}}, {"id": "18-9", "type": "multi", "stem": "“双肩挑”这种职业生涯管理方法，正确的是（ ）。", "options": {"A": "它是一种组织层次的职业生涯管理法", "B": "它主要为组织中技术或专业人员设计", "C": "它是指员工同时承担技术和管理工作", "D": "它是一种评价中心方法", "E": "它是组织培养高层管理的一种主要方式"}, "answer": "ABCE", "analysis": "“双肩挑”是组织层次的职业生涯管理方法，主要面向具有技术或专业背景的人员。组织通过让相关员工同时承担一定的技术工作和管理工作，考察并培养其综合管理能力，为组织选拔和培养高层管理人员创造条件。", "optionAnalysis": {"A": "正确。“双肩挑”由组织安排和实施，属于组织层次的职业生涯管理方法。", "B": "正确。该方法主要针对技术人员或专业人员，为其提供接触管理工作的机会。", "C": "正确。“双肩挑”的基本特点是员工同时承担技术或专业工作与管理工作。", "D": "错误。评价中心是综合运用情境模拟、无领导小组讨论、公文筐测试等方法评价人员能力的技术，“双肩挑”并非评价中心方法。", "E": "正确。通过让技术或专业人员承担管理职责，组织可以发现并培养具有综合能力的管理人才，是培养高层管理人员的重要方式之一。"}}, {"id": "18-10", "type": "single", "stem": "在职业生涯发展过程中，如果个体的主要任务是训练帮助他人以及制定政策，说明该个体处在职业生涯发展阶段的（ ）。", "options": {"A": "建立期", "B": "衰退期", "C": "维持期", "D": "探索期"}, "answer": "C", "analysis": "职业生涯维持期的个体通常已经积累了较丰富的工作经验并取得一定职业地位，其主要任务不再只是学习和证明自身能力，而是维持已有成就、更新技能、指导和帮助他人，并参与组织政策的制定。", "optionAnalysis": {"A": "错误。建立期的主要任务是寻找职业定位、适应工作、展示能力并建立稳定的职业地位。", "B": "错误。衰退期的主要任务通常是逐渐减少工作责任，为退休和退出职业生活作准备。", "C": "正确。训练和帮助他人、参与政策制定是职业生涯维持期的重要任务。", "D": "错误。探索期主要是进行自我考察、尝试不同角色并选择适合自己的职业。"}}, {"id": "18-11", "type": "single", "stem": "30-45岁属于职业生涯管理的什么阶段（ ）。", "options": {"A": "探索期", "B": "建立期", "C": "维持期", "D": "衰退期"}, "answer": "B", "analysis": "按照教材中常见的职业生涯发展阶段划分，探索期一般处于30岁以前，建立期一般为30—45岁，维持期一般为45—60岁，衰退期通常从60岁以后开始。年龄划分是一般性参考，具体个体可能因职业经历不同而存在差异。", "optionAnalysis": {"A": "错误。探索期主要发生在职业生涯早期，个体主要进行职业选择和初步尝试。", "B": "正确。30—45岁通常属于建立期，个体的主要任务是确定职业方向、发展专长并建立职业地位。", "C": "错误。维持期通常在45岁以后，重点是维持成就、更新技能和指导他人。", "D": "错误。衰退期通常接近职业生涯后期，个体逐渐减少职业责任并为退休作准备。"}}, {"id": "18-12", "type": "multi", "stem": "关于职业生涯锚的说法，正确的有（ ）。", "options": {"A": "它是可以通过各种测试提前预测得出来的", "B": "它并非完全固定不变的", "C": "它强调个人能力、动机和价值观三方面的相互作用与整合", "D": "它产生于一个人的早期职业生涯阶段，以个体习得的工作经验为基础", "E": "它是一个人无论如何都不会放弃的职业生涯中的某种至关重要的东西或价值观"}, "answer": "BCDE", "analysis": "职业生涯锚是个体在职业选择和发展过程中逐渐形成的、不可轻易放弃的核心能力、动机和价值观。它以实际工作经验为基础，需要个体在职业实践中逐步认识，不能仅依靠职业测试在进入职业生涯前准确预测。", "optionAnalysis": {"A": "错误。职业生涯锚需要通过实际工作经历逐步发现，不能仅凭各种测试提前准确预测。", "B": "正确。职业生涯锚具有一定稳定性，但并非永远固定不变；随着工作经历和个人环境的变化，仍可能发生调整。", "C": "正确。职业生涯锚体现个人能力、动机和价值观三方面的相互作用与整合。", "D": "正确。职业生涯锚通常产生于早期职业生涯阶段，并建立在个体已经获得的实际工作经验之上。", "E": "正确。职业生涯锚代表个体在面临职业选择时不愿放弃的核心需要、价值观或能力取向。"}}, {"id": "18-13", "type": "single", "stem": "小张等员工来自技术部门和财务部门，他们期望在专业方面发展，不愿意承担一般的管理工作，小张等员工的职业生涯锚类型是（ ）。", "options": {"A": "创造型", "B": "技术/职能能力型", "C": "管理能力型", "D": "自主独立型"}, "answer": "B", "analysis": "技术/职能能力型职业生涯锚的个体重视在特定专业领域内不断提高技术或职能水平，希望成为专业领域的专家，通常不愿意为了晋升而离开专业工作去承担一般管理职责。题干中员工希望在技术、财务等专业方面发展，符合该类型特征。", "optionAnalysis": {"A": "错误。创造型职业生涯锚强调创办企业、开发新产品或建立个人事业，题干未体现创业和创造组织的需要。", "B": "正确。重视专业能力发展且不愿承担一般管理工作，是技术/职能能力型职业生涯锚的典型表现。", "C": "错误。管理能力型个体通常希望承担综合管理责任，并追求更高层次的管理职位。", "D": "错误。自主独立型个体主要追求工作方式、时间和程序上的自主性，题干强调的是专业发展而非摆脱组织约束。"}}, {"id": "18-14", "type": "single", "stem": "关于管理能力型职业生涯锚的说法，错误的是（ ）。", "options": {"A": "强调实际工作", "B": "分析能力、人际沟通能力和情绪控制能力强强组合", "C": "有很强的升职欲望", "D": "对组织有很强的依赖性第十九章劳动关系"}, "answer": "A", "analysis": "管理能力型职业生涯锚的个体希望承担综合管理责任，追求职位晋升和更大的管理权限。这类人员通常重视分析能力、人际沟通能力和情绪控制能力的组合，并且由于其职业发展依赖组织提供管理职位和晋升通道，对组织具有较强的依赖性。强调具体专业或技术实际工作的特征更符合技术/职能能力型职业生涯锚。", "optionAnalysis": {"A": "错误。管理能力型人员关注综合管理、组织协调和管理责任，而不是强调从事某项具体的专业实际工作。", "B": "正确。管理能力型职业生涯锚强调分析能力、人际沟通能力和情绪控制能力的有机结合。", "C": "正确。这类人员通常希望承担更高层次的管理职责，具有较强的职位晋升愿望。", "D": "正确。管理职位、权力和晋升机会主要由组织提供，因此管理能力型人员对组织具有较强的依赖性。"}}]}, {"id": 19, "title": "劳动关系", "questions": [{"id": "19-1", "type": "single", "stem": "市场经济中的劳动关系具有的最主要特点是（ ）。", "options": {"A": "流动性", "B": "从属性", "C": "多样性", "D": "外部性"}, "answer": "B", "analysis": "劳动关系建立后，劳动者需要将劳动力交由用人单位支配，在用人单位的组织和管理下从事劳动，并遵守依法制定的劳动规章制度。因此，从属性是市场经济中劳动关系最主要、最本质的特点。", "optionAnalysis": {"A": "错误，市场经济条件下劳动力具有一定流动性，但流动性并不是劳动关系最主要的本质特征。", "B": "正确，劳动者在人格和经济等方面对用人单位具有一定从属性。", "C": "错误，劳动关系在主体、形式和内容上具有多样性，但多样性不是其最主要特点。", "D": "错误，外部性是经济活动可能产生的影响，不属于劳动关系最主要的特征。"}}, {"id": "19-2", "type": "single", "stem": "劳动关系正常运行的基本要求是（ ）。", "options": {"A": "劳动者当家作主", "B": "用人单位和劳动者都不追求自身利益", "C": "劳动者服从用人单位管理", "D": "劳资双方寻求双方都能接受的平衡点"}, "answer": "D", "analysis": "劳动关系双方既有共同利益，也存在利益差异。劳动关系正常运行的基本要求，是通过协商、规则和制度安排，在双方利益之间寻求均衡，形成双方都能够接受的利益平衡点。", "optionAnalysis": {"A": "错误，劳动者参与民主管理是劳动关系制度的重要内容，但不能概括劳动关系正常运行的基本要求。", "B": "错误，用人单位和劳动者都是利益主体，客观上都会追求自身合法利益，不可能完全不追求自身利益。", "C": "错误，劳动者应当接受用人单位依法进行的劳动管理，但单方面服从并不能解决劳资双方的利益协调问题。", "D": "正确，劳资双方寻求能够共同接受的平衡点，有利于实现劳动关系的稳定运行。"}}, {"id": "19-3", "type": "single", "stem": "劳动关系是以（ ）作为基本构成的社会关系。", "options": {"A": "经济关系", "B": "政治关系", "C": "文化关系", "D": "法律关系"}, "answer": "A", "analysis": "劳动关系产生于劳动者向用人单位提供劳动、用人单位向劳动者支付劳动报酬的经济交换过程，其基本构成是经济关系，同时又受到法律制度和社会制度的规范。", "optionAnalysis": {"A": "正确，劳动力的使用和劳动报酬的支付构成劳动关系的经济基础。", "B": "错误，劳动关系可能受到政治制度和公共政策影响，但政治关系不是其基本构成。", "C": "错误，组织文化会影响劳动关系的具体状态，但不是劳动关系的基本构成。", "D": "错误，劳动关系具有法律属性并受到劳动法律调整，但从基础性质看，它首先是建立在劳动交换基础上的经济关系。"}}, {"id": "19-4", "type": "single", "stem": "我国法律规定的用人单位不包括（ ）。", "options": {"A": "家庭", "B": "民办幼儿园", "C": "个体工商户", "D": "大学校办企业"}, "answer": "A", "analysis": "我国劳动法律所称用人单位，主要包括中华人民共和国境内的企业、个体经济组织、民办非企业单位等组织，以及依法与劳动者建立劳动关系的国家机关、事业单位和社会团体。一般家庭雇用家政服务人员所形成的关系通常不属于劳动法意义上的标准劳动关系。", "optionAnalysis": {"A": "正确，家庭本身通常不是我国劳动法律规定的用人单位。", "B": "错误，依法设立的民办幼儿园可以属于民办非企业单位，能够成为劳动关系中的用人单位。", "C": "错误，个体工商户属于个体经济组织，可以成为用人单位。", "D": "错误，大学校办企业属于依法设立的企业，可以成为用人单位。"}}, {"id": "19-5", "type": "single", "stem": "关于劳动关系理论中雇主权利义务的说法，错误的是（ ）。", "options": {"A": "雇主权利源自劳动力的占有权", "B": "雇主权利主要包括组织权、劳动指挥权、奖惩权和闭厂权", "C": "雇主权利是雇主维护自身利益所必需的", "D": "保证工人休息休假权是雇主的义务"}, "answer": "A", "analysis": "雇主的管理权利建立在其生产资料所有权、经营管理权以及依法订立的劳动合同基础上。劳动者对自己的劳动力具有人身不可分离的权利，用人单位只能按照劳动合同约定使用劳动者提供的劳动力，不能取得对劳动力的所有或占有权。", "optionAnalysis": {"A": "错误，雇主权利并非源自对劳动力的占有权，而是与生产资料所有权、经营管理权及劳动合同关系有关。", "B": "正确，组织权、劳动指挥权、奖惩权以及依法实施的闭厂权，是劳动关系理论中雇主权利的主要表现。", "C": "正确，雇主必须拥有必要的组织和管理权，才能组织生产经营并维护其合法利益。", "D": "正确，依法保障劳动者的休息休假权，是用人单位应当履行的法定义务。"}}, {"id": "19-6", "type": "single", "stem": "1994年颁布的落实劳动保障法律法规，规范劳动关系双方权利和义务的重要载体的法律是（ ）。", "options": {"A": "《劳动合同法》", "B": "《劳动争议调解仲裁法》", "C": "《劳动法》", "D": "《劳动保障监察条例》"}, "answer": "C", "analysis": "《中华人民共和国劳动法》于1994年7月5日通过并公布，自1995年1月1日起施行，是我国规范劳动关系双方权利和义务的重要基础性法律。", "optionAnalysis": {"A": "错误，《劳动合同法》于2007年通过，不是1994年颁布的法律。", "B": "错误，《劳动争议调解仲裁法》于2007年通过，主要规范劳动争议的调解和仲裁程序。", "C": "正确，《劳动法》于1994年颁布，对劳动合同、工作时间、休息休假、工资、劳动安全卫生等作出系统规定。", "D": "错误，《劳动保障监察条例》于2004年公布，主要规范劳动保障行政监察活动。"}}, {"id": "19-7", "type": "multi", "stem": "关于平等保护的说法正确的有（ ）。", "options": {"A": "劳动关系中，首先保护劳动者", "B": "国有和非国有单位赋予同等的权力", "C": "对各类用人主体的权益平等保护", "D": "对于女职工优先保护", "E": "对于特定人群的平等保护"}, "answer": "BC", "analysis": "平等保护强调不同所有制形式的用人单位、不同类型的市场主体在法律适用和合法权益保护方面处于平等地位，不能因所有制或主体类型不同而受到不合理的区别对待。", "optionAnalysis": {"A": "错误，劳动法对处于相对弱势地位的劳动者实行倾斜保护，不等同于平等保护中所说的对各类主体一律平等对待。", "B": "正确，国有单位与非国有单位在法律规定的范围内应当享有平等的权利并承担相应义务。", "C": "正确，对不同类型用人主体的合法权益应当依法给予平等保护。", "D": "错误，女职工劳动保护属于对特定群体的特殊劳动保护，而不是所谓优先保护。", "E": "错误，对未成年工、女职工等特定群体实行的是基于实际差异的特殊保护，不能简单概括为本题所指的用人主体平等保护。"}}, {"id": "19-8", "type": "single", "stem": "我国劳动关系调整的原则包括（ ）。", "options": {"A": "促进经济发展和社会进步的原则", "B": "以政府协调为基础的原则", "C": "重点保护劳动者权益的原则", "D": "强调劳动关系主体各自义务的原则"}, "answer": "A", "analysis": "劳动关系调整不仅要依法保护劳动关系主体的合法权益，还应当兼顾生产经营、就业稳定和社会公共利益，最终促进经济发展与社会进步。", "optionAnalysis": {"A": "正确，促进经济发展和社会进步是劳动关系调整应当遵循的重要原则。", "B": "错误，劳动关系调整需要政府发挥协调和监管作用，但不能把政府协调表述为劳动关系运行的唯一基础；劳动关系还需要法律规范、市场机制、集体协商和社会协调机制共同发挥作用。", "C": "错误，劳动法确实对劳动者实行倾斜保护，但规范表述通常是依法保护劳动关系主体权益，并对劳动者给予必要的特殊保护，不能简单概括为只重点保护劳动者权益。", "D": "错误，劳动关系调整坚持权利与义务相统一，不能只强调双方义务而忽视双方依法享有的权利。"}}, {"id": "19-9", "type": "single", "stem": "在劳动关系调整的原则中，劳动者和用人单位通过平等协商一致，依法签订劳动合同，明确双方的权利和义务，这涉及（ ）。", "options": {"A": "劳动关系主体权利义务统一的原则", "B": "保护劳动关系主体权益的原则", "C": "以劳动关系双方自主协调为基础的原则", "D": "促进经济发展和社会进步的原则"}, "answer": "C", "analysis": "C项正确，以劳动关系双方自主协调为基础的原则：劳动关系当事人双方（劳动者＋用人单位），在平等自愿基础上自主协商、达成一致，签订劳动合同，属于双方自主协调。", "optionAnalysis": {"A": "错误，权利义务统一原则，强调权利和义务对等，不能只享受权利不履行义务，题干没有体现。", "B": "错误，保护主体权益原则，侧重法律对双方（尤其劳动者）权益的保护，不是协商签约这个行为。", "D": "错误，促进经济发展和社会进步，是宏观最终目标，和协商签合同无关。"}}, {"id": "19-10", "type": "single", "stem": "协调劳动关系三方机制中的“三方”是指（ ）。", "options": {"A": "工会、劳动者和政府组织", "B": "政府、劳动者和企业", "C": "劳动者、工会和雇主", "D": "政府、工会代表和雇主代表"}, "answer": "D", "analysis": "协调劳动关系三方机制由政府、职工方和企业方共同参与。职工方通常由工会代表，企业方通常由企业联合会、企业家协会等雇主组织代表。", "optionAnalysis": {"A": "错误，工会已经代表劳动者一方，不能再将工会和劳动者分别列为两个独立方面，而且缺少雇主方。", "B": "错误，三方机制中的职工方和企业方通常由相应的代表组织参加，并不是由个别劳动者和单个企业直接构成。", "C": "错误，该选项缺少政府一方，并且劳动者与工会在三方机制中不能分别作为两个方面。", "D": "正确，政府、工会代表和雇主代表共同构成协调劳动关系三方机制。"}}, {"id": "19-11", "type": "single", "stem": "我国职工民主管理制度的主要体现形式是（ ）。", "options": {"A": "职工代表大会制度", "B": "劳动关系三方协调机制", "C": "集体协商制度", "D": "劳动争议调解制度"}, "answer": "A", "analysis": "职工代表大会是职工依法参与本单位民主决策、民主管理和民主监督的基本形式，是我国职工民主管理制度的主要体现。", "optionAnalysis": {"A": "正确，职工代表大会制度集中体现了职工参与企事业单位民主管理的权利。", "B": "错误，劳动关系三方协调机制主要用于政府、工会和雇主组织之间协调劳动关系，不是单位内部职工民主管理的主要形式。", "C": "错误，集体协商制度用于职工方与用人单位就劳动报酬、工作时间等事项进行协商，是协调集体劳动关系的重要制度。", "D": "错误，劳动争议调解制度主要用于处理已经发生的劳动争议，不属于职工民主管理的主要体现形式。"}}, {"id": "19-12", "type": "single", "stem": "集体劳动关系处理规则的基本表现方式是（ ）。", "options": {"A": "集体劳动法律", "B": "劳资协商制度", "C": "集体合同", "D": "劳动合同"}, "answer": "C", "analysis": "集体合同是用人单位与职工方通过集体协商，就劳动报酬、工作时间、休息休假、劳动安全卫生等事项订立的书面协议，是集体劳动关系处理规则的基本表现方式。", "optionAnalysis": {"A": "错误，劳动法律为集体劳动关系提供法律规范，但不是劳动关系双方协商形成的具体处理规则。", "B": "错误，劳资协商是形成集体劳动规则的过程和机制，不是规则最终的基本表现形式。", "C": "正确，集体合同以书面形式确定集体协商结果，是集体劳动关系处理规则的基本载体。", "D": "错误，劳动合同是用人单位与单个劳动者建立劳动关系、明确双方权利义务的协议，主要调整个别劳动关系。"}}, {"id": "19-13", "type": "single", "stem": "可以直接作为用人单位管理的文件依据不包括（ ）。", "options": {"A": "依据市场行情制定的裁员方案", "B": "集体合同", "C": "劳动合同", "D": "依法制定的劳动规章制度"}, "answer": "A", "analysis": "用人单位对劳动者实施管理应当具有合法、有效的制度或合同依据。劳动合同、集体合同和依法制定并公示的劳动规章制度，都可以成为确定双方权利义务和实施劳动管理的依据。仅依据市场行情单方制定的裁员方案，不能当然作为解除劳动合同或实施裁员的直接法律依据。", "optionAnalysis": {"A": "正确，裁员必须符合法定条件和程序，单纯依据市场行情制定的方案不具有当然的管理依据效力。", "B": "错误，依法订立并生效的集体合同对用人单位和职工具有约束力，可以作为劳动管理的依据。", "C": "错误，劳动合同明确用人单位与劳动者的权利义务，是实施个别劳动关系管理的重要依据。", "D": "错误，依法通过民主程序制定并向劳动者公示的劳动规章制度，可以作为用人单位管理劳动者的依据。"}}, {"id": "19-14", "type": "multi", "stem": "关于我国劳动争议处理制度的说法，正确的有（ ）。", "options": {"A": "劳动争议由法定机构进行依法处理", "B": "实行“一调、一裁、三审”的劳动争议处理机制", "C": "该制度专门处理劳动关系当事人因实现劳动权利和履行劳动义务而发生的纠纷", "D": "实行“或裁或审”的劳动争议处理制度", "E": "劳动争议处理的四个主要环节是协商、沟通、仲裁和诉讼"}, "answer": "AC", "analysis": "我国劳动争议处理制度主要包括协商、调解、仲裁和诉讼等环节。劳动争议仲裁通常是提起劳动争议诉讼的法定前置程序，但法律另有规定的除外。", "optionAnalysis": {"A": "正确，劳动争议调解组织、劳动人事争议仲裁委员会和人民法院等法定机构依法处理劳动争议。", "B": "错误，我国通常实行“一调一裁两审”的处理机制，并非“一调、一裁、三审”。", "C": "正确，劳动争议处理制度专门解决劳动关系当事人因实现劳动权利、履行劳动义务而产生的纠纷。", "D": "错误，我国劳动争议处理通常实行仲裁前置，而不是由当事人在仲裁和诉讼之间任意选择的“或裁或审”。", "E": "错误，四个主要环节是协商、调解、仲裁和诉讼，不是协商、沟通、仲裁和诉讼。"}}, {"id": "19-15", "type": "single", "stem": "要明确界定员工的申诉范围，避免员工将本可以通过正常管理渠道解决的问题也通过申诉方式提出，这体现了员工申诉管理原则中的（ ）。", "options": {"A": "合法原则", "B": "明晰原则", "C": "及时原则", "D": "反馈原则"}, "answer": "B", "analysis": "明晰原则要求用人单位明确员工申诉的适用范围、受理条件、处理程序和责任主体，使员工能够区分申诉事项与一般管理事项。", "optionAnalysis": {"A": "错误，合法原则强调申诉制度及其处理过程应当符合法律法规，不得侵害员工合法权益。", "B": "正确，明确界定申诉范围，防止一般管理问题被不当纳入申诉程序，体现了明晰原则。", "C": "错误，及时原则强调及时受理、调查和处理员工申诉，防止矛盾扩大。", "D": "错误，反馈原则强调将申诉受理情况和处理结果及时告知申诉人。"}}, {"id": "19-16", "type": "multi", "stem": "员工申诉原则的说法正确的有（ ）。", "options": {"A": "将员工申诉的内容结果公开，违反了保密原则", "B": "本应通过正常管理程序解决的问题却通过申诉解决，违反了明晰原则", "C": "及时预防和处理员工的申诉问题，违反了及时原则", "D": "领导和员工共同违反规定只对员工进行处罚违反了公平原则", "E": "用人单位认为自己内部规章不涉及法律法规问题，违反了合法原则"}, "answer": "ABDE", "analysis": "员工申诉管理通常应遵循合法、明晰、及时、公平、反馈和保密等原则。", "optionAnalysis": {"A": "正确，未经必要授权公开申诉内容和处理结果，可能泄露员工隐私或敏感信息，违反保密原则。", "B": "正确，申诉制度应当明确适用范围，将本应通过日常管理程序处理的问题纳入申诉程序，说明申诉范围不清晰，违反明晰原则。", "C": "错误，及时预防和处理员工申诉正是及时原则的要求，并不违反及时原则。", "D": "正确，对于相同或相关违规行为，应当按照统一规则公平处理。领导和员工共同违规却只处罚员工，违反公平原则。", "E": "正确，用人单位的内部规章制度必须符合法律法规，不能以属于内部管理事项为由排除合法性审查，否则违反合法原则。"}}, {"id": "19-17", "type": "single", "stem": "关于劳动争议非正式申诉处理程序的说法，错误的是（ ）。", "options": {"A": "主要是依靠企业劳动争议调解委员会实现的", "B": "需要双方当事人对各自的行为进行详细的解释", "C": "需要提出一套双方当事人都认可的解决方案", "D": "若非正式的申诉处理不成功，可以转为正式的申诉处理程序解决矛盾"}, "answer": "A", "analysis": "非正式申诉处理通常通过员工与直接主管、人力资源管理人员等进行沟通、说明和协商，力求以较灵活、较低成本的方式化解矛盾。企业劳动争议调解委员会属于具有第三方调解性质的组织，并不是非正式申诉处理程序主要依靠的主体。", "optionAnalysis": {"A": "错误，企业劳动争议调解委员会参与的调解具有相对正式的组织和程序，非正式申诉主要依靠当事人及企业内部管理渠道直接沟通。", "B": "正确，为查明矛盾原因，双方需要对有关事实及各自行为作出说明。", "C": "正确，非正式处理的目标是通过协商形成双方可以接受的解决办法。", "D": "正确，非正式程序未能解决问题时，可以按照申诉制度转入正式处理程序。"}}, {"id": "19-18", "type": "single", "stem": "员工申诉正式与非正式处理程序的区别，表述正确的是（ ）。", "options": {"A": "正式处理程序解决问题能力强", "B": "非正式处理程序依靠第三方调解", "C": "非正式处理程序需要更多时间了解事实真相", "D": "非正式处理程序在正式处理程序之后"}, "answer": "B", "analysis": "", "optionAnalysis": {}}, {"id": "19-19", "type": "multi", "stem": "在调解劳动争议前，企业劳动争议调解委员会应做的准备工作有（ ）。", "options": {"A": "告知当事人调解员的身份", "B": "通知被申请人提供相关证据资料", "C": "收集有关证据", "D": "制作调解协议书", "E": "审查调解申请"}, "answer": "ABCE", "analysis": "劳动争议调解开始前，调解组织需要审查申请、了解争议基本情况、确定和告知调解人员、通知有关当事人并收集必要证据，为查明事实和开展调解做好准备。调解协议书应当在双方经调解达成协议后制作。", "optionAnalysis": {"A": "正确，告知调解员身份有利于保障当事人的知情权，并便于当事人依法提出回避等意见。", "B": "正确，通知被申请人提供相关证据资料，有利于全面了解争议事实。", "C": "正确，收集与争议有关的证据是查明事实、分清责任的重要准备工作。", "D": "错误，只有双方经调解达成协议后，才需要制作调解协议书，不能在调解前预先制作。", "E": "正确，调解委员会应当审查调解申请，判断申请事项是否属于劳动争议以及是否符合受理条件。"}}, {"id": "19-20", "type": "single", "stem": "企业劳动争议调解委员会调解劳动争议前的准备工作中，在弄清案件的基本情况后，下一步是（ ）。", "options": {"A": "通知被申请人", "B": "进一步调查事实", "C": "分析证据", "D": "做好当事人的思想工作"}, "answer": "B", "analysis": "企业劳动争议调解委员会在初步弄清案件基本情况后，应进一步调查争议事实、收集和核实证据。在事实基本查清后，才能对证据和双方责任进行分析，并有针对性地开展调解工作。", "optionAnalysis": {"A": "错误，通知被申请人属于受理申请后的前期程序，通常在初步了解案件过程中进行，不是弄清基本情况后的核心下一步骤。", "B": "正确，初步掌握案件情况后，需要进一步调查事实，以确保调解建立在真实、完整的事实基础上。", "C": "错误，分析证据应以调查和收集证据为基础，通常在进一步调查事实之后进行。", "D": "错误，做好当事人的思想疏导工作属于具体调解活动的重要内容，应当在基本事实和争议焦点较为明确后开展。"}}]}]};
